// GARDE-FOU CODE VILLE — résolution du "_" final + récupération au démarrage
// ─────────────────────────────────────────────────────────────────────────────
// Le coeur (m1prime.js / m2body.js selectCityFunction) construit l'URL du
// fichier d'horaires SANS aucune tolérance :
//     data/<CC>/wtimes-<JS_DATA.ucNowCityCODE>.js
// Si ce code ne correspond à AUCUN fichier livré -> <script> 404 -> JS_TIMES
// reste undefined -> le tout premier calculateAndDisplayTimesFunction()
// (rejoué par custom.js juste après la garde jomoa/Dohr, ~L2670) plante
// (timeStringToMinutesFunction(undefined).substr -> throw). Ce throw
// INTERROMPT l'exécution synchrone du RESTE de custom.js : config sync,
// polling distant, automatisations lumières, tout. L'appli reste figée sur un
// affichage sans horaires, sans plus aucun moyen de se réparer toute seule.
//
// Origine constatée (28/08/2026, boîtier mosquée tn.monastir.aboubakr, IP .246
// -- même famille de bug qu'un incident d'import Supabase antérieur) :
//   - l'EXPORT vers Supabase strippe le "_" final de ucNowCityCODE (artefact
//     des noms de fichiers wtimes-*.js) -> mosques.location_code =
//     "tn.ksibet-el-mediouni"
//   - l'IMPORT léger (_applyRow, appelé par le polling de config toutes les
//     ~18 s) réinjecte cette valeur TELLE QUELLE dans JS_DATA.ucNowCityCODE
//   - or le fichier réellement livré est "wtimes-tn.ksibet-el-mediouni_.js"
//     (AVEC "_") -> 404 -> plantage au rechargement suivant.
//
// _ucResolveCityCode : ramène n'importe quel code (avec/sans "_", casse) vers
// le code EXACT présent dans le catalogue JS_CITIES_DATA (data/<CC>/<cc>.js,
// chargé par le coeur) -- le seul pour lequel un fichier wtimes existe.
// Appelé à CHAQUE point d'import (_applyRow, _applyMosqueConfig,
// _restoreFromJson) + ici au boot pour rattraper un état déjà corrompu.
// ═══════════════════════════════════════════════════════════════════════════
function _ucResolveCityCode(code) {
    var raw = String(code || '').trim().toLowerCase();
    if (!raw || raw.indexOf('.') === -1) return raw;
    if (typeof JS_CITIES_DATA === 'undefined' || !Array.isArray(JS_CITIES_DATA) || !JS_CITIES_DATA.length) {
        return raw;   // catalogue pas encore chargé -> on ne peut rien résoudre
    }
    var known = Object.create(null);
    for (var i = 0; i < JS_CITIES_DATA.length; i++) {
        var e = String(JS_CITIES_DATA[i] || '').toLowerCase();
        var d1 = e.indexOf('.');
        if (d1 < 0) continue;
        var d2 = e.indexOf('.', d1 + 1);
        var c = (d2 < 0) ? e.replace(/\.+$/, '') : e.slice(0, d2);   // "tn.xxx" ou "tn.xxx_"
        if (c) known[c] = true;
    }
    if (known[raw]) return raw;
    var bare = raw.replace(/_+$/, '');
    if (known[bare + '_']) return bare + '_';
    if (known[bare])       return bare;
    return raw;   // introuvable au catalogue -> inchangé (le garde de boot tentera un repli)
}
window._ucResolveCityCode = _ucResolveCityCode;

// ── Blindage anti-crash de timeStringToMinutesFunction (coeur m2body.js:4019) ──
// Tant que la récupération de code ville n'a pas rechargé l'appli avec un
// wtimes-*.js valide, JS_TIMES reste vide et le coeur appelle
// timeStringToMinutesFunction(undefined) -> `undefined.substr(...)` -> throw
// non rattrapé qui INTERROMPT le reste de custom.js (config sync, polling,
// lumières...) ET fige l'écran. Ce patch neutralise le throw : entrée non
// exploitable -> 0 (les horaires affichent alors 00:00, transitoirement, le
// temps que _hardReload() ci-dessous recharge). Sans effet une fois les
// horaires chargés (délègue tel quel à l'original pour toute chaîne "HH:MM").
(function _hardenTimeStringToMinutes() {
    try {
        var _orig = window.timeStringToMinutesFunction;
        if (typeof _orig !== 'function') return;
        window.timeStringToMinutesFunction = function (v) {
            if (typeof v !== 'string' || v.indexOf(':') < 1) return 0;
            try { return _orig(v); } catch (e) { return 0; }
        };
    } catch (e) {}
})();

(function _ucGuardCityCodeOnBoot() {
    // NB : le catalogue JS_CITIES_DATA n'est PAS chargé au boot (le coeur ne
    // charge data/<CC>/<cc>.js que quand l'utilisateur ouvre la liste des
    // villes). La récupération procède donc par étapes, coordonnées par un
    // compteur sessionStorage (survit à location.reload, évite toute boucle) :
    //   étape 0 -> bascule SYNCHRONE du "_" final (couvre ~toutes les villes TN
    //              livrées) + reload : rapide, pas de plantage
    //   étape 1 -> chargement ASYNC du catalogue pays -> résolution exacte,
    //              sinon 1re ville "_" du pays + reload
    //   étape 2 -> abandon propre (trace, pas de boucle)
    var STEP_KEY = 'ucCityGuardStep';

    function _step() {
        try { return parseInt(sessionStorage.getItem(STEP_KEY) || '0', 10) || 0; } catch (e) { return 0; }
    }
    function _setStep(n) { try { sessionStorage.setItem(STEP_KEY, String(n)); } catch (e) {} }
    function _clearStep() { try { sessionStorage.removeItem(STEP_KEY); } catch (e) {} }
    function _persist() {
        try {
            if (typeof saveSettingsToStorageFunction === 'function') saveSettingsToStorageFunction();
            else localStorage.setItem('JS_DATA', JSON.stringify(JS_DATA));
        } catch (e) {}
    }
    function _applyAndReload(newCode, reason, nextStep) {
        if (!newCode || newCode === cur) return false;
        JS_DATA.ucNowCityCODE = newCode;
        _persist();
        _setStep(nextStep);
        _L('CFG', 'CITYCODE_RECOVER', { was: cur, now: newCode, reason: reason });
        _hardReload();
        return true;
    }
    // location.reload() appelé pendant l'exécution SYNCHRONE initiale du <script>
    // n'est pas honoré de façon fiable par l'Android WebView (constaté téléphone
    // SM-S938B, 28/08/2026 : le toggle "_" se faisait + persistait, mais AUCUN
    // rechargement -> appli bloquée sur écran sans horaires). On couvre donc
    // trois fenêtres : immédiat, après l'évènement 'load', et filet setTimeout.
    // Les timers/écouteurs de la page morte disparaissent dès qu'un reload
    // aboutit -> au pire un flash de rechargement, jamais de boucle (le
    // compteur d'étape sessionStorage est posé AVANT).
    function _hardReload() {
        function go() {
            try { location.reload(); }
            catch (e) { try { location.href = location.href; } catch (e2) {} }
        }
        go();
        try {
            if (document.readyState !== 'complete') {
                window.addEventListener('load', function () { setTimeout(go, 50); }, { once: true });
            }
            setTimeout(go, 1200);
        } catch (e) {}
    }

    var timesOk, cur;
    try {
        if (typeof JS_DATA === 'undefined' || !JS_DATA.ucNowCityCODE) return;
        cur     = String(JS_DATA.ucNowCityCODE).trim().toLowerCase();
        timesOk = (typeof JS_TIMES !== 'undefined' && Array.isArray(JS_TIMES) && JS_TIMES.length > 200);
    } catch (e) { return; }

    // ── Horaires OK ────────────────────────────────────────────────────────
    if (timesOk) {
        if (_step() !== 0) { _clearStep(); _L('CFG', 'CITYCODE_RECOVER_OK', { city: cur }); }
        // Normalisation opportuniste si le catalogue est déjà chargé.
        try {
            var norm = _ucResolveCityCode(cur);
            if (norm && norm !== cur && typeof JS_CITIES_DATA !== 'undefined'
                && Array.isArray(JS_CITIES_DATA) && JS_CITIES_DATA.length) {
                JS_DATA.ucNowCityCODE = norm;
                _persist();
                _L('CFG', 'CITYCODE_NORMALIZED', { was: cur, now: norm });
            }
        } catch (e) {}
        return;
    }

    // ── Horaires ABSENTS : le fichier wtimes-<cur>.js n'a pas chargé ───────
    var step = _step();
    _L('CFG', 'CITYCODE_RECOVER_START', { city: cur, step: step });

    if (step === 0) {
        // Étape 0 : bascule synchrone du "_" final.
        var alt = (cur.slice(-1) === '_') ? cur.replace(/_+$/, '') : (cur + '_');
        if (_applyAndReload(alt, 'underscore_toggle', 1)) return;
        _setStep(1); step = 1;   // rien à basculer -> passer à l'étape catalogue
    }

    if (step === 1) {
        _setStep(2);   // marque la tentative catalogue AVANT de la lancer (anti-boucle)
        var doResolve = function () {
            var resolved;
            try { resolved = _ucResolveCityCode(cur); } catch (e) { resolved = cur; }
            if (resolved && resolved !== cur) { _applyAndReload(resolved, 'catalog_variant', 3); return; }
            // introuvable -> 1re ville "_" du pays (sinon 1re ville tout court)
            try {
                var pfx = (cur.split('.')[0] || '') + '.', fb = '';
                for (var i = 0; i < JS_CITIES_DATA.length; i++) {
                    var e = String(JS_CITIES_DATA[i] || '').toLowerCase();
                    if (e.indexOf(pfx) !== 0) continue;
                    var d2 = e.indexOf('.', pfx.length);
                    var cand = (d2 < 0) ? e.replace(/\.+$/, '') : e.slice(0, d2);
                    if (!fb) fb = cand;
                    if (cand.slice(-1) === '_') { fb = cand; break; }
                }
                _applyAndReload(fb, 'country_first_city', 3);
            } catch (e) {
                _L('CFG', 'CITYCODE_RECOVER_GIVEUP', { city: cur, reason: 'catalog_scan_failed' });
            }
        };
        if (typeof JS_CITIES_DATA !== 'undefined' && Array.isArray(JS_CITIES_DATA) && JS_CITIES_DATA.length) {
            doResolve(); return;
        }
        var cc = (cur.split('.')[0] || '').toUpperCase();
        if (!cc) { _L('CFG', 'CITYCODE_RECOVER_GIVEUP', { city: cur, reason: 'no_country' }); return; }
        var srcs = ['data/' + cc + '/' + cc.toLowerCase() + '.js', 'spec/data/' + cc + '/' + cc.toLowerCase() + '.js'], ti = 0;
        (function _loadCat() {
            if (ti >= srcs.length) { _L('CFG', 'CITYCODE_RECOVER_GIVEUP', { city: cur, reason: 'catalog_unreachable' }); return; }
            var s = document.createElement('script');
            s.src = srcs[ti++] + '?ev=' + Date.now();
            s.onload  = function () {
                if (typeof JS_CITIES_DATA !== 'undefined' && Array.isArray(JS_CITIES_DATA) && JS_CITIES_DATA.length) doResolve();
                else _loadCat();
            };
            s.onerror = function () { _loadCat(); };
            (document.head || document.documentElement).appendChild(s);
        })();
        return;
    }

    // step >= 2 : déjà tout tenté cette session -> abandon propre (pas de boucle)
    _L('CFG', 'CITYCODE_RECOVER_GIVEUP', { city: cur, reason: 'all_steps_exhausted', step: step });
})();

// ── STOCKAGE INDÉPENDANT des réglages custom ──────────────────────────────
// (totalement séparé de JS_DATA pour ne jamais interférer avec les updates)


// Uniquement en mode telephone reel (hors boitier Android TV ET hors mode
// navigateur/Windows de test, cf. window.AndroidMobile absent dans ce
// dernier cas) : ucShowSpeakerIcon/ucShowQuranIcon desactives par defaut
// (demande explicite du 16/08/2026) -- ne s'applique qu'a la valeur PAR
// DEFAUT d'une premiere installation : une fois JS_CUSTOM construit plus
// bas (Object.assign(JS_CUSTOM_DEFAULTS, storedValues)), toute valeur deja
// sauvegardee (choix explicite de l'utilisateur, y compris une reactivation
// ulterieure) prend le pas sur ce defaut, comme pour tout autre reglage.
var _ucIsRealPhone = !!(window.AndroidMobile && typeof window.AndroidMobile.isAndroidTv === 'function'
    && !window.AndroidMobile.isAndroidTv());

// ═════════════════════════════════════════════════════════════════════════════
// RELOAD DIFFÉRABLE — jamais de location.reload() pendant la fenêtre azan/iqama
// ─────────────────────────────────────────────────────────────────────────────
// Un location.reload() est un redémarrage à froid de toute l'app (~40 000
// lignes de JS re-parsées) : plusieurs secondes d'écran figé, aggravées sous
// mauvaise connexion (rafale de fetch d'init qui pendouillent). Inacceptable en
// plein compte à rebours d'iqama ou juste avant un azan. Ce garde-fou central
// reporte tout reload NON SOLLICITÉ (sync config reçue à distance, action
// distante 'reload') jusqu'à la sortie de la fenêtre critique — il ne bloque
// jamais définitivement, il re-tente toutes les 60 s.
//
// EXCEPTION (demande terrain 01/09/2026) : le reload MANUEL déclenché par
// l'utilisateur lui-même n'est PLUS différé — il s'exécute immédiatement, à
// n'importe quel moment. Concerne les 4 déclencheurs manuels :
//   - #psFlagImageVertical (double-tap)  -> restartApplicationFunction()
//   - #psFlagImageHorizontal (tap, onclick index.html) -> restartApplicationFunction()
//   - #ucReloadLink (lien "RELOAD" des crédits) -> restartApplicationFunction()
//   - #ucManualReloadBtn (icône flèche, vertical) -> location.reload() direct (déjà non gardé)
// Raison : sur une box sans RTC, après un redémarrage l'imam connecte le Wi-Fi
// et corrige l'horloge EN PLEIN compte à rebours, puis a besoin de reloader
// pour repartir sur les bons horaires — le report l'en empêchait (fenêtre de
// garde ~32 min autour de chaque azan). L'utilisateur qui touche volontairement
// le drapeau/RELOAD sait ce qu'il fait. Seuls les reloads NON sollicités (sync
// config reçue, action distante 'reload') restent différés.
// Les horaires n'ont de toute façon pas besoin de reload : calculés en local
// (calculateAndDisplayTimesFunction), 100 % hors-ligne. m2body.js est chargé
// avant custom.js -> restartApplicationFunction existe déjà ici.
// ═════════════════════════════════════════════════════════════════════════════
(function _installDeferrableReload() {
    var GUARD_BEFORE_MIN = 12;   // azan imminent : 12 min avant l'heure
    var GUARD_AFTER_MIN  = 20;   // fenêtre iqama : jusqu'à 20 min après l'azan
    var RETRY_MS         = 60000;

    function _pt(name) {
        try {
            var v = window[name];
            return (typeof v === 'number' && !isNaN(v)) ? v : null;
        } catch (e) { return null; }
    }

    // True si un reload maintenant couperait un azan / une séquence d'iqama.
    window._ucReloadGuardActive = function () {
        try {
            if (typeof isIqamaCounterActive !== 'undefined' && isIqamaCounterActive) return true;
            var ids = ['azanPopupVertical', 'azanPopupHorizontal', 'iqamaPopupVertical', 'iqamaPopupHorizontal'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && !el.classList.contains('hiddenClass')) return true;
            }
            var now  = new Date();
            var mins = now.getHours() * 60 + now.getMinutes();
            var times = [_pt('fajrTimeInMinutes'), _pt('dohrTimeInMinutes'), _pt('asrTimeInMinutes'),
                         _pt('maghribTimeInMinutes'), _pt('ishaTimeInMinutes')];
            for (var j = 0; j < times.length; j++) {
                if (times[j] === null) continue;
                var d = times[j] - mins;
                if (d <= GUARD_BEFORE_MIN && d >= -GUARD_AFTER_MIN) return true;
            }
            return false;
        } catch (e) { return false; }
    };

    function _deferMsg() {
        return 'سيُعاد التحميل بعد الإقامة | Actualisation reportée (prière en cours)';
    }
    function _toast() {
        try { if (typeof window._ucToast === 'function') window._ucToast(_deferMsg(), 'ok'); } catch (e) {}
    }

    var _retry = null;
    function _doReload(reason) {
        if (typeof _L === 'function') _L('RELOAD', 'FIRE', { reason: reason });
        try { location.reload(); } catch (e) {}
    }

    // API centrale : appelle-la à la place de tout location.reload() volontaire.
    window._ucDeferrableReload = function (reason) {
        reason = reason || 'unspecified';
        if (!window._ucReloadGuardActive()) { _doReload(reason); return; }
        if (typeof _L === 'function') _L('RELOAD', 'DEFERRED', { reason: reason });
        _toast();
        if (_retry) return;   // une re-tentative est déjà armée
        _retry = setInterval(function () {
            if (window._ucReloadGuardActive()) return;
            clearInterval(_retry); _retry = null;
            _doReload(reason + '_deferred');
        }, RETRY_MS);
    };

    // restartApplicationFunction (core m2body.js) = reload MANUEL de l'utilisateur :
    // drapeau #psFlagImageVertical (double-tap) / #psFlagImageHorizontal (tap,
    // onclick index.html) / lien #ucReloadLink. On le rend DIRECT et immédiat,
    // sans garde azan/iqama (cf. bloc de commentaire en tête de cette section).
    // Les reloads NON sollicités (sync config reçue, action distante 'reload')
    // n'appellent PAS restartApplicationFunction : ils appellent
    // window._ucDeferrableReload(...) directement depuis leurs handlers et
    // restent donc différés.
    if (typeof window.restartApplicationFunction === 'function') {
        window.restartApplicationFunction = function () {
            _doReload('manual_user_reload');
        };
    }

    if (typeof _L === 'function') _L('CUSTOM', 'INIT', { item: 'deferrableReload' });
})();

