// REPOSITIONNEMENT HORIZONTAL QUAND LA ROTATION DES AYATS EST DÉSACTIVÉE
// (demande explicite du 12/08/2026, mode horizontal uniquement)
// ─────────────────────────────────────────────────────────────────────────────
// Vérification demandée explicitement : applyHrLayoutFunction() (m2body.js
// ~7237) écrit directement prayerTimesContainerHorizontalElement.style.top à
// CHAQUE appel (58.3% si JS_DATA.ucHr5BoxesOnly==1, sinon 61.0%) -- appelée à
// l'init (m2body.js ~8766) ET à chaque bascule de fiveBoxesOnlyCheckbox/
// jomoaOnHrCheckbox (toggleHr5BoxesFunction/toggleJomoaOnHrScreenFunction).
// Sans monkey-patch, ces bascules écraseraient silencieusement notre
// décalage. On duplique donc son calcul de base (58.3/61.0) -- plus fiable
// qu'une valeur inline capturée une fois, qui peut changer sous nos pieds --
// et on repatche applyHrLayoutFunction pour réappliquer notre décalage juste
// après l'original. ayaDisplayContainerHorizontal, lui, n'est jamais touché
// par le coeur à l'exécution (aucune occurrence de `.style.top` dans
// m2body.js pour cet id) : pas de monkey-patch nécessaire pour celui-là.
function _hrAyaBaseTop() {
    return (typeof JS_DATA !== 'undefined' && JS_DATA.ucHr5BoxesOnly == 1) ? 58.3 : 61.0;
}
var UC_AYA_HR_SHIFT_UP = 4;   // points de %, ajustable
// Écran 720p plein écran (box bas de gamme, window.innerHeight == hauteur
// réelle de l'écran en WebView plein écran) : décalage supplémentaire
// (demande explicite du 13/08/2026) -- s'ajoute à UC_AYA_HR_SHIFT_UP
// uniquement quand la rotation des ayats est déjà désactivée (shift != 0).
//
// Calibré le 13/08/2026 par mesure empirique réelle sur la box (pas deviné) :
// un bug caché (cf. commentaire de _applyHrAyaRotationLayout ci-dessous --
// certains modes ont leur propre `top: ...% !important` qui battait notre
// style inline) faisait qu'AUCUN décalage n'avait jamais d'effet visuel réel
// avant le correctif "setProperty(...,'important')". Une fois corrigé, un
// 1er calibrage (extra=3, 7% total) mesuré contre #marqueeTextHorizontal
// donnait +17.5px -- mais cet élément était VIDE (largeur/hauteur 0) au
// moment du test : le texte réellement affiché en bas est
// #hadithDisplayHorizontal (même ancre bottom:1.9%, mais height:auto au lieu
// d'une hauteur fixe -- style1.css core -- donc son bord haut n'est PAS à la
// même position que celui, fixe, de marqueeContainerHorizontal). Contre le
// bon élément, 7% ne laissait que +14.0px, jugé encore trop juste (chevauchement
// perçu réel signalé par l'utilisateur). Nouveau balayage contre
// #hadithDisplayHorizontal :
//   0% → -36.4px   4% → -7.6px   6% → +6.8px   7% → +14.0px
//   8% → +21.2px   9% → +28.4px (retenu)   10% → +35.6px   14% → +64.4px
// 9% total retenu (marge confortable) → extra = 9 - 4(base) = 5.
var UC_AYA_HR_SHIFT_UP_720P_EXTRA = 5;
// window.isHorizontalOrientation n'existe PAS (vérifié en test réel sur
// boîtier, 12/08/2026 : typeof window.isHorizontalOrientation === 'undefined')
// -- la variable du coeur (m2body.js ~4050, assignation sans var/let/const)
// vit dans une fermeture qui n'expose rien sur window, même piège que les
// `const` documentés dans Common Pitfalls (CLAUDE.md). On reproduit donc
// exactement le calcul du coeur plutôt que de dépendre de cette variable.
function _ucIsHorizontalOrientation() {
    var h = (window.innerHeight < window.innerWidth);
    if (h && typeof JS_DATA !== 'undefined' && JS_DATA.ucForcedVertical > 0) h = false;
    return h;
}
function _applyHrAyaRotationLayout() {
    if (!_ucIsHorizontalOrientation()) return;
    var aya = document.getElementById('ayaDisplayContainerHorizontal');
    var msg = document.getElementById('messageDisplayContainerHorizontal');
    var tbl = document.getElementById('prayerTimesContainerHorizontal');
    var shift = (JS_CUSTOM.ucAyaRotationEnabled == 1) ? 0 : UC_AYA_HR_SHIFT_UP;
    if (shift && window.innerHeight <= 720) shift += UC_AYA_HR_SHIFT_UP_720P_EXTRA;
    // BUG RÉEL TROUVÉ EN TEST (13/08/2026, sur box réelle -- vérifié via
    // getComputedStyle/getBoundingClientRect, pas juste le style inline) :
    // certains modes (au moins 4 et 6) ont leur PROPRE règle
    // `#mainHorizontalContainer[data-layout-mode="X"] #prayerTimesContainerHorizontal/
    // #ayaDisplayContainerHorizontal { top: ...% !important; }` (custom.css).
    // Un `!important` de feuille de style bat un style inline SANS
    // !important, quel que soit son ordre d'application -- notre décalage ne
    // s'appliquait donc JAMAIS visuellement sur ces modes, ni aujourd'hui ni
    // avant (bug préexistant au 12/08/2026, pas introduit aujourd'hui).
    // Fix : poser notre style inline EN !important aussi (gagne alors sur la
    // spécificité, seule départageuse une fois les deux à égalité
    // d'importance) ; le retirer entièrement (au lieu d'une chaîne vide) au
    // repos pour laisser la règle de mode reprendre la main normalement.
    if (aya) {
        if (shift) aya.style.setProperty('top', (40.5 - shift) + '%', 'important');
        else aya.style.removeProperty('top');
    }
    // messageDisplayContainerHorizontal (annonces admin) partage la même
    // position de base que ayaDisplayContainerHorizontal (40.5%, style1.css
    // core) -- les deux occupent le même emplacement en alternance (verset OU
    // message, jamais les deux). Oublié dans le 1er passage (13/08/2026) :
    // ayaDisplayContainerHorizontal se décalait mais pas lui. Un simple même-
    // décalage-que-aya ne suffit PAS ici (vérifié par calcul géométrique
    // réel, 13/08/2026, demande explicite : "au milieu entre l'horloge et le
    // tableau") : appliquer le même % laisse le message notablement plus
    // proche de l'horloge que du tableau, pas centré. Calcul dynamique donc,
    // à partir des positions réellement mesurées (robuste à la résolution,
    // contrairement à un pourcentage fixe deviné) : centre le conteneur
    // message au milieu du vrai espace vertical entre le bas de l'horloge
    // (fullClockContainerHorizontal) et le haut du tableau déjà décalé.
    // messageContainerVertical (nom core trompeur, pointe sur ce même id)
    // est aussi réinitialisé en dur à '40.5%' par closeFullScreenCounterFunction
    // (déjà patché plus bas) -- recalculé à chaque appel, pas figé une fois.
    if (msg) {
        if (shift) {
            var clockEl = document.getElementById('fullClockContainerHorizontal');
            var clockBottomPx = clockEl ? clockEl.getBoundingClientRect().bottom : null;
            var tblTopPx = (_hrAyaBaseTop() - shift) / 100 * window.innerHeight;
            if (clockBottomPx != null) {
                var msgHeightPx = msg.getBoundingClientRect().height || (0.24 * window.innerHeight);
                var midPx = (clockBottomPx + tblTopPx) / 2;
                var msgTopPct = (midPx - msgHeightPx / 2) / window.innerHeight * 100;
                msg.style.setProperty('top', msgTopPct + '%', 'important');
            } else {
                msg.style.setProperty('top', (40.5 - shift) + '%', 'important');
            }
        } else {
            msg.style.removeProperty('top');
        }
    }
    if (tbl) {
        if (shift) tbl.style.setProperty('top', (_hrAyaBaseTop() - shift) + '%', 'important');
        else tbl.style.removeProperty('top');
    }
    _fixHrTableOverlap(shift);
}
// TOUT le tableau des prières (prayerTimesContainerHorizontal), pas
// seulement prayerCellAsrHorizontal -- correction demandée le 17/08/2026
// (boîtier 720p) : HmtALT3 (icône tirée à top: var(--mt7) = -13% au-dessus
// de prayerCellAsrHorizontal sur les thèmes cadre pb.png/pb6.png, modes 4/6,
// cf. custom.css) chevauche visuellement le texte affiché juste au-dessus
// (verset OU message admin, même emplacement, jamais les deux en même
// temps) une fois le tableau remonté par le décalage ci-dessus (ex. message
// "TAWKIT.NET - تطبيق مجاني" contre HmtALT3, capture écran réelle fournie
// par l'utilisateur). Un 1er correctif ne déplaçait que HmtALT3 seule,
// rejeté ("n'importe quoi") ; un 2e ne déplaçait que prayerCellAsrHorizontal
// seule (colonne Asr décalée hors alignement des 5 autres colonnes),
// également rejeté -- ici on redescend TOUT le tableau (mêmes 6 colonnes
// ensemble, alignement de ligne intact).
// Mesure réelle sur boîtier (CDP distant, pas headless) : dégager
// ENTIÈREMENT le haut demande ~100px, alors que la marge totale disponible
// avant hadithDisplayHorizontal/marqueeContainerHorizontal n'est que
// d'~28px -- impossible de satisfaire les deux à la fois avec ce seul
// levier (tableau entier). Compromis EXPLICITE choisi par l'utilisateur
// (17/08/2026, après vérification des chiffres réels) : combler la MOITIÉ
// du besoin, tout en ne descendant jamais sous une marge basse minimale de
// secours -- réduit nettement le chevauchement (sans le supprimer
// entièrement) tout en gardant toujours quelques px vers le bas.
function _fixHrTableOverlap(shift) {
    var tbl  = document.getElementById('prayerTimesContainerHorizontal');
    var hmt3 = document.getElementById('HmtALT3');
    if (!tbl || !hmt3 || !shift) return;   // !shift : tbl.style.top déjà réinitialisé juste au-dessus, rien à ajouter
    // Repart TOUJOURS du top "propre" (sans px supplémentaire) avant de
    // mesurer -- indispensable pour rester idempotent : cette fonction est
    // rappelée en boucle (chaque tick horloge ET à chaque changement du
    // texte observé plus bas) ; sans ce reset, un appel mesure sa PROPRE
    // correction précédente comme "position actuelle" et calcule un delta
    // erroné à chaque nouvel appel au lieu de rester stable sur un même
    // contenu.
    var baseTopPct = _hrAyaBaseTop() - shift;
    tbl.style.setProperty('top', baseTopPct + '%', 'important');

    var TOP_MARGIN_PX = 6;            // marge mini à garder sous le texte au-dessus
    var BOTTOM_MARGIN_FLOOR_PX = 3;   // filet de sécurité absolu envers hadith/marquee -- jamais sous ce seuil, même au compromis 50%

    var hmtTop = hmt3.getBoundingClientRect().top;
    var neededPush = 0;
    // Ces deux blocs sont masqués via style.visibility (showElementFunction/
    // hideElementByIdFunction, m2body.js), PAS display:none -- un élément en
    // visibility:hidden garde sa taille/position en getBoundingClientRect(),
    // donc le test largeur/hauteur seul ne suffit pas à détecter "pas affiché
    // actuellement" : il faut aussi lire la visibilité réelle du conteneur.
    [
        { textId: 'messageTextDisplayHorizontal', containerId: 'messageDisplayContainerHorizontal' },
        { textId: 'ayaTextDisplayHorizontal',      containerId: 'ayaDisplayContainerHorizontal' }
    ].forEach(function(pair) {
        var el = document.getElementById(pair.textId);
        var container = document.getElementById(pair.containerId);
        if (!el || !container) return;
        if (getComputedStyle(container).visibility === 'hidden') return;
        var r = el.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) return;   // pas affiché actuellement
        var overlapPx = (r.bottom + TOP_MARGIN_PX) - hmtTop;
        if (overlapPx > neededPush) neededPush = overlapPx;
    });
    if (neededPush <= 0) return;

    var desiredPush = neededPush / 2;   // compromis 50% explicite (cf. commentaire ci-dessus)

    var tblBottom = tbl.getBoundingClientRect().bottom;
    var maxAllowedPush = 0;
    var anyBottomRef = false;
    ['hadithDisplayHorizontal', 'marqueeContainerHorizontal'].forEach(function(id) {
        var el = document.getElementById(id);
        if (!el) return;
        var r = el.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) return;
        var room = (r.top - BOTTOM_MARGIN_FLOOR_PX) - tblBottom;
        if (!anyBottomRef || room < maxAllowedPush) maxAllowedPush = room;
        anyBottomRef = true;
    });
    if (!anyBottomRef || maxAllowedPush < 0) maxAllowedPush = 0;

    var applied = Math.min(desiredPush, maxAllowedPush);
    if (applied > 0) {
        tbl.style.setProperty('top', 'calc(' + baseTopPct + '% + ' + applied + 'px)', 'important');
    }
}
// Le texte du message admin change indépendamment des points de déclenchement
// ci-dessus (showMessagePopupFunction, m2body.js, ne rappelle pas
// _applyHrAyaRotationLayout) -- observe donc aussi directement son contenu,
// même idiome que _installAyaRotationFilter un peu plus bas dans ce fichier.
(function _installHrTableOverlapWatcher() {
    var msgEl = document.getElementById('messageTextDisplayHorizontal');
    if (!msgEl) return;
    var _observer = new MutationObserver(function() {
        var shift = (JS_CUSTOM.ucAyaRotationEnabled == 1) ? 0 : UC_AYA_HR_SHIFT_UP;
        if (shift && window.innerHeight <= 720) shift += UC_AYA_HR_SHIFT_UP_720P_EXTRA;
        _fixHrTableOverlap(shift);
    });
    _observer.observe(msgEl, { childList: true, characterData: true, subtree: true });
})();
(function _patchApplyHrLayoutForAyaRotation() {
    var _orig = window.applyHrLayoutFunction;
    if (typeof _orig !== 'function') return;
    window.applyHrLayoutFunction = function () {
        _orig.apply(this, arguments);
        _applyHrAyaRotationLayout();
    };
})();
// closeFullScreenCounterFunction() (m2body.js ~1836, via la variable
// core mal nommée ayaContainerVertical qui pointe en fait sur
// ayaDisplayContainerHorizontal) écrit en dur `.style.top = '40.5%'` à
// chaque fermeture du compteur plein écran -- appelé très régulièrement
// (fin de chaque compte à rebours iqama), ça écrasait silencieusement notre
// décalage à chaque cycle. Trouvé en vérifiant explicitement TOUS les writers
// core de `.style.top` sur ces éléments (grep ciblé, 13/08/2026) : le tableau
// (prayerTimesContainerHorizontalElement) n'a qu'UN SEUL writer (déjà patché
// ci-dessus), mais ce second writer sur le conteneur ayats n'était pas
// couvert. showIqamaCounter() (m2body.js ~2980) pose aussi '11%' sur ce même
// élément, mais volontairement -- position dédiée au mode plein écran actif,
// non touchée ici.
(function _patchCloseFullScreenCounterForAyaRotation() {
    var _orig = window.closeFullScreenCounterFunction;
    if (typeof _orig !== 'function') return;
    window.closeFullScreenCounterFunction = function () {
        _orig.apply(this, arguments);
        _applyHrAyaRotationLayout();
    };
})();
_applyHrAyaRotationLayout();

// Garantit 10 slots récitateurs même si le cache est ancien ou incomplet
// (format ajouté ici : backfill 'mp3' pour les configs déjà stockées avant
// l'introduction du choix de format par récitateur)
(function normalizeReciters() {
    const base = Array.isArray(JS_CUSTOM.ucReciters) ? JS_CUSTOM.ucReciters : [];
    JS_CUSTOM.ucReciters = Array.from({length:10}, function(_,i) {
        var defaults = {enabled:1, name:'', dir:'C'+(i+1), format:'mp3'};
        return base[i] ? Object.assign(defaults, base[i], {format: base[i].format || 'mp3'}) : defaults;
    });
})();

// ── Récitateurs dynamiques (USB / téléchargés) ─────────────────────────────
// Les 10 premiers slots (index 0-9) restent le format historique, fixe,
// configurable manuellement dans les réglages (server HTTP externe, mp3/ogg).
// Les récitateurs "device" (présents nativement sur l'appareil — importés
// depuis une clé USB ou téléchargés depuis le cloud) sont ajoutés à la SUITE
// du tableau, à des index positifs ≥10. Tous les mécanismes existants
// (forEach, indexOf, accès [idx]) restent inchangés : seuls _buildQPUrl()
// (ajout d'une branche source==='device') et initQuranRecitersUI()/
// refreshQuranServerUI() (slice aux 10 premiers, réglages = legacy only)
// ont besoin d'être adaptés. normalizeReciters() ci-dessus tronque déjà le
// tableau à 10 à chaque chargement : _syncDeviceReciters() peut donc
// ajouter les entrées fraîches sans risque de croissance non bornée, même
// si saveCustomSettingsFunction() persiste le tableau entier (les entrées
// au-delà de 10 sont simplement ré-ignorées par normalizeReciters() au
// prochain chargement, puis régénérées ici).
var UC_RECITERS_STATIC_COUNT = 10;

// Résout le nom affiché d'un récitateur "device" renvoyé par le natif
// (ReciterManager.listReciters) : soit une simple chaîne (rétro-compat,
// meta.json à l'ancien format {"name":"..."}), soit un objet par langue
// ex. {"AR":"...","FR":"...","EN":"...","TR":"...","ID":"..."} — on choisit
// alors la langue courante de l'interface (JS_DATA.ucLangNOW), puis on
// retombe sur AR, puis FR, puis la première valeur disponible, puis l'id
// du dossier en dernier recours (ex. meta.json absent/corrompu).
function _localizedReciterName(nameVal, fallbackId) {
    if (!nameVal) return fallbackId;
    if (typeof nameVal === 'string') return nameVal || fallbackId;
    if (typeof nameVal === 'object') {
        var lang = _ucLang();
        if (nameVal[lang]) return nameVal[lang];
        if (nameVal.AR) return nameVal.AR;
        if (nameVal.FR) return nameVal.FR;
        var firstKey = Object.keys(nameVal)[0];
        if (firstKey && nameVal[firstKey]) return nameVal[firstKey];
    }
    return fallbackId;
}

// DIAGNOSTIC : "reason" identifie qui a déclenché ce resync (page_load,
// remove_reciter, usb_import_done, download_done...) — combiné au JSON brut
// renvoyé par le natif (SYNC_RAW), ça permet de savoir précisément quand/
// pourquoi un récitateur "device" apparaît/disparaît de la liste (cf. le
// total qui avait été vu fluctuer 11→10→11 dans un même test sans action
// utilisateur visible).
function _syncDeviceReciters(reason) {
    // Retire les anciens device-reciters déjà ajoutés à la fin (idempotent)
    JS_CUSTOM.ucReciters = JS_CUSTOM.ucReciters.slice(0, UC_RECITERS_STATIC_COUNT);
    if (!window.AndroidMobile || typeof window.AndroidMobile.listReciters !== 'function') {
        _L('RM','SYNC_NO_BRIDGE',{reason:(reason || 'unknown')});
        return;
    }
    var raw = '';
    var list;
    try {
        raw  = window.AndroidMobile.listReciters() || '[]';
        list = JSON.parse(raw);
    } catch(e) {
        _L('RM','SYNC_PARSE_ERROR',{reason:(reason || 'unknown'), error:e.message, raw:String(raw).slice(0,300)});
        list = [];
    }
    _L('RM','SYNC_RAW',{reason:(reason || 'unknown'), count:(Array.isArray(list) ? list.length : 0), raw:String(raw).slice(0,500)});
    list.forEach(function(r) {
        if (!r || !r.id || !r.trackCount) {
            _L('RM','SYNC_SKIP',{reason:(reason || 'unknown'), id:(r && r.id) || '?', trackCount:(r && r.trackCount) || 0});
            return;
        }
        JS_CUSTOM.ucReciters.push({
            enabled: 1,
            name:    _localizedReciterName(r.name, r.id),
            dir:     r.id,
            format:  'ogg',
            source:  'device'
        });
    });
    _L('RM','SYNC_DONE',{reason:(reason || 'unknown'), totalReciters:JS_CUSTOM.ucReciters.length,
        deviceCount:(JS_CUSTOM.ucReciters.length - UC_RECITERS_STATIC_COUNT)});
    // Box : republie la liste vers Supabase (l'admin distant la relit).
    // Différé : au 1er appel ('page_load') _ucPushRecitersSnapshot n'existe
    // pas encore (défini plus bas). Sans effet hors box (fonction absente).
    if (reason && reason !== 'page_load' && typeof window._ucPushRecitersSnapshot === 'function') {
        window._ucPushRecitersSnapshot('reciters_changed');
    }
}
_syncDeviceReciters('page_load');

(function normalizeQuranAutoStartDays() {
    [
        'ucStartQuranBeforeAzanFajrDays',
        'ucStartQuranBeforeAzanDohrDays',
        'ucStartQuranBeforeAzanAsrDays',
        'ucStartQuranBeforeAzanMgrbDays',
        'ucStartQuranBeforeAzanIshaDays'
    ].forEach(function(key) {
        let val = String(JS_CUSTOM[key] || '');
        if (!/^[01]{7}$/.test(val)) val = '1111111';
        JS_CUSTOM[key] = val;
    });
})();

// ── Migration Takbir : ancien modèle (ucTakbirEnabled/Mode/Delay/Duration) → M0/M1
(function _migrateTakbirSettings() {
    var stored = localStorage.getItem('JS_DATA_CUSTOM');
    if (!stored) return;
    var obj;
    try { obj = JSON.parse(stored); } catch(e) { return; }
    if (!('ucTakbirEnabled' in obj)) return;  // déjà migré
    var hasOwn = Object.prototype.hasOwnProperty;
    var en  = (obj.ucTakbirEnabled  == 1);
    var mo  = (obj.ucTakbirMode     == 1) ? 1 : 0;
    var del = parseInt(obj.ucTakbirDelay,    10) || 60;
    var dur = parseInt(obj.ucTakbirDuration, 10);
    if (isNaN(dur)) dur = 300;
    if (mo === 0) {
        if (!hasOwn.call(obj, 'ucTakbirM0Enabled'))  JS_CUSTOM.ucTakbirM0Enabled  = en ? 1 : 0;
        if (!hasOwn.call(obj, 'ucTakbirM0Delay'))    JS_CUSTOM.ucTakbirM0Delay    = del;
        if (!hasOwn.call(obj, 'ucTakbirM0Duration')) JS_CUSTOM.ucTakbirM0Duration = dur;
    } else {
        if (!hasOwn.call(obj, 'ucTakbirM1Enabled'))  JS_CUSTOM.ucTakbirM1Enabled  = en ? 1 : 0;
        if (!hasOwn.call(obj, 'ucTakbirM1Delay'))    JS_CUSTOM.ucTakbirM1Delay    = del;
        if (!hasOwn.call(obj, 'ucTakbirM1Duration')) JS_CUSTOM.ucTakbirM1Duration = dur;
    }
    _TAKBIR_LEGACY_KEYS.forEach(function(key) {
        delete obj[key];
    });
    obj.ucTakbirM0Enabled  = JS_CUSTOM.ucTakbirM0Enabled;
    obj.ucTakbirM0Delay    = JS_CUSTOM.ucTakbirM0Delay;
    obj.ucTakbirM0Duration = JS_CUSTOM.ucTakbirM0Duration;
    obj.ucTakbirM1Enabled  = JS_CUSTOM.ucTakbirM1Enabled;
    obj.ucTakbirM1Delay    = JS_CUSTOM.ucTakbirM1Delay;
    obj.ucTakbirM1Duration = JS_CUSTOM.ucTakbirM1Duration;
    localStorage.setItem('JS_DATA_CUSTOM', JSON.stringify(obj));
    console.log('[TAKBIR] Migration anciens paramètres → M0/M1 effectuée');
})();

// ── Migration "Coran avant azan" : ancien modèle (case Enabled séparée +
// délai en secondes toujours présent même si Enabled=0) → nouveau modèle
// (0 = désactivé, valeur en secondes en interne / minutes à l'affichage,
// cf. relookage en tableau jours x prières). Si l'utilisateur avait
// explicitement désactivé une prière (Enabled=0), la valeur numérique doit
// devenir 0 pour ne pas la réactiver par surprise après la mise à jour.
(function _migrateQuranAutoStartToMinutes() {
    var stored = localStorage.getItem('JS_DATA_CUSTOM');
    if (!stored) return;
    var obj;
    try { obj = JSON.parse(stored); } catch (e) { return; }
    var PAIRS = [
        ['ucStartQuranBeforeAzanFajrEnabled', 'ucStartQuranBeforeAzanFajr'],
        ['ucStartQuranBeforeAzanDohrEnabled', 'ucStartQuranBeforeAzanDohr'],
        ['ucStartQuranBeforeAzanAsrEnabled',  'ucStartQuranBeforeAzanAsr'],
        ['ucStartQuranBeforeAzanMgrbEnabled', 'ucStartQuranBeforeAzanMgrb'],
        ['ucStartQuranBeforeAzanIshaEnabled', 'ucStartQuranBeforeAzanIsha'],
        ['ucStartQuranBeforeAzanJomoaEnabled', 'ucStartQuranBeforeAzanJomoa']
    ];
    var hasOwn = Object.prototype.hasOwnProperty;
    var migrated = false;
    PAIRS.forEach(function (pair) {
        var enabledKey = pair[0], delayKey = pair[1];
        if (!hasOwn.call(obj, enabledKey)) return; // déjà migré (ou install neuve)
        if (obj[enabledKey] != 1) {
            obj[delayKey] = 0;
            JS_CUSTOM[delayKey] = 0;
        }
        delete obj[enabledKey];
        migrated = true;
    });
    if (migrated) {
        localStorage.setItem('JS_DATA_CUSTOM', JSON.stringify(obj));
        console.log('[QURAN_AUTOSTART] Migration Enabled -> 0=désactivé effectuée');
    }
})();

function saveCustomSettingsFunction() {
    localStorage.setItem('JS_DATA_CUSTOM', JSON.stringify(JS_CUSTOM));
}

// ── Détection APK Android (GeckoView) ────────────────────────────────────────
// Sur Android, la page tourne sous resource://android — on pose la classe
// 'uc-android' sur <html> pour permettre des ajustements CSS ciblés.
(function _detectAndroid() {
    if (location.protocol === 'resource:') {
        document.documentElement.classList.add('uc-android');
    }
})();



