// ═══════════════════════════════════════════════════════════════════════════
// SURCHARGE HORAIRES OFFICIELS (spec/data/<CC>/wtimes-<code>.js)
// ═══════════════════════════════════════════════════════════════════════════
// Le core (m1prime.js) charge toujours data/<CC>/wtimes-<code>.js via
// document.write, SYNCHRONE, avant meme que ce fichier (custom.js) ne
// s'execute -- impossible d'intercepter ce premier chargement sans toucher
// au core. A la place : une fois JS_TIMES deja rempli avec les valeurs core,
// on tente de charger EN PLUS spec/data/<CC>/wtimes-<code>.js -- EXACTEMENT
// le meme format ("var JS_TIMES = [...]"), donc s'il existe, son chargement
// REECRIT simplement window.JS_TIMES avec les valeurs officielles (source :
// tools/compare_affaires_religieuses.py, calendrier du ministere tunisien
// des Affaires Religieuses -- villes generees le 15/08/2026). Absence de ce
// fichier = cas normal (la grande majorite des villes n'ont pas de
// surcharge) -- l'erreur de chargement (onerror) est silencieuse, JS_TIMES
// core reste alors actif sans aucun changement de comportement.
(function _installOfficialWtimesOverride() {
    if (typeof JS_DATA === 'undefined' || !JS_DATA.ucNowCityCODE) return;
    var cc = (JS_DATA.ucNowCityCODE.split('.')[0] || '').toUpperCase();
    if (!cc) return;
    var cacheBust = (typeof appVersionNumber !== 'undefined') ? appVersionNumber : Date.now();
    var s = document.createElement('script');
    s.src = 'spec/data/' + cc + '/wtimes-' + JS_DATA.ucNowCityCODE + '.js?e=' + cacheBust;
    // BUG CONSTATE ET CORRIGE (17/08/2026, retour utilisateur -- console
    // Windows) : contrairement a _probeAndLoad/_tryLoad (memes sondes
    // "override optionnel" plus bas dans ce fichier), cette balise <script>
    // n'etait jamais marquee dataset.ucOptionalProbe -- le listener 'error'
    // global (plus bas, cf. "Sondes d'override optionnel") ne pouvait donc
    // pas la reconnaitre comme un miss normal et affichait un faux positif
    // rouge 🔴 [RES] SCRIPT load failed pour TOUTE ville sans surcharge
    // horaires officiels (la grande majorite, ex. Akouda) -- alors meme que
    // onerror ci-dessous geraient deja ce cas correctement (JS_TIMES core
    // inchange, aucun impact fonctionnel). Purement cosmetique (bruit
    // console trompeur), jamais un vrai echec.
    s.dataset.ucOptionalProbe = '1';
    s.onload = function() {
        if (typeof _L === 'function') {
            _L('CFG', 'OFFICIAL_WTIMES_OVERRIDE_APPLIED', { city: JS_DATA.ucNowCityCODE });
        }
        if (typeof calculateAndDisplayTimesFunction === 'function') {
            calculateAndDisplayTimesFunction();
        }
    };
    s.onerror = function() {
        // Pas de surcharge pour cette ville -- cas normal, rien a faire.
    };
    document.head.appendChild(s);
})();

// ── HISTORIQUE MULTI-MOSQUÉE (abonnement notifications cumulatif) ───────────
// Chaque mosque_id jamais sélectionné sur cet appareil est mémorisé dans
// localStorage (clé UC_MOSQUE_HISTORY, tableau JSON dédupliqué). Utilisé par
// _installOneSignalMosqueTag() ci-dessous pour poser un tag OneSignal PAR
// mosquée déjà choisie, afin que l'utilisateur continue de recevoir les
// notifications de toutes ses mosquées, même en étant actuellement connecté
// à une seule d'entre elles.
function _ucGetMosqueHistory() {
    try {
        var arr = JSON.parse(localStorage.getItem('UC_MOSQUE_HISTORY') || '[]');
        return Array.isArray(arr) ? arr : [];
    } catch(e) { return []; }
}
// Une mosquée anonyme n'a pas de mosque_id réel côté serveur (OneSignal tag,
// Supabase...) — elle ne doit jamais entrer dans l'historique de notifications
// (UC_MOSQUE_HISTORY), sans quoi elle apparaît à tort dans ucMosqueInfoNotifList
// / ucMosqueNotifList (panneau "Mes notifications").
function _ucIsAnonymousMosqueId(id) {
    if (!id || id === 'anonymous.generic') return true;
    var reg = window.MOSQUES_REGISTRY || {};
    return !!(reg[id] && reg[id]._UC_ANONYMOUS);
}
function _ucAddMosqueToHistory(id) {
    var hist = _ucGetMosqueHistory();
    if (id && !_ucIsAnonymousMosqueId(id) && hist.indexOf(id) === -1) {
        hist.push(id);
        try { localStorage.setItem('UC_MOSQUE_HISTORY', JSON.stringify(hist)); } catch(e) {}
    }
    return hist;
}
window._ucGetMosqueHistory      = _ucGetMosqueHistory;
window._ucAddMosqueToHistory    = _ucAddMosqueToHistory;
window._ucIsAnonymousMosqueId   = _ucIsAnonymousMosqueId;

// ── MOSQUÉES EN SOURDINE (opt-out de notifications par mosquée) ─────────────
// L'utilisateur peut choisir de ne plus recevoir les notifications d'une
// mosquée présente dans son historique, sans pour autant la retirer de
// l'historique (elle reste visible/réactivable dans le panneau de gestion
// "Mes notifications"). Liste stockée dans localStorage (clé UC_MOSQUE_MUTED,
// tableau JSON dédupliqué des mosque_id mis en sourdine).
function _ucGetMutedMosques() {
    try {
        var arr = JSON.parse(localStorage.getItem('UC_MOSQUE_MUTED') || '[]');
        return Array.isArray(arr) ? arr : [];
    } catch(e) { return []; }
}
function _ucIsMosqueMuted(id) {
    return _ucGetMutedMosques().indexOf(id) !== -1;
}
function _ucMuteMosque(id) {
    var muted = _ucGetMutedMosques();
    if (id && muted.indexOf(id) === -1) {
        muted.push(id);
        try { localStorage.setItem('UC_MOSQUE_MUTED', JSON.stringify(muted)); } catch(e) {}
    }
    return muted;
}
function _ucUnmuteMosque(id) {
    var muted = _ucGetMutedMosques();
    var idx = muted.indexOf(id);
    if (idx !== -1) {
        muted.splice(idx, 1);
        try { localStorage.setItem('UC_MOSQUE_MUTED', JSON.stringify(muted)); } catch(e) {}
    }
    return muted;
}
window._ucGetMutedMosques = _ucGetMutedMosques;
window._ucIsMosqueMuted   = _ucIsMosqueMuted;
window._ucMuteMosque      = _ucMuteMosque;
window._ucUnmuteMosque    = _ucUnmuteMosque;

// ── TAGS ONESIGNAL mosque_id / mosque_sub_<id> (bridge natif) ───────────────
// notify-mosque (Edge Function Supabase) cible désormais les push OneSignal
// EXCLUSIVEMENT par le tag mosque_sub_<id> (le legacy mosque_id = <id> a été
// retiré du ciblage côté serveur — phase de test, pas encore en prod).
// Deux appels posés ici, via le bridge natif MobileJsBridge :
//   1. setMosqueId(id)              → tag mosque_id = <id> (mosquée courante,
//      conservé à titre informatif/legacy uniquement, ne conditionne plus la
//      réception des notifications)
//   2. addMosqueSubscriptionTag(id) → tag mosque_sub_<id> = 1, posé pour
//      CHAQUE mosquée de l'historique NON mise en sourdine → permet de
//      recevoir les notifs de toutes les mosquées suivies, même après avoir
//      changé de mosquée active. Pour les mosquées mises en sourdine,
//      removeMosqueSubscriptionTag(id) est appelé à la place (nettoyage
//      idempotent : retire le tag s'il était déjà posé).
// Idempotent → safe à chaque chargement de page, y compris après
// _applyMosqueConfig() / changement de mosquée via le sélecteur (qui font
// tous les deux un location.reload()).
(function _installOneSignalMosqueTag() {
    if (typeof window.AndroidMobile === 'undefined') {
        return; // pas dans l'app Android (ex: test navigateur Chrome)
    }
    var _mosqueId = '';
    try { _mosqueId = localStorage.getItem('UC_MOSQUE_ID') || ''; } catch(e) {}

    if (!_mosqueId) {
        // Aucune mosquée choisie encore (sélecteur va s'afficher) : rien à tagger.
        console.log('[ONESIGNAL] Aucun UC_MOSQUE_ID en localStorage — tag non posé');
        return;
    }

    if (typeof window.AndroidMobile.setMosqueId === 'function') {
        window.AndroidMobile.setMosqueId(_mosqueId);
        console.log('[ONESIGNAL] Tag mosque_id posé (informatif) : ' + _mosqueId);
    }

    var _hist  = _ucAddMosqueToHistory(_mosqueId);
    var _muted = _ucGetMutedMosques();
    var _added = [], _removed = [];
    _hist.forEach(function(id) {
        if (_muted.indexOf(id) !== -1) {
            if (typeof window.AndroidMobile.removeMosqueSubscriptionTag === 'function') {
                window.AndroidMobile.removeMosqueSubscriptionTag(id);
                _removed.push(id);
            }
        } else if (typeof window.AndroidMobile.addMosqueSubscriptionTag === 'function') {
            window.AndroidMobile.addMosqueSubscriptionTag(id);
            _added.push(id);
        }
    });
    if (_added.length)   console.log('[ONESIGNAL] Tags abonnement posés : '  + _added.join(', '));
    if (_removed.length) console.log('[ONESIGNAL] Tags abonnement retirés (sourdine) : ' + _removed.join(', '));
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── TAG ONESIGNAL mosque_admin_<id> (ciblage EXCLUSIF des responsables) ──────
// Posé UNIQUEMENT sur les téléphones dont le PIN d'administration à distance a
// été validé côté serveur (rapid-service → 200). Sert au ciblage des alertes
// de surveillance des modules Shelly (box → admin, cf. _installLightWatchdog
// plus bas + rapid-service mode "light_watchdog_alert") : contrairement à
// mosque_sub_<id> (tous les fidèles abonnés), seuls les responsables reçoivent
// ces alertes. Plusieurs téléphones admin par mosquée sont supportés.
//
// Persistance : localStorage.UC_ADMIN_PUSH_FOR = { "<mosque_id>": <ts_ms>, ... }.
// TTL 90 jours : chaque validation de PIN ré-arme les 90 j ; un responsable qui
// ne ré-administre plus jamais cesse d'être notifié au bout de 90 j.
// Volontairement INDÉPENDANT de la mosquée courante (comme mosque_sub_<id> via
// UC_MOSQUE_HISTORY) : un admin peut piloter la mosquée A depuis un téléphone
// affichant la mosquée B.
var _UC_ADMIN_PUSH_KEY = 'UC_ADMIN_PUSH_FOR';
var _UC_ADMIN_PUSH_TTL_MS = 90 * 24 * 60 * 60 * 1000;

function _ucReadAdminPushMap() {
    try {
        var o = JSON.parse(localStorage.getItem(_UC_ADMIN_PUSH_KEY) || '{}');
        return (o && typeof o === 'object') ? o : {};
    } catch (e) { return {}; }
}
function _ucWriteAdminPushMap(o) {
    try { localStorage.setItem(_UC_ADMIN_PUSH_KEY, JSON.stringify(o || {})); } catch (e) {}
}

// Appelé après un 200 de rapid-service (PIN validé serveur) dans
// _sendRemoteAction / _submit. Arme / ré-arme le tag admin pour cette mosquée.
function _ucArmMosqueAdminPush(mosqueId) {
    if (!mosqueId || _ucIsAnonymousMosqueId(mosqueId)) return;
    var map = _ucReadAdminPushMap();
    map[mosqueId] = Date.now();
    _ucWriteAdminPushMap(map);
    if (window.AndroidMobile && typeof window.AndroidMobile.addMosqueAdminTag === 'function') {
        try { window.AndroidMobile.addMosqueAdminTag(mosqueId); } catch (e) {}
    }
    _L('REMOTE_ADMIN', 'ADMIN_PUSH_ARMED', { mosque_id: mosqueId });
}
window._ucArmMosqueAdminPush = _ucArmMosqueAdminPush;

// IIFE idempotente (à chaque chargement) : ré-affirme les tags admin encore
// valides, purge ceux expirés (TTL).
(function _installOneSignalMosqueAdminTag() {
    if (typeof window.AndroidMobile === 'undefined') return;
    var map = _ucReadAdminPushMap();
    var now = Date.now();
    var _armed = [], _expired = [], _changed = false;
    Object.keys(map).forEach(function (id) {
        var ts = map[id];
        if (typeof ts === 'number' && (now - ts) <= _UC_ADMIN_PUSH_TTL_MS) {
            if (typeof window.AndroidMobile.addMosqueAdminTag === 'function') {
                try { window.AndroidMobile.addMosqueAdminTag(id); _armed.push(id); } catch (e) {}
            }
        } else {
            if (typeof window.AndroidMobile.removeMosqueAdminTag === 'function') {
                try { window.AndroidMobile.removeMosqueAdminTag(id); } catch (e) {}
            }
            delete map[id];
            _expired.push(id);
            _changed = true;
        }
    });
    if (_changed) _ucWriteAdminPushMap(map);
    _L('CUSTOM', 'INIT', { item: 'oneSignalMosqueAdminTag', armed: _armed.join(',') || '-', expired: _expired.join(',') || '-' });
})();
