// ── PATCH checkInternetConnectionFunction ────────────────────────────────────
// Problème : la fonction core (m2body.js) sonde https://www.tawkit.net/version/
// (const versionCheckUrl, index.html) — ce serveur timeout régulièrement
// (ERR_CONNECTION_TIMED_OUT en console), ce qui fait passer l'indicateur
// internet au rouge alors que la connexion est bien active.
// Solution : remplacer la cible par le projet Supabase (tjmjmlzwzebocfdmifrg,
// mêmes URL/clé anon déjà utilisées partout ailleurs dans ce fichier), plus
// fiable/rapide que tawkit.net pour une simple sonde de connectivité — même
// mécanique que le core (fetch + response.ok), simplement retargetée.
(function _patchInternetCheck() {
    if (typeof checkInternetConnectionFunction !== 'function') return;
    var _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
               || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
               || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';
    var CHECK_TIMEOUT_MS = 6000;

    // Sonde générique : GET (jamais HEAD -- moins fiable via certains
    // proxys/CDN, cf. retour utilisateur 01/08/2026 : étoile rouge alors que
    // la connexion était bonne) avec timeout explicite (AbortController) --
    // sans lui, un hôte qui ne répond pas peut faire pendre le fetch bien
    // au-delà de l'intervalle de re-sondage du core.
    function _probe(url, opts) {
        var hasAbort = (typeof AbortController !== 'undefined');
        var controller = hasAbort ? new AbortController() : null;
        var timer = hasAbort ? setTimeout(function () { controller.abort(); }, CHECK_TIMEOUT_MS) : null;
        var fetchOpts = { method: (opts && opts.method) || 'GET', headers: (opts && opts.headers) || {} };
        if (hasAbort) fetchOpts.signal = controller.signal;
        return fetch(url, fetchOpts).then(function (r) {
            if (timer) clearTimeout(timer);
            return !!r.ok;
        }).catch(function () {
            if (timer) clearTimeout(timer);
            return false;
        });
    }

    window.checkInternetConnectionFunction = function() {
        if (JS_DATA.ucVerifyInternet == 0) return;
        // navigator.onLine n'est PAS fiable sur WebView Chrome 91 après un
        // changement de réseau (reste false alors que tout marche) : on ne s'y
        // fie que s'il dit "en ligne", jamais pour couper. La vraie source
        // reste la sonde HTTP ci-dessous (Supabase, repli GitHub) -- si les
        // deux échouent, l'app ne peut réellement atteindre personne
        // (résolveur DNS cassé inclus), donc rouge légitime.
        if (window.navigator.onLine === false
            && !(window.AndroidMobile && typeof window.AndroidMobile.getNetworkInfo === 'function')) {
            dolog('___navigator_NOT_onLine');
            setInternetStatus(false);
            return;
        }
        // Un seul fournisseur peut ponctuellement échouer (incident côté
        // Supabase, pile réseau/TLS d'un WebView ancien sur certains
        // boîtiers...) sans que la connexion internet soit réellement
        // absente -- Supabase d'abord (déjà utilisé partout ailleurs dans ce
        // fichier), GitHub en secours seulement si Supabase échoue. "Hors
        // ligne" uniquement si les deux échouent.
        _probe(_SB_URL + '/rest/v1/mosques?select=mosque_id&limit=1', {
            headers: { apikey: _SB_KEY, Authorization: 'Bearer ' + _SB_KEY }
        }).then(function (ok) {
            if (ok) { setInternetStatus(true); return; }
            dolog('supabase_probe_failed_trying_github');
            _probe('https://api.github.com/').then(function (ok2) {
                if (!ok2) dolog('github_probe_failed_too');
                setInternetStatus(ok2);
            });
        });
    };
    console.log('[CFG] patch checkInternetConnectionFunction (Supabase+GitHub, GET, timeout) installé');
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── GARDE-FOU : heure fixe de la jomoa jamais avant le Dohr du jour ──────────
// Règle métier : si JS_DATA.ucJomoaFixedTime (heure fixe choisie pour l'azan
// de la jomoa) est ANTÉRIEURE à l'azan du Dohr prévu ce jour-là, on force la
// jomoa à l'heure du Dohr (jamais l'inverse — le Dohr n'est jamais retardé).
//
// Piège (core, m2body.js, calculateAndDisplayTimesFunction, bloc if(isFriday)) :
// le vendredi, prayerTimesMinutesObject.DOHR est ÉCRASÉ par le core avec
// l'heure de la jomoa elle-même, via UN SEUL garde : le bloc
// "if(JS_DATA.ucJomoaFixedTime !== '') { ...; dohrTimeStr = jomoaFixedTime; }"
// — donc INUTILISABLE comme référence le jour où on en a justement besoin
// (comparaison circulaire, toujours "égale"). Solution : une "sonde" —
// rejouer le calcul BRUT (fonction core originale, non wrappée) avec
// ucJomoaFixedTime TEMPORAIREMENT vidé ('') pour désactiver ce seul garde le
// temps d'un appel : le core calcule alors le VRAI Dohr du jour (y compris un
// vendredi) sans jamais dupliquer sa logique (JS_TIMES/WCSV, ajustements été/
// force-heure, etc. — tout reste calculé par le core lui-même). La valeur
// d'origine est restaurée aussitôt après.
//
// (Une première version de cette garde mémorisait le dernier Dohr connu un
// jour non-vendredi — mais échouait donc au tout premier vendredi rencontré,
// faute de référence précédente, cf. retour utilisateur. La sonde fonctionne
// dès le premier jour, sans historique.)
//
// Point d'ancrage unique : calculateAndDisplayTimesFunction (déjà monkey-
// patchée une fois plus haut pour la mention de version) — recalculée après
// CHAQUE écriture de ucJomoaFixedTime, quelle que soit son origine (dialog
// éditJomoaFixedTimeFunction, _applyMosqueConfig, synchro Supabase admin),
// donc ce point unique couvre tous les chemins sans avoir à les dupliquer.
(function _installJomoaDohrGuard() {
    if (typeof calculateAndDisplayTimesFunction !== 'function') return;
    if (typeof getNextFridayPrayerTime !== 'function') return;

    function _toMinutes(hhmm) {
        var parts = String(hhmm).split(':');
        return (parseInt(parts[0], 10) || 0) * 60 + (parseInt(parts[1], 10) || 0);
    }
    function _toHHmm(totalMinutes) {
        var h = Math.floor(totalMinutes / 60) % 24;
        var m = totalMinutes % 60;
        return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
    }

    // ── TRACE TEMPORAIRE (désactivée — réactiver en cas de besoin) ─────────
    function _dbg() {}
    // ─────────────────────────────────────────────────────────────────────

    // Référence : Dohr "brut" du PROCHAIN vendredi, calculé exactement comme le
    // fait le core en mode AUTO (m2body.js ~3411-3424) — via getNextFridayPrayerTime,
    // avec le même décalage ucDohrXminutesAsr le cas échéant. Ne dépend PAS du
    // jour actuel : contrairement à une 1ère version de cette garde, restreinte
    // à isFriday (donc inactive tout le reste de la semaine, alors que l'heure
    // de la jomoa est affichée en permanence, cf. _patchJomoaDisplay).
    //
    // Piège #2 (celui-ci propre à notre garde, pas au core) : getNextFridayPrayerTime
    // renvoie l'heure BRUTE du tableau (JS_TIMES/WCSV), qui n'inclut PAS l'ajustement
    // manuel du Dohr (boutons +/-, JS_DATA.ucAthanMinutesDOHR) — le core l'applique
    // à dohrTimeStr le jour même (m2body.js ~3300) mais jamais à sa propre sonde
    // "prochain vendredi", donc getNextFridayPrayerTime(2) seul reste désynchronisé
    // du VRAI Dohr affiché dès qu'on touche les boutons +/- du Dohr. On réplique donc
    // ici cet ajustement (absent du core sur ce point précis) pour que la garde
    // compare toujours contre le Dohr réellement affiché, pas contre sa valeur brute.
    function _getNextFridayDohr() {
        if (JS_DATA.ucDohrXminutesAsr > 0 && !(JS_DATA.ucWcsvIsActive == 1)) {
            return adjustAthanTime(getNextFridayPrayerTime(3), -(JS_DATA.ucDohrXminutesAsr));
        }
        if (!(JS_DATA.ucWcsvIsActive == 1)) {
            return adjustAthanTime(getNextFridayPrayerTime(2), JS_DATA.ucAthanMinutesDOHR);
        }
        return getNextFridayPrayerTime(2);
    }

    var _guardRunning = false;
    var _origCalc = window.calculateAndDisplayTimesFunction;

    window.calculateAndDisplayTimesFunction = function() {
        if (_guardRunning) { _origCalc.apply(this, arguments); return; }

        var fixed = JS_DATA.ucJomoaFixedTime;
        var needsGuard = !!fixed && fixed !== 'AUTO' && fixed.length === 5;

        _dbg('entry', { now: new Date().toString(), ucJomoaFixedTime: fixed, needsGuard: needsGuard });

        if (!needsGuard) {
            _origCalc.apply(this, arguments);
            return;
        }

        var nextFridayDohr = _getNextFridayDohr();
        var realDohrMin = (typeof nextFridayDohr === 'string' && nextFridayDohr.indexOf(':') > -1)
            ? _toMinutes(nextFridayDohr) : 0;

        _dbg('probe', { nextFridayDohr: nextFridayDohr, realDohrMin: realDohrMin, fixed: fixed, fixedMin: _toMinutes(fixed) });

        // Correction si nécessaire.
        if (realDohrMin > 0 && _toMinutes(fixed) < realDohrMin) {
            var forced = _toHHmm(realDohrMin);
            JS_DATA.ucJomoaFixedTime = forced;
            if (typeof saveSettingsToStorageFunction === 'function') saveSettingsToStorageFunction();
            if (typeof updateFixedTimesDisplayFunction === 'function') updateFixedTimesDisplayFunction();
            _L('CFG', 'JOMOA_DOHR_GUARD', { was: fixed, forced: forced });
            _dbg('decision', { corrected: true, was: fixed, forced: forced });
        } else {
            _dbg('decision', { corrected: false, kept: fixed });
        }

        // Calcul final (réel), affichage cohérent avec la valeur (corrigée ou non).
        _guardRunning = true;
        try { _origCalc.apply(this, arguments); } finally { _guardRunning = false; }

        _dbg('final', {
            ucJomoaFixedTime: JS_DATA.ucJomoaFixedTime,
            moduleJomoaFixedTime: (typeof jomoaFixedTime !== 'undefined' ? jomoaFixedTime : 'n/a'),
            domHorizontal: (document.getElementById('jomoaTimeDisplayHorizontal') || {}).innerHTML,
            domVertical:   (document.getElementById('jomoaTimeDisplayVertical')   || {}).innerHTML
        });
    };

    console.log('[CFG] garde-fou jomoa/Dohr installé');

    // ── Auto-correction immédiate au chargement de custom.js ────────────────
    // Bug identifié : le tout premier calculateAndDisplayTimesFunction() de la
    // session (boot, m2body.js ligne ~8843) s'exécute AVANT que custom.js (et
    // donc cette garde) ne soit chargé — cf. ordre de chargement des scripts,
    // CLAUDE.md. Après un _applyMosqueConfig() qui écrit ucJomoaFixedTime puis
    // fait un location.reload(), l'affichage initial reste donc "brut" tant
    // qu'aucun autre événement (réglage, minuit, focus fenêtre) ne redéclenche
    // un recalcul — ce qui n'arrive jamais lors d'un simple test ponctuel. On
    // rejoue donc UN calcul ici, juste après l'installation de la garde, pour
    // corriger immédiatement le rendu initial.
    _dbg('self-check-on-load', { reason: 'rejoue calculateAndDisplayTimesFunction juste apres install de la garde' });
    window.calculateAndDisplayTimesFunction();
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── Aya aléatoire : masque le message de diagnostic interne du core ──────────
// Bug source (m2body.js, displayRandomAyaFunction, core, non modifiable) :
// après 20 tentatives infructueuses pour choisir une aya aléatoire valide
// (longueur compatible avec l'écran, période spéciale, etc.), le core écrit
// littéralement "error _RECURSIONS : ayats-XX" dans #ayaTextDisplayVertical/
// Horizontal — un texte de diagnostic interne, jamais loggé nulle part (d'où
// l'absence totale de trace console), qui reste affiché à l'utilisateur
// jusqu'au prochain appel (déclenché seulement au démarrage puis une fois par
// minute, à la seconde '08' — d'où le délai avant correction observé).
// On ne peut pas patcher la fonction elle-même sans dupliquer toute sa
// logique de sélection/filtrage : on observe donc le DOM et, si ce texte
// apparaît, on restaure la dernière aya valide affichée puis on relance un
// essai quasi immédiat au lieu d'attendre la minute suivante.
(function _fixAyaRecursionErrorFlash() {
    var vEl = document.getElementById('ayaTextDisplayVertical');
    var hEl = document.getElementById('ayaTextDisplayHorizontal');
    if (!vEl && !hEl) return;

    var ERROR_MARKER   = 'error _RECURSIONS';
    var _lastGoodHtml  = { ayaTextDisplayVertical: '', ayaTextDisplayHorizontal: '' };
    var _retryScheduled = false;

    function _checkAndFix(el) {
        // subtree:true + characterData:true peuvent rapporter un noeud texte
        // (mutation en place, pas via innerHTML=) : on ne traite que les
        // éléments eux-mêmes, avec leur propriété innerHTML.
        if (el && el.nodeType !== 1) el = el.parentElement;
        if (!el || typeof el.innerHTML !== 'string') return;
        if (el.innerHTML.indexOf(ERROR_MARKER) === -1) {
            _lastGoodHtml[el.id] = el.innerHTML;
            return;
        }
        _L('AYA', 'RESCUE', { el: el.id, reason: 'recursion_cap_hit' });
        el.innerHTML = _lastGoodHtml[el.id] || '';
        if (!_retryScheduled) {
            _retryScheduled = true;
            setTimeout(function() {
                _retryScheduled = false;
                if (typeof window.displayRandomAyaFunction === 'function') window.displayRandomAyaFunction();
            }, 400);
        }
    }

    var _ayaObserver = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) { _checkAndFix(m.target); });
    });
    [vEl, hEl].forEach(function(el) {
        if (el) _ayaObserver.observe(el, { childList: true, characterData: true, subtree: true });
    });
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── Rotation des versets/ayats : réglage ON/OFF (ucAyaRotationEnabled) ───────
// Coupe l'affichage rotatif des versets coraniques génériques quand le
// réglage est désactivé, TOUT EN laissant passer les rappels ponctuels
// (10 derniers jours de Ramadan, 10 premières nuits de Dhoul Hijja, jours
// blancs, Takbir) que le coeur repère lui-même via le wrapper
// 'specialAyaClass' (m2body.js, displayRandomAyaFunction).
// Même contrainte que _fixAyaRecursionErrorFlash ci-dessus : impossible de
// monkey-patcher displayRandomAyaFunction directement -- ses propres retries
// internes s'appellent par leur nom global bare (`displayRandomAyaFunction()`),
// qui résoudrait alors vers NOTRE wrapper (functions au global scope, lookup
// dynamique par nom, pas par référence capturée) au lieu de l'original,
// causant une explosion récursive. On observe donc le DOM, comme le fait déjà
// le correctif ci-dessus, plutôt que de patcher la fonction.
(function _installAyaRotationFilter() {
    var vEl = document.getElementById('ayaTextDisplayVertical');
    var hEl = document.getElementById('ayaTextDisplayHorizontal');
    if (!vEl && !hEl) return;

    function _checkAndFilter(el) {
        if (el && el.nodeType !== 1) el = el.parentElement;
        if (!el || typeof el.innerHTML !== 'string') return;
        if (JS_CUSTOM.ucAyaRotationEnabled == 1) return;               // rotation classique, ne rien changer
        if (el.innerHTML === '') return;                               // déjà vide, rien à faire
        if (el.innerHTML.indexOf('specialAyaClass') > -1) return;      // rappel ponctuel : laisser passer
        el.innerHTML = '';
    }

    var _filterObserver = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) { _checkAndFilter(m.target); });
    });
    [vEl, hEl].forEach(function(el) {
        if (el) _filterObserver.observe(el, { childList: true, characterData: true, subtree: true });
    });
    // Applique aussi immédiatement à l'état déjà présent au chargement.
    _checkAndFilter(vEl);
    _checkAndFilter(hEl);
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── AZKAR (page "doaa" après azan) : anti-débordement en mode vertical ───────
// Bug source (m2body.js, displayNextAzkarFunction) : la taille de police est
// calculée uniquement à partir du nombre de caractères du bloc
// (calculateFontSizeFunction), sans tenir compte du nombre de lignes (<br>)
// qu'il contient. Un bloc avec beaucoup de lignes courtes (ex. le 1er bloc de
// JS_GLOBAL_AZKAR_VR : 6 courtes phrases) obtient donc une police proche du
// maximum (10.4vw en vertical, le plus grand des deux réglages) alors que sur
// 6 lignes cumulées ça déborde largement de #azkarTextWrapperVertical
// (haut:0, height:100% dans une zone qui ne fait que 78% de l'écran) — le
// texte déborde alors par-dessus l'horloge/les horaires affichés autour,
// donnant l'impression que tout est "mélangé" au milieu de l'écran.
// Correctif : après chaque mise à jour du texte, on réduit la police par
// petits paliers jusqu'à ce que le contenu tienne réellement dans sa zone.
(function _fixAzkarOverflowVertical() {
    if (typeof window.displayNextAzkarFunction !== 'function') {
        console.warn('[AZKAR] displayNextAzkarFunction introuvable -- patch annulé');
        return;
    }

    var _origDisplayNextAzkar = window.displayNextAzkarFunction;
    window.displayNextAzkarFunction = function() {
        _origDisplayNextAzkar.apply(this, arguments);
        // Court délai : laisse le layout se stabiliser (scrollHeight fiable
        // seulement après le reflow qui suit l'injection du texte/de la police).
        setTimeout(_ucShrinkAzkarTextToFit, 30);
    };

    function _ucShrinkAzkarTextToFit() {
        var el   = document.getElementById('azkarTextDisplayVertical');
        var wrap = document.getElementById('azkarTextWrapperVertical');
        if (!el || !wrap || !el.textContent) return;

        var currentSize = parseFloat(window.getComputedStyle(el).fontSize);
        if (!currentSize) return;

        var guard = 0;
        while (el.scrollHeight > wrap.clientHeight && currentSize > 10 && guard < 40) {
            currentSize -= 1;
            el.style.fontSize = currentSize + 'px';
            guard++;
        }
    }

    console.log('[AZKAR] patch anti-débordement (vertical) installé');
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── RESYNC AU RETOUR AU PREMIER PLAN ─────────────────────────────────────────
// Toute la sequence azan -> compte a rebours iqama -> ecran noir -> azkar/doaa
// est pilotee par des setTimeout/setInterval RELATIFS (m2body.js), sans aucun
// ancrage sur une heure absolue. Quand Android suspend les timers JS de la
// WebView (appli en arriere-plan/ecran d'accueil), tout se fige ; au retour,
// l'affichage reprend exactement la ou il s'etait arrete au lieu de refleter
// l'heure reelle. Comme rien n'est reellement "reprenable" (pas d'horodatage
// absolu stocke nulle part), la strategie est : remettre les surcouches
// transitoires (popup azan, popup/compteur iqama, ecran noir, azkar, slides) a
// leur etat de base masque, puis laisser checkAndRestoreIqamaCounter() (deja
// present dans le core, utilise une seule fois au chargement de la page,
// m2body.js ~L8842) recalculer depuis l'heure reelle si un compte a rebours
// iqama doit effectivement etre actif maintenant.
// Epoque de sequence iqama : incrementee a chaque resync (retour au premier
// plan apres pause reelle). Les continuations tardives de startIqamaSequenceFunction()
// (setTimeout('onIqamaEndFunction()'), setTimeout('activateBlackScreenIfEnabled()'),
// setTimeout('animateBlackScreenCountdown()'), setTimeout(hideElementFunction, ..., 'iqamaPopup...'))
// sont TOUTES programmees via setTimeout brut (parfois eval'e en chaine) sans
// identifiant recuperable -> impossible a annuler avec clearTimeout. Sans ce
// garde-fou, elles continuent de s'executer en rafale au reveil des timers
// (resumeTimers()), rejouant toute la fin de sequence (popup, rideau noir,
// azkar) meme si elle ne correspond plus a la priere reelle courante. Chaque
// fonction potentiellement replayee compare _ucIqamaSeqEpoch (vivant, ici) a
// _ucActiveIqamaSeqEpoch (instantane pris au demarrage de LA sequence en cours,
// via UC_EVT.IQAMA_TIME, cf. plus bas) ; en cas d'ecart, elle se sait perimee
// et ne fait rien.
// _ucActiveIqamaSeqEpoch est mis a jour directement dans les monkey-patches de
// startIqamaSequenceFunction() plus bas (section UC_EVT bridge, EVENTS 2+6 et
// _installJomoaIqamaSuppress) plutot que via ucOn(UC_EVT.IQAMA_TIME, ...) ici :
// ucOn()/UC_EVT n'existent pas encore a ce point du fichier (definis plus bas).
var _ucIqamaSeqEpoch = 0;
var _ucActiveIqamaSeqEpoch = -1;

// ── FERMETURE CANONIQUE DE TOUTES LES FORMES DU COMPTEUR IQAMA ────────────
// Point d'entree UNIQUE (02/08/2026, suite audit) : avant ce refactor,
// _ucResyncPrayerSequence (juste en dessous) et _cancelStaleCounter
// (_installCounterDriftCorrection, plus bas dans ce fichier) avaient chacune
// leur PROPRE copie de cette liste de nettoyage, maintenue separement.
// Consequence concrete constatee sur 5 bugs distincts entre le 25/07 et le
// 01/08/2026 (compteur invisible, compteur fige "00:40", puis fige "40" sur
// secondCounterContainer...) : chaque nouveau symptome n'etait corrige que
// dans UNE des deux copies -- au moment d'ecrire ce refactor, le fix
// secondCounterContainer/isLastMinuteCounter du 01/08 (ajoute dans
// _ucResyncPrayerSequence) manquait encore dans _cancelStaleCounter, sans
// qu'aucun rapport ne l'ait signale (meme bug, mais uniquement declenchable
// par le chemin drift-correction, jamais encore observe en pratique par ce
// chemin precis). Toute liste de nettoyage dupliquee finit par diverger --
// ceci est desormais LA seule fonction qui sait fermer un compteur perime.
window._ucForceCloseAllCounterOverlays = function () {
    if (typeof window.hideElementFunction === 'function') {
        window.hideElementFunction('iqamaCounterContainerVertical');
        window.hideElementFunction('iqamaCounterContainerHorizontal');
        // closeFullScreenCounterFunction() (coeur) plutot qu'un hide partiel :
        // remet aussi --izBigCNTR a 1 (sinon le tableau standard des prieres
        // reste invisible en permanence, cf. style1/2.css opacity:var(--izBigCNTR)).
        if (typeof window.closeFullScreenCounterFunction === 'function') {
            window.closeFullScreenCounterFunction();
        } else {
            window.hideElementFunction('fullScreenCounterContainerVertical');
            window.hideElementFunction('fullScreenCounterContainerHorizontal');
        }
        // secondCounterContainer* : chiffre geant "derniere minute" (secondes
        // seules, cf. clockTickFunction ~L2018-2023, coeur), DISTINCT des deux
        // conteneurs ci-dessus -- angle mort trouve le 01/08/2026 (compteur
        // fige sur "40" survivant a tous les resyncs suivants).
        window.hideElementFunction('secondCounterContainerVertical');
        window.hideElementFunction('secondCounterContainerHorizontal');
    }
    // Identifiants NUS obligatoires -- ce sont des `let` top-level de
    // m2body.js (coeur), PAS des proprietes de window : window.isIqamaCounterActive
    // (ou window.isLastMinuteCounter) serait une propriete separee et INERTE,
    // sans aucun effet sur le vrai compteur que la boucle de tick lit en
    // identifiant nu (confirme par test direct, cf. discussion 27/07/2026).
    if (typeof isIqamaCounterActive !== 'undefined') isIqamaCounterActive = false;
    if (typeof isLastMinuteCounter !== 'undefined') isLastMinuteCounter = false;
    if (typeof window._ucResetAyaPositionGuard === 'function') window._ucResetAyaPositionGuard();
    // Popup texte iqama (verset/hadith) : masque directement via la MEME
    // classe que hideElementFunction() (m2body.js) plutot que via
    // window.hideElementFunction() -- cet appel passerait par l'extension
    // "+5s" (custom.js, plus bas) qui retarderait ce masquage de 5s de plus.
    ['iqamaPopupVertical', 'iqamaPopupHorizontal'].forEach(function (id) {
        var el = document.getElementById(id);
        if (el) el.className = 'hiddenClass';
    });
    if (typeof window.resetPrayerRowsStyleFunction === 'function') window.resetPrayerRowsStyleFunction();
};

// ── GARDE-FOU PERIODIQUE : aucune forme du compteur ne doit rester visible
// sans que isIqamaCounterActive ne le justifie ───────────────────────────
// Meme principe que _installMiniOverlayInvariantGuard (28/07/2026, plus bas
// dans ce fichier) et le meme constat qui a motive le refactor ci-dessus :
// corriger au cas par cas (un resync ici, un drift-check la) oublie toujours
// un chemin. Plutot que d'esperer avoir couvert tous les chemins possibles,
// ce garde-fou impose l'invariant directement, en balayage periodique,
// independamment de la cause exacte de l'incoherence -- absorbe non
// seulement les bugs deja rencontres mais toute variante future du meme
// probleme (nouvel element visuel lie au compteur qu'on ajouterait plus
// tard sans penser a l'ajouter partout).
(function _installCounterOverlayInvariantGuard() {
    var CHECK_MS = 4000;
    var _ids = [
        'iqamaCounterContainerVertical', 'iqamaCounterContainerHorizontal',
        'fullScreenCounterContainerVertical', 'fullScreenCounterContainerHorizontal',
        'secondCounterContainerVertical', 'secondCounterContainerHorizontal'
    ];
    function _sweep() {
        if (typeof isIqamaCounterActive !== 'undefined' && isIqamaCounterActive) return;
        var stuck = _ids.filter(function (id) {
            var el = document.getElementById(id);
            return el && el.className !== 'hiddenClass';
        });
        if (!stuck.length) return;
        _L('CTR', 'COUNTER_OVERLAY_STUCK_CORRECTED', { ids: stuck.join(',') });
        window._ucForceCloseAllCounterOverlays();
    }
    setInterval(_sweep, CHECK_MS);
    _L('CUSTOM', 'INIT', { item: 'counterOverlayInvariantGuard' });
})();

(function _installResyncOnResume() {
    var HIDDEN_THRESHOLD_MS = 5000; // ignorer les coups d'oeil rapides (volet de notifications, etc.)
    var _ucHiddenAt = null;
    // Empeche un double reload : ce resync tourne 2x pour le meme evenement
    // (declencheurs visibilitychange ET native_resume, quasi simultanes,
    // cf. les deux ecouteurs plus bas) -- sans ce garde-fou, le 2e passage
    // relancerait un location.reload() par-dessus le premier deja en cours.
    var _ucAutoReloadTriggered = false;

    function _ucResyncPrayerSequence(reason) {
        // Capture AVANT tout nettoyage : le natif joue-t-il reellement l'azan
        // a cet instant precis ? (cf. AzanPlaybackService.isPlayingNow /
        // MobileJsBridge.isAzanCurrentlyPlaying). Necessaire ICI, tout au
        // debut -- des la ligne _ucReleaseAzanBlock plus bas, la cascade
        // hideAzanPopupFunction() va justement COUPER cette lecture native ;
        // interroger apres coup donnerait toujours false. Sert a decider, en
        // fin de fonction, s'il faut enchainer sur un reload automatique
        // (cf. bas de fonction) : un azan reellement interrompu par ce
        // resync signifie que l'utilisateur vient de rouvrir l'appli pendant
        // qu'il sonnait -- sans ca il atterrit sur la page principale sans
        // countdown iqama ni rideau noir, meme si leur horaire n'est pas
        // encore passe (constate en pratique, discussion debug 24/07/2026).
        var _wasNativeAzanPlaying = !!(window.AndroidMobile &&
            typeof window.AndroidMobile.isAzanCurrentlyPlaying === 'function' &&
            window.AndroidMobile.isAzanCurrentlyPlaying());

        // 0) Perime toute continuation deja programmee par une sequence iqama
        //    en cours (cf. commentaire _ucIqamaSeqEpoch ci-dessus).
        _ucIqamaSeqEpoch++;

        // Diagnostic AVANT nettoyage : capture ce qui etait effectivement
        // bloque/visible a cet instant -- permet de confirmer, dans les logs,
        // si ce resync avait bien quelque chose a rattraper (et quoi) plutot
        // que de deviner apres coup.
        var _wasAzanBlocked   = (typeof window._ucIsAzanBlocked === 'function') && window._ucIsAzanBlocked();
        var _wasSalatNabiVis  = (typeof window._ucIsSalatNabiVisible === 'function') && window._ucIsSalatNabiVisible();
        var _iqamaTextWasShown = ['iqamaPopupVertical', 'iqamaPopupHorizontal'].some(function(id) {
            var el = document.getElementById(id);
            return el && el.className === 'visibleTransitionClass';
        });
        // Angle mort corrige (27/07/2026) : isIqamaCounterActive est force a
        // false plus bas SANS jamais logger sa valeur AVANT -- si le compteur
        // tournait deja (fige ou non) a cet instant precis, aucune trace ne
        // le prouvait. Capture ici, avant tout nettoyage.
        //
        // BUG DISTINCT ET PLUS GRAVE, decouvert en testant ce qui precede
        // (27/07/2026) : isIqamaCounterActive/remainingSeconds sont des `let`
        // au TOP-LEVEL de m2body.js (script core), PAS des proprietes de
        // window -- `window.isIqamaCounterActive = false` (l'ecriture plus
        // bas AVANT ce correctif) cree une propriete window totalement
        // SEPAREE et INERTE : ca n'arrete jamais reellement le compteur reel
        // que la boucle de tick du core lit en identifiant nu. Confirme par
        // test direct : ecrire isIqamaCounterActive (nu) modifie la vraie
        // variable, mais window.isIqamaCounterActive reste a son ancienne
        // valeur, totalement decorrelee. Toujours utiliser l'identifiant NU,
        // jamais window.isIqamaCounterActive / window.remainingSeconds.
        var _wasCounterActive = (typeof isIqamaCounterActive !== 'undefined') && isIqamaCounterActive;
        var _remAtResync      = (typeof remainingSeconds !== 'undefined') ? remainingSeconds : null;
        _L('RESYNC', 'STATE_BEFORE', {
            reason: reason || 'visibilitychange',
            azanBlocked: _wasAzanBlocked, salatNabiVisible: _wasSalatNabiVis, iqamaTextShown: _iqamaTextWasShown,
            counterActive: _wasCounterActive, remainingSeconds: _remAtResync, prayerInterval: (typeof currentPrayerInterval !== 'undefined') ? currentPrayerInterval : null
        });

        // 1) Etat de base : masque toutes les surcouches transitoires via leurs
        //    vraies fonctions core (pas un toggle DOM brut) pour que le nettoyage
        //    associe (audio, ecouteurs UC_EVT, etc.) se declenche normalement.
        //    Idempotent : ne rien changer visuellement si deja masque.
        // Lever D'ABORD le verrou "audio azan en cours" (cf. custom.js,
        // _ucReleaseAzanBlock) : sinon hideAzanPopupFunction() ci-dessous
        // refuse de fermer (POPUP_HIDE_BLOCKED) si l'ecran s'est eteint
        // PENDANT la lecture -- le <audio> JS (desormais muet, cf. source
        // audio unique cote natif) gele avant son 'ended' et ne relache
        // jamais le verrou tout seul. Meme raisonnement pour SalatNabi.
        if (typeof window._ucReleaseAzanBlock === 'function') window._ucReleaseAzanBlock('resync_' + (reason || 'visibilitychange'));
        // IMPORTANT : ne fermer SalatNabi que s'il etait DEJA visible avant ce
        // resync (etat vraiment perime, cf. _wasSalatNabiVis capture plus haut)
        // -- pas inconditionnellement. La ligne precedente peut, en cascade
        // (hideAzanPopupFunction -> AZAN_HIDE), declencher un TOUT NOUVEAU
        // SalatNabi legitime (jeudi soir) ; l'appeler sans condition ici le
        // refermerait immediatement, une fraction de seconde apres son
        // ouverture normale -- constate en test (cf. STATE_AFTER montrant
        // salatNabiVisible=false alors qu'un salatNabi venait tout juste
        // d'etre correctement declenche par la cascade).
        if (_wasSalatNabiVis && typeof window._ucSalatNabiForceHide === 'function') {
            window._ucSalatNabiForceHide('resync_' + (reason || 'visibilitychange'));
        }
        if (typeof window.hideAzanPopupFunction === 'function') window.hideAzanPopupFunction();
        if (typeof window.deactivateBlackScreen === 'function') window.deactivateBlackScreen();
        if (typeof window.hideAzkarDisplayFunction === 'function') window.hideAzkarDisplayFunction();
        if (typeof window.hideSlidesDisplayFunction === 'function') window.hideSlidesDisplayFunction();
        // Reaffiche le tableau des horaires (cf. _installBlackScreenHidesPrayerTable,
        // masque a BLACK_SHOW et normalement restaure seulement au prochain
        // AZAN_SHOW reel) : une reprise active de l'appli doit sortir tout de
        // suite du mode nocturne azkar/slides (deja stoppes ci-dessus), donc
        // le tableau doit redevenir visible ici aussi, sans attendre le
        // prochain azan.
        ['prayerTimesContainerHorizontal', 'prayerTimesContainerVertical'].forEach(function (id) {
            var _ptEl = document.getElementById(id);
            if (_ptEl) _ptEl.style.visibility = 'visible';
        });
        // Ferme toutes les formes du compteur (compact, plein ecran, "derniere
        // minute") + reinitialise les flags associes -- fonction canonique
        // unique, cf. son commentaire (juste au-dessus de _installResyncOnResume)
        // pour l'historique des bugs qui ont motive ce regroupement.
        window._ucForceCloseAllCounterOverlays();
        // Hadiths avant iqama (58-40s / 30-20s, custom.js plus bas) : leurs
        // propres declencheurs de fermeture sont bases sur COUNTDOWN_TICK
        // (plage de remainingSeconds, cf. fix du 15/08/2026) -- mais une
        // pause d'arriere-plan de plusieurs HEURES gele l'app avant que le
        // moindre tick suivant ne puisse s'executer, laissant l'overlay
        // visible indefiniment jusqu'au prochain cycle azan (rapporte a
        // nouveau le 16/08/2026 malgre le fix du tick). Meme categorie de
        // bug documentee au-dessus de _ucForceCloseAllCounterOverlays :
        // rattrapage explicite ici, independant de leur propre logique.
        if (typeof window._ucForceHideIqamaHadithOverlay === 'function') window._ucForceHideIqamaHadithOverlay();
        if (typeof window._ucForceHideIqama15sOverlay === 'function') window._ucForceHideIqama15sOverlay();
        // Doua post-azan (custom.js _installPostAzanDoua) : son propre timer
        // de fermeture (20s) est lui aussi suspendu en arriere-plan — meme
        // logique que les surcouches core ci-dessus.
        if (typeof window._ucForceHidePostAzanDoua === 'function') window._ucForceHidePostAzanDoua();

        // Rattrapage : Coran auto-demarre resté en lecture au-delà de son
        // azan (constate en pratique via rapport debug — Isha jamais
        // arrêté). Cause : applyNextPrayerHighlight() (custom.js) ne réagit
        // QU'AU FRANCHISSEMENT EN TEMPS RÉEL du seuil d'arrêt (remainingMinutes
        // <= thresholdMin) — si l'écran s'éteint PILE à ce moment, le check
        // n'est jamais évalué, et il ne "rattrape" jamais après coup : une
        // fois réveillé, la prière suivante (_getUpcomingPrayerKey) a déjà
        // changé, donc le seuil de l'ANCIENNE prière n'est plus jamais
        // atteignable. Ici : si le Coran auto-démarré est toujours audible
        // ET que la prière suivante a changé depuis son déclenchement
        // (_sqaPrayerKey), l'azan pour laquelle il avait été lancé est
        // nécessairement déjà passé -> on l'arrête maintenant, tardivement
        // mais proprement (même chaîne que l'arrêt normal : pause + fin.mp3).
        if (typeof _sqaPrayerKey !== 'undefined' && _sqaPrayerKey &&
            typeof _getUpcomingPrayerKey === 'function') {
            var _freshNextKey = _getUpcomingPrayerKey();
            var _qAudio = document.getElementById('quranAudioPlayer');
            var _qStillPlaying = (typeof _qpPlayedThisCycle !== 'undefined' && _qpPlayedThisCycle) ||
                                  (_qAudio && !_qAudio.paused);
            if (_qStillPlaying && _freshNextKey !== _sqaPrayerKey) {
                _L('AUDIO', 'STOP', {
                    action: 'stopBeforeAzan', prayer: _sqaPrayerKey, reason: 'resync_catchup',
                    note: 'prayer_changed_while_frozen_never_reached_stop_threshold'
                });
                if (_qAudio && !_qAudio.paused) _qAudio.pause();
                if (typeof window._qpStopEq === 'function') window._qpStopEq();
                if (typeof window._playFinAudio === 'function') window._playFinAudio();
                if (typeof window._pendingAutoStart !== 'undefined') window._pendingAutoStart = false;
                if (typeof window._hideAutoplayUnlockModal === 'function') window._hideAutoplayUnlockModal();
                // Repart propre pour le prochain cycle (celui de _freshNextKey) :
                // sans ceci, _sqaFired/_sqbFired resteraient a l'etat de l'ANCIEN
                // cycle et pourraient empecher a tort le prochain declenchement.
                _sqaPrayerKey = _freshNextKey;
                _sqaFired = false;
                _sqbFired = false;
                _qpPlayedThisCycle = false;
            } else {
                _L('AUDIO', 'INFO', {
                    action: 'resync_quran_check', stillPlaying: _qStillPlaying,
                    prayerAtStart: _sqaPrayerKey, prayerNow: _freshNextKey
                });
            }
        }

        // 2) Neutralise l'unique continuation deja programmee (setTimeout avec
        //    chaine eval'ee, donc impossible a annuler via clearTimeout) pour les
        //    chaines azkar/slides -- ces deux flags sont lus en tete de leurs
        //    fonctions respectives dans m2body.js et consomment l'annulation une
        //    seule fois avant de se reinitialiser a false.
        window.stopAzkarFlag  = true;
        window.stopSlidesFlag = true;

        // 3) Recalcule depuis l'heure reelle : si une fenetre d'iqama est
        //    effectivement en cours, redemarre le compteur avec les bonnes
        //    valeurs (et l'affiche) ; sinon ne fait rien de plus qu'un
        //    rafraichissement normal (meme appel que window.onfocus, m2body.js
        //    ~L8845).
        //
        //    IMPORTANT : rafraichir currentTimeInMinutes de facon SYNCHRONE
        //    en premier. checkAndRestoreIqamaCounter() (core, m2body.js
        //    ~L8233) decide de la priere "active" en lisant currentTimeInMinutes
        //    tout de suite dans un switch(true), mais ne fait que PROGRAMMER
        //    (setTimeout) le rafraichissement de cette variable -- si elle est
        //    encore figee sur l'heure d'avant la mise en arriere-plan (JS gele),
        //    la fonction peut matcher la fenetre d'iqama de la PRIERE PRECEDENTE
        //    (perimee) et rejouer tout son affichage (compteur, seuils hadith,
        //    popup verset, ecran noir) avant que la correction n'arrive.
        //    Constate en pratique : popup+sequence iqama Asr entierement
        //    rejouee au retour au premier plan alors que Maghreb venait de
        //    sonner. En rafraichissant nous-memes AVANT, checkAndRestoreIqamaCounter()
        //    lit directement la bonne priere des le premier appel.
        //
        //    RECIDIVE (24/07/2026, rapport debug #24) : meme symptome constate
        //    a nouveau APRES une pause de ~2h30 -- currentTimeInMinutes seul ne
        //    suffit pas. calculateAndDisplayTimesFunction() (qui calcule
        //    fajrTimeInMinutes/asrTimeInMinutes/etc. depuis la table JS_TIMES)
        //    ne se relance QUE sur changement de jour calendaire (guard interne
        //    de updateTimeAndPrayersFunction, meme journee ici -> jamais
        //    redeclenche) : si une de ces variables est restee incoherente
        //    apres une longue pause pour une raison encore non identifiee avec
        //    certitude, rien ne la corrige avant ce point. On la force donc ici
        //    explicitement, sans attendre un hypothetique changement de jour --
        //    recalcul sans risque (meme journee, memes donnees source), elimine
        //    cette source de peremption quel que soit le mecanisme exact.
        if (typeof window.calculateAndDisplayTimesFunction === 'function') {
            window.calculateAndDisplayTimesFunction();
        }
        if (typeof window.updateTimeAndPrayersFunction === 'function') {
            window.updateTimeAndPrayersFunction(true);
        }
        if (typeof window.checkAndRestoreIqamaCounter === 'function') {
            window.checkAndRestoreIqamaCounter();
        }
        // cf. definition de _ucJomoaBlackScreenCatchUp plus bas dans ce fichier
        // (hoisting : declaration function top-level, disponible ici malgre
        // l'ordre d'ecriture) -- meme resync que checkAndRestoreIqamaCounter()
        // juste au-dessus, mais pour le rideau noir specifique a Jumu'a.
        if (typeof _ucJomoaBlackScreenCatchUp === 'function') {
            _ucJomoaBlackScreenCatchUp();
        }

        // Diagnostic APRES nettoyage : confirme que rien n'est reste bloque
        // (a comparer avec STATE_BEFORE plus haut -- tout doit etre a false ici).
        var _stillAzanBlocked  = (typeof window._ucIsAzanBlocked === 'function') && window._ucIsAzanBlocked();
        var _stillSalatNabiVis = (typeof window._ucIsSalatNabiVisible === 'function') && window._ucIsSalatNabiVisible();
        _L('RESYNC', 'STATE_AFTER', {
            reason: reason || 'visibilitychange',
            azanBlocked: _stillAzanBlocked, salatNabiVisible: _stillSalatNabiVis,
            recovered: (_wasAzanBlocked && !_stillAzanBlocked) || (_wasSalatNabiVis && !_stillSalatNabiVis)
        });

        // Horodatage du dernier resync : cf. _installPostAzanDoua plus bas, qui
        // l'utilise pour ignorer un AZAN_HIDE tardif emis par le
        // setTimeout('hideAzanPopupFunction()', ...) du CORE (m2body.js
        // showAzanPopup, eval'e en chaine, jamais annulable -- meme famille de
        // probleme que _ucIqamaSeqEpoch plus haut, mais pour la fermeture du
        // popup azan plutot que la sequence iqama). Ce timer, arme des
        // l'ouverture du popup et gele pendant la mise en arriere-plan, peut se
        // declencher juste APRES que ce resync ait deja tout nettoye, rouvrant
        // une "nouvelle" postAzanDoua bien apres coup (constate en pratique :
        // page doua encore affichee au retour au premier plan, alors que le
        // compteur iqama etait attendu -- debug 24/07/2026).
        window._ucLastResyncCloseAt = Date.now();

        _L('RESYNC', 'FIRE', { action: 'resync_prayer_sequence', reason: reason || 'visibilitychange' });

        // Azan natif reellement interrompu par ce resync (capture tout en
        // haut, cf. _wasNativeAzanPlaying) : un simple nettoyage ne suffit
        // pas a retrouver le countdown iqama / rideau noir en cours (cf.
        // bouton reload manuel, meme logique) -- on l'enchaine ici
        // automatiquement, une seule fois (garde _ucAutoReloadTriggered,
        // cf. double declenchement visibilitychange+native_resume).
        if (_wasNativeAzanPlaying && !_ucAutoReloadTriggered) {
            _ucAutoReloadTriggered = true;
            _L('SYS', 'FIRE', { action: 'auto_reload', reason: 'native_azan_interrupted_by_resume' });
            location.reload();
        }
    }

    document.addEventListener('visibilitychange', function() {
        if (document.hidden) {
            _ucHiddenAt = Date.now();
            return;
        }
        if (_ucHiddenAt === null) return; // jamais masque depuis le chargement
        var hiddenMs = Date.now() - _ucHiddenAt;
        _ucHiddenAt = null;
        if (hiddenMs > HIDDEN_THRESHOLD_MS) _ucResyncPrayerSequence('visibilitychange');
    });

    // Expose pour un declenchement fiable depuis le natif (MainActivity.onResume,
    // via evaluateJavascript) : sur WebView Android, `document.visibilitychange`
    // ne se synchronise pas de facon fiable avec le cycle de vie de l'Activity
    // (onPause/onResume), qui est pourtant ce qui suspend/reprend reellement les
    // timers JS (webView.pauseTimers()/resumeTimers()) -- voir MainActivity.kt.
    // Le seuil de 5s (HIDDEN_THRESHOLD_MS) est duplique cote natif ; garder les
    // deux en phase si l'un des deux change.
    window._ucResyncPrayerSequence = _ucResyncPrayerSequence;

    _L('CUSTOM', 'INIT', { item: 'resyncOnResume' });
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── QR CODE — UNIQUE QR ───────────────────────────────────────────────────────
// Affichage d'un QR code unique basé sur spec/images/qrmosquee.png.
// Piloté par JS_DATA.ucQrFlag.
// ─────────────────────────────────────────────────────────────────────────────
(function _patchQrFlag() {
    if (typeof updatePsFlagVisibilityFunction !== 'function') {
        console.warn('[QR] updatePsFlagVisibilityFunction introuvable -- patch annule');
        return;
    }

    var _SRC = 'spec/images/qrmosquee.png';

    // -- Helpers visuels -------------------------------------------------------
    function _applyLayoutClass(isQr) {
        var vc = document.getElementById('mainVerticalContainer');
        var hc = document.getElementById('mainHorizontalContainer');
        if (vc) vc.classList.toggle('uc-qr-active', isQr);
        if (hc) hc.classList.toggle('uc-qr-active', isQr);
    }

    function _setImgSrc(id, src, visible) {
        var el = document.getElementById(id);
        if (!el) return;
        if (src) el.src = src;
        el.style.visibility = visible ? 'visible' : 'hidden';
    }

    function _applyQrVisibility() {
        if (typeof JS_DATA.ucQrFlag === 'undefined') JS_DATA.ucQrFlag = 0;
        var isQr = (JS_DATA.ucQrFlag == 1);
        var cb = document.getElementById('qrFlagCheckbox');
        if (cb) cb.checked = isQr;
        _applyLayoutClass(isQr);

        // qrFlagImageVertical retiré définitivement : remplacé par psFlagImageVertical
        // + le lien de menu (cf. section "QR CODE — modale d'agrandissement" plus bas).
        // Toujours masqué, quelle que soit ucQrFlag. qrFlagImageHorizontal (mode
        // horizontal) conserve son comportement d'origine, inchangé.
        _setImgSrc('qrFlagImageVertical',   _SRC, false);
        _setImgSrc('qrFlagImageHorizontal', _SRC, isQr);

        _L('QR', 'VISIBILITY', { isQr: isQr });
    }

    // -- Toggle ----------------------------------------------------------------
    window.toggleQrFlagFunction = function() {
        JS_DATA.ucQrFlag = +(JS_DATA.ucQrFlag != 1);
        saveSettingsToStorageFunction();
        _applyQrVisibility();
    };

    var _origFn = updatePsFlagVisibilityFunction;
    window.updatePsFlagVisibilityFunction = function() { _origFn(); _applyQrVisibility(); };

    // -- Lancement ------------------------------------------------------------
    updatePsFlagVisibilityFunction();

    window.addEventListener('load', function() {
        setTimeout(_applyQrVisibility, 250);
        setTimeout(_applyQrVisibility, 1500);
    });

    _L('QR', 'INIT', { mode: 'static_png', src: _SRC });
})();
// ─────────────────────────────────────────────────────────────────────────────

// ── QR CODE — modale d'agrandissement — UNIQUE point d'entrée : psFlagImageVertical ──
// qrFlagImageVertical et qrFlagCheckbox sont retirés de l'usage (cf. plus haut :
// qrFlagImageVertical forcé masqué en permanence dans _applyQrVisibility ;
// qrFlagCheckbox masqué ci-dessous). Seuls restent :
//   - #psFlagImageVertical : simple clic/tap = ouvre la modale (JAMAIS de
//     rafraîchissement) ; double clic/tap = restartApplicationFunction().
//     Ne touche pas #psFlagImageHorizontal.
//   - Un lien de menu (#ucQrCodeMenuLink, injecté après la section "onboarding
//     tour" plus bas, pour s'insérer juste après #ucTourRelaunchLink) qui ouvre
//     exactement la même modale.
// Aucun lien avec customSpeakerIcon / customQuranIcon ni positionCustomIcons() :
// aucun impact sur leur positionnement.
(function injectQrCodeModal() {

    var QR_SRC = 'spec/images/qrmosquee.png';

    // Aligne le libellé de #psFlagCheckbox sur l'image RÉELLEMENT affichée par
    // #psFlagImageVertical (QR de la mosquée vs drapeau palestinien). index.html
    // fige le texte à "علم فلسطين | Palestine flag" ; ici on le remplace par la
    // formulation "QR" dès que la source de l'image contient "qrmosquee". Le
    // <label> n'a pas d'id dédié -> ciblé via [for="psFlagCheckbox"].
    function _ucSyncPsFlagCheckboxLabel() {
        try {
            var lbl = document.querySelector('label[for="psFlagCheckbox"]');
            if (!lbl) return;
            var img = document.getElementById('psFlagImageVertical');
            var src = (img && (img.getAttribute('src') || img.src)) || '';
            var isQr = /qrmosquee/i.test(src);
            var txt = isQr ? 'رمز QR للمسجد | Mosque QR code'
                           : 'علم فلسطين | Palestine flag';
            if (lbl.textContent.trim() !== txt) lbl.textContent = txt;
        } catch (e) {}
    }
    window._ucSyncPsFlagCheckboxLabel = _ucSyncPsFlagCheckboxLabel;

    var overlay = document.createElement('div');
    overlay.id = 'qrCodeOverlay';
    overlay.className = 'qcHidden';
    overlay.onclick = function (e) { if (e.target === overlay) closeQrCodeModal(); };

    overlay.innerHTML =
        '<div id="qrCodeModal">' +
            '<div id="qrCodeHeader">' +
                '<div id="qrCodeTitle">رمز QR الخاص بالمسجد</div>' +
                '<div id="qrCodeClose">&#10006;</div>' +
            '</div>' +
            '<div id="qrCodeBody">' +
                '<img id="qrCodeImageBig" alt="QR" src="' + QR_SRC + '">' +
                '<div id="qrCodeMosqueName"></div>' +
                '<div id="qrCodeHint">وجّه كاميرا هاتفك نحو الرمز لمسحه</div>' +
            '</div>' +
        '</div>';

    document.documentElement.appendChild(overlay);

    var _qcCloseBtn = document.getElementById('qrCodeClose');
    if (_qcCloseBtn) _qcCloseBtn.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        closeQrCodeModal();
    });

    // Clic sur l'en-tête de la modale (hors bouton fermer, qui stoppe déjà sa
    // propagation) -> affiche la console de debug. debugConsoleOverlay a un
    // z-index inférieur (99999999) à qrCodeOverlay (999999999) : sans masquer
    // cette modale au préalable, la console resterait invisible derrière.
    // N'affecte aucun autre déclencheur existant de la console
    // (cityCodeDisplay.../qrFlagImage... restent inchangés).
    var _qcHeader = document.getElementById('qrCodeHeader');
    if (_qcHeader) {
        _qcHeader.style.cursor = 'pointer';
        // Double clic / double tap requis (un simple clic ne doit plus ouvrir
        // la console de debug — retour utilisateur 01/09/2026).
        var _qcHdrLastClick = 0;
        _qcHeader.addEventListener('click', function (e) {
            e.stopPropagation();
            var now = Date.now();
            if (now - _qcHdrLastClick > 0 && now - _qcHdrLastClick < 450) {
                _qcHdrLastClick = 0;
                overlay.classList.add('qcHidden');
                if (typeof window._toggleDebugConsole === 'function') window._toggleDebugConsole();
            } else {
                _qcHdrLastClick = now;
            }
        });
    }

    function openQrCodeModal() {
        var nameEl = document.getElementById('qrCodeMosqueName');
        if (nameEl) nameEl.textContent = (typeof MOSQUE_CONFIG !== 'undefined' && MOSQUE_CONFIG.MOSQUE_NAME) || '';
        overlay.classList.remove('qcHidden');
        if (typeof window._pushBack === 'function') window._pushBack();
        _L('QRMODAL', 'FIRE', { action: 'open' });
    }

    function closeQrCodeModal() {
        overlay.classList.add('qcHidden');
        if (typeof window._popBack === 'function') window._popBack();
        _L('QRMODAL', 'FIRE', { action: 'close' });
    }

    window.openQrCodeModal  = openQrCodeModal;
    window.closeQrCodeModal = closeQrCodeModal;

    // -- #psFlagImageVertical : SEUL déclencheur icône restant. Simple clic/tap
    //    = ouvre la modale, sans condition d'orientation (le simple clic ne doit
    //    JAMAIS déclencher de rafraîchissement). Appui long (maintien >= 600 ms)
    //    = restartApplicationFunction(). Distinction gérée nous-mêmes (timer
    //    démarré au press, annulé si relâché avant le délai ou si le doigt/la
    //    souris bouge) plutôt que via un évènement natif — ainsi le même code
    //    fonctionne identiquement au doigt et à la souris.
    //    Ne touche pas #psFlagImageHorizontal.
    function _bindPsFlagVerticalOverride() {
        var el = document.getElementById('psFlagImageVertical');
        if (!el) return false;

        // CRITIQUE : index.html définit onclick="restartApplicationFunction();" en
        // attribut inline. On le neutralise : le clic simple ne doit jamais
        // rafraîchir, seul l'appui long doit le faire desormais.
        el.onclick = null;

        // Image affichée : ps.png -> qrmosquee.png en mode TÉLÉPHONE/VERTICAL
        // uniquement (retour utilisateur 23/08/2026) -- indice visuel qu'un
        // appui ouvre la modale QR, sans quoi rien ne le suggère. Boîtier TV
        // en vertical/kiosque non concerné (garde ps.png) : ce n'est pas
        // l'utilisateur qui scanne sur un écran fixe, seul le comportement
        // au clic (déjà installé plus bas, indépendant de l'appareil) importe
        // là-bas. Dimensions inchangées : mêmes règles CSS #psFlagImageVertical,
        // seul l'attribut src change.
        if (_ucIsRealPhone) el.src = QR_SRC;

        // La case #psFlagCheckbox (Réglages > Options d'affichage > Affichage)
        // pilote la visibilité de CETTE image. Son libellé index.html est figé
        // sur "علم فلسطين | Palestine flag" -- trompeur quand l'image affichée
        // est en réalité le QR de la mosquée (cas téléphone ci-dessus). On
        // aligne le libellé sur ce qui est RÉELLEMENT affiché (source de
        // l'image), pas sur l'appareil, pour rester juste si la logique évolue.
        _ucSyncPsFlagCheckboxLabel();

        var LONG_PRESS_DELAY = 600;
        var _psPressTimer = null;
        var _psLongPressFired = false;

        function _psSingleTap() { openQrCodeModal(); }
        function _psLongPress() {
            _psLongPressFired = true;
            if (typeof restartApplicationFunction === 'function') restartApplicationFunction();
        }
        function _psStartPress() {
            _psLongPressFired = false;
            if (_psPressTimer) clearTimeout(_psPressTimer);
            _psPressTimer = setTimeout(_psLongPress, LONG_PRESS_DELAY);
        }
        function _psEndPress(triggerTapIfShort) {
            if (_psPressTimer) { clearTimeout(_psPressTimer); _psPressTimer = null; }
            if (triggerTapIfShort && !_psLongPressFired) _psSingleTap();
        }
        function _psCancelPress() {
            if (_psPressTimer) { clearTimeout(_psPressTimer); _psPressTimer = null; }
        }

        // Touch (Android / GeckoView) : preventDefault() bloque le click
        // synthétique que le navigateur émettrait sinon en plus.
        el.addEventListener('touchstart', function (e) {
            e.preventDefault();
            _psStartPress();
        }, { passive: false });
        el.addEventListener('touchend', function (e) {
            e.preventDefault();
            _psEndPress(true);
        }, { passive: false });
        el.addEventListener('touchmove', function () { _psCancelPress(); }, { passive: true });
        el.addEventListener('touchcancel', function () { _psCancelPress(); });

        // Souris (desktop) : même logique press/release que le tactile.
        el.addEventListener('mousedown', _psStartPress);
        el.addEventListener('mouseup', function () { _psEndPress(true); });
        el.addEventListener('mouseleave', function () { _psCancelPress(); });
        el.addEventListener('contextmenu', function (e) { e.preventDefault(); });

        return true;
    }
    if (!_bindPsFlagVerticalOverride()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_bindPsFlagVerticalOverride()) setTimeout(_bindPsFlagVerticalOverride, 300);
        });
    }

    // -- Masque l'ancienne case #qrFlagCheckbox (+ sa ligne) : remplacée
    //    fonctionnellement par le lien de menu #ucQrCodeMenuLink (injecté plus
    //    bas, après la section "onboarding tour"). index.html n'étant pas
    //    modifiable, on masque la ligne existante plutôt que de la supprimer.
    function _hideOldQrCheckboxRow() {
        var cb = document.getElementById('qrFlagCheckbox');
        if (!cb) return false;
        var row = cb.closest ? cb.closest('div') : cb.parentElement;
        if (row) row.style.display = 'none';
        return true;
    }
    if (!_hideOldQrCheckboxRow()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_hideOldQrCheckboxRow()) setTimeout(_hideOldQrCheckboxRow, 300);
        });
    }

    _L('CUSTOM', 'INIT', { item: 'qrCodeModal' });

})();
