// ── Variables Quran Player partagées : déclarées ici (global) car utilisées
//    dans des fonctions top-level (_startQuranAutoPlayback, etc.) ET dans
//    injectTechOptionsUI. Les let/var internes les masqueront localement.
var _qpServerState = 'unknown'; // 'unknown' | 'ok' | 'error'
var _qpProbeTimer  = null;
var _qpReciterIdx  = -1;
var _qpSurahNum    = 0;
var _qpAutoAdvance = false;
var _qpUserAborted = false;
// Intention réelle de lecture au moment du dernier _playQP() (reflète son
// propre calcul de shouldPlay) -- cf. commentaire dans le handler 'error'
// (injectQuranPlayerModal) qui l'utilise pour ne PAS jouer le Coran lors
// d'un simple chargement silencieux (_qpAutoLoadIfNeeded au boot, forcePlay
// = false) qui échoue sur .ogg et retente en .mp3.
var _qpShouldBePlaying = false;
var _qpSrcChanging    = false;
var _qpRestoring      = false;
var _pendingAutoStart = false;
var _audioUnlocked    = false;
// Extension en cours d'essai pour le récitateur "serveur" actif (C1..C10) :
// _buildQPUrl() essaie toujours .ogg en premier ; si la lecture échoue, le
// handler 'error' (dans injectQuranPlayerModal) bascule ceci sur 'mp3' et
// retente UNE fois avant d'afficher la bannière d'erreur. Remis à 'ogg' au
// début de chaque nouvelle lecture (_playQP).
var _qpTryExt = 'ogg';

// ── Variables Gestionnaire de récitateurs (USB / Cloud) : même raison que
//    ci-dessus — injectTechOptionsUI() (IIFE plus bas) appelle
//    initReciterManagerUI() -> _rmRenderCatalog() de façon SYNCHRONE pendant
//    son exécution. Si ces var restaient déclarées plus bas (avant leur
//    ancien emplacement juste au-dessus de initReciterManagerUI), elles
//    seraient encore `undefined` à ce moment précis (hoisting sans valeur
//    assignée) -> "Cannot read properties of undefined (reading 'length')"
//    sur _rmCatalog.length, qui interrompait tout le reste de l'IIFE
//    (ucOn/UC_EVT, _hideAutoplayUnlockModal, etc. jamais définis ensuite).
// URL de secours si JS_CUSTOM.ucReciterCatalogUrl est vide — y compris pour les
// installs déjà existantes dont le localStorage contient encore l'ancienne
// valeur '' enregistrée avant l'ajout de ce défaut (JS_CUSTOM_DEFAULTS n'est
// alors plus appliqué : voir Object.assign(JS_CUSTOM_DEFAULTS, _storedCustom),
// où _storedCustom gagne toujours). initReciterManagerUI() s'auto-corrige en
// réécrivant cette valeur dans JS_CUSTOM + localStorage dès qu'elle est vide.
var UC_RECITER_CATALOG_DEFAULT_URL = 'https://taoukitprayer.github.io/tawkit-reciters/catalog.json';
var UC_RECITER_CATALOG_URL    = '';   // chargé depuis JS_CUSTOM.ucReciterCatalogUrl
var _rmImportPollTimer        = null;
var _rmDownloadPollTimers     = {};   // id -> setInterval handle
var _rmCatalog                = [];   // dernier catalogue JSON chargé depuis le réseau
var _rmPollLastStatus         = {};   // id -> dernier statut vu (DIAGNOSTIC : ne logger que les transitions)
var _rmPollLastLogTs          = {};   // id -> timestamp du dernier heartbeat loggé pendant "downloading"
var _rmActiveDownloads        = {};   // id -> true pendant qu'un téléchargement est réellement en cours (pilote FLAG_KEEP_SCREEN_ON)

// Empêche/autorise l'écran de s'éteindre ou de passer en veille tant qu'au
// moins un téléchargement de récitateur est en cours : l'extinction d'écran
// coupe le worker WorkManager (cf. logs RM/DL_STATUS "paused" avec message
// isStopped=true sans DL_PAUSE_CLICK précédent). Ne bascule l'appel natif
// qu'au changement 0<->1 téléchargement actif (pas à chaque tick).
function _rmSetDownloadActive(id, active) {
    var hadAny = Object.keys(_rmActiveDownloads).length > 0;
    if (active) { _rmActiveDownloads[id] = true; } else { delete _rmActiveDownloads[id]; }
    var hasAny = Object.keys(_rmActiveDownloads).length > 0;
    if (hadAny !== hasAny && window.AndroidMobile && typeof window.AndroidMobile.setKeepScreenOn === 'function') {
        window.AndroidMobile.setKeepScreenOn(hasAny);
        _L('RM','KEEP_SCREEN_ON',{enabled:hasAny, activeIds:Object.keys(_rmActiveDownloads).join(',') || '(none)'});
    }
}

