let _iqamaZeroBlinkDurEditTarget = 'minaret';

function editIqamaZeroBlinkDurFunction(target) {
    if (!isInputDialogOpen) {
        _iqamaZeroBlinkDurEditTarget = target || 'minaret';
        const cur = (_iqamaZeroBlinkDurEditTarget === 'minaret')
            ? JS_CUSTOM.ucIqamaZeroMinaretBlinkDuration
            : JS_CUSTOM.ucIqamaZeroMihrabBlinkDuration;
        const lbl = (_iqamaZeroBlinkDurEditTarget === 'minaret')
            ? _dlgT('iqamaZeroBlinkMinaret')
            : _dlgT('iqamaZeroBlinkMihrab');
        inputDialogValue  = '';
        isInputDialogOpen = false;
        openInputDialogFunction(lbl, cur, "editIqamaZeroBlinkDurFunction('" + _iqamaZeroBlinkDurEditTarget + "')", true);
        return;
    }
    let val = parseInt(inputDialogValue, 10);
    if (isNaN(val) || val < 1) val = 10;
    if (_iqamaZeroBlinkDurEditTarget === 'minaret') {
        JS_CUSTOM.ucIqamaZeroMinaretBlinkDuration = val;
    } else {
        JS_CUSTOM.ucIqamaZeroMihrabBlinkDuration = val;
    }
    saveCustomSettingsFunction();
    refreshIqamaZeroBlinkUI();
}

function refreshIqamaZeroBlinkUI() {
    const cbMin  = document.getElementById('iqamaZeroMinaretBlinkCb');
    const cbMih  = document.getElementById('iqamaZeroMihrabBlinkCb');
    const durMin = document.getElementById('iqamaZeroMinaretBlinkDurBtn');
    const durMih = document.getElementById('iqamaZeroMihrabBlinkDurBtn');
    if (cbMin)  cbMin.checked    = (JS_CUSTOM.ucIqamaZeroMinaretBlinkEnabled  == 1);
    if (cbMih)  cbMih.checked    = (JS_CUSTOM.ucIqamaZeroMihrabBlinkEnabled   == 1);
    if (durMin) durMin.innerHTML = '⌛ ' + (parseInt(JS_CUSTOM.ucIqamaZeroMinaretBlinkDuration, 10) || 10) + 's';
    if (durMih) durMih.innerHTML = '⌛ ' + (parseInt(JS_CUSTOM.ucIqamaZeroMihrabBlinkDuration,  10) || 10) + 's';
}

