// Miroir "QP" (onglet ⚙ الإعدادات de quranPlayerModal, cf. injectQuranPlayerModal) :
// mêmes fonctions toggle/edit globales des deux côtés (elles ne dépendent pas
// de l'élément qui a déclenché l'appel), donc il suffit de recopier l'état
// affiché (checked / innerHTML) vers l'ID suffixé "QP" quand il existe dans le
// DOM. Pas de collision possible : les deux jeux d'IDs sont distincts.
function _qpSyncMirrorEl(origId) {
    const orig = document.getElementById(origId);
    const mir  = document.getElementById(origId + 'QP');
    if (!orig || !mir) return;
    if (orig.tagName === 'INPUT' && orig.type === 'checkbox') {
        mir.checked = orig.checked;
    } else {
        mir.innerHTML = orig.innerHTML;
    }
}

function refreshStartQuranBeforeAzanButtonsUI() {
    _qpSyncMirrorEl('startQuranBeforeAzanCheckbox');

    const tableHtml = _buildQuranAutoStartTableHtml();
    const host = document.getElementById('ucQuranAutoStartTableHost');
    if (host) host.innerHTML = tableHtml;
    const hostQP = document.getElementById('ucQuranAutoStartTableHostQP');
    if (hostQP) hostQP.innerHTML = tableHtml;
}

function toggleStartQuranBeforeAzanFunction() {
    JS_CUSTOM.ucStartQuranBeforeAzan = +(!JS_CUSTOM.ucStartQuranBeforeAzan);
    saveCustomSettingsFunction();
    document.getElementById('startQuranBeforeAzanCheckbox').checked = (JS_CUSTOM.ucStartQuranBeforeAzan == 1);
    _qpSyncMirrorEl('startQuranBeforeAzanCheckbox');
    _sqaFired = false;
}

function toggleStartQuranBeforeAzanPrayerDayFunction(prayerKey, dayIndex) {
    _toggleAutoStartPrayerDay(prayerKey, dayIndex);
    saveCustomSettingsFunction();
    refreshStartQuranBeforeAzanButtonsUI();
    _sqaFired = false;
}

// Plus de plancher à 10s ni de repli sur une valeur par défaut : 0 est une
// valeur valide et signifiante (= désactivé). Saisie et affichage en
// minutes ; stockage en secondes en interne (JS_CUSTOM[cfg.setting]),
// inchangé pour ne pas toucher aux comparaisons de seuils existantes
// (_getAutoStartDelaySeconds toujours utilisée par le countdown).
function editStartQuranBeforeAzanDelayFunction(prayerKey) {
    if (!isInputDialogOpen) {
        _sqaEditPrayerKey = prayerKey || _sqaEditPrayerKey || 'FAJR';
        const lang = _quranAutoStartLang();
        const nameMap = L_QURAN_PRAYER_NAMES[_sqaEditPrayerKey];
        const name = (nameMap && nameMap[lang]) || _sqaEditPrayerKey;
        const titleFn = L_QURAN_EDIT_DIALOG[lang] || L_QURAN_EDIT_DIALOG.EN;
        inputDialogValue  = '';
        isInputDialogOpen = false;
        openInputDialogFunction(titleFn(name), _getAutoStartDelayMinutes(_sqaEditPrayerKey), 'editStartQuranBeforeAzanDelayFunction()', true);
        return;
    }

    const cfg = _quranAutoStartConfig[_sqaEditPrayerKey] || _quranAutoStartConfig.FAJR;
    let minutes = parseInt(inputDialogValue, 10);
    if (isNaN(minutes) || minutes < 0) minutes = 0;

    JS_CUSTOM[cfg.setting] = minutes * 60;
    saveCustomSettingsFunction();
    refreshStartQuranBeforeAzanButtonsUI();
    _sqaFired = false;
}

function initLightProgrammingUI() {
    const container = document.getElementById('lightProgrammingContentContainer');
    if (!container) return;
    container.innerHTML = '';

    _lightProgramConfig.forEach(function(item, idx) {
        // Ligne principale
        const row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:6px 0;';
        var _delayHelp   = item.delayTitle     || 'التأخير قبل التنفيذ';
        var _jomaHelp    = item.jomaDelayTitle  || 'تأخير خاص بأذان الجمعة';
        var _extraHelp   = item.extraTitle      || 'المدة';
        var _urlHelp     = 'عنوان HTTP للتنفيذ';
        row.innerHTML =
            "<input type='checkbox' id='lightCfgCb_" + item.key + "' onchange=\"toggleLightProgrammingItemFunction('" + item.key + "');\">" +
            "<span style='min-width:16em;'>" + item.title + "</span>" +
            (item.delaySetting    ? "<span class='clickableWhiteClass' id='lightCfgDelayBtn_"     + item.key + "' title='" + _delayHelp  + "' data-help='" + _delayHelp  + "' style='white-space:nowrap;' onclick=\"editLightProgrammingDelayFunction('"     + item.key + "');\"></span>" : "") +
            (item.jomaDelaySetting? "<span class='clickableWhiteClass' id='lightCfgJomaDelayBtn_" + item.key + "' title='" + _jomaHelp   + "' data-help='" + _jomaHelp   + "' style='white-space:nowrap;' onclick=\"editLightProgrammingJomaDelayFunction('" + item.key + "');\"></span>" : "") +
            (item.extraSetting    ? "<span class='clickableWhiteClass' id='lightCfgExtraBtn_"     + item.key + "' title='" + _extraHelp  + "' data-help='" + _extraHelp  + "' style='white-space:nowrap;' onclick=\"editLightProgrammingExtraFunction('"     + item.key + "');\"></span>" : "") +
            "<span class='clickableWhiteClass' id='lightCfgBtn_" + item.key + "' title='" + _urlHelp + "' data-help='" + _urlHelp + "' style='flex:1;min-width:18em;text-align:left;direction:ltr;' onclick=\"editLightProgrammingUrlFunction('" + item.key + "');\"></span>" +
            "<span style='cursor:pointer;font-size:0.8em;padding:1px 7px;border:1px solid #446;border-radius:4px;color:#8cf;user-select:none;flex-shrink:0;' title='اختبار الرابط' onclick=\"ucTestLightBtnFunction('" + item.key + "');\">▶</span>";
        container.appendChild(row);

        // Ligne filtre prières (si prayersMaskSetting défini)
        if (item.prayersMaskSetting) {
            const prayerRow = document.createElement('div');
            prayerRow.id = 'lightCfgPrayerMask_' + item.key;
            prayerRow.className = 'ucTakbirTableRow';
            container.appendChild(prayerRow);
        }

        // Sélecteur de déclencheur (si triggerSetting défini) — tableau 3
        // colonnes x 2 lignes (labels / case "✕" exclusive), cf.
        // _buildLightTriggerTableHtml, même style que le masque prières.
        if (item.triggerSetting) {
            const trigRow = document.createElement('div');
            trigRow.id = 'lightCfgTrigRow_' + item.key;
            trigRow.style.cssText = 'padding:3px 0 4px 24px;';
            trigRow.innerHTML = "<div style='color:#aaa;font-size:.85em;padding-bottom:2px;'>موعد التشغيل :</div>"
                + _buildLightTriggerTableHtml(item);
            container.appendChild(trigRow);
        }

        if (idx < _lightProgramConfig.length - 1) container.appendChild(document.createElement('hr'));
    });

    // ─── Section : وميض عند نهاية العد التنازلي للإقامة ──────────────────
    const _iqamaZeroSection = document.createElement('div');
    _iqamaZeroSection.innerHTML =
        "<hr>" +
        "<div style='text-align:center;font-size:0.85em;color:#aaa;padding:2px 0 4px 0;'>وميض عند انتهاء العد التنازلي للإقامة</div>" +
        "<div style='display:flex;align-items:center;gap:8px;flex-wrap:nowrap;overflow-x:auto;margin:6px 0;'>" +
            "<input type='checkbox' id='iqamaZeroMinaretBlinkCb' style='flex-shrink:0;' onchange='toggleIqamaZeroMinaretBlinkFunction();'>" +
            "<span style='white-space:nowrap;flex-shrink:0;'>وميض المِأذنة عند الإقامة</span>" +
            "<span class='clickableWhiteClass' id='iqamaZeroMinaretBlinkDurBtn' title='مدة الوميض (ثواني)' style='white-space:nowrap;flex-shrink:0;' onclick=\"editIqamaZeroBlinkDurFunction('minaret');\"></span>" +
            "<span style='cursor:pointer;font-size:0.8em;padding:1px 7px;border:1px solid #664;border-radius:4px;color:#fc9;user-select:none;flex-shrink:0;white-space:nowrap;' title='اختبار وميض المِأذنة 10ث' onclick='ucTestMinaretBlinkFunction();'>⚡</span>" +
        "</div>" +
        "<div style='display:flex;align-items:center;gap:8px;flex-wrap:nowrap;overflow-x:auto;margin:6px 0;'>" +
            "<input type='checkbox' id='iqamaZeroMihrabBlinkCb' style='flex-shrink:0;' onchange='toggleIqamaZeroMihrabBlinkFunction();'>" +
            "<span style='white-space:nowrap;flex-shrink:0;'>وميض المحراب عند الإقامة</span>" +
            "<span class='clickableWhiteClass' id='iqamaZeroMihrabBlinkDurBtn' title='مدة الوميض (ثواني)' style='white-space:nowrap;flex-shrink:0;' onclick=\"editIqamaZeroBlinkDurFunction('mihrab');\"></span>" +
            "<span style='cursor:pointer;font-size:0.8em;padding:1px 7px;border:1px solid #664;border-radius:4px;color:#fc9;user-select:none;flex-shrink:0;white-space:nowrap;' title='اختبار وميض المحراب 10ث' onclick='ucTestMihrabBlinkFunction();'>⚡</span>" +
        "</div>";
    container.appendChild(_iqamaZeroSection);

    refreshLightProgrammingUI();
    refreshIqamaZeroBlinkUI();
    _initLightTooltips();
}

/* ── Tooltip tactile (Android) pour les boutons data-help ─────────────────
   • Desktop  : le `title` natif suffit (hover souris).
   • Android  : pas de hover → long-press 500 ms affiche un tooltip flottant.
   Le même tooltip sert tous les conteneurs qui ont des éléments [data-help]. */
function _initLightTooltips() {
    /* Créer (une seule fois) le div tooltip flottant */
    var tip = document.getElementById('_ucLightTip');
    if (!tip) {
        tip = document.createElement('div');
        tip.id = '_ucLightTip';
        tip.style.cssText =
            'position:fixed;background:rgba(20,20,20,.93);color:#eee;' +
            'padding:7px 12px;border-radius:8px;font-size:.82em;' +
            'direction:rtl;text-align:center;z-index:99999;' +
            'pointer-events:none;max-width:80vw;display:none;' +
            'box-shadow:0 2px 8px rgba(0,0,0,.5);';
        document.body.appendChild(tip);
    }

    var _tipTimer = null;

    function _showTip(text, touchEvt) {
        clearTimeout(_tipTimer);
        _tipTimer = setTimeout(function () {
            tip.textContent = text;
            tip.style.display = 'block';
            var touch = touchEvt.touches ? touchEvt.touches[0] : touchEvt;
            var x = Math.max(8, Math.min(touch.clientX - 60, window.innerWidth - 240));
            var y = touch.clientY - 70;
            if (y < 8) y = touch.clientY + 36;
            tip.style.left = x + 'px';
            tip.style.top  = y + 'px';
        }, 500);
    }

    function _hideTip() {
        clearTimeout(_tipTimer);
        tip.style.display = 'none';
    }

    /* Brancher sur le conteneur principal (délégation d'événements) */
    var container = document.getElementById('lightProgrammingContentContainer');
    if (!container) return;

    /* Supprimer les anciens listeners en clonant le nœud */
    var fresh = container.cloneNode(false);
    while (container.firstChild) fresh.appendChild(container.firstChild);
    container.parentNode.replaceChild(fresh, container);
    container = fresh;

    container.addEventListener('touchstart', function (evt) {
        var el = evt.target.closest ? evt.target.closest('[data-help]')
                                    : (evt.target.getAttribute('data-help') ? evt.target : null);
        if (el) _showTip(el.getAttribute('data-help'), evt);
    }, { passive: true });

    container.addEventListener('touchend',  _hideTip, { passive: true });
    container.addEventListener('touchmove', _hideTip, { passive: true });
}

function refreshLightProgrammingUI() {
    _lightProgramConfig.forEach(function(item) {
        const cb            = document.getElementById('lightCfgCb_' + item.key);
        const btn           = document.getElementById('lightCfgBtn_' + item.key);
        const delayBtn      = document.getElementById('lightCfgDelayBtn_' + item.key);
        const jomaDelayBtn  = document.getElementById('lightCfgJomaDelayBtn_' + item.key);
        const extraBtn      = document.getElementById('lightCfgExtraBtn_' + item.key);
        if (cb)            cb.checked            = (JS_CUSTOM[item.enabledSetting] == 1);
        if (btn)           btn.innerHTML         = '🔗 ' + (JS_CUSTOM[item.urlSetting] || '');
        if (delayBtn)      delayBtn.innerHTML      = '⏱ ' + ((parseInt(JS_CUSTOM[item.delaySetting], 10) || item.delayDefault || 0) + 's');
        if (jomaDelayBtn)  jomaDelayBtn.innerHTML  = '🕌 ' + ((parseInt(JS_CUSTOM[item.jomaDelaySetting], 10) || item.jomaDelayDefault || 0) + 's');
        if (extraBtn)      extraBtn.innerHTML      = '⌛ ' + ((parseInt(JS_CUSTOM[item.extraSetting], 10) || item.extraDefault || 0) + 's');

        // Filtre prières
        if (item.prayersMaskSetting) {
            const prayerRow = document.getElementById('lightCfgPrayerMask_' + item.key);
            if (prayerRow) {
                prayerRow.innerHTML = _buildLightPrayerMaskTableHtml(item);
            }
        }

        // Sélecteur de déclencheur — ré-affiche le tableau (case "✕" exclusive)
        if (item.triggerSetting) {
            var trig = JS_CUSTOM[item.triggerSetting] || item.trigger;
            var trigTableHost = document.getElementById('lightCfgTrigRow_' + item.key);
            if (trigTableHost) {
                trigTableHost.innerHTML = "<div style='color:#aaa;font-size:.85em;padding-bottom:2px;'>موعد التشغيل :</div>"
                    + _buildLightTriggerTableHtml(item);
            }
            // Mettre à jour le libellé du bouton délai selon le déclencheur actif
            var dBtn = document.getElementById('lightCfgDelayBtn_' + item.key);
            if (dBtn) {
                var _dHelp = (trig === 'beforeAzan')    ? 'تشغيل المحراب قبل الأذان بـ (ثواني)'
                           : (trig === 'beforeIqama')   ? 'تشغيل المحراب قبل الإقامة بـ (ثواني)'
                           : 'تشغيل المحراب بعد إغلاق نافذة الأذان بـ (ثواني)';
                dBtn.title = _dHelp;
                dBtn.setAttribute('data-help', _dHelp);
            }
        }
    });
}

function toggleLightPrayerMaskFunction(itemKey, prayerIdx) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item || !item.prayersMaskSetting) return;
    const chars = String(JS_CUSTOM[item.prayersMaskSetting] || '11111').split('');
    while (chars.length < 5) chars.push('1');
    chars[prayerIdx] = (chars[prayerIdx] === '1') ? '0' : '1';
    JS_CUSTOM[item.prayersMaskSetting] = chars.join('');
    saveCustomSettingsFunction();
    // Pas besoin de refreshLightProgrammingUI complet — juste re-render la ligne prières
    refreshLightProgrammingUI();
}

// Colonne Jumu'a dédiée (booléen séparé, cf. jomoaMaskSetting) -- même
// principe que toggleLightPrayerMaskFunction ci-dessus, mais mihrabOn ET
// mihrabOff partagent le MÊME réglage (ucLightMihrabOnJomoa) : basculer
// depuis l'une ou l'autre ligne change la même valeur, la fermeture suit
// donc automatiquement la décision d'ouverture pour Jumu'a.
function toggleLightPrayerMaskJomoaFunction(itemKey) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item || !item.jomoaMaskSetting) return;
    JS_CUSTOM[item.jomoaMaskSetting] = (JS_CUSTOM[item.jomoaMaskSetting] == 1) ? 0 : 1;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function toggleLightProgrammingItemFunction(itemKey) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item) return;
    JS_CUSTOM[item.enabledSetting] = +(JS_CUSTOM[item.enabledSetting] != 1);
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function toggleLightItemTriggerFunction(itemKey, value) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item || !item.triggerSetting) return;
    // Radio behavior : l'autre case se décoche automatiquement via refreshLightProgrammingUI
    JS_CUSTOM[item.triggerSetting] = value;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingUrlFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item) return;
        _lightEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(_lightT(item, 'title'), JS_CUSTOM[item.urlSetting] || '', "editLightProgrammingUrlFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightEditKey; });
    if (!currentItem) return;

    const val = String(inputDialogValue || '').trim();
    JS_CUSTOM[currentItem.urlSetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingDelayFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item || !item.delaySetting) return;
        _lightDelayEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(_lightT(item, 'delayTitle'), JS_CUSTOM[item.delaySetting] || item.delayDefault || 0, "editLightProgrammingDelayFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightDelayEditKey; });
    if (!currentItem || !currentItem.delaySetting) return;

    let val = parseInt(inputDialogValue, 10);
    if (isNaN(val) || val < 0) val = currentItem.delayDefault || 0;
    JS_CUSTOM[currentItem.delaySetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

