// prévu pour quelques sourates -- l'accès hors-limites renvoie alors
// `undefined`, et sa concaténation directe dans le HTML (_qrRenderPage plus
// bas) affichait littéralement le mot "undefined" à la place du verset
// (retour utilisateur 25/08/2026, ex. Ash-Shura verset 51). _qrAyahText()
// centralise la détection (texte manquant/vide/littéralement "undefined")
// pour les DEUX endroits qui lisent surah.ayats[aIdx] (_qrRenderPage et
// _qrSearch) : ne corrige pas la donnée source (hors de portée ici, fichier
// distant), mais garantit qu'aucune des deux vues ne peut plus jamais
// afficher ce mot au lieu du texte.
var _QR_AYAH_MISSING_TEXT = '⚠ نص هذه الآية غير متوفر حالياً في هذه الرواية';
function _qrAyahTextOrNull(rawText) {
    if (typeof rawText !== 'string') return null;
    var t = rawText.trim();
    if (!t || t === 'undefined' || t === 'null') return null;
    return rawText;
}

function _qrTajweedHtml(sIdx, aIdx, rawText) {
    if (!JS_CUSTOM.ucQrTajweedColors) return rawText;
    if (JS_CUSTOM.ucRiwayaActive !== 'qaloun') return rawText; // dataset limité à Qaloun pour l'instant
    var TJ = window.QR_TAJWEED_QALOUN;
    if (!TJ || !TJ.data || !TJ.data[sIdx]) return rawText;
    var annots = TJ.data[sIdx][aIdx];
    if (!annots || !annots.length) return rawText;
    var sorted = annots.slice().sort(function(a, b) { return a[1] - b[1]; });
    var html = '', pos = 0;
    for (var i = 0; i < sorted.length; i++) {
        var ruleIdx = sorted[i][0], start = sorted[i][1], end = sorted[i][2];
        if (start < pos || end > rawText.length) continue; // garde-fou défensif (chevauchement/désync inattendu)
        if (start > pos) html += rawText.slice(pos, start);
        var ruleName = TJ.rules[ruleIdx];
        html += '<span class="qrTaj qrTaj-' + ruleName + '">' + rawText.slice(start, end) + '</span>';
        _qrLastPageTajRules[ruleName] = true;
        pos = end;
    }
    html += rawText.slice(pos);
    return html;
}

// Infos affichées dans la bande de légende + la modale détaillée. Ordre fixe
// (pas l'ordre d'apparition) pour une légende stable d'une page à l'autre.
// Définitions générales du tajwid (manuels usuels) — indépendantes de notre
// classificateur, qui lui reste expérimental (cf. commentaire plus haut).
// hamzat_wasl n'apparaît jamais dans les données actuelles (Qaloun.json
// n'utilise pas le caractère ٱ dont dépend cette règle) — exclue de la liste.
var _QR_TAJ_ORDER = [
    'ghunnah', 'idghaam_ghunnah', 'idghaam_no_ghunnah', 'idghaam_shafawi',
    'idghaam_mutajanisayn', 'idghaam_mutaqaribayn', 'ikhfa', 'ikhfa_shafawi',
    'iqlab', 'qalqalah', 'madd_2', 'madd_246', 'madd_muttasil',
    'madd_munfasil', 'madd_6', 'lam_shamsiyyah', 'silent'
];
var _QR_TAJ_INFO = {
    ghunnah:              { label: 'غنة',                 desc: 'غنة النون والميم المشددتين، تمتد بمقدار حركتين في الخيشوم.' },
    idghaam_ghunnah:      { label: 'إدغام بغنة',           desc: 'إدغام النون الساكنة أو التنوين في أحد حروف (ي ن م و) مع بقاء الغنة.' },
    idghaam_no_ghunnah:   { label: 'إدغام بلا غنة',        desc: 'إدغام النون الساكنة أو التنوين في اللام أو الراء بدون غنة.' },
    idghaam_shafawi:      { label: 'إدغام شفوي',           desc: 'إدغام الميم الساكنة في ميم بعدها مع غنة.' },
    idghaam_mutajanisayn: { label: 'إدغام متجانسين',       desc: 'إدغام حرفين من نفس المخرج (مثل الدال في التاء).' },
    idghaam_mutaqaribayn: { label: 'إدغام متقاربين',       desc: 'إدغام حرفين متقاربين في المخرج والصفة (مثل اللام في الراء، أو القاف في الكاف).' },
    ikhfa:                { label: 'إخفاء',                 desc: 'إخفاء النون الساكنة أو التنوين مع غنة عند أحد الحروف الخمسة عشر المتبقية.' },
    ikhfa_shafawi:        { label: 'إخفاء شفوي',           desc: 'إخفاء الميم الساكنة عند الباء مع غنة.' },
    iqlab:                { label: 'إقلاب',                 desc: 'قلب النون الساكنة أو التنوين ميمًا مخفاة عند الباء.' },
    qalqalah:             { label: 'قلقلة',                 desc: 'اضطراب الصوت عند النطق بأحد حروف (ق ط ب ج د) الساكنة.' },
    madd_2:               { label: 'مد طبيعي',              desc: 'مد بمقدار حركتين، بلا سبب زائد.' },
    madd_246:             { label: 'مد عارض للسكون',        desc: 'مد يقع قبل الوقف بمقدار حركتين أو أربع أو ست.' },
    madd_muttasil:        { label: 'مد واجب متصل',          desc: 'حرف المد والهمزة في كلمة واحدة، بمقدار أربع أو خمس حركات.' },
    madd_munfasil:        { label: 'مد جائز منفصل',         desc: 'حرف المد آخر كلمة والهمزة أول الكلمة التالية، بمقدار أربع أو خمس حركات.' },
    madd_6:                { label: 'مد لازم',               desc: 'مد بمقدار ست حركات بسبب سكون أصلي بعد حرف المد.' },
    lam_shamsiyyah:       { label: 'لام شمسية',             desc: 'لام "ال" التعريف تُدغم في الحرف الشمسي الذي بعدها فلا تُنطق.' },
    silent:               { label: 'حرف ساكن لا يُنطق',      desc: 'حرف مرسوم في الكتابة لكنه لا يُنطق في الوصل أو الوقف.' }
};

function _qrBuildTajLegendRow() {
    var keys = [];
    for (var i = 0; i < _QR_TAJ_ORDER.length; i++) {
        if (_qrLastPageTajRules[_QR_TAJ_ORDER[i]]) keys.push(_QR_TAJ_ORDER[i]);
    }
    if (!keys.length) return '';
    var html = '<div class="qrTajLegendRow" id="qrTajLegendRow" title="اضغط لمعرفة المزيد عن ألوان أحكام التجويد">';
    for (var j = 0; j < keys.length; j++) {
        var info = _QR_TAJ_INFO[keys[j]];
        if (!info) continue;
        html += '<span class="qrTajLegendChip"><span class="qrTajDot qrTaj-' + keys[j] + '"></span>' + info.label + '</span>';
    }
    html += '</div>';
    return html;
}

function _qrBuildTajInfoPanel() {
    var body = document.getElementById('qrTajInfoBody');
    if (!body) return;
    var html = '<div class="qrTajInfoIntro">تلوين تجريبي لأحكام التجويد على رواية قالون، لتسهيل المراجعة أثناء القراءة.</div>';
    for (var i = 0; i < _QR_TAJ_ORDER.length; i++) {
        var key = _QR_TAJ_ORDER[i], info = _QR_TAJ_INFO[key];
        if (!info) continue;
        html += '<div class="qrTajInfoRow">'
              + '<span class="qrTajDot qrTaj-' + key + '"></span>'
              + '<div class="qrTajInfoText"><div class="qrTajInfoLabel">' + info.label + '</div>'
              + '<div class="qrTajInfoDesc">' + info.desc + '</div></div>'
              + '</div>';
    }
    body.innerHTML = html;
}

function _qrOpenTajInfo() {
    var panel = document.getElementById('qrTajInfoPanel');
    if (!panel) return;
    if (!panel.dataset.built) { _qrBuildTajInfoPanel(); panel.dataset.built = '1'; }
    panel.classList.remove('qrFahrasHidden');
}

function _qrCloseTajInfo() {
    var panel = document.getElementById('qrTajInfoPanel');
    if (panel) panel.classList.add('qrFahrasHidden');
}

function _qpSwitchTab(tab) {
    // 'settings' n'est pas persisté comme dernier onglet visité au même titre que
    // 'audio'/'read' : ouvrir directement sur le mini-panneau de réglages à
    // chaque lancement serait surprenant — on retombe alors sur 'audio'.
    localStorage.setItem('tawkit_qp_last_tab', (tab === 'settings') ? 'audio' : tab);
    var audioBody    = document.getElementById('qpAudioTabBody');
    var readBody     = document.getElementById('qpReadTabBody');
    var settingsBody = document.getElementById('qpSettingsTabBody');
    var tabAudio     = document.getElementById('qpTabAudio');
    var tabRead      = document.getElementById('qpTabRead');
    var tabSettings  = document.getElementById('qpTabSettings');
    if (audioBody)    audioBody.style.display    = (tab === 'audio')    ? '' : 'none';
    if (readBody)     readBody.style.display     = (tab === 'read')     ? 'flex' : 'none';
    if (settingsBody) settingsBody.style.display = (tab === 'settings') ? '' : 'none';
    if (tabAudio)     tabAudio.classList.toggle('qpTabActive', tab === 'audio');
    if (tabRead)      tabRead.classList.toggle('qpTabActive', tab === 'read');
    if (tabSettings)  tabSettings.classList.toggle('qpTabActive', tab === 'settings');
    if (tab === 'settings') {
        // initQuranRecitersUI() ne s'exécute normalement qu'une fois au chargement
        // (avant l'injection lazy de ce modal, donc avant que #quranRecitersContainerQP
        // n'existe) — on la rappelle ici pour construire les lignes du miroir la
        // première fois que cet onglet est ouvert (idempotent, ~10 lignes).
        // refreshStartQuranBeforeAzanButtonsUI()/refreshQuranServerUI() ont été
        // étendues pour aussi resynchroniser les IDs miroirs "...QP".
        initQuranRecitersUI();
        refreshStartQuranBeforeAzanButtonsUI();
        refreshQuranServerUI();
        // Idem pour le gestionnaire de récitateurs (USB/cloud) : construit
        // #rmInstalledContainerQP / #rmCatalogContainerQP la première fois.
        initReciterManagerUI();
    }
    // En-tête : boutons A−/A+ et ▲/▼ (plein-texte) visibles sur l'onglet Lecture,
    // sizeToggle sur l'onglet Audio. sizeToggle a sa propre règle @media portrait —
    // on force 'none' en mode lecture pour qu'il reste caché même en portrait.
    var sizeToggleEl  = document.getElementById('quranPlayerSizeToggle');
    var fontCtrlEl    = document.getElementById('qpReadFontCtrl');
    var navToggleEl   = document.getElementById('qpReadNavToggle');
    if (sizeToggleEl) sizeToggleEl.style.display = (tab === 'read') ? 'none'  : '';
    if (fontCtrlEl)   fontCtrlEl.style.display   = (tab === 'read') ? 'flex'  : 'none';
    if (navToggleEl)  navToggleEl.style.display  = (tab === 'read') ? 'block' : 'none';
    if (tab === 'read') {
        // Applique l'état mémorisé (plein-texte ou normal) en entrant dans l'onglet.
        _qrApplyNavHidden(_qrNavHiddenGet());
        if (!_qrCatalogLoaded) { _qrLoadCatalog(); } else { _qrRenderRiwayaButton(); }
        _qrLoadActiveRiwayaAndRender();
    } else {
        // En quittant l'onglet lecture, restaurer visuellement les barres SANS
        // écraser localStorage : au prochain retour sur القراءة, _qrNavHiddenGet()
        // relira l'état sauvegardé et le réappliquera (plein-texte persistant).
        var _rTabs = document.getElementById('quranPlayerTabs');
        var _rNRow = document.getElementById('qpReadNavRow');
        if (_rTabs) _rTabs.style.display = '';
        if (_rNRow) _rNRow.style.display = '';
    }
}
window._qpSwitchTab = _qpSwitchTab;

// Vrai si le bridge natif Android existe et expose cette méthode. L'app
// tourne aussi en simple page web (navigateur, cf. CLAUDE.md racine — pas
// que dans le WebView Android), donc window.AndroidMobile peut être
// totalement absent : tout appel direct dessus y lèverait une exception
// non rattrapée ("Cannot read properties of undefined").
function _ucHasNative(methodName) {
    return !!(window.AndroidMobile && typeof window.AndroidMobile[methodName] === 'function');
}
// Exposition globale explicite : cette déclaration est en réalité imbriquée
// dans la closure de injectTechOptionsUI() (IIFE plus haut dans le fichier),
// pas au vrai top-level du script malgré l'absence d'indentation visible —
// invisible depuis toute AUTRE IIFE top-level (ex. injectAzanCatalogFeature,
// bien plus loin dans le fichier) qui appelle _ucHasNative(...) en identifiant
// nu. Confirmé par analyse AST (acorn) : ReferenceError "_ucHasNative is not
// defined" reproductible à chaque appel depuis injectAzanCatalogFeature.
// window.X = X rend la fonction résolvable par la chaîne de portée (repli sur
// l'objet global) depuis n'importe quel autre closure du fichier.
window._ucHasNative = _ucHasNative;

// ── Stockage natif des textes de riwaya (getExternalFilesDir/riwayat/) —
// remplace l'ancien cache IndexedDB + le flag JS_CUSTOM.ucRiwayaInstalled :
// un fichier sur disque, scanné par RiwayaManager (Kotlin), est le seul état
// "installé" — survit aux mises à jour de l'appli. Repli navigateur (pas de
// bridge natif) : présence dans localStorage (cf. _qrDownloadRiwaya). ──────
var _QR_BROWSER_KEY_PREFIX = 'UC_QR_BROWSER_';
function _qrGetInstalledIds() {
    if (_ucHasNative('listInstalledRiwaya')) {
        try { return JSON.parse(window.AndroidMobile.listInstalledRiwaya()) || []; }
        catch (e) { return []; }
    }
    var ids = [];
    ['hafs', 'qaloun', 'warsh'].forEach(function(id) {
        try { if (localStorage.getItem(_QR_BROWSER_KEY_PREFIX + id)) ids.push(id); } catch (e) {}
    });
    return ids;
}

// ── Catalogue riwayatCatalog.json (même format que catalog.json récitateurs :
// {"riwayat":[{id,name,url,size,version}]}) ────────────────────────────────
// Catalogue par défaut (intégré, pas besoin d'héberger un riwayatCatalog.json
// séparé) : les 3 riwayat hébergées sur les releases GitHub de l'utilisateur.
// ucRiwayaCatalogUrl (réglages) reste disponible pour pointer vers un
// catalogue distant si l'utilisateur préfère gérer les URLs à distance.
// Hébergées sur GitHub Pages (CORS OK), et non en Release GitHub (qui redirige
// en 302 vers objects.githubusercontent.com sans en-tête CORS -> fetch() échoue).
var _QR_DEFAULT_CATALOG = [
    { id: 'hafs',   name: 'حفص عن عاصم',  url: 'https://taoukitprayer.github.io/riwayat/Hafs.json',   size: '1.3 MB',  version: '1.0' },
    { id: 'qaloun', name: 'قالون عن نافع', url: 'https://taoukitprayer.github.io/riwayat/Qaloun.json', size: '1.34 MB', version: '1.0' },
    { id: 'warsh',  name: 'ورش عن نافع',   url: 'https://taoukitprayer.github.io/riwayat/Warsh.json',  size: '1.35 MB', version: '1.0' }
];

function _qrLoadCatalog() {
    _qrCatalogLoaded = true;
    if (!JS_CUSTOM.ucRiwayaCatalogUrl) {
        _qrCatalog = _QR_DEFAULT_CATALOG;
        _L('QR', 'CATALOG_DEFAULT', { count: _qrCatalog.length });
        _qrRenderRiwayaButton();
        return;
    }
    fetch(JS_CUSTOM.ucRiwayaCatalogUrl, { cache: 'no-store' })
        .then(function(r) { return r.json(); })
        .then(function(json) {
            _qrCatalog = Array.isArray(json.riwayat) ? json.riwayat : _QR_DEFAULT_CATALOG;
            _L('QR', 'CATALOG_LOADED', { count: _qrCatalog.length });
            _qrRenderRiwayaButton();
        })
        .catch(function(e) {
            _qrCatalog = _QR_DEFAULT_CATALOG;
            _L('QR', 'CATALOG_ERROR_FALLBACK', { error: e.message });
            _qrRenderRiwayaButton();
        });
}

// Libellé générique du bouton qpReadRiwayaBtn tant qu'aucune riwaya n'est
// encore INSTALLÉE (première installation, ou après un reset qui a purgé les
// fichiers téléchargés -- JS_CUSTOM.ucRiwayaActive vaut toujours 'hafs' par
// défaut, cf. JS_CUSTOM_DEFAULTS, mais ça ne veut pas dire hafs.json est déjà
// sur l'appareil). "Riwaya" n'a pas d'équivalent usuel en français/anglais,
// d'où la translittération telle quelle hors arabe (cf. convention T[_ucLang()]
// || T.EN de _ucLang() en tête de fichier).
var _QR_RIWAYA_PLACEHOLDER = { AR: 'الرواية', FR: 'Riwaya', EN: 'Riwaya' };

// Met à jour le libellé de #qpReadRiwayaBtn : nom de la riwaya active si elle
// est réellement installée, sinon le libellé générique ci-dessus. Élément
// statique du gabarit (jamais régénéré) -- on ne touche que son texte.
function _qrRenderRiwayaButton() {
    var btn = document.getElementById('qpReadRiwayaBtn');
    if (!btn) return;
    var id = JS_CUSTOM.ucRiwayaActive;
    var installed = id && _qrGetInstalledIds().indexOf(id) !== -1;
    btn.textContent = installed ? (_QR_LABELS[id] || id) : (_QR_RIWAYA_PLACEHOLDER[_ucLang()] || _QR_RIWAYA_PLACEHOLDER.EN);
}

// Reconstruit le corps de la modale #qrRiwayaPanel (3 boutons Hafs/Qaloun/
// Warsh) à chaque ouverture -- cf. _qrOpenRiwayaPanel() -- pour refléter
// l'état d'installation/sélection courant à coup sûr.
function _qrRenderRiwayaModalBody() {
    var body = document.getElementById('qrRiwayaBody');
    if (!body) return;
    var ids = ['hafs', 'qaloun', 'warsh'];
    var installedIds = _qrGetInstalledIds();
    body.innerHTML = '';
    ids.forEach(function(id) {
        var catEntry  = _qrCatalog.find(function(c) { return c.id === id; });
        var installed = installedIds.indexOf(id) !== -1;
        var row = document.createElement('div');
        row.className = 'qrFahrasRow' + (JS_CUSTOM.ucRiwayaActive === id && installed ? ' qrRiwayaRowActive' : '');
        row.innerHTML = '<span class="qrFahrasRowLabel">' + (_QR_LABELS[id] || id) + '</span>'
                       + (installed ? '' : '<span class="qrDlBadge">&#8595;</span>');
        row.addEventListener('click', function() {
            _qrCloseRiwayaPanel();
            _qrSelectRiwaya(id, catEntry);
        });
        body.appendChild(row);
    });
}

function _qrOpenRiwayaPanel() {
    var panel = document.getElementById('qrRiwayaPanel');
    if (!panel) return;
    _qrRenderRiwayaModalBody();
    panel.classList.remove('qrFahrasHidden');
}
function _qrCloseRiwayaPanel() {
    var panel = document.getElementById('qrRiwayaPanel');
    if (panel) panel.classList.add('qrFahrasHidden');
}

function _qrSelectRiwaya(id, catEntry) {
    var installed = _qrGetInstalledIds().indexOf(id) !== -1;
    if (installed) {
        JS_CUSTOM.ucRiwayaActive = id;
        saveCustomSettingsFunction();
        _qrRenderRiwayaButton();
        _qrLoadActiveRiwayaAndRender();
        return;
    }
    if (!catEntry || !catEntry.url) {
        _L('QR', 'SELECT_NO_CATALOG_ENTRY', { id: id });
        var msgEl = document.getElementById('qpReadStateMsg');
        if (msgEl) msgEl.textContent = 'الرابط غير متوفر بعد لهذه الرواية';
        return;
    }
    _qrDownloadRiwaya(id, catEntry);
}

var _qrDownloading = {};   // id -> true pendant qu'un téléchargement natif est en cours
var _qrPollTimers  = {};   // id -> setInterval id du polling de statut

function _qrDownloadRiwaya(id, catEntry) {
    var msgEl = document.getElementById('qpReadStateMsg');
    if (msgEl) msgEl.textContent = 'جارٍ تحميل ' + (_QR_LABELS[id] || id) + '...';
    _L('QR', 'DL_START', { id: id, url: catEntry.url });
    if (_qrDownloading[id]) return;
    _qrDownloading[id] = true;

    function _settleOk() {
        delete _qrDownloading[id];
        JS_CUSTOM.ucRiwayaActive = id;
        saveCustomSettingsFunction();
        _qrRenderRiwayaButton();
        _qrLoadActiveRiwayaAndRender();
        _L('QR', 'DL_DONE', { id: id });
    }
    function _settleError(message) {
        delete _qrDownloading[id];
        _L('QR', 'DL_ERROR', { id: id, error: message });
        if (msgEl) msgEl.textContent = 'تعذّر التحميل: ' + (message || '');
        // JS_CUSTOM.ucRiwayaActive n'a pas bougé sur un échec (seul _settleOk
        // le fait) : #qpReadRiwayaBtn n'affichait donc déjà pas le nom de la
        // riwaya visée avant cet échec. Rappel par cohérence uniquement (même
        // réflexe que _settleOk juste au-dessus).
        _qrRenderRiwayaButton();
    }

    if (_ucHasNative('downloadRiwayaItem')) {
        window.AndroidMobile.downloadRiwayaItem(id, catEntry.url);
        _qrPollTimers[id] = setInterval(function() {
            var st;
            try { st = JSON.parse(window.AndroidMobile.getRiwayaDownloadStatus(id)); }
            catch (e) { return; }
            if (st.status === 'done') {
                clearInterval(_qrPollTimers[id]); delete _qrPollTimers[id];
                _settleOk();
            } else if (st.status === 'error') {
                clearInterval(_qrPollTimers[id]); delete _qrPollTimers[id];
                _settleError(st.message);
            }
        }, 500);
        return;
    }

    // Repli navigateur (pas de bridge natif, ex. test local Chrome/Windows) :
    // fetch() direct vers l'URL distante (CORS OK, hébergement GitHub Pages)
    // + cache dans localStorage (pas d'IndexedDB : plus simple, taille ~1.3 Mo
    // par riwaya, largement sous le quota localStorage habituel).
    fetch(catEntry.url, { cache: 'no-store' })
        .then(function(r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
        .then(function(text) {
            try { localStorage.setItem(_QR_BROWSER_KEY_PREFIX + id, text); }
            catch (e) { _L('QR', 'DL_CACHE_SKIP', { id: id, error: e.message }); }
            _settleOk();
        })
        .catch(function(e) { _settleError(e.message); });
}

// ── Chargement de la riwaya active depuis IndexedDB + rendu ────────────────
// Schéma confirmé des fichiers Hafs.json / Qaloun.json / Warsh.json :
//   [ { name: "سُورَةُ ...", basmalah?: "بِسۡمِ ٱللَّهِ..."، ayats: ["...", ...] }, ... ]
// — un tableau de 114 sourates (index 0 = Al-Fatiha … 113 = An-Nas), chaque
// "ayats" est un tableau de textes de versets SANS numéro ni champ juz
// (le numéro de verset = position dans le tableau + 1). Seules Al-Fatiha et
// At-Tawbah n'ont pas de champ "basmalah" (Al-Fatiha : la basmala est son
// verset 1 ; At-Tawbah : pas de basmala dans le texte coranique).
// NB : Hafs compte 6236 versets au total, Qaloun/Warsh 6214 — le découpage
// des versets diffère légèrement selon la riwaya (convention de comptage).
// La table des جزء ci-dessous est calibrée sur la numérotation Hafs ; pour
// Qaloun/Warsh elle reste une bonne approximation (à 1-2 versets près sur
// certains جزء) tant qu'aucune table dédiée à ces riwayat n'est disponible.
function _qrLoadActiveRiwayaAndRender() {
    var msgEl = document.getElementById('qpReadStateMsg');
    var id = JS_CUSTOM.ucRiwayaActive;
    // Contenu lu directement via le bridge natif (String), pas fetch(file://...) :
    // l'API Fetch de Chromium/WebView rejette le schéma file:// côté client avant
    // toute requête ("Failed to fetch", aucune trace réseau/console) — cf.
    // RiwayaManager.readContent()/MobileJsBridge.getRiwayaContent(). Repli
    // navigateur (pas de bridge natif) : localStorage, rempli par _qrDownloadRiwaya.
    var raw = '';
    if (id) {
        if (_ucHasNative('getRiwayaContent')) raw = window.AndroidMobile.getRiwayaContent(id);
        else { try { raw = localStorage.getItem(_QR_BROWSER_KEY_PREFIX + id) || ''; } catch (e) { raw = ''; } }
    }
    if (!raw) {
        _qrActiveData = null;
        if (msgEl) { msgEl.style.display = ''; msgEl.textContent = 'اختر رواية أعلاه لتحميلها وقراءتها'; }
        return;
    }
    try {
        _qrActiveData = JSON.parse(raw);
    } catch (e) {
        _qrActiveData = null;
        if (msgEl) { msgEl.style.display = ''; msgEl.textContent = 'خطأ تحميل محلي: ' + e.message; }
        return;
    }
    _qrPageBoundaries = _qrBuildSafePageBoundaries(_qrActiveData);
    if (msgEl) { msgEl.style.display = 'none'; }
    var _savedRaw  = localStorage.getItem(_QR_PAGE_IDX_KEY);
    var _savedPage = parseInt(_savedRaw, 10);
    _qrGoToPage(isNaN(_savedPage) ? 0 : _savedPage);
    // Première visite jamais enregistrée : ouvre le fahras plein écran au lieu
    // d'atterrir silencieusement page 1 — même effet "premium" que les autres
    // applis Mushaf qui s'ouvrent directement sur leur sommaire.
    if (_savedRaw === null) _qrOpenFahras('surah');
}

// Début de chaque جزء : [numéroSourate(1-114), numéroVerset(1-based)] — numérotation Hafs.
var _QR_JUZ_STARTS = [
    [1, 1], [2, 142], [2, 253], [3, 93], [4, 24], [4, 148], [5, 82], [6, 111],
    [7, 88], [8, 41], [9, 93], [11, 6], [12, 53], [15, 1], [17, 1], [18, 75],
    [21, 1], [23, 1], [25, 21], [27, 56], [29, 46], [33, 31], [36, 28], [39, 32],
    [41, 47], [46, 1], [51, 31], [58, 1], [67, 1], [78, 1]
];

var _QR_ARABIC_DIGITS = ['٠','١','٢','٣','٤','٥','٦','٧','٨','٩'];
function _qrToArabicDigits(n) {
    // Respecte le réglage global ucIsArabicDigits (même logique que
    // convertToArabicDigitsFunction dans m2body.js) : par défaut (0) on garde
    // les chiffres occidentaux 0123456789, sans forcer les chiffres arabo-indiens.
    if (!JS_DATA.ucIsArabicDigits) return String(n);
    return String(n).split('').map(function(c) {
        var d = parseInt(c, 10);
        return isNaN(d) ? c : _QR_ARABIC_DIGITS[d];
    }).join('');
}

// Normalisation pour la recherche : retire tachkîl/tatwîl, uniformise alif/hamza/ta marbouta/alif maqsoura.
function _qrNormalizeArabic(s) {
    if (!s) return '';
    return s
        .replace(/[ً-ْٖ-ٰٟۖ-ۭـ]/g, '') // tachkîl + tatwîl
        .replace(/[إأآٱا]/g, 'ا')
        .replace(/ى/g, 'ي')
        .replace(/ة/g, 'ه')
        .replace(/ؤ/g, 'و')
        .replace(/ئ/g, 'ي')
        .replace(/\s+/g, ' ')
        .trim();
}

// ── Vue paginée (mode صفحة) ───────────────────────────────────────────────
// Navigue vers la page pageIdx et persiste le choix.
function _qrGoToPage(pageIdx) {
    if (!_qrPageBoundaries.length) return;
    pageIdx = Math.max(0, Math.min(_qrPageBoundaries.length - 1, pageIdx));
    _qrCurrentPage = pageIdx;
    _qrRenderPage(pageIdx);
    try { localStorage.setItem(_QR_PAGE_IDX_KEY, pageIdx); } catch (e) {}
}

// Index (0-based) de la page où commence surahIdx0 (ayat 0 de cette sourate),
// dans le référentiel de _qrPageBoundaries de la riwaya ACTIVE (déjà
// reprojeté par _qrBuildSafePageBoundaries si besoin -- cf. son commentaire) :
// ne pas utiliser _QR_FAHRAS[surahIdx0].page directement, ce champ reste
// calé sur la numérotation Hafs d'origine. _QR_PAGE_STARTS ne contient une
// entrée que là où une PAGE commence, pas à chaque sourate -- plusieurs
// sourates courtes en fin de Coran partagent une même page sans saut de
// page entre elles (ex. page 604 : Al-Ikhlas + Al-Falaq + An-Nas) : on
// cherche donc la dernière borne <= (surahIdx0, 0), pas une égalité stricte
// sur .s.
function _qrPageIndexForSurahStart(surahIdx0) {
    var result = 0;
    for (var i = 0; i < _qrPageBoundaries.length; i++) {
        var b = _qrPageBoundaries[i];
        if (b.s > surahIdx0) break;
        if (b.s < surahIdx0 || b.a === 0) result = i;
    }
    return result;
}
// Saute directement au début de la sourate surahIdx0 (boutons qrSurahPrev/
// qrSurahNext du pied de page).
function _qrGoToSurah(surahIdx0) {
    var pageIdx = _qrPageIndexForSurahStart(surahIdx0);
    if (pageIdx >= 0) _qrGoToPage(pageIdx);
}

// Affiche une page du Mushaf Qaloun avec présentation premium :
//   • barre supérieure  : جزء / nom(s) de sourate(s) / marque de hizb
//   • bannière de sourate décorative avec badge مكية/مدنية et compteur d'ayats
//   • corps parchemin : texte justifié, numéros d'ayats ornés, marque ۩ pour les sajdah
//   • pied de page RTL : bouton DROITE = page suivante (convention Mushaf)
function _qrRenderPage(pageIdx) {
    var area = document.getElementById('qpReadTextArea');
    if (!area || !_qrActiveData || !_qrPageBoundaries.length) return;

    _qrLastPageTajRules = {}; // repeuplée par _qrTajweedHtml() pendant la boucle des versets ci-dessous
    _qrCurrentPage = pageIdx;
    var total    = _qrPageBoundaries.length;
    var pageNum1 = pageIdx + 1;
    var from     = _qrPageBoundaries[pageIdx];
    var to       = _qrPageBoundaries[pageIdx + 1] || null;

    // ── Métadonnées ─────────────────────────────────────────────────────────
    var juzNum    = (_QR_PAGE_JUZ   && _QR_PAGE_JUZ[pageIdx])             || '';
    var hizbMarks = (_QR_HIZB_MARKS && _QR_HIZB_MARKS[String(pageNum1)]) || [];

    // Lookup rapide : sajdah
    var sajdahSet = {};
    if (_QR_SAJDAH) _QR_SAJDAH.forEach(function(p){ sajdahSet[p[0]+','+p[1]] = true; });

    // Lookup rapide : marques de hizb par ayat  →  clé = 'sIdx,aIdx'  valeur = type
    var hizbAyahSet = {};
    if (_QR_HIZB_AYAHS) _QR_HIZB_AYAHS.forEach(function(p){ hizbAyahSet[p[0]+','+p[1]] = p[2]; });

    // Noms des sourates présentes sur cette page (pour la barre du haut)
    var surahNames = [];
    for (var si = from.s; si < _qrActiveData.length; si++) {
        if (to && si > to.s) break;
        var sn = _qrActiveData[si].name;
        if (surahNames.indexOf(sn) < 0) surahNames.push(sn);
        if (to && si === to.s) break;
    }

    // Badge hizb éventuel
    var hizbLabel = '';
    if (hizbMarks.length) {
        var _hm = hizbMarks[0];
        var _htxt = { rub: 'ربع', nusf: 'نصف', tlt: 'ثلاثة أرباع', hizb: 'حزب' }[_hm.t] || '';
        hizbLabel = '<span class="qrTopHizbBadge">' + _htxt + ' ' + _qrToArabicDigits(Math.ceil(_hm.h)) + '</span>';
    }

    // ── HTML ─────────────────────────────────────────────────────────────────
    var html = '<div class="qrPageView">';

    // Barre supérieure
    var _isBookmarked = _qrIsBookmarked(pageIdx);
    html += '<div class="qrTopBar">'
          + '<span class="qrTopJuz">جزء ' + _qrToArabicDigits(juzNum) + '</span>'
          + '<span class="qrBookmarkToggle' + (_isBookmarked ? ' qrBookmarked' : '') + '" id="qrBookmarkToggle" title="حفظ هذه الصفحة">'
          + (_isBookmarked ? '&#9733;' : '&#9734;') + '</span>'
          + '<span class="qrTajweedToggleBtn' + (JS_CUSTOM.ucQrTajweedColors ? ' qrTajweedToggleOn' : '') + '" id="qrTajweedToggleBtn" title="تلوين أحكام التجويد (تجريبي، قالون فقط)">&#127912;</span>'
          + '<span class="qrTopSurahLabel">' + surahNames.join(' · ') + '</span>'
          + hizbLabel
          + '</div>';

    // Corps parchemin
    html += '<div class="qrPageContent">';

    for (var sIdx = from.s; sIdx < _qrActiveData.length; sIdx++) {
        if (to && sIdx === to.s && to.a === 0) break;
        if (to && sIdx > to.s) break;

        var surah  = _qrActiveData[sIdx];
        var startA = (sIdx === from.s) ? from.a : 0;
        var endA   = (to && sIdx === to.s) ? to.a : surah.ayats.length;
        if (startA >= surah.ayats.length) break;

        // Bannière de sourate (si la sourate débute sur cette page)
        if (startA === 0) {
            var _fi      = (_QR_FAHRAS && _QR_FAHRAS[sIdx]) || null;
            var _type    = _fi ? (_fi.type === 'مك' ? 'مكيّة' : 'مدنيّة') : '';
            var _ayahs   = _fi ? _qrToArabicDigits(_fi.ayahs) + ' آيات' : '';
            html += '<div class="qrSurahBanner">'
                  + '<div class="qrSurahBannerDeco"></div>'
                  + '<div class="qrSurahBannerText">'
                  + '<span class="qrSurahCircleNum">' + _qrToArabicDigits(sIdx + 1) + '</span>'
                  // surah.name (donnée téléchargée) inclut déjà le préfixe "سُورَةُ" —
                  // ne pas le reconcaténer ici sous peine de doublon visuel
                  // ("سُورَةُ سُورَةُ الفَاتِحَةِ").
                  + ' ' + surah.name
                  + '</div>'
                  + (_type ? '<div class="qrSurahBannerMeta">' + _type + (_ayahs ? ' · ' + _ayahs : '') + '</div>' : '')
                  + '<div class="qrSurahBannerDeco"></div>'
                  + '</div>';
            // Basmala : sauf Fatiha (v.1 = la basmala) et Tawba (pas de basmala)
            if (surah.basmalah && sIdx !== 0 && sIdx !== 8) {
                html += '<div class="qrPageBasmalah">' + surah.basmalah + '</div>';
            }
        }

        // Versets
        var _hizbLabels = { rub: 'ربع', nusf: 'نصف', tlt: 'ثلاثة أرباع', hizb: 'حزب' };
        for (var aIdx = startA; aIdx < endA; aIdx++) {
            var _isSajdah  = !!sajdahSet[sIdx + ',' + aIdx];
            var _hizbType  = hizbAyahSet[sIdx + ',' + aIdx];
            // Marque de hizb (ربع / نصف / ثلاثة أرباع / حزب) avant cet ayat
            if (_hizbType) {
                var _isFullHizb = (_hizbType === 'hizb');
                html += '<div class="qrHizbMark' + (_isFullHizb ? ' qrHizbMarkFull' : '') + '">'
                      + '<span class="qrHizbMarkDeco"></span>'
                      + '<span class="qrHizbMarkLabel">۞ ' + (_hizbLabels[_hizbType] || '') + '</span>'
                      + '<span class="qrHizbMarkDeco"></span>'
                      + '</div>';
            }
            var _ayahText = _qrAyahTextOrNull(surah.ayats[aIdx]);
            if (_ayahText === null && typeof _L === 'function') {
                _L('QR', 'AYAH_MISSING', { surah: sIdx + 1, ayah: aIdx + 1, riwaya: JS_CUSTOM.ucRiwayaActive });
            }
            html += '<span class="qrAyah' + (_ayahText === null ? ' qrAyahMissing' : '') + '">'
                  + (_ayahText === null ? _QR_AYAH_MISSING_TEXT : _qrTajweedHtml(sIdx, aIdx, _ayahText))
                  + (_isSajdah ? ' <span class="qrSajdahMark">۩</span>' : '')
                  + ' <span class="qrAyahNum">&#64831;' + _qrToArabicDigits(aIdx + 1) + '&#64830;</span>'
                  + '</span> ';
        }

        if (to && sIdx === to.s) break;
    }

    html += '</div>'; // .qrPageContent

    // Bande de légende تجويد : uniquement les couleurs réellement présentes
    // sur cette page (_qrLastPageTajRules, peuplée pendant la boucle ci-dessus),
    // vide (donc invisible) si coloration désactivée / riwaya ≠ Qaloun / aucune
    // règle sur la page. Appui -> modale détaillée (_qrOpenTajInfo()).
    html += _qrBuildTajLegendRow();

    // Pied de page — Mushaf RTL :
    //   ❯ à GAUCHE = page précédente (aller vers le début du Mushaf, à droite)
    //   ❮ à DROITE = page suivante  (aller vers la fin du Mushaf, à gauche)
    // Boutons سورة (❯❯/❮❮, doublés pour se distinguer du saut de page simple)
    // en position extérieure : même sens que les boutons page, mais sautent
    // directement au début de la sourate précédente/suivante.
    var _isFirst = (pageIdx === 0);
    var _isLast  = (pageIdx === total - 1);
    var _isFirstSurah = (from.s === 0);
    // Cible de "sourate suivante" = la DERNIÈRE sourate déjà visible sur
    // cette page (pas from.s, qui n'est que la PREMIÈRE) + 1. Plusieurs
    // sourates courtes de fin de Coran partagent souvent une même page sans
    // saut de page entre elles (cf. commentaire de _qrPageIndexForSurahStart) :
    // viser from.s+1 pouvait retomber sur une sourate déjà entièrement
    // affichée ICI, _qrGoToSurah calculait alors la MÊME page que la page
    // courante et le bouton semblait ne rien faire, ou se bloquait après un
    // ou deux appuis (signalé 26/08/2026). to.s n'est inclus que s'il
    // apparaît réellement sur cette page (to.a > 0 -- sinon il ne commence
    // qu'à la page suivante, cf. la garde `to.a === 0` de la boucle de rendu
    // ci-dessus).
    var _lastSurahOnPage = to ? (to.a === 0 ? to.s - 1 : to.s) : (_qrActiveData.length - 1);
    var _isLastSurah = (_lastSurahOnPage >= _qrActiveData.length - 1);
    var _prevSurahName = _isFirstSurah ? '' : _qrActiveData[from.s - 1].name;
    var _nextSurahName = _isLastSurah  ? '' : _qrActiveData[_lastSurahOnPage + 1].name;
    html += '<div class="qrPageFooter">'
          + '<span class="qrPageNavBtn qrSurahNavBtn' + (_isFirstSurah ? ' qrNavDisabled' : '') + '" id="qrSurahPrev" title="' + _prevSurahName + '">&#10095;&#10095;</span>'
          + '<span class="qrPageNavBtn' + (_isFirst ? ' qrNavDisabled' : '') + '" id="qrPagePrev">&#10095;</span>'
          + '<span class="qrPageNum">' + _qrToArabicDigits(pageNum1) + ' / ' + _qrToArabicDigits(total) + '</span>'
          + '<span class="qrPageNavBtn' + (_isLast  ? ' qrNavDisabled' : '') + '" id="qrPageNext">&#10094;</span>'
          + '<span class="qrPageNavBtn qrSurahNavBtn' + (_isLastSurah ? ' qrNavDisabled' : '') + '" id="qrSurahNext" title="' + _nextSurahName + '">&#10094;&#10094;</span>'
          + '</div>';

    html += '</div>'; // .qrPageView

    area.innerHTML = html;
    area.scrollTop = 0;

    // Bouton marque-page (⭐/☆) — cf. _qrToggleBookmark/_qrIsBookmarked plus bas.
    var bmEl = document.getElementById('qrBookmarkToggle');
    if (bmEl) bmEl.addEventListener('click', function() {
        _qrToggleBookmark(pageIdx);
        var _nowSet = _qrIsBookmarked(pageIdx);
        bmEl.classList.toggle('qrBookmarked', _nowSet);
        bmEl.innerHTML = _nowSet ? '&#9733;' : '&#9734;';
    });

    // Bascule coloration tajwid (expérimental, Qaloun uniquement) — déplacé
    // dans la barre supérieure à côté de qrBookmarkToggle (regroupe les deux
    // bascules par-page) ; réécouté à chaque rendu comme qrBookmarkToggle
    // ci-dessus puisque tout #qrTopBar est régénéré via innerHTML.
    var tajBtnEl = document.getElementById('qrTajweedToggleBtn');
    if (tajBtnEl) tajBtnEl.addEventListener('click', function() {
        JS_CUSTOM.ucQrTajweedColors = JS_CUSTOM.ucQrTajweedColors ? 0 : 1;
        saveCustomSettingsFunction();
        _qrRenderPage(_qrCurrentPage);
    });

    // Boutons nav
    var prevEl = document.getElementById('qrPagePrev');
    var nextEl = document.getElementById('qrPageNext');
    if (prevEl && !_isFirst) prevEl.addEventListener('click', function(){ _qrGoToPage(_qrCurrentPage - 1); });
    if (nextEl && !_isLast)  nextEl.addEventListener('click', function(){ _qrGoToPage(_qrCurrentPage + 1); });

    var surahPrevEl = document.getElementById('qrSurahPrev');
    var surahNextEl = document.getElementById('qrSurahNext');
    if (surahPrevEl && !_isFirstSurah) surahPrevEl.addEventListener('click', function(){ _qrGoToSurah(from.s - 1); });
    if (surahNextEl && !_isLastSurah)  surahNextEl.addEventListener('click', function(){ _qrGoToSurah(_lastSurahOnPage + 1); });

    // Bande de légende تجويد (régénérée à chaque page -> réécoute à chaque fois).
    var tajLegendEl = document.getElementById('qrTajLegendRow');
    if (tajLegendEl) tajLegendEl.addEventListener('click', function() { _qrOpenTajInfo(); });

    _L('QR', 'PAGE_RENDER', { page: pageNum1, total: total });
}

// ── Marque-pages (⭐) ────────────────────────────────────────────────────
// Un marque-page est un simple index de page (0-based, même référentiel que
// _qrPageBoundaries) : comme la navigation جزء/حزب existante retombe déjà sur
// "la page où ça commence", marquer cette page-là couvre aussi le besoin
// "marquer un جزء/حزب pour y revenir" sans dupliquer de modèle de données.
var _QR_BOOKMARKS_KEY = 'tawkit_qp_read_bookmarks';
var _qrBookmarks = [];
(function _qrLoadBookmarks() {
    try { _qrBookmarks = JSON.parse(localStorage.getItem(_QR_BOOKMARKS_KEY) || '[]'); }
    catch (e) { _qrBookmarks = []; }
    if (!Array.isArray(_qrBookmarks)) _qrBookmarks = [];
})();
function _qrSaveBookmarks() {
    try { localStorage.setItem(_QR_BOOKMARKS_KEY, JSON.stringify(_qrBookmarks)); } catch (e) {}
}
function _qrIsBookmarked(pageIdx) {
    return _qrBookmarks.indexOf(pageIdx) !== -1;
}
function _qrToggleBookmark(pageIdx) {
    var i = _qrBookmarks.indexOf(pageIdx);
    if (i === -1) { _qrBookmarks.push(pageIdx); _qrBookmarks.sort(function(a, b) { return a - b; }); }
    else { _qrBookmarks.splice(i, 1); }
    _qrSaveBookmarks();
    _L('QR', 'BOOKMARK_TOGGLE', { page: pageIdx + 1, active: i === -1 });
}
function _qrRemoveBookmark(pageIdx) {
    var i = _qrBookmarks.indexOf(pageIdx);
    if (i !== -1) { _qrBookmarks.splice(i, 1); _qrSaveBookmarks(); }
}
// Nom de la sourate en cours à la page donnée (dernière sourate dont la page
// de début est <= pageNum1) — utilisé pour étiqueter un marque-page.
function _qrSurahNameForPage(pageIdx) {
    var pageNum1 = pageIdx + 1;
    var name = '';
    for (var i = 0; i < _QR_FAHRAS.length; i++) {
        if (_QR_FAHRAS[i].page <= pageNum1) name = _QR_FAHRAS[i].name; else break;
    }
    return name;
}

// Page de début (0-based) de chaque جزء 1..30.
function _qrJuzFirstPages() {
    var arr = [];
    if (_QR_PAGE_JUZ) {
        for (var pg = 0; pg < _QR_PAGE_JUZ.length; pg++) {
            var jz = _QR_PAGE_JUZ[pg];
            if (arr[jz] === undefined) arr[jz] = pg;
        }
    }
    return arr;
}
// Page de début (0-based) de chaque حزب 1..60 — le حزب N+1 commence à la page
// portant la marque h=N.0 (type 'hizb').
function _qrHizbFirstPages() {
    var map = { 1: 0 };
    if (_QR_HIZB_MARKS) {
        Object.keys(_QR_HIZB_MARKS).forEach(function(pageKey) {
            _QR_HIZB_MARKS[pageKey].forEach(function(m) {
                if (m.t === 'hizb') {
                    var nextH = Math.round(m.h) + 1;
                    if (nextH <= 60) map[nextH] = parseInt(pageKey, 10) - 1;
                }
            });
        });
    }
    return map;
}

// ── Fahras plein écran (سورة / جزء / حزب / المرجعيات) ──────────────────────
function _qrOpenFahras(tab) {
    var panel = document.getElementById('qrFahrasPanel');
    if (!panel) return;
    panel.classList.remove('qrFahrasHidden');
    _qrSwitchFahrasTab(tab || 'surah');
}
window._qrOpenFahras = _qrOpenFahras;

function _qrCloseFahras() {
    var panel = document.getElementById('qrFahrasPanel');
    if (panel) panel.classList.add('qrFahrasHidden');
}
window._qrCloseFahras = _qrCloseFahras;

function _qrSwitchFahrasTab(tab) {
    var btns = document.querySelectorAll('.qrFahrasTabBtn');
    for (var i = 0; i < btns.length; i++) {
        btns[i].classList.toggle('qrFahrasTabActive', btns[i].getAttribute('data-ftab') === tab);
    }
    var body = document.getElementById('qrFahrasBody');
    if (!body) return;
    if (tab === 'juz')            body.innerHTML = _qrBuildFahrasJuzList();
    else if (tab === 'hizb')      body.innerHTML = _qrBuildFahrasHizbList();
    else if (tab === 'bookmarks') body.innerHTML = _qrBuildFahrasBookmarksList();
    else                          body.innerHTML = _qrBuildFahrasSurahList();
    body.onclick = function(e) {
        var rm = e.target.closest('[data-remove-bookmark]');
        if (rm) {
            e.stopPropagation();
            _qrRemoveBookmark(parseInt(rm.getAttribute('data-remove-bookmark'), 10));
            body.innerHTML = _qrBuildFahrasBookmarksList();
            return;
        }
        var item = e.target.closest('[data-goto-page]');
        if (item) {
            _qrGoToPage(parseInt(item.getAttribute('data-goto-page'), 10));
            _qrCloseFahras();
        }
    };
}
window._qrSwitchFahrasTab = _qrSwitchFahrasTab;

function _qrBuildFahrasSurahList() {
    if (!_qrActiveData) return '<div class="qrFahrasEmpty">اختر رواية أعلاه أولاً</div>';
    var html = '<div class="qrFahrasGrid">';
    _QR_FAHRAS.forEach(function(fi) {
        var pageIdx = fi.page - 1;
        html += '<div class="qrFahrasItem" data-goto-page="' + pageIdx + '">'
              + '<span class="qrFahrasItemNum">' + _qrToArabicDigits(fi.num) + '</span>'
              + '<span class="qrFahrasItemName">' + fi.name + '</span>'
              + '<span class="qrFahrasItemMeta">' + (fi.type === 'مك' ? 'مكية' : 'مدنية') + ' · ' + _qrToArabicDigits(fi.ayahs) + '</span>'
              + '</div>';
    });
    html += '</div>';
    return html;
}
function _qrBuildFahrasJuzList() {
    var firstPages = _qrJuzFirstPages();
    var html = '<div class="qrFahrasList">';
    for (var j = 1; j <= 30; j++) {
        var pageIdx = (firstPages[j] !== undefined) ? firstPages[j] : 0;
        html += '<div class="qrFahrasRow" data-goto-page="' + pageIdx + '">'
              + '<span class="qrFahrasRowLabel">الجزء ' + _qrToArabicDigits(j) + '</span>'
              + '<span class="qrFahrasRowPage">ص ' + _qrToArabicDigits(pageIdx + 1) + '</span>'
              + '</div>';
    }
    html += '</div>';
    return html;
}
function _qrBuildFahrasHizbList() {
    var firstPages = _qrHizbFirstPages();
    var html = '<div class="qrFahrasList">';
    for (var h = 1; h <= 60; h++) {
        var pageIdx = (firstPages[h] !== undefined) ? firstPages[h] : 0;
        html += '<div class="qrFahrasRow" data-goto-page="' + pageIdx + '">'
              + '<span class="qrFahrasRowLabel">الحزب ' + _qrToArabicDigits(h) + '</span>'
              + '<span class="qrFahrasRowPage">ص ' + _qrToArabicDigits(pageIdx + 1) + '</span>'
              + '</div>';
    }
    html += '</div>';
    return html;
}
function _qrBuildFahrasBookmarksList() {
    if (!_qrBookmarks.length) {
        return '<div class="qrFahrasEmpty">لا توجد صفحات محفوظة بعد.<br>اضغط على ⭐ أثناء القراءة لحفظ الصفحة الحالية.</div>';
    }
    var html = '<div class="qrFahrasList">';
    _qrBookmarks.forEach(function(pageIdx) {
        var juz   = (_QR_PAGE_JUZ && _QR_PAGE_JUZ[pageIdx]) || '';
        var sName = _qrSurahNameForPage(pageIdx);
        html += '<div class="qrFahrasRow" data-goto-page="' + pageIdx + '">'
              + '<span class="qrFahrasRowLabel">ص ' + _qrToArabicDigits(pageIdx + 1) + ' — ' + sName + '</span>'
              + '<span class="qrFahrasRowPage">جزء ' + _qrToArabicDigits(juz) + '</span>'
              + '<span class="qrFahrasRowRemove" data-remove-bookmark="' + pageIdx + '" title="حذف">&#10006;</span>'
              + '</div>';
    });
    html += '</div>';
    return html;
}

// Retourne l'index de page (0-based) contenant l'ayat (surahIdx0, ayahIdx0).
// Utilisé par la recherche pour sauter à la bonne page.
function _qrFindPageForAyah(surahIdx, ayahIdx) {
    var best = 0;
    for (var i = 0; i < _qrPageBoundaries.length; i++) {
        var b = _qrPageBoundaries[i];
        if (b.s < surahIdx)                       { best = i; continue; }
        if (b.s === surahIdx && b.a <= ayahIdx)   { best = i; continue; }
        break;
    }
    return best;
}

// Navigation par glissement — tous les modes utilisent la vue paginée.
// direction : +1 (page suivante) ou -1 (page précédente).
function _qrSwipeToSurah(direction) {
    _qrGoToPage(_qrCurrentPage + direction);
}

function _qrSearch(query) {
    var msgEl = document.getElementById('qpReadStateMsg');
    var area  = document.getElementById('qpReadTextArea');
    if (!query) return;
    if (!_qrActiveData) {
        if (msgEl) { msgEl.style.display = ''; msgEl.textContent = 'اختر رواية وحمّلها أولاً'; }
        return;
    }
    var qNorm = _qrNormalizeArabic(query);
    if (!qNorm) return;
    var results = [];
    _qrActiveData.forEach(function(surah, sIdx) {
        surah.ayats.forEach(function(text, aIdx) {
            var _t = _qrAyahTextOrNull(text);
            if (_t === null) return; // texte manquant côté dataset, cf. _qrAyahTextOrNull
            if (_qrNormalizeArabic(_t).indexOf(qNorm) !== -1) {
                results.push({ sIdx: sIdx, aIdx: aIdx, name: surah.name, text: _t });
            }
        });
    });
    if (!results.length) {
        if (area) area.innerHTML = '<div id="qpReadStateMsg">لا توجد نتائج لـ "' + query + '"</div>';
        return;
    }
    var html = '<div class="qrSearchResultsHeader">' + _qrToArabicDigits(results.length) + ' نتيجة لـ "' + query + '"</div>';
    results.slice(0, 200).forEach(function(r) {
        html += '<div class="qrSearchResult" data-sidx="' + r.sIdx + '" data-aidx="' + r.aIdx + '">' +
                '<span class="qrSearchResultRef">' + r.name + ' ' + _qrToArabicDigits(r.aIdx + 1) + '</span>' +
                '<span class="qrSearchResultText">' + r.text + '</span></div>';
    });
    if (area) {
        area.innerHTML = html;
        area.querySelectorAll('.qrSearchResult').forEach(function(el) {
            el.addEventListener('click', function() {
                var _sIdx = parseInt(el.getAttribute('data-sidx'), 10);
                var _aIdx = parseInt(el.getAttribute('data-aidx'), 10);
                _qrGoToPage(_qrFindPageForAyah(_sIdx, _aIdx));
            });
        });
    }
}

// ── Construction / rafraîchissement de l'UI ──────────────────────────────
// Vrai s'il existe au moins une source audio réellement exploitable :
// serveur HTTP activé (khadim al-Qur'an) OU au moins un récitateur "device"
// (USB/téléchargé) installé. Sert à éviter toute tentative de lecture contre
// les récitateurs C1..C10 "serveur" quand aucun serveur ne tourne (ce qui
// provoquait auparavant une erreur SRC_NOT_SUPPORTED dès la première
// ouverture, sur une installation fraîche sans serveur ni récitateur local).
function _qpHasPlayableSource() {
    if (JS_CUSTOM.ucQuranServerEnabled == 1) return true;
    var reciters = Array.isArray(JS_CUSTOM.ucReciters) ? JS_CUSTOM.ucReciters : [];
    return reciters.some(function(r) { return r.enabled == 1 && r.source === 'device'; });
}
// Exposition globale explicite : cette déclaration est imbriquée dans la
// closure de injectTechOptionsUI() (IIFE), pas au vrai top-level du script.
// _startQuranAutoPlayback() (top-level, bien plus haut dans le fichier,
// déclenché avant chaque azan quand "تشغيل القرآن قبل الأذان" est actif)
// l'appelle en identifiant nu depuis une closure totalement différente —
// confirmé par analyse AST (acorn) : ReferenceError garanti à CHAQUE appel,
// qu'une source soit disponible ou non (l'exception part avant même
// d'évaluer le résultat). Même classe de bug que _ucHasNative plus haut ;
// window.X = X la rend résolvable via la chaîne de portée (repli sur l'objet
// global) depuis n'importe quel closure du fichier.
window._qpHasPlayableSource = _qpHasPlayableSource;

// Affiche le message informatif "rien à jouer" (et masque les blocs
// récitateurs/sourates/lecteur) tant qu'aucune source n'est disponible ;
// restaure l'affichage normal dès qu'un serveur est activé ou qu'un
// récitateur local est installé. Appelée à chaque (re)construction des
// récitateurs (_buildQPReciters : ouverture de la modale, changement du
// réglage serveur, retour d'un téléchargement) — donc revérifiée en
// continu plutôt qu'une seule fois à l'ouverture.
function _qpRefreshSourceAvailability() {
    var hasSource = _qpHasPlayableSource();
    var banner = document.getElementById('qpNoSourceBanner');
    // NB : '#qpNoSourceBanner' a 'display:none' en CSS de base (cf. custom.css) —
    // remettre l'inline style à '' ne fait qu'annuler le style inline et
    // retomber sur la règle CSS 'none', donc le message ne s'affichait jamais.
    // Il faut une valeur explicite ('block') pour réellement l'afficher.
    if (banner) banner.style.display = hasSource ? 'none' : 'block';

    // quranRecitersBlock / quranRecitersDeviceBlock gèrent déjà leur propre
    // affichage juste avant cet appel (cf. _buildQPReciters) — on ne les
    // force que dans le sens "masquer" ici (hasSource=false implique de
    // toute façon 0 récitateur activé, donc aucune info perdue).
    var recitersBlock = document.getElementById('quranRecitersBlock');
    var devBlock       = document.getElementById('quranRecitersDeviceBlock');
    if (!hasSource) {
        if (recitersBlock) recitersBlock.style.display = 'none';
        if (devBlock)      devBlock.style.display = 'none';
    }
    // Sourates + lecteur : entièrement gérés ici (pas de logique de visibilité
    // propre ailleurs). qpTakbirRow N'EN FAIT PAS PARTIE : le تكبير joue un
    // fichier local toujours disponible, indépendant du serveur/des
    // récitateurs — cf. commentaire "TOUJOURS affiché" dans _buildQPReciters().
    ['quranSurahsBlock', 'quranPlayerBlock'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = hasSource ? '' : 'none';
    });
    return hasSource;
}

function _buildQPReciters() {
    const block   = document.getElementById('quranRecitersBlock');
    const devBlock = document.getElementById('quranRecitersDeviceBlock');
    const devRow   = document.getElementById('quranRecitersDeviceRow');
    if (!block) return;
    // qpTakbirRow (cf. plus bas) est reconstruit à chaque appel ; on récupère
    // le <audio> existant AVANT le wipe pour le replacer (même noeud, donc
    // même lecture en cours/contrôles) plutôt que d'en recréer un neuf qui
    // perdrait le takbir en train de jouer (cf. _playTakbirAuto).
    const _existingTakbirAudio = document.getElementById('qpTakbirAudio');
    block.innerHTML = '';
    if (devRow) devRow.innerHTML = '';

    // Règle "masquer les C1..C10 quand le serveur Coran est désactivé" :
    // propre à l'APK Android (présence de window.AndroidMobile, absent en
    // navigateur classique — cf. ligne ~2419). Sur Windows/navigateur, cette
    // règle n'a donc aucun effet et le comportement reste celui d'avant.
    const isAndroidApp = !!window.AndroidMobile;
    const serverOn     = (JS_CUSTOM.ucQuranServerEnabled == 1);
    const hideFixed    = isAndroidApp && !serverOn;

    const allReciters = Array.isArray(JS_CUSTOM.ucReciters) ? JS_CUSTOM.ucReciters : [];
    const enabled        = allReciters.filter(function(r) { return r.enabled == 1; });
    const enabledFixed   = enabled.filter(function(r) { return r.source !== 'device'; });
    const enabledDevice  = enabled.filter(function(r) { return r.source === 'device'; });

    _L('QP','INIT',{total:allReciters.length, enabled:enabled.length,
        fixed:enabledFixed.length, device:enabledDevice.length,
        deviceIds:enabledDevice.map(function(r){return r.dir;}).join(',') || '(none)',
        reciter:_qpReciterIdx, surah:_qpSurahNum, android:isAndroidApp?1:0, serverOn:serverOn?1:0});

    function _makeReciterBtn(reciter) {
        const idx = JS_CUSTOM.ucReciters.indexOf(reciter);
        const btn = document.createElement('span');
        btn.className = 'quranReciterBtn' + (idx === _qpReciterIdx ? ' qSel' : '');
        btn.id = 'qpRBtn' + idx;
        // Afficher le nom court : dernier mot (sauf pour عبد الباسط → 2 derniers)
        const words = reciter.name.trim().split(/\s+/);
        btn.textContent = words.length >= 4 ? words.slice(-3).join(' ') : reciter.name;
        btn.onclick = function() { selectQPReciter(idx); };
        return btn;
    }

    // ── Récitateurs locaux (USB / téléchargés) : bande séparée, indépendante
    // du serveur — hauteur plafonnée + scroll (#quranRecitersDeviceRow, voir
    // custom.css). Sans ça, chaque import USB agrandirait indéfiniment
    // quranRecitersBlock et finirait par écraser le bloc des 114 sourates.
    if (devBlock) {
        if (enabledDevice.length) {
            enabledDevice.forEach(function(reciter) { devRow.appendChild(_makeReciterBtn(reciter)); });
            devBlock.style.display = '';
        } else {
            devBlock.style.display = 'none';
        }
        // Espace libéré par les C1..C10 cachés → la bande locale s'étend
        // (Android uniquement, voir hideFixed ci-dessus).
        devBlock.classList.toggle('qpDeviceExpanded', hideFixed);
    }

    if (!hideFixed && !enabled.length) {
        // Règle 2 : aucun récitateur activé → texte arabe uniquement, pas de boutons
        block.innerHTML = '<span style="color:#aaa;font-size:.9em;padding:6px 0;display:block;text-align:center;direction:rtl;">— لم يتم اختيار أي قارئ —</span>';
    }

    // ── Récitateurs fixes (serveur, C1..C10) : cachés sur Android quand le
    // serveur est désactivé (ils en dépendent) ; inchangé hors APK (Windows).
    if (!hideFixed) {
        enabledFixed.forEach(function(reciter) { block.appendChild(_makeReciterBtn(reciter)); });
    }

    // Masquer entièrement le bloc s'il ne contient rien (serveur désactivé sur
    // Android → hideFixed=true → ni C1..C10 ni message "aucun récitateur" ci-
    // dessus, cf. leurs conditions respectives) : sinon, depuis l'ajout de la
    // bordure uniforme des blocs du lecteur, ce cadre restait affiché
    // complètement vide, prenant une place verticale inutile pendant que
    // quranRecitersDeviceBlock (récitateurs locaux) s'affiche juste en-dessous.
    // قpTakbirRow est un noeud séparé (inséré après quranPlayerBlock, pas
    // enfant de ce bloc) : le masquer ici ne l'affecte pas.
    block.style.display = block.innerHTML.trim() ? '' : 'none';

    // ── 2ᵉ ligne : bouton تكبير permanent — TOUJOURS affiché, quel que soit
    // l'état du serveur ou la plateforme (servi en local, indépendant des
    // C1..C10). Rangée placée sous quranPlayerBlock (bloc lecteur principal),
    // PAS dans quranRecitersBlock : on réutilise donc le même noeud #qpTakbirRow
    // à chaque appel (au lieu d'en recréer un) — sinon, n'étant plus enfant de
    // quranRecitersBlock, il ne serait plus jamais wipé par block.innerHTML=''
    // ci-dessus et on accumulerait des rangées dupliquées à chaque rafraîchissement.
    var _tRow = document.getElementById('qpTakbirRow');
    if (!_tRow) {
        _tRow = document.createElement('div');
        _tRow.id = 'qpTakbirRow';
        var _qpBlock = document.getElementById('quranPlayerBlock');
        if (_qpBlock && _qpBlock.parentNode) {
            _qpBlock.parentNode.insertBefore(_tRow, _qpBlock.nextSibling);
        }
    }
    _tRow.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:center;' +
        'gap:12px;padding-top:8px;border-top:1px solid #3a2e18;margin-top:6px;';
    _tRow.innerHTML = '';   // reconstruit le bouton (état qSel) à chaque appel

    var _tBtn = document.createElement('span');
    _tBtn.id        = 'qpTakbirBtn';
    _tBtn.className = 'quranReciterBtn qpTakbirBtnStyle' + (_qpReciterIdx === _QP_TAKBIR_IDX ? ' qSel' : '');
    _tBtn.textContent = 'تكبير';
    _tBtn.title       = 'تشغيل ملف التكبير';
    _tBtn.onclick     = selectQPTakbir;
    _tRow.appendChild(_tBtn);

    // Mini lecteur dédié au takbir, à côté du bouton تكبير — toujours visible
    // (pas de show/hide), <audio controls> natif pour permettre l'arrêt
    // manuel. Élément séparé de quranAudioPlayer à dessein : jamais câblé sur
    // l'égaliseur Web Audio (createMediaElementSource), car un fichier local
    // file:// routé à travers ce graphe perd son flag "origin-clean" et
    // devient silencieux sous Chrome/Windows (cf. notes dans selectQPTakbir()
    // / _installTakbirAutoPlay). On réutilise le même noeud DOM s'il existe
    // déjà (_existingTakbirAudio, capturé en tout début de fonction avant le
    // wipe) pour ne pas couper une lecture en cours.
    var _tAudio = _existingTakbirAudio || document.createElement('audio');
    _tAudio.id      = 'qpTakbirAudio';
    _tAudio.controls = true;
    _tAudio.style.cssText = 'width:240px;max-width:60%;height:32px;';
    _tRow.appendChild(_tAudio);

    _qpRefreshSourceAvailability();
}

function _refreshQPReciters() {
    JS_CUSTOM.ucReciters.forEach(function(_, i) {
        const btn = document.getElementById('qpRBtn' + i);
        if (btn) btn.classList.toggle('qSel', i === _qpReciterIdx);
    });
}

function _refreshQPSurahs() {
    _SURAH_NAMES.forEach(function(_, i) {
        const btn = document.getElementById('qpSurah' + (i + 1));
        if (btn) btn.classList.toggle('qSel', (i + 1) === _qpSurahNum);
    });
    // Scroll vers la sourate sélectionnée
    if (_qpSurahNum > 0) {
        const sel = document.getElementById('qpSurah' + _qpSurahNum);
        if (sel) sel.scrollIntoView({block: 'nearest', behavior: 'smooth'});
    }
}

function _refreshQPNowPlaying() {
    const el = document.getElementById('quranNowPlaying');
    if (!el) return;
    if (_qpReciterIdx < 0 || _qpSurahNum < 1) {
        el.innerHTML = '&#9904;&nbsp;—';
        return;
    }
    const reciterName = JS_CUSTOM.ucReciters[_qpReciterIdx].name;
    const surahName   = _SURAH_NAMES[_qpSurahNum - 1];
    el.innerHTML = '&#9904;&nbsp;' + reciterName + '&nbsp;&ndash;&nbsp;' + surahName;
}

// Exposition explicite : _ensureQuranSelectionForAutoStart (bien plus haut
// dans le fichier, hors de portée lexicale de ces helpers) en a besoin pour
// rafraîchir l'UI sans lever de ReferenceError -- cf. window._playQP plus
// bas pour le même constat sur _playQP/_qpStartEq/_showAutoplayUnlockModal.
window._refreshQPReciters   = _refreshQPReciters;
window._refreshQPSurahs     = _refreshQPSurahs;
window._refreshQPNowPlaying = _refreshQPNowPlaying;

// ═══════════════════════════════════════════════════════════════════════════
// ── GESTION ÉTAT SERVEUR : probe · dot · bannière · lock UI ───────────────
// ═══════════════════════════════════════════════════════════════════════════

var _QP_PROBE_INTERVAL_MS = 30000; // 30 s entre deux probes de récupération

// ── Machine d'état centrale ───────────────────────────────────────────────
function _qpSetServerState(state) {
    var prev = _qpServerState;
    _qpServerState = state;
    _refreshQPServerStatus();   // met à jour le dot uniquement
    if (state === 'ok' && prev === 'error') {
        _qpStopProbeLoop();
        _L('QP','RESUME',{action:'server_recovery',from:prev});
        // Ne pas toucher à la bannière ni à l'UI ici :
        // une erreur de fichier peut avoir verrouillé l'UI indépendamment
        // du statut serveur. C'est _qpRetry() / _qpBack() qui déverrouillent.
    } else if (state === 'error' && prev !== 'error') {
        _qpStartProbeLoop();
        _L('QP','STOP',{action:'server_error'});
    }
}

// ── Rafraîchissement du dot de statut ─────────────────────────────────────
function _refreshQPServerStatus() {
    var dot = document.getElementById('qpServerStatusDot');
    if (!dot) return;
    if (JS_CUSTOM.ucQuranServerEnabled != 1) {
        dot.style.background = '#e05050'; // rouge : serveur désactivé (avant : gris, moins visible)
        dot.title = 'الخادم: معطَّل';
        return;
    }
    var map = {
        unknown: { c: '#888',    t: 'الخادم: جارٍ التحقق…' },
        ok:      { c: '#4caf50', t: 'الخادم: متاح ✓' },
        error:   { c: '#e05050', t: 'الخادم: غير متاح — ' + (JS_CUSTOM.ucQuranServerUrl || '') }
    };
    var cfg = map[_qpServerState] || map.unknown;
    dot.style.background = cfg.c;
    dot.title = cfg.t;
}

// ── Sonde de connectivité HTTP (no-cors, fire-and-forget) ─────────────────
function _qpServerProbe() {
    if (JS_CUSTOM.ucQuranServerEnabled != 1) return;
    if (JS_CUSTOM.ucQPServerProbeEnabled != 1) return;
    // /health : réponse vide définie par server_cors.py v2.
    // Évite de charger le listing HTML du dossier racine (grosse réponse
    // immédiatement abandonnée par AbortSignal → ConnectionAbortedError côté serveur).
    var url = (JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '') + '/health';
    var opts = { mode: 'no-cors' };
    if (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function') {
        opts.signal = AbortSignal.timeout(3000);
    }
    _L('QP','FIRE',{action:'server_probe',url:url,state:_qpServerState});
    fetch(url, opts).then(function() {
        _L('QP','RESUME',{action:'server_probe',result:'ok'});
        _qpSetServerState('ok');
    }).catch(function(err) {
        if (_qpRestoring) return;
        _L('QP','STOP',{action:'server_probe',result:'error',reason:(err && err.message)||String(err)});
        _qpSetServerState('error');
    });
}

// ── Boucle de re-probe après panne (toutes les 30 s) ─────────────────────
function _qpStartProbeLoop() {
    _qpStopProbeLoop();
    _qpProbeTimer = setInterval(function() {
        if (_qpServerState === 'error') { _qpServerProbe(); }
        else { _qpStopProbeLoop(); }
    }, _QP_PROBE_INTERVAL_MS);
}

function _qpStopProbeLoop() {
    if (_qpProbeTimer) { clearInterval(_qpProbeTimer); _qpProbeTimer = null; }
}

// ── Bannière d'erreur ─────────────────────────────────────────────────────
function _qpShowErrorBanner(msg) {
    var b = document.getElementById('quranPlayerErrorBanner');
    var m = document.getElementById('qpErrMsg');
    if (!b) return;
    if (m) {
        // Mettre خطأ en gras/grand via un span si le message commence par ce mot
        var display = msg || '';
        if (display.indexOf('خطأ') === 0) {
            var colon = display.indexOf(':');
            if (colon > 0) {
                m.innerHTML = '<span class="qpErrLabel">' + display.substring(0, colon) + '</span>'
                            + display.substring(colon);
            } else {
                m.innerHTML = '<span class="qpErrLabel">' + display + '</span>';
            }
        } else {
            m.textContent = display;
        }
        m.style.display = '';
    }
    b.style.display = 'flex';
}

function _qpHideErrorBanner() {
    var b = document.getElementById('quranPlayerErrorBanner');
    if (b) b.style.display = 'none';
}

// ── Bouton "إعادة المحاولة" ─────────────────────────────────────────────
function _qpRetry() {
    _qpHideErrorBanner();
    _qpServerState = 'unknown';
    _refreshQPServerStatus();
    _qpUnlockUI();
    _qpServerProbe();
    // Re-tenter la lecture si une sélection est en cours
    var audio = document.getElementById('quranAudioPlayer');
    if (audio && _qpReciterIdx >= 0 && _qpSurahNum >= 1) {
        audio.load();
        var p = audio.play();
        if (p && p.catch) p.catch(function() {});
    }
}

// ── Bouton "اختيار آخر" — retour à la sélection récitateur / sourate ──────
function _qpBack() {
    // 1. Lever le flag AVANT de toucher à l'audio pour bloquer le handler d'erreur
    _qpUserAborted = true;

    // 2. Stopper la lecture et vider la src (provoque un error event → ignoré grâce au flag)
    var audio = document.getElementById('quranAudioPlayer');
    if (audio) {
        audio.pause();
        audio.src = '';
        audio.load();
    }

    // 3. Masquer la bannière d'erreur + déverrouiller l'UI
    _qpHideErrorBanner();
    _qpUnlockUI();

    // 4. Stopper la sonde serveur si elle tourne
    if (typeof _qpStopProbeLoop === 'function') _qpStopProbeLoop();

    // 5. Faire défiler vers le haut du modal pour que les blocs soient visibles
    var body = document.getElementById('quranPlayerBody');
    if (body) body.scrollTop = 0;

    _L('QP','BACK',{action:'user_back_to_selection'});

    // 6. Relâcher le flag après que tous les events audio soient consommés (~300ms)
    setTimeout(function() { _qpUserAborted = false; }, 300);
}

// ── Verrouillage / déverrouillage visuel de l'UI ─────────────────────────
function _qpLockUI() {
    var b1 = document.getElementById('quranRecitersBlock');
    var b1d = document.getElementById('quranRecitersDeviceBlock');
    var b2 = document.getElementById('quranSurahsBlock');
    if (b1) b1.classList.add('qpBlocked');
    if (b1d) b1d.classList.add('qpBlocked');
    if (b2) b2.classList.add('qpBlocked');
    _setQPNowPlayingState('error');
}

function _qpUnlockUI() {
    var b1 = document.getElementById('quranRecitersBlock');
    var b1d = document.getElementById('quranRecitersDeviceBlock');
    var b2 = document.getElementById('quranSurahsBlock');
    if (b1) b1.classList.remove('qpBlocked');
    if (b1d) b1d.classList.remove('qpBlocked');
    if (b2) b2.classList.remove('qpBlocked');
    if (_qpReciterIdx >= 0 && _qpSurahNum >= 1) _refreshQPNowPlaying();
    else _setQPNowPlayingState('idle');
}

// ── États textuels du "now playing" ─────────────────────────────────────
function _setQPNowPlayingState(state) {
    var el = document.getElementById('quranNowPlaying');
    if (!el) return;
    if (state === 'playing') { _refreshQPNowPlaying(); return; }
    var html = {
        idle:      '&#9904;&nbsp;—',
        loading:   'جارٍ التحميل…',
        buffering: '&#9203;&nbsp;يتم التخزين المؤقت…',
        error:     '&#9888;&nbsp;خطأ في التحميل'
    };
    if (html[state] !== undefined) el.innerHTML = html[state];
}


// ── Sélections ───────────────────────────────────────────────────────────
function selectQPReciter(idx) {
    _qpUserAborted = false;   // choix actif → réactiver le handler d'erreur
    _qpErrorCount  = 0;       // nouveau choix → compteur d'erreurs remis à zéro
    _qpReciterIdx = idx;
    _refreshQPReciters();
    if (_qpSurahNum > 0) _playQP();
    else _refreshQPNowPlaying();
}

function selectQPSurah(num) {
    _qpUserAborted = false;   // choix actif → réactiver le handler d'erreur
    _qpErrorCount  = 0;       // nouveau choix → compteur d'erreurs remis à zéro
    _qpSrcChanging = true;    // ABORTED attendu si une src était en cours
    _qpSurahNum = num;
    _refreshQPSurahs();
    if (_qpReciterIdx >= 0) _playQP();
    else { _qpSrcChanging = false; _refreshQPNowPlaying(); }
}

// ── Lecture ──────────────────────────────────────────────────────────────
function _buildQPUrl(reciterIdx, surahNum) {
    const r = JS_CUSTOM.ucReciters[reciterIdx];
    // crossorigin="anonymous" force un fetch en mode CORS : indispensable pour
    // que l'égaliseur (Web Audio createMediaElementSource) reste audible avec
    // une source cross-origin (serveur http://127.0.0.1:8080), mais ce mode
    // échoue systématiquement sur une source file:// (récitateur "device" —
    // USB/téléchargé), qui ne peut jamais fournir d'en-têtes CORS -> c'était
    // la cause de "[RES] AUDIO load failed" / SRC_NOT_SUPPORTED. On bascule
    // donc l'attribut selon la source, avant de fournir l'URL (tous les
    // appelants de _playQP passent par cette fonction pour fixer audio.src).
    const _qpAudioEl = document.getElementById('quranAudioPlayer');
    if (_qpAudioEl) {
        if (r.source === 'device') _qpAudioEl.removeAttribute('crossorigin');
        else _qpAudioEl.setAttribute('crossorigin', 'anonymous');
    }
    // Récitateur "device" (USB ou téléchargé) : fichier local, servi en
    // file:// par le bridge natif — pas de serveur HTTP externe impliqué.
    if (r.source === 'device') {
        if (!window.AndroidMobile || typeof window.AndroidMobile.getReciterAudioUrl !== 'function') return '';
        try { return window.AndroidMobile.getReciterAudioUrl(r.dir, surahNum) || ''; }
        catch(e) { return ''; }
    }
    const base   = JS_CUSTOM.ucQuranServerUrl.replace(/\/+$/, '');
    // Règle : on essaie toujours .ogg en premier ; le handler 'error' du
    // lecteur bascule _qpTryExt sur 'mp3' et retente si .ogg est introuvable.
    // (r.format n'est plus utilisé ici : conservé seulement pour compat des
    // anciennes configs stockées — plus aucun contrôle dans l'UI.)
    const ext    = _qpTryExt === 'mp3' ? 'mp3' : 'ogg';
    const file   = String(surahNum).padStart(3, '0') + '.' + ext;
    return base + '/' + r.dir + '/' + file;
}

// Lecture du fichier de fin (spec/audio/fin.ogg) – indépendant du lecteur Coran principal
// Le src est déjà positionné par _redirectFinAudio() au chargement.
// Fallback sur local si l'élément n'a pas encore de src valide (ex: injection tardive du DOM).
function _playFinAudio() {
    // Toute la logique est protegee par un try/catch global : une exception
    // synchrone ici (ex: .play() ne renvoyant pas de Promise sur un vieux
    // moteur WebView) ne doit jamais remonter dans updateNextPrayerDisplay
    // (monkey-patch appele a chaque tick d'horloge) -- sinon ce tick entier
    // avorte silencieusement et _sqbFired reste a true, empechant toute
    // nouvelle tentative pour ce cycle (fin.mp3 jamais joue, sans aucune trace).
    try {
        _playFinAudioImpl();
    } catch (e) {
        _L('AUDIO','ERR',{action:'fin_mp3', reason:'exception', err:(e&&e.message)||String(e)});
    }
}

function _playFinAudioImpl() {
    if (_ucUnloading) return;
    var localSrc = 'spec/audio/fin.ogg';

    // Fallback final : jouer sur quranAudioPlayer (contexte geste utilisateur acquis)
    function _fallbackOnQP() {
        try {
            var qp = document.getElementById('quranAudioPlayer');
            if (!qp) { _L('AUDIO','ERR',{action:'fin_mp3', reason:'fallback_qp_not_found'}); return; }
            _L('AUDIO','WARN',{action:'fin_mp3', reason:'fallback_to_qp_element'});
            qp.src = localSrc;
            qp.load();
            var p2 = qp.play();
            if (p2 && p2.catch) p2.catch(function(err2) {
                _L('AUDIO','ERR',{action:'fin_mp3', reason:'fallback_qp_failed', err:(err2&&err2.message)||String(err2)});
            });
        } catch (e2) {
            _L('AUDIO','ERR',{action:'fin_mp3', reason:'fallback_qp_exception', err:(e2&&e2.message)||String(e2)});
        }
    }

    // Fallback intermediaire : local si le src serveur echoue
    function _tryPlay(el, src, onFail) {
        try {
            _L('AUDIO','FIRE',{action:'fin_mp3', src:src});
            var p = el.play();
            if (p && p.catch) p.catch(function(err) {
                var reason = (err && err.message) || String(err);
                _L('AUDIO','WARN',{action:'fin_mp3', src:src, reason:reason});
                if (onFail) onFail(err);
            });
        } catch (e3) {
            _L('AUDIO','ERR',{action:'fin_mp3', src:src, reason:'tryplay_exception', err:(e3&&e3.message)||String(e3)});
            if (onFail) onFail(e3);
        }
    }

    var fin = document.getElementById('quranFinAudio');
    if (!fin) { _fallbackOnQP(); return; }

    var isServerSrc = fin.src && fin.src !== window.location.href
                   && fin.src.indexOf('127.0.0.1') !== -1;

    // Aucun src valide : forcer local directement
    if (!fin.src || fin.src === window.location.href) {
        fin.src = localSrc;
        fin.load();
        _L('AUDIO','WARN',{action:'fin_mp3', reason:'no_src_yet', fallback:'local'});
        _tryPlay(fin, localSrc, _fallbackOnQP);
        return;
    }

    // Src serveur : si echec reseau, retry local, puis quranAudioPlayer
    if (isServerSrc) {
        fin.addEventListener('error', function _onFinErr() {
            fin.removeEventListener('error', _onFinErr);
            _L('AUDIO','WARN',{action:'fin_mp3', reason:'server_src_failed', fallback:'local'});
            fin.src = localSrc;
            fin.load();
            _tryPlay(fin, localSrc, _fallbackOnQP);
        }, { once: true });
    }

    // Tentative principale (src deja defini par _redirectFinAudio)
    _tryPlay(fin, fin.src, isServerSrc ? null : _fallbackOnQP);
}

function _playQP(forcePlay) {
    if (_qpRestoring) return null;             // ne pas interrompre une restauration en cours
    if (_qpReciterIdx < 0 || _qpSurahNum < 1) return null;
    // Ni serveur activé ni récitateur local installé → rien à jouer ; le
    // message informatif de qpNoSourceBanner est déjà affiché (cf.
    // _qpRefreshSourceAvailability, appelée à chaque (re)construction des
    // récitateurs). Évite une tentative de lecture qui échouerait à coup sûr.
    if (!_qpHasPlayableSource()) {
        _qpRefreshSourceAvailability();
        return null;
    }
    const audio = document.getElementById('quranAudioPlayer');
    if (!audio) return null;
    forcePlay = !!forcePlay;
    const shouldPlay = forcePlay || !audio.paused || _qpAutoAdvance;
    _qpShouldBePlaying = shouldPlay;
    _qpAutoAdvance = false;
    _qpTryExt = 'ogg';   // nouvelle lecture → on retente .ogg en premier
    // Sauvegarder AVANT de changer le src (currentTime encore valide sur l'ancienne sourate)
    // Puis mettre à jour reciterIdx/surahNum déjà faits par l'appelant → on sauve la nouvelle sélection
    _qpSavePosition();
    audio.src = _buildQPUrl(_qpReciterIdx, _qpSurahNum);
    audio.load();
    _refreshQPNowPlaying();
    _refreshQPSurahs();
    if (!shouldPlay) return null;
    _qpKickAudioCtx();   // resume() du contexte Web Audio dans le geste utilisateur
    const p = audio.play();
    if (p && p.catch) p.catch(function() {});
    return p;
}

// Exposition explicite : _startQuranAutoPlayback (bien plus haut, hors de
// portée lexicale de _playQP) en a besoin -- SANS ceci, tout appel à
// _playQP() depuis _startQuranAutoPlayback levait une ReferenceError et
// interrompait la fonction en silence, empêchant purement et simplement tout
// déclenchement PROGRAMMÉ de la lecture du Coran (le bug remonté par
// l'utilisateur : la sélection apparaissait faite mais rien ne se lancait
// jamais automatiquement). Ce bug préexistait à toute modification de cette
// session -- _startQuranAutoPlayback n'avait tout simplement jamais pu
// atteindre son appel _playQP(true).
window._playQP = _playQP;


// ═══════════════════════════════════════════════════════════════════════════
// ── MOTEUR ÉVÉNEMENTIEL TAWKIT ─────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Usage :
//    const unsub = ucOn(UC_EVT.AZAN_SHOW, function(e) {
//        console.log('Azan de', e.prayer, 'à', e.timeInMinutes, 'min');
//    });
//    unsub(); // se désabonner
//
//  Payload commun à tous les événements :
//    { type, timestamp }   +   champs spécifiques listés ci-dessous
//
//  UC_EVT.AZAN_TIME      → { prayer, timeInMinutes, isDohaPrayer }
//  UC_EVT.IQAMA_TIME     → { prayer }
//  UC_EVT.AZAN_SHOW      → { prayer, timeInMinutes, isDohaPrayer }
//  UC_EVT.AZAN_HIDE      → { }
//  UC_EVT.COUNTDOWN_TICK → { remainingSeconds, minutes, seconds, display }
//  UC_EVT.IQAMA_SHOW     → { prayer }
//  UC_EVT.IQAMA_HIDE     → { }
//  UC_EVT.BLACK_SHOW     → { }
//  UC_EVT.BLACK_HIDE     → { }
// ─────────────────────────────────────────────────────────────────────────

// ── Catalogue des types d'événements ─────────────────────────────────────
const UC_EVT = Object.freeze({
    AZAN_TIME:      1,   // Heure d'azan atteinte pour une prière
    IQAMA_TIME:     2,   // Heure d'iqama atteinte (fin du compte à rebours)
    AZAN_SHOW:      3,   // Écran azan s'affiche
    AZAN_HIDE:      4,   // Écran azan se cache
    COUNTDOWN_TICK: 5,   // Tick du compte à rebours iqama (chaque seconde)
    IQAMA_SHOW:     6,   // Écran iqama s'affiche
    IQAMA_HIDE:     7,   // Écran iqama se cache
    BLACK_SHOW:     8,   // Écran noir (début de salat) s'affiche
    BLACK_HIDE:     9,   // Écran noir se cache
});

// ── Registre interne ──────────────────────────────────────────────────────
const _ucReg = {};

// ── API publique : ucOn(type, handler) → unsubscribe() ───────────────────
function ucOn(type, handler) {
    if (!_ucReg[type]) _ucReg[type] = [];
    _ucReg[type].push(handler);
    return function() {
        _ucReg[type] = (_ucReg[type] || []).filter(function(h) { return h !== handler; });
    };
}
// Exposition globale : ucOn/UC_EVT sont utilises depuis des fonctions/setTimeout
// hors du scope d'injectTechOptionsUI (ex: applyNextPrayerHighlight, ligne ~1164).
window.ucOn   = ucOn;
window.UC_EVT = UC_EVT;

// ── Traces lisibles en français (complément de _L ci-dessous) ─────────────
// Ne remplace jamais la ligne technique existante (utile pour le debug fin) :
// ajoute une ligne SUPPLÉMENTAIRE en français simple pour les évènements les
// plus utiles à relire après coup (mosquée/admin distant qui consulte la
// console de debug suite à un incident), sans avoir à décoder key=val. Un
// seul point d'entrée (_ucHumanLog, appelé depuis _L) plutôt que dupliquer
// une phrase à chaque site d'appel _L('LIGHTS','FIRE',...) (il y en a une
// dizaine) : garantit une couverture complète (y compris les items futurs)
// et évite la dérive entre les deux formulations.
var _UC_PRAYER_FR = {
    FAJR: 'Fajr', SHRQ: 'Chourouk (Doha)', DOHR: 'Dhuhr', ASSR: 'Asr',
    MGRB: 'Maghreb', ISHA: 'Isha', JOMOA: "Jumu'a",
    Fajr: 'Fajr', Dhuhr: 'Dhuhr', Asr: 'Asr', Maghreb: 'Maghreb', Isha: 'Isha'
};
function _ucPrayerFr(p) { return _UC_PRAYER_FR[p] || p || '?'; }

var _UC_LIGHT_ITEM_FR = {
    ampliIntOn: "l'amplificateur intérieur",  ampliIntOff: "l'amplificateur intérieur",
    ampliExtOn: "l'amplificateur extérieur",  ampliExtOff: "l'amplificateur extérieur",
    minaretOn:  'le minaret',                 minaretOff:  'le minaret',
    mihrabOn:   'le mihrab',                  mihrabOff:   'le mihrab',
    rollerOpen: 'le rideau',                  rollerClose: 'le rideau',
    minaretBlink: 'le clignotement du minaret', mihrabBlink: 'le clignotement du mihrab'
};
function _ucLightItemFr(key) { return _UC_LIGHT_ITEM_FR[key] || key || '?'; }
function _ucLightActionFr(key) {
    if (key === 'rollerOpen') return 'Ouverture de';
    if (key === 'rollerClose') return 'Fermeture de';
    if (/Blink$/.test(key)) return 'Clignotement de';
    if (/Off$/.test(key)) return 'Extinction de';
    return 'Allumage de';
}
var _UC_LIGHT_EVT_FR = {
    beforeAzan: "avant l'azan", AZAN_SHOW: "à l'affichage de l'azan",
    afterAzanHide: "après la fin de l'azan", afterBlackHide: "après l'écran noir",
    afterBlackShow: "au début de l'écran noir", IQAMA_TIME: "à l'iqama",
    BLACK_HIDE: "après l'écran noir", BLACK_SHOW: "au début de l'écran noir",
    BTN_TEST: '(test manuel)'
};

function _ucHumanLog(cat, verb, ctx, ts) {
    ctx = ctx || {};
    var line = null;
    if (cat === 'EVT' && verb === 'AZAN_SHOW') {
        line = "Affichage de la page de l'azan de la prière de " + _ucPrayerFr(ctx.prayer);
    } else if (cat === 'AZAN' && verb === 'WEBVIEW_PLAY_START') {
        line = "Début de la lecture audio de l'azan de la prière de " + _ucPrayerFr(ctx.prayer);
    } else if (cat === 'LIGHTS' && verb === 'FIRE' && ctx.item) {
        var delayTxt = ctx.delay || ctx.threshold || ctx.duration || '';
        var evtFr = _UC_LIGHT_EVT_FR[ctx.evt] || '';
        line = _ucLightActionFr(ctx.item) + ' ' + _ucLightItemFr(ctx.item) +
               (delayTxt ? ' (délai ' + delayTxt + ')' : '') +
               (evtFr ? ' ' + evtFr : '') +
               (ctx.prayer ? ' — ' + _ucPrayerFr(ctx.prayer) : '');
    } else if (cat === 'AUDIO' && verb === 'FIRE' && ctx.action === 'autoStart') {
        line = "Début de la lecture du Coran avant l'azan de la prière de " + _ucPrayerFr(ctx.prayer);
    } else if (cat === 'AUDIO' && verb === 'STOP' && ctx.action === 'stopBeforeAzan' && ctx.result === 'stopped') {
        line = "Arrêt de la lecture du Coran avant l'azan de la prière de " + _ucPrayerFr(ctx.prayer);
    } else if (cat === 'AUDIO' && verb === 'FIRE' && ctx.action === 'fin_mp3') {
        line = "Lecture du son de fin de récitation (fin.ogg)";
    } else if (cat === 'POPUP' && verb === 'SHOW' && ctx.item === 'hadith_iqama') {
        line = "Affichage du hadith avant l'iqama (58s-40s)";
    } else if (cat === 'POPUP' && verb === 'HIDE' && ctx.item === 'hadith_iqama') {
        line = "Fermeture du hadith avant l'iqama";
    } else if (cat === 'POPUP' && verb === 'SHOW' && ctx.item === 'hadith_15s') {
        line = "Affichage du second hadith avant l'iqama (15s-7s)";
    } else if (cat === 'POPUP' && verb === 'HIDE' && ctx.item === 'hadith_15s') {
        line = "Fermeture du second hadith avant l'iqama";
    } else if (cat === 'AZKAR' && verb === 'START') {
        line = "Début de l'affichage des azkar" + (ctx.prayer ? ' — après ' + _ucPrayerFr(ctx.prayer) : '');
    } else if (cat === 'AZKAR' && verb === 'END') {
        line = "Fin de l'affichage des azkar" + (ctx.reason ? ' (' + ctx.reason + ')' : '');
    }
    if (line) console.log('[' + ts + '][' + cat + '] ' + line);
}

// ── Progression du chargement (écran de démarrage natif) ───────────────────
// Écran natif (activity_main.xml, splashOverlay) : logo + basmala + cercle de
// progression 0-100 par-dessus le WebView tant que ce fichier n'a pas fini de
// construire le DOM/CSS final -- retour utilisateur explicite du 19/08/2026
// ("éviter de voir la construction progressive du CSS"). On se branche sur
// les ~50 jalons _L('CUSTOM','INIT',...) déjà émis par les IIFEs
// d'initialisation réparties dans tout ce fichier (aucune de ces ~50 IIFEs
// n'a besoin d'être modifiée) pour alimenter un pourcentage 0-95 envoyé au
// natif au fil de l'exécution. Plafonné à 95 ici à dessein : certains jalons
// ne se déclenchent pas selon la config/l'appareil (gardes `if (!el) return`
// fréquentes dans ce fichier), donc le compte réel n'atteint pas toujours
// _UC_BOOT_TOTAL_MILESTONES. Le passage à 100 et la fermeture réelle du
// splash (MobileJsBridge.notifyAppFullyReady()) n'arrivent qu'à la toute fin
// de ce fichier -- seul signal fiable de "plus rien à exécuter en synchrone".
var _UC_BOOT_TOTAL_MILESTONES = 50; // nb actuel de _L('CUSTOM','INIT',...) ci-dessous -- ajuster si on en ajoute/retire
var _ucBootMilestoneCount = 0;
var _ucBootComplete = false;
function _ucReportBootProgress(pct) {
    if (_ucBootComplete) return;
    if (window.AndroidMobile && typeof window.AndroidMobile.reportLoadProgress === 'function') {
        window.AndroidMobile.reportLoadProgress(pct);
    }
}

// ── Log structuré commun ──────────────────────────────────────────────────
// Format : [HH:MM:SS][CAT] VERB key=val key=val ...
// Verbes normalisés : FIRE | SKIP | RESUME | STOP | EVT
function _L(cat, verb, ctx) {
    var now = new Date();
    var ts  = String(now.getHours()).padStart(2,'0')   + ':' +
              String(now.getMinutes()).padStart(2,'0')  + ':' +
              String(now.getSeconds()).padStart(2,'0');
    var parts = Object.keys(ctx || {}).map(function(k) { return k + '=' + ctx[k]; });
    console.log('[' + ts + '][' + cat + '] ' + verb + (parts.length ? ' ' + parts.join(' ') : ''));
    _ucHumanLog(cat, verb, ctx, ts);
    if (cat === 'CUSTOM' && verb === 'INIT' && !_ucBootComplete) {
        _ucBootMilestoneCount++;
        _ucReportBootProgress(Math.min(95, Math.round(_ucBootMilestoneCount / _UC_BOOT_TOTAL_MILESTONES * 100)));
    }
    if (_ucShouldPersist(cat, verb) && window.AndroidMobile && typeof window.AndroidMobile.logPrayerEvent === 'function') {
        try { window.AndroidMobile.logPrayerEvent(cat, verb + (parts.length ? ' ' + parts.join(' ') : '')); } catch (e) {}
    }
}

// ── Dispatcher interne ────────────────────────────────────────────────────
const _UC_EVT_NAME = {
    1: 'AZAN_TIME',  2: 'IQAMA_TIME', 3: 'AZAN_SHOW',  4: 'AZAN_HIDE',
    5: 'COUNTDOWN_TICK', 6: 'IQAMA_SHOW', 7: 'IQAMA_HIDE',
    8: 'BLACK_SHOW', 9: 'BLACK_HIDE'
};
function _ucFire(type, payload) {
    const data = Object.assign({ type: type, timestamp: Date.now() }, payload || {});
    // Trace TOUS les événements (avec ou sans handler) sauf COUNTDOWN_TICK (milestones séparés)
    if (type !== UC_EVT.COUNTDOWN_TICK) {
        var _evtName = _UC_EVT_NAME[type] || ('EVT#' + type);
        var _ctx = {};
        if (data.prayer) _ctx.prayer = data.prayer;
        if (data.timeInMinutes != null)
            _ctx.time = Math.floor(data.timeInMinutes/60) + ':' +
                        String(Math.round(data.timeInMinutes%60)).padStart(2,'0');
        const _h = _ucReg[type];
        _ctx.handlers = (_h ? _h.length : 0);
        _L('EVT', _evtName, _ctx);
    }
    const handlers = _ucReg[type];
    if (!handlers || !handlers.length) return;
    handlers.forEach(function(fn) {
        try { fn(data); } catch (e) { console.warn('[UC_EVT] ' + (_UC_EVT_NAME[type] || type) + ' handler error:', e); }
    });
}

// ── Helpers prière ────────────────────────────────────────────────────────
// Nom de la prière courante depuis currentPrayerInterval ("FAJR|SHRQ" → "FAJR")
function _ucPrayerNow() {
    try { return String(currentPrayerInterval || '').split('|')[0] || 'UNKNOWN'; }
    catch (e) { return 'UNKNOWN'; }
}

// Repli de dernier recours pour _ucCurrentPrayerKey() : recalcule la prière
// courante DIRECTEMENT depuis l'horloge et les variables globales du cœur
// (fajrTimeInMinutes...ishaTimeInMinutes, déjà écrites par
// calculateAndDisplayTimesFunction()), sans dépendre de currentPrayerInterval.
// Constaté en conditions réelles (07/08/2026, mosquée Nour Chaker, reprise
// mi-cycle après reboot pendant l'iqama Maghreb) : currentPrayerInterval est
// resté à sa valeur initiale ('') pendant toute la session (18+ minutes,
// plusieurs ticks minute passés) alors que le vrai azan Maghreb avait bien
// sonné à l'heure calculée -- la seule explication compatible est qu'aucun
// des chemins du cœur qui écrivent currentPrayerInterval
// (updateNextPrayerDisplayFunction(), appelée uniquement depuis
// updateTimeAndPrayersFunction(false) -- jamais avec skipPrayerTimeChecks=
// true, cf. resync-on-resume/onfocus) n'a fini par s'exécuter avec succès
// dans ce cycle de reprise. Résultat : _ucPrayerNow() retombait sur
// 'UNKNOWN', _ucCurrentPrayerKey() sur '', et ampliInt (et tout ce qui
// dépend du masque prière) restait bloqué avec reason=mask_blocked même
// pendant une prière explicitement autorisée par le masque. Reproduit
// exactement la même logique d'intervalle que updateNextPrayerDisplayFunction
// (m2body.js) mais localement, sans dépendance à une variable partagée
// pouvant rester périmée.
function _ucComputeCurrentPrayerFromClock() {
    try {
        if (typeof fajrTimeInMinutes !== 'number' || typeof ishaTimeInMinutes !== 'number') return '';
        // Les globales sont initialisées à 0 (m1prime.js) : `typeof ... number`
        // ne suffit pas -- si les horaires du jour ne sont pas encore calculés,
        // tout vaut 0 et la cascade ci-dessous renverrait 'ISHA' à tort.
        if (!fajrTimeInMinutes || !dohrTimeInMinutes || !maghribTimeInMinutes || !ishaTimeInMinutes) return '';
        var now = new Date();
        var mins = now.getHours() * 60 + now.getMinutes();
        if (mins <= fajrTimeInMinutes)    return 'ISHA';   // nuit precedente, avant Fajr
        if (mins <= shuruqTimeInMinutes)  return 'FAJR';
        if (mins <= dohrTimeInMinutes)    return 'SHRQ';
        if (mins <= asrTimeInMinutes)     return 'DOHR';
        if (mins <= maghribTimeInMinutes) return 'ASSR';
        if (mins <= ishaTimeInMinutes)    return 'MGRB';
        return 'ISHA';
    } catch (e) { return ''; }
}

// Identification de la prière par son heure exacte
function _ucPrayerAtMinutes(t) {
    if (t === fajrTimeInMinutes)    return 'FAJR';
    if (t === shuruqTimeInMinutes)  return 'SHRQ';
    if (t === dohrTimeInMinutes)    return 'DOHR';
    if (t === asrTimeInMinutes)     return 'ASSR';
    if (t === maghribTimeInMinutes) return 'MGRB';
    if (t === ishaTimeInMinutes)    return 'ISHA';
    return _ucPrayerNow();
}
// Exposé sur window : _ucPrayerAtMinutes / _ucPrayerNow / _ucComputeCurrentPrayerFromClock
// sont définis DANS injectTechOptionsUI et donc invisibles en portée lexicale depuis
// le code hors de cette IIFE (top-level ET IIFE frères déclarés plus bas).
// Sans cet export, un appel `_ucPrayerAtMinutes(...)` hors injectTechOptionsUI lève
// ReferenceError (constaté boîtier aboubaker, playAzanSoundFunction, custom.js:30952) ;
// et `typeof _ucPrayerNow` / `typeof _ucComputeCurrentPrayerFromClock` valaient
// silencieusement 'undefined' dans _ucCurrentPrayerKey() (top-level) -> ses deux
// replis étaient du code MORT, d'où reason=mask_blocked sur les amplis après
// tout reload mi-cycle (constaté box tn.monastir.aboubakr, Maghreb 30/08/2026).
window._ucPrayerAtMinutes = _ucPrayerAtMinutes;
window._ucPrayerNow = _ucPrayerNow;
window._ucComputeCurrentPrayerFromClock = _ucComputeCurrentPrayerFromClock;

// Heure en minutes depuis minuit pour une clé de prière
function _ucPrayerMinutes(key) {
    const _m = { FAJR: fajrTimeInMinutes, SHRQ: shuruqTimeInMinutes,
                 DOHR: dohrTimeInMinutes,  ASSR: asrTimeInMinutes,
                 MGRB: maghribTimeInMinutes, ISHA: ishaTimeInMinutes };
    return (_m[key] !== undefined) ? _m[key] : -1;
}

// ── Installation des hooks ────────────────────────────────────────────────
(function _ucInstallHooks() {

    // ─ EVENTS 1 + 3 : AZAN_TIME & AZAN_SHOW ─────────────────────────────
    //   Monkey-patch showAzanPopup() — appelée exactement quand
    //   currentTimeInMinutes == heure de la prière dans clockTickFunction()
    const _origShowAzan = showAzanPopup;
    showAzanPopup = function(isDohaPrayer) {
        const prayer = _ucPrayerAtMinutes(currentTimeInMinutes);
        const evtData = { prayer:        prayer,
                          timeInMinutes: _ucPrayerMinutes(prayer),
                          isDohaPrayer:  !!isDohaPrayer };
        _ucFire(UC_EVT.AZAN_TIME, evtData);       // avant l'affichage visuel
        _origShowAzan(isDohaPrayer);
        _ucFire(UC_EVT.AZAN_SHOW, evtData);       // après l'affichage visuel
    };

    // ─ EVENT 4 : AZAN_HIDE ───────────────────────────────────────────────
    //   Monkey-patch hideAzanPopupFunction()
    const _origHideAzan = hideAzanPopupFunction;
    hideAzanPopupFunction = function() {
        _origHideAzan();
        _ucFire(UC_EVT.AZAN_HIDE, {});
    };

    // ─ EVENTS 2 + 6 : IQAMA_TIME & IQAMA_SHOW ───────────────────────────
    //   Monkey-patch startIqamaSequenceFunction()
    //   Appelée dans clockTickFunction() quand remainingSeconds == 0
    const _origIqamaSeq = startIqamaSequenceFunction;
    startIqamaSequenceFunction = function() {
        const prayer = _ucPrayerNow();
        _ucActiveIqamaSeqEpoch = _ucIqamaSeqEpoch; // cf. _installResyncOnResume plus haut
        _ucFire(UC_EVT.IQAMA_TIME, { prayer: prayer });   // avant l'affichage
        _origIqamaSeq();
        _ucFire(UC_EVT.IQAMA_SHOW, { prayer: prayer });   // après l'affichage
    };

    // ─ EVENT 7 : IQAMA_HIDE ──────────────────────────────────────────────
    //   MutationObserver sur class de iqamaPopupVertical
    //   Raison : masqué via hideElementFunction() dans un setTimeout indirect
    //   → monkey-patch de hideElementFunction serait trop invasif
    const _iqamaEl = document.getElementById('iqamaPopupVertical');
    if (_iqamaEl) {
        let _iqamaVisible = !_iqamaEl.classList.contains('hiddenClass') &&
                            !_iqamaEl.classList.contains('fullScreenHiddenClass');
        new MutationObserver(function() {
            const nowHidden = _iqamaEl.classList.contains('hiddenClass') ||
                              _iqamaEl.classList.contains('fullScreenHiddenClass');
            if (nowHidden && _iqamaVisible)  _ucFire(UC_EVT.IQAMA_HIDE, {});
            _iqamaVisible = !nowHidden;
        }).observe(_iqamaEl, { attributes: true, attributeFilter: ['class'] });
    }

    // ─ EVENTS 8 + 9 : BLACK_SHOW & BLACK_HIDE ───────────────────────────
    //   MutationObserver sur style.transform de blackScreenVertical
    //   Raison : déclenché via setTimeout('activateBlackScreenIfEnabled()')
    //   → string eval dans setTimeout rend le monkey-patch moins fiable
    //   scaleX(1) = affiché  |  scaleX(0) = caché
    const _blackEl = document.getElementById('blackScreenVertical');
    if (_blackEl) {
        let _blackVisible = (_blackEl.style.transform === 'scaleX(1)');
        new MutationObserver(function() {
            const nowVisible = (_blackEl.style.transform === 'scaleX(1)');
            if  ( nowVisible && !_blackVisible) _ucFire(UC_EVT.BLACK_SHOW, {});
            else if (!nowVisible &&  _blackVisible) _ucFire(UC_EVT.BLACK_HIDE, {});
            _blackVisible = nowVisible;
        }).observe(_blackEl, { attributes: true, attributeFilter: ['style'] });
    }

    // ─ EVENT 5 : COUNTDOWN_TICK ──────────────────────────────────────────
    //   Polling 500ms sur remainingSeconds + isIqamaCounterActive
    //   Raison : evite de modifier clockTickFunction() (boucle principale)
    //   Cadence 500ms → pas de tick manqué même si le poll est légèrement décalé
    var _lastRemSecs = -1;
    var _ctrMilestones = [300, 240, 180, 120, 60, 30, 20, 15, 10, 5, 0];
    setInterval(function() {
        if (typeof isIqamaCounterActive === 'undefined' || !isIqamaCounterActive) {
            if (_lastRemSecs !== -1) _lastRemSecs = -1;
            return;
        }
        const rem = (typeof remainingSeconds !== 'undefined') ? remainingSeconds : -1;
        if (rem < 0 || rem === _lastRemSecs) return;
        var _prev = _lastRemSecs;
        _lastRemSecs = rem;
        _ucFire(UC_EVT.COUNTDOWN_TICK, {
            remainingSeconds: rem,
            minutes: Math.floor(rem / 60),
            seconds: Math.floor(rem % 60),
            display: Math.floor(rem / 60) + ':' + String(Math.floor(rem % 60)).padStart(2, '0'),
        });
        // Trace uniquement sur jalons remarquables
        if (_prev === -1)
            _L('CTR','START',{rem:rem+'s',display:Math.floor(rem/60)+':'+String(rem%60).padStart(2,'0'),prayer:_ucCurrentPrayerKey()});
        else if (_ctrMilestones.indexOf(rem) !== -1)
            _L('CTR','TICK', {rem:rem+'s',display:String(Math.floor(rem/60)).padStart(2,'0')+':'+String(rem%60).padStart(2,'0')});
    }, 500);

})();

// ── Jumu'ah : pas d'écran iqama ──────────────────────────────────────────────
// Pour la salat du vendredi, on court-circuite startIqamaSequenceFunction()
// entièrement : on ne l'appelle pas, donc aucun élément iqama n'est affiché.
// On reproduit uniquement ce qui est nécessaire : rideau noir après 12s et
// déclenchement des événements UC_EVT pour les autres systèmes.
(function _installJomoaIqamaSuppress() {

    // ── MutationObserver : trace TOUT changement de classe sur les popups iqama ──
    // (MutationObserver de diagnostic retiré — utiliser les traces [EVT] et [POPUP] à la place)

    var _prevIqamaSeq = startIqamaSequenceFunction;   // version déjà monkey-patchée
    startIqamaSequenceFunction = function() {
        _L('EVT','IQAMA_SEQ',{prayer:_ucCurrentPrayerKey(),isFriday:isFriday,duration:prayerDurationMinutes+'min',idx:currentPrayerIndex});
        // On se base sur _ucCurrentPrayerKey() (pas isFriday, qui est remis à false
        // par clockTickFunction() avant que cette fonction soit appelée)
        if (_ucCurrentPrayerKey() !== 'JOMOA') {
            _prevIqamaSeq();
            return;
        }
        // ── Jumu'ah : séquence sans écran iqama ──────────────────────────
        if (prayerDurationMinutes > 0) {
            setTimeout('onIqamaEndFunction()', prayerDurationMinutes * 60000);
        }
        if (JS_DATA.ucBlackScreenInPraying == 1) {
            setTimeout('activateBlackScreenIfEnabled()',   12000);
            setTimeout('animateBlackScreenCountdown()',    15000);
        }
        var _pr = (typeof _ucPrayerNow === 'function') ? _ucPrayerNow() : 'JOMOA';
        _ucActiveIqamaSeqEpoch = _ucIqamaSeqEpoch; // cf. _installResyncOnResume plus haut
        _ucFire(UC_EVT.IQAMA_TIME, { prayer: _pr });
        _ucFire(UC_EVT.IQAMA_SHOW, { prayer: _pr });

    };
})();

// ═══════════════════════════════════════════════════════════════════════════
// ── HANDLERS PROGRAMMATION LUMINEUSE (nécessitent UC_EVT + ucOn) ───────────
// ═══════════════════════════════════════════════════════════════════════════

// Anti-répétition iqama (réinitialisé à chaque nouvelle séquence)
const _lightIqamaFiredSet = {};

// Strobe : alterne ON/OFF toutes les 500ms pendant durationSec secondes
// Une seule trace au début (FIRE strobe_start) et une à la fin (STOP strobe_end).
// Les appels HTTP intermédiaires sont silencieux (pas de trace HTTP individuelle).
//
// Annulation : _strobeRunId[label] est incrémenté pour invalider le tick en cours.
// _cancelStrobe(label) arrête proprement un strobe par label (envoie le OFF final).
var _strobeRunId     = {};   // label → numéro de run courant
var _strobeUrlOff    = {};   // label → urlOff utilisée (arrêt propre)
var _strobeUrlOn     = {};   // label → urlOn utilisée  (arrêt réversible)
var _strobeEndWithOn = {};   // label → true = blink réversible (fin en ON)

function _cancelStrobe(label) {
    if (!_strobeRunId[label]) return;   // pas de strobe actif pour ce label
    _strobeRunId[label]++;              // invalide le tick en cours
    var endWithOn = _strobeEndWithOn[label];
    var urlFinal  = endWithOn ? (_strobeUrlOn[label] || _strobeUrlOff[label]) : _strobeUrlOff[label];
    if (urlFinal) _ucHttpCall(urlFinal, label);
    _L('LIGHTS','STOP',{action:'strobe_cancelled',item:label,endState:endWithOn?'ON':'OFF'});
    delete _strobeUrlOff[label];
    delete _strobeUrlOn[label];
    delete _strobeEndWithOn[label];
}

// endWithOn (optionnel, défaut false) : si true, le strobe se termine en état ON
// => blink réversible : la lumière revient à ON après le clignotement.
// L'extinction définitive reste exclusivement confiée à minaretOff / mihrabOff.
function _runStrobe(urlOn, urlOff, durationSec, label, endWithOn) {
    const INTERVAL_MS = 500;
    const endTime = Date.now() + durationSec * 1000;
    let phase = true;
    delete _httpErrSilenced[label];            // nouveau cycle → autoriser 1 erreur si échec
    _strobeRunId[label]     = (_strobeRunId[label] || 0) + 1;  // nouveau run ID
    _strobeUrlOff[label]    = urlOff;
    _strobeUrlOn[label]     = urlOn;
    _strobeEndWithOn[label] = !!endWithOn;
    const myRunId = _strobeRunId[label];
    const _endState = endWithOn ? 'ON' : 'OFF';
    _L('LIGHTS','FIRE',{action:'strobe_start',item:label,duration:durationSec+'s',endState:_endState});
    (function tick() {
        if (_strobeRunId[label] !== myRunId) return;  // annulé par _cancelStrobe
        if (Date.now() >= endTime) {
            var urlFinal = endWithOn ? urlOn : urlOff;
            _ucHttpCall(urlFinal, label);   // état final : loggué (fin visible)
            _L('LIGHTS','STOP',{action:'strobe_end',item:label,endState:_endState});
            delete _strobeUrlOff[label];
            delete _strobeUrlOn[label];
            delete _strobeEndWithOn[label];
            return;
        }
        _ucHttpCall(phase ? urlOn : urlOff, label, true);  // silent=true
        phase = !phase;
        setTimeout(tick, INTERVAL_MS);
    })();
}

// afterAzanShow : déclenché à l'affichage de l'écran azan (filtre par prière)
(function _installLightAfterAzanShow() {
    ucOn(UC_EVT.AZAN_SHOW, function(e) {
        _lastAzanPrayer = e.prayer || '';
        // Garde-fou Jumu'ah désactivée (même pattern que _installLightAfterAzanHide/
        // _applyLightTriggers, retour utilisateur 22/08/2026 : mosquée qui n'assure
        // pas la salat du vendredi, jomoaOnHrCheckbox décoché -- manquait ici,
        // seul afterAzanHide l'avait). _ucCurrentPrayerKey() substitue DOHR->JOMOA
        // le vendredi INDÉPENDAMMENT de ucJomoaOnHRscreen (cf. son propre
        // commentaire) : sans ce garde, l'automatisation afterAzanShow (ampliExtOn,
        // mihrabOn...) se déclenchait quand même le vendredi malgré la case décochée.
        if (_ucCurrentPrayerKey() === 'JOMOA' && JS_DATA.ucJomoaOnHRscreen != 1) return;
        _lightProgramConfig.forEach(function(item) {
            if (item.trigger !== 'afterAzanShow') return;
            var _ctx = { item: item.key, evt: 'AZAN_SHOW', prayer: e.prayer };
            if (item.prayerFilter && item.prayerFilter.split('|').indexOf(e.prayer) === -1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'prayer_filter',filter:item.prayerFilter})); return; }
            if (JS_CUSTOM[item.enabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'disabled'})); return; }
            if (item.pairEnabledSetting && JS_CUSTOM[item.pairEnabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'pair_off',pair:item.pairEnabledSetting})); return; }
            const url = (JS_CUSTOM[item.urlSetting] || '').trim();
            if (!url)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty'})); return; }
            const delaySec = parseInt(JS_CUSTOM[item.delaySetting], 10);
            const delayMs  = (isNaN(delaySec) || delaySec < 0 ? (item.delayDefault || 0) : delaySec) * 1000;
            var _bh_delaySec = delayMs/1000;
            _L('LIGHTS','FIRE', Object.assign({},_ctx,{delay:_bh_delaySec+'s'}));
            (function(capturedItem, capturedCtx) {
                setTimeout(function() {
                    if (JS_CUSTOM[capturedItem.enabledSetting] != 1) {
                        _L('LIGHTS','SKIP_DEFERRED', Object.assign({},capturedCtx,{reason:'disabled_at_fire'}));
                        return;
                    }
                    const u = (JS_CUSTOM[capturedItem.urlSetting] || '').trim();
                    if (!u) { _L('LIGHTS','SKIP_DEFERRED', Object.assign({},capturedCtx,{reason:'url_empty_at_fire'})); return; }
                    _L('LIGHTS','HTTP_SEND', capturedCtx);
                    _ucHttpCall(u, capturedItem.key);
                }, delayMs);
            })(item, Object.assign({},_ctx,{delay:_bh_delaySec+'s'}));
        });
    });
})();

// afterAzanHide : déclenché à la fermeture de l'écran azan
(function _installLightAfterAzanHide() {

    // Guard anti-double-fire : AZAN_HIDE peut s'émettre 2× par cycle de prière
    // (1× immédiatement si l'audio échoue, 1× ~1 min plus tard lors de la rotation
    // vers la prière suivante). Sans guard, ampliExtOff partirait deux fois.
    // Cooldown 5 min par item ; reset à chaque AZAN_TIME (nouveau cycle).
    var _azanHideFiredMs = {};
    ucOn(UC_EVT.AZAN_TIME, function() {
        Object.keys(_azanHideFiredMs).forEach(function(k) { _azanHideFiredMs[k] = 0; });
    });

    ucOn(UC_EVT.AZAN_HIDE, function() {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        if (_ucCurrentPrayerKey() === 'JOMOA' && JS_DATA.ucJomoaOnHRscreen != 1) return; // Jumu'ah désactivée → pas de déclenchement
        const isJomoa = (_ucCurrentPrayerKey() === 'JOMOA');
        _lightProgramConfig.forEach(function(item) {
            if (_getItemTrigger(item) !== 'afterAzanHide') return;
            var _ctx = { item: item.key, evt: 'AZAN_HIDE', prayer: _ucCurrentPrayerKey() };

            // Guard anti-double-fire (cooldown 5 min)
            var _msAgo = Date.now() - (_azanHideFiredMs[item.key] || 0);
            if (_msAgo < 5 * 60 * 1000) {
                _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'cooldown_5min_azanHide',
                    msSince:Math.round(_msAgo/1000)+'s'}));
                return;
            }
            _azanHideFiredMs[item.key] = Date.now();

            if (JS_CUSTOM[item.enabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'disabled'})); return; }
            if (item.pairEnabledSetting && JS_CUSTOM[item.pairEnabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'pair_off',pair:item.pairEnabledSetting})); return; }
            if (!_lightPrayerAllowed(item, _ucCurrentPrayerKey()))
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'mask_blocked'})); return; }
            const url = (JS_CUSTOM[item.urlSetting] || '').trim();
            if (!url)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty'})); return; }
            let delaySec;
            if (isJomoa && item.jomaDelaySetting) {
                delaySec = parseInt(JS_CUSTOM[item.jomaDelaySetting], 10);
                if (isNaN(delaySec) || delaySec < 0) delaySec = item.jomaDelayDefault || 0;
            } else {
                delaySec = parseInt(JS_CUSTOM[item.delaySetting], 10);
                if (isNaN(delaySec) || delaySec < 0) delaySec = item.delayDefault || 0;
            }
            _L('LIGHTS','FIRE', Object.assign({},_ctx,{delay:delaySec+'s', jomoa:isJomoa}));
            const delayMs = delaySec * 1000;
            var _capturedCtx = Object.assign({}, _ctx, {delay:delaySec+'s'});
            var _fireItem = (function(capturedItem, capturedCtx) {
                return function() {
                    if (JS_CUSTOM[capturedItem.enabledSetting] != 1) {
                        _L('LIGHTS','SKIP_DEFERRED', Object.assign({},capturedCtx,{reason:'disabled_at_fire'}));
                        return;
                    }
                    var u = (JS_CUSTOM[capturedItem.urlSetting] || '').trim();
                    if (!u) { _L('LIGHTS','SKIP_DEFERRED', Object.assign({},capturedCtx,{reason:'url_empty_at_fire'})); return; }
                    _L('LIGHTS','HTTP_SEND', capturedCtx);
                    _ucHttpCall(u, capturedItem.key);
                };
            })(item, _capturedCtx);
            setTimeout(function() {
                if (window._salatNabiActive) {
                    // salatNabi encore en cours → on diffère jusqu'à sa fin
                    _L('LIGHTS','WAIT', Object.assign({},_ctx,{reason:'salatNabi_active'}));
                    window._salatNabiOnEndCallbacks = window._salatNabiOnEndCallbacks || [];
                    window._salatNabiOnEndCallbacks.push(_fireItem);
                } else {
                    _fireItem();
                }
            }, delayMs);
        });
    });
})();

// beforeIqama : déclenché pendant le countdown iqama
(function _installLightBeforeIqama() {
    ucOn(UC_EVT.IQAMA_SHOW, function() {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        _lightProgramConfig.forEach(function(item) {
            if (_getItemTrigger(item) === 'beforeIqama') _lightIqamaFiredSet[item.key] = false;
        });
    });

    ucOn(UC_EVT.COUNTDOWN_TICK, function(e) {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        _lightProgramConfig.forEach(function(item) {
            if (_getItemTrigger(item) !== 'beforeIqama') return;
            const thresholdSec = parseInt(JS_CUSTOM[item.delaySetting], 10);
            const threshold    = isNaN(thresholdSec) ? (item.delayDefault || 0) : thresholdSec;
            // Pas encore dans la fenêtre ou déjà décidé → silencieux
            if (e.remainingSeconds > threshold) return;
            if (_lightIqamaFiredSet[item.key]) return;

            // Décision unique au franchissement du seuil
            _lightIqamaFiredSet[item.key] = true;
            var _ctx = { item: item.key, evt: 'COUNTDOWN_TICK', prayer: _ucCurrentPrayerKey(),
                         rem: e.remainingSeconds+'s', threshold: threshold+'s' };

            if (JS_CUSTOM[item.enabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'disabled'})); return; }
            if (item.pairEnabledSetting && JS_CUSTOM[item.pairEnabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'pair_off',pair:item.pairEnabledSetting})); return; }
            if (!_lightPrayerAllowed(item, _ucCurrentPrayerKey()))
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'mask_blocked'})); return; }

            if (item.isStrobe) {
                const pairItem = _lightProgramConfig.find(function(x) { return x.key === item.strobePairKey; });
                const urlOn  = (JS_CUSTOM[item.urlSetting]  || '').trim();
                const urlOff = pairItem ? (JS_CUSTOM[pairItem.urlSetting] || '').trim() : '';
                const durSec = parseInt(JS_CUSTOM[item.extraSetting], 10);
                const duration = isNaN(durSec) ? (item.extraDefault || 10) : durSec;
                if (!urlOn || !urlOff)
                    { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty',mode:'strobe'})); return; }
                _L('LIGHTS','FIRE', Object.assign({},_ctx,{mode:'strobe',duration:duration+'s'}));
                _runStrobe(urlOn, urlOff, duration, item.key);
            } else {
                const url = (JS_CUSTOM[item.urlSetting] || '').trim();
                if (!url)
                    { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty'})); return; }
                _L('LIGHTS','FIRE', _ctx);
                _ucHttpCall(url, item.key);
            }
        });
    });
})();

// afterBlackHide : déclenché à la fermeture du rideau noir (fin de salat)
(function _installLightAfterBlackHide() {
    ucOn(UC_EVT.BLACK_HIDE, function() {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        // Garde-fou Jumu'ah désactivée (cf. commentaire identique dans
        // _installLightAfterAzanShow un peu plus haut) : le rideau noir du
        // vendredi (BLACK_SHOW/BLACK_HIDE, cœur m2body.js) se déclenche sur
        // isFriday SEUL, sans jamais vérifier ucJomoaOnHRscreen -- sans ce
        // garde, afterBlackHide (ampliIntOff, mihrabOff, rollerClose...) se
        // déclenchait donc aussi malgré la case décochée.
        if (_ucCurrentPrayerKey() === 'JOMOA' && JS_DATA.ucJomoaOnHRscreen != 1) return;
        _lightProgramConfig.forEach(function(item) {
            if (item.trigger !== 'afterBlackHide') return;
            var _ctx = { item: item.key, evt: 'BLACK_HIDE', prayer: _ucCurrentPrayerKey() };
            if (JS_CUSTOM[item.enabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'disabled'})); return; }
            if (!_lightPrayerAllowed(item, _ucCurrentPrayerKey()))
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'mask_blocked'})); return; }
            const url = (JS_CUSTOM[item.urlSetting] || '').trim();
            if (!url)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty'})); return; }
            const delaySec = parseInt(JS_CUSTOM[item.delaySetting], 10);
            const delayMs  = (isNaN(delaySec) || delaySec < 0 ? (item.delayDefault || 0) : delaySec) * 1000;
            _L('LIGHTS','FIRE', Object.assign({},_ctx,{delay:(delayMs/1000)+'s'}));
            setTimeout(function() {
                if (JS_CUSTOM[item.enabledSetting] != 1) return;
                const u = (JS_CUSTOM[item.urlSetting] || '').trim();
                if (u) _ucHttpCall(u, item.key);
            }, delayMs);
        });
    });
})();

// afterBlackShow : déclenché à l'ouverture du rideau noir (début de salat)
(function _installLightAfterBlackShow() {
    ucOn(UC_EVT.BLACK_SHOW, function() {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        // Garde-fou Jumu'ah désactivée (cf. commentaire identique dans
        // _installLightAfterAzanShow un peu plus haut) : le rideau noir du
        // vendredi (BLACK_SHOW/BLACK_HIDE, cœur m2body.js) se déclenche sur
        // isFriday SEUL, sans jamais vérifier ucJomoaOnHRscreen -- sans ce
        // garde, afterBlackShow (ampliIntOn, mihrabOn...) se déclenchait donc
        // aussi malgré la case décochée.
        if (_ucCurrentPrayerKey() === 'JOMOA' && JS_DATA.ucJomoaOnHRscreen != 1) return;
        _lightProgramConfig.forEach(function(item) {
            if (item.trigger !== 'afterBlackShow') return;
            var _ctx = { item: item.key, evt: 'BLACK_SHOW', prayer: _ucCurrentPrayerKey() };
            if (JS_CUSTOM[item.enabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'disabled'})); return; }
            if (item.pairEnabledSetting && JS_CUSTOM[item.pairEnabledSetting] != 1)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'pair_off',pair:item.pairEnabledSetting})); return; }
            if (!_lightPrayerAllowed(item, _ucCurrentPrayerKey()))
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'mask_blocked'})); return; }
            const url = (JS_CUSTOM[item.urlSetting] || '').trim();
            if (!url)
                { _L('LIGHTS','SKIP', Object.assign({},_ctx,{reason:'url_empty'})); return; }
            const delaySec = parseInt(JS_CUSTOM[item.delaySetting], 10);
            const delayMs  = (isNaN(delaySec) || delaySec < 0 ? (item.delayDefault || 0) : delaySec) * 1000;
            _L('LIGHTS','FIRE', Object.assign({},_ctx,{delay:(delayMs/1000)+'s'}));
            setTimeout(function() {
                if (JS_CUSTOM[item.enabledSetting] != 1) return;
                const u = (JS_CUSTOM[item.urlSetting] || '').trim();
                if (u) _ucHttpCall(u, item.key);
            }, delayMs);
        });
    });
})();

// atIqamaZero : وميض المِأذنة / المحراب quand remainingSeconds == 0 (UC_EVT.IQAMA_TIME)
(function _installLightAtIqamaZero() {
    ucOn(UC_EVT.IQAMA_TIME, function() {
        if (_ucCurrentPrayerKey() === 'SHRQ') return;   // Doha : aucun déclenchement lumières
        // ── Minaret ──────────────────────────────────────────────────────
        var _ctxMin = { item: 'minaretBlink', evt: 'IQAMA_TIME', prayer: _ucCurrentPrayerKey() };
        if (JS_CUSTOM.ucIqamaZeroMinaretBlinkEnabled != 1) {
            _L('LIGHTS','SKIP', Object.assign({},_ctxMin,{reason:'disabled'}));
        } else {
            var urlOn  = (JS_CUSTOM.ucLightMinaretOnUrl  || '').trim();
            var urlOff = (JS_CUSTOM.ucLightMinaretOffUrl || '').trim();
            var durMin = parseInt(JS_CUSTOM.ucIqamaZeroMinaretBlinkDuration, 10);
            if (isNaN(durMin) || durMin < 1) durMin = 10;
            if (!urlOn || !urlOff) {
                _L('LIGHTS','SKIP', Object.assign({},_ctxMin,{reason:'url_empty', urlOn:urlOn||'—', urlOff:urlOff||'—'}));
            } else {
                // Filtre prière : blink autorisé uniquement pour MGRB, ISHA, FAJR
                var _minBlinkAllowed = ['MGRB', 'ISHA', 'FAJR'];
                if (_minBlinkAllowed.indexOf(_ucCurrentPrayerKey()) === -1) {
                    _L('LIGHTS','SKIP', Object.assign({},_ctxMin,{reason:'prayer_filter', allowed:'MGRB|ISHA|FAJR', prayer:_ucCurrentPrayerKey()}));
                } else {
                    var _minaretEndOn = (_ucCurrentPrayerKey() !== 'FAJR'); // MGRB/ISHA: fin en ON | FAJR: fin en OFF
                _L('LIGHTS','FIRE', Object.assign({},_ctxMin,{mode:'strobe', duration:durMin+'s', urlOn:urlOn, urlOff:urlOff, endState:_minaretEndOn?'ON':'OFF'}));
                    _runStrobe(urlOn, urlOff, durMin, 'minaretBlink', _minaretEndOn);
                }
            }
        }
        // ── Mihrab ───────────────────────────────────────────────────────
        var _ctxMih = { item: 'mihrabBlink', evt: 'IQAMA_TIME', prayer: _ucCurrentPrayerKey() };
        if (JS_CUSTOM.ucIqamaZeroMihrabBlinkEnabled != 1) {
            _L('LIGHTS','SKIP', Object.assign({},_ctxMih,{reason:'disabled'}));
        } else if (JS_CUSTOM.ucLightMihrabOnEnabled != 1) {
            _L('LIGHTS','SKIP', Object.assign({},_ctxMih,{reason:'mihrabOn_not_enabled'}));
        } else if (!_lightPrayerAllowed({prayersMaskSetting:'ucLightMihrabOnPrayers'}, _ucCurrentPrayerKey())) {
            _L('LIGHTS','SKIP', Object.assign({},_ctxMih,{reason:'prayer_not_in_mask', prayer:_ucCurrentPrayerKey()}));
        } else {
            var urlOn2  = (JS_CUSTOM.ucLightMihrabOnUrl  || '').trim();
            var urlOff2 = (JS_CUSTOM.ucLightMihrabOffUrl || '').trim();
            var durMih  = parseInt(JS_CUSTOM.ucIqamaZeroMihrabBlinkDuration, 10);
            if (isNaN(durMih) || durMih < 1) durMih = 10;
            if (!urlOn2 || !urlOff2) {
                _L('LIGHTS','SKIP', Object.assign({},_ctxMih,{reason:'url_empty', urlOn:urlOn2||'—', urlOff:urlOff2||'—'}));
            } else {
                _L('LIGHTS','FIRE', Object.assign({},_ctxMih,{mode:'strobe', duration:durMih+'s', urlOn:urlOn2, urlOff:urlOff2, endState:'ON'}));
                _runStrobe(urlOn2, urlOff2, durMih, 'mihrabBlink', true);  // reversible : fin en ON
            }
        }
    });
})();

// ═══════════════════════════════════════════════════════════════════════════
// ── SALAT 'ALA NABI ﷺ ─────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//  Déclenchement : UC_EVT.AZAN_HIDE le jeudi soir (= début de la nuit du
//  vendredi en calendrier islamique) pour les prières MGRB et/ou ISHA.
//
//  Cas 1 : ucSalatNabiEnabled=1 ET prière activée  → popup + lecture audio
//            durée popup = durée réelle audio (onended) ; fallback 15s si erreur
//  Cas 2 : ucSalatNabiEnabled=0 ET prière activée  → popup seule 15s, pas d'audio
//  Cas 3 : prière non activée (quelle que soit la checkbox principale) → rien
//
//  Anti-double : _snFired remis à false à chaque UC_EVT.AZAN_TIME.
//  Anti-empilement : _snVisible bloque un nouveau show si déjà visible.
//  Fermeture auto si iqama démarre (UC_EVT.IQAMA_SHOW).
// ═══════════════════════════════════════════════════════════════════════════
(function _installSalatNabi() {

    // ── Injection CSS ─────────────────────────────────────────────────────
    var _css = document.createElement('style');
    _css.id  = 'ucSalatNabiStyle';
    _css.textContent =
        '#ucSalatNabiOverlay {' +
        '    position: fixed;' +
        '    top: 0; left: 0; right: 0; bottom: 0;' +
        '    z-index: 99996;' +           /* au-dessus de l'overlay hadith (99995) */
        '    display: flex;' +
        '    flex-direction: column;' +
        '    align-items: center;' +
        '    justify-content: center;' +
        '    text-align: center;' +
        '    direction: rtl;' +
        '    background: rgba(0,0,0,0.95);' +
        '    opacity: 0;' +
        '    pointer-events: none;' +
        '    transition: opacity 0.7s ease-in;' +
        '}' +
        '#ucSalatNabiOverlay.ucSN-visible {' +
        '    opacity: 1;' +
        '    pointer-events: auto;' +
        '}' +
        '#ucSalatNabiOverlay.ucSN-fading {' +
        '    opacity: 0 !important;' +
        '    transition: opacity 1.8s ease-out;' +
        '}' +
        '#ucSalatNabiBox {' +
        '    display: flex;' +
        '    flex-direction: column;' +
        '    align-items: center;' +
        '    gap: 1.7em;' +
        '    padding: 3em 4em;' +
        '    max-width: 90vw;' +
        '}' +
        '.ucSN-intro {' +
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 4.5vw;' +
        '    font-weight: 600;' +
        '    color: #f39e0b;' +
        '    text-shadow: 0 0 18px rgba(211,165,85,0.55);' +
        '    letter-spacing: 0.06em;' +
        '}' +
        '.ucSN-hadith {' +
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 5.5vw;' +
        '    font-weight: 700;' +
        '    color: #f5f0e8;' +
        '    line-height: 1.65;' +
        '    text-shadow: 0 1px 6px rgba(0,0,0,0.8);' +
        '    letter-spacing: 0.03em;' +
        '}' +
        '.ucSN-source {' +
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 3.0vw;' +
        '    font-weight: 400;' +
        '    color: #a89060;' +
        '    opacity: 0.85;' +
        '    letter-spacing: 0.08em;' +
        '}';
    document.head.appendChild(_css);

    // ── Injection DOM ─────────────────────────────────────────────────────
    var _overlay = document.createElement('div');
    _overlay.id  = 'ucSalatNabiOverlay';
    _overlay.innerHTML =
        '<div id="ucSalatNabiBox">' +
            '<div class="ucSN-intro">قال رسول الله \uFDFA :</div>' +
            '<div class="ucSN-hadith">' +
                '\u00AB إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الجُمُعَةِ،<br>' +
                'فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ،<br>' +
                'فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ \u00BB' +
            '</div>' +
            '<div class="ucSN-source">رواه أبو داود</div>' +
        '</div>';
    document.body.appendChild(_overlay);

    // ── Élément audio (préchargé, non visible) ────────────────────────────
    var _localSalatNabi = './spec/audio/salatnabi.ogg';
    var _audio = new Audio(_localSalatNabi);
    _audio.id      = 'ucSalatNabiAudio';
    _audio.preload = 'auto';
    // Élément DÉTACHÉ du DOM (jamais appendChild) -- getElementById ne le
    // trouverait pas, d'où l'enregistrement direct par fermeture (cf. tout en
    // haut du fichier, _installUniversalFlipToMute).
    _ucRegisterFlipMuteTarget(function() { return _audio; });

    // Source audio salatnabi.mp3 : redirection au chargement (même pattern que azan)
    (function _redirectSalatNabiAudio() {
        function _applySrc(src, source) {
            _audio.src = src;
            _audio.load();
            _L('AUDIO','FIRE',{action:'redirect_salatnabi', source:source, src:src});
        }

        if (JS_CUSTOM.ucAzanFromServer != 1) {
            _applySrc(_localSalatNabi, 'local');
            return;
        }

        var base      = (JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '');
        var serverSrc = base + '/AUDIO/salatnabi.mp3';
        var xhr = new XMLHttpRequest();
        xhr.open('HEAD', serverSrc, true);
        xhr.timeout = 3000;
        xhr.onload = function() {
            if (xhr.status >= 200 && xhr.status < 400) {
                _applySrc(serverSrc, 'server');
            } else {
                _L('AUDIO','WARN',{action:'redirect_salatnabi',
                    reason:'server_http_' + xhr.status, fallback:'local'});
                _applySrc(_localSalatNabi, 'local_fallback');
            }
        };
        xhr.onerror   = function() {
            _L('AUDIO','WARN',{action:'redirect_salatnabi',
                reason:'server_unreachable', fallback:'local'});
            _applySrc(_localSalatNabi, 'local_fallback');
        };
        xhr.ontimeout = function() {
            _L('AUDIO','WARN',{action:'redirect_salatnabi',
                reason:'server_timeout', fallback:'local'});
            _applySrc(_localSalatNabi, 'local_fallback');
        };
        xhr.send();
    })();

    // ── État interne ──────────────────────────────────────────────────────
    var _snVisible     = false;    // overlay actuellement affiché
    var _snFired       = false;    // anti-double par cycle de prière
    var _fadeTimer     = null;     // id du setTimeout de transition de fermeture
    var _fallbackTimer = null;     // id du setTimeout de fermeture automatique (fallback)
    _ucRegisterCleanup(function() {
        if (_fadeTimer)     { clearTimeout(_fadeTimer);     _fadeTimer     = null; }
        if (_fallbackTimer) { clearTimeout(_fallbackTimer); _fallbackTimer = null; }
    });

    // ── Helpers ───────────────────────────────────────────────────────────

    // Jeudi civil (getDay()===4) = début de la nuit du vendredi islamique.
    // On couvre ainsi MGRB et ISHA du jeudi, qui correspondent au début du
    // vendredi en calendrier islamique (la journée islamique commence au coucher du soleil).
    function _isThursdayNight() {
        return (new Date()).getDay() === 4;
    }

    function _isPrayerEnabled(prayer) {
        if (prayer === 'MGRB') return JS_CUSTOM.ucSalatNabiMagrebEnabled == 1;
        if (prayer === 'ISHA') return JS_CUSTOM.ucSalatNabiIshaEnabled   == 1;
        return false;
    }

    function _clearTimers() {
        if (_fallbackTimer) { clearTimeout(_fallbackTimer); _fallbackTimer = null; }
        if (_fadeTimer)     { clearTimeout(_fadeTimer);     _fadeTimer     = null; }
    }

    function _startFade() {
        if (!_snVisible) return;
        _clearTimers();
        _overlay.classList.remove('ucSN-visible');
        _overlay.classList.add('ucSN-fading');
        _fadeTimer = setTimeout(function() {
            _overlay.classList.remove('ucSN-fading');
            _snVisible = false;
            _fadeTimer = null;
            _L('POPUP','HIDE',{item:'salatNabi'});
            // Notifier les modules en attente (ex : ampliExtOff)
            window._salatNabiActive = false;
            var cbs = window._salatNabiOnEndCallbacks || [];
            window._salatNabiOnEndCallbacks = [];
            cbs.forEach(function(cb) { try { cb(); } catch(e) {} });
        }, 2000);
    }

    function _forceHide(reason) {
        _L('POPUP','FORCE_HIDE',{item:'salatNabi',reason:reason||'unspecified',wasVisible:_snVisible});
        _audio.pause();
        _audio.currentTime = 0;
        _audio.onended  = null;
        _audio.onerror  = null;
        _clearTimers();
        _overlay.classList.remove('ucSN-visible', 'ucSN-fading');
        _snVisible = false;
        window._salatNabiActive = false;
        window._salatNabiOnEndCallbacks = [];  // abandon des callbacks si fermeture forcée
    }
    // État lisible depuis l'extérieur (diagnostic resync).
    window._ucIsSalatNabiVisible = function() { return _snVisible; };
    // Exposé pour _ucResyncPrayerSequence (tout en haut du fichier) : même
    // classe de bug que l'azan (audio JS gelé par pauseTimers() avant son
    // 'ended' si l'écran s'éteint pendant la lecture) pourrait laisser cet
    // overlay bloqué indéfiniment au retour. Idempotent (no-op si déjà masqué,
    // hormis le reset ci-dessus qui est sans effet visuel si déjà à l'état bas).
    window._ucSalatNabiForceHide = _forceHide;

    function _show(withAudio) {
        if (_snVisible) return;
        _snVisible = true;
        window._salatNabiActive = true;            // signale aux autres modules qu'on joue
        _overlay.classList.remove('ucSN-fading');
        _overlay.classList.add('ucSN-visible');
        _L('POPUP','SHOW',{item:'salatNabi',audio:withAudio});

        if (withAudio) {
            _audio.currentTime = 0;

            _audio.onended = function() {
                _L('AUDIO','STOP',{action:'salatNabi',result:'ended'});
                _audio.onended = null;
                _audio.onerror = null;
                _startFade();
            };

            _audio.onerror = function() {
                _audio.onended = null;
                _audio.onerror = null;
                // Fallback spec/audio/ si le serveur HTTP est indisponible à la lecture
                var _cur = (_audio.src || '').replace(/\?.*$/, '');
                if (_cur.indexOf('spec/audio/') === -1) {
                    _L('AUDIO','FALLBACK',{action:'salatNabi_fallback',
                        from:'server', to:_localSalatNabi});
                    _audio.src = _localSalatNabi;
                    _audio.load();
                    _audio.onended = function() {
                        _L('AUDIO','STOP',{action:'salatNabi',result:'ended'});
                        _audio.onended = null; _audio.onerror = null;
                        _startFade();
                    };
                    _audio.onerror = function() {
                        _L('AUDIO','FALLBACK_ERR',{action:'salatNabi_fallback',
                            src:_localSalatNabi});
                        _audio.onended = null; _audio.onerror = null;
                        _fallbackTimer = setTimeout(_startFade, 15000);
                    };
                    var _pf = _audio.play();
                    if (_pf && typeof _pf.catch === 'function') {
                        _pf.catch(function(err) {
                            _L('AUDIO','SKIP',{action:'salatNabi_fallback',
                                reason:'play_blocked', err:(err&&err.message||String(err))});
                            _audio.onended = null; _audio.onerror = null;
                            _fallbackTimer = setTimeout(_startFade, 15000);
                        });
                    }
                    return;
                }
                // spec/audio a aussi échoué
                _L('AUDIO','SKIP',{action:'salatNabi',reason:'onerror_all_failed'});
                _fallbackTimer = setTimeout(_startFade, 15000);
            };

            var _p = _audio.play();
            if (_p && typeof _p.catch === 'function') {
                _p.catch(function(err) {
                    _L('AUDIO','SKIP',{action:'salatNabi',reason:'play_blocked',err:(err && err.message || String(err))});
                    _audio.onended = null;
                    _audio.onerror = null;
                    _fallbackTimer = setTimeout(_startFade, 15000);
                });
            } else {
                _L('AUDIO','FIRE',{action:'salatNabi',result:'started'});
            }
        } else {
            _L('POPUP','SHOW',{item:'salatNabi',audio:false,mode:'popup_only_15s'});
            _fallbackTimer = setTimeout(_startFade, 15000);
        }
    }

    // ── Déclenchement principal : fermeture écran azan ────────────────────
    ucOn(UC_EVT.AZAN_HIDE, function() {
        var prayer   = _ucCurrentPrayerKey();
        var isThur   = _isThursdayNight();
        var prayerOk = _isPrayerEnabled(prayer);
        var _ctx     = { item: 'salatNabi', prayer: prayer, isThursday: isThur };

        if (_snFired) {
            _L('POPUP','SKIP', Object.assign({}, _ctx, { reason: 'already_fired' }));
            return;
        }
        if (!isThur) {
            _L('POPUP','SKIP', Object.assign({}, _ctx, { reason: 'not_thursday' }));
            return;
        }
        if (!prayerOk) {
            _L('POPUP','SKIP', Object.assign({}, _ctx, { reason: 'prayer_not_enabled' }));
            return;
        }

        _snFired = true;
        var withAudio = (JS_CUSTOM.ucSalatNabiEnabled == 1);
        _L('POPUP','FIRE', Object.assign({}, _ctx, { withAudio: withAudio }));
        _show(withAudio);
    });

    // ── Sécurité : réinitialiser le flag à chaque nouvel azan ────────────
    ucOn(UC_EVT.AZAN_TIME, function() {
        _snFired = false;
        _forceHide('new_azan_cycle');
    });

    // ── Fermer proprement si l'iqama démarre ─────────────────────────────
    ucOn(UC_EVT.IQAMA_SHOW, function() {
        if (_snVisible) _forceHide('iqama_started');
    });

    // ── Fonction de test console (bypass gardes) ──────────────────────────
    //    snTest()       → popup seule    snTest(true) → popup + audio
    window.snTest = function(withAudio) {
        _snFired = false;
        _show(withAudio === true);
    };

    // ── Interruption manuelle : tap n'importe où sur l'overlay + petite
    //    croix en haut (repère visuel). Réutilise _forceHide (déjà utilisée
    //    pour les fermetures automatiques) : coupe l'audio ET la popup
    //    ensemble, jamais l'un sans l'autre. pointer-events:none tant que
    //    l'overlay n'est pas visible (cf. CSS) : sans effet si masqué.
    (function _installDismiss() {
        var _btn = document.createElement('div');
        _btn.id = 'ucSalatNabiClose';
        _btn.innerHTML = '&#10006;';
        _btn.style.cssText =
            'position:absolute;top:3vh;left:50%;transform:translateX(-50%);' +
            'font-size:2.2em;color:#a89060;opacity:0.8;cursor:pointer;' +
            'padding:0.2em 0.5em;z-index:1;user-select:none;';
        _overlay.appendChild(_btn);

        function _dismiss(reason) {
            _forceHide('user_' + reason);
        }
        _overlay.addEventListener('click', function() { _dismiss('tap'); });
        _btn.addEventListener('click', function(e) { e.stopPropagation(); _dismiss('close_btn'); });
    })();

})();

// ═══════════════════════════════════════════════════════════════════════════
// ── ÉGALISEUR ICÔNE CORAN ──────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════

let _qpAudioCtx = null;
let _qpAnalyser = null;
let _qpFreqData = null;
let _qpRafId    = null;

// Initialise l'analyseur Web Audio API (une seule fois)
function _qpInitAnalyser() {
    if (_qpAnalyser) return true;
    try {
        const Ctx   = window.AudioContext || window.webkitAudioContext;
        const audio = document.getElementById('quranAudioPlayer');
        if (!Ctx || !audio) { _L('EQ','ERR',{reason:'no_ctx_or_audio',hasCtx:!!Ctx,hasAudio:!!audio}); return false; }
        _qpAudioCtx = new Ctx();
        const src   = _qpAudioCtx.createMediaElementSource(audio);
        _qpAnalyser = _qpAudioCtx.createAnalyser();
        _qpAnalyser.fftSize        = 64;    // 32 bins de fréquence
        _qpAnalyser.smoothingTimeConstant = 0.75;  // lissage de l'animation
        _qpFreqData = new Uint8Array(_qpAnalyser.frequencyBinCount);
        src.connect(_qpAnalyser);
        _qpAnalyser.connect(_qpAudioCtx.destination);  // audio toujours audible
        _L('EQ','INIT',{state:_qpAudioCtx.state,sampleRate:_qpAudioCtx.sampleRate});
        return true;
    } catch (e) {
        _L('EQ','ERR',{reason:'init_threw',err:(e && e.message) || String(e)});
        return false;   // fallback CSS
    }
}

// À appeler de façon SYNCHRONE depuis le gestionnaire de clic qui démarre la
// lecture (avant/au moment de audio.play()), pas seulement depuis l'event
// 'play' (cf. _qpStartEq). Sur certains navigateurs desktop, la politique
// autoplay du Web Audio API n'autorise resume() que s'il est appelé pendant
// le geste utilisateur ; appelé plus tard (event 'play' asynchrone), il reste
// bloqué en 'suspended' indéfiniment -> lecture silencieuse alors que
// l'élément <audio> continue de décoder normalement (currentTime avance)
// puisque sa sortie est redirigée vers ce contexte Web Audio une fois câblé.
function _qpKickAudioCtx() {
    _qpInitAnalyser();
    if (_qpAudioCtx && _qpAudioCtx.state === 'suspended') {
        var _stateBefore = _qpAudioCtx.state;
        _qpAudioCtx.resume().then(function() {
            _L('EQ','RESUME_OK',{before:_stateBefore,after:_qpAudioCtx.state});
        }).catch(function(e) {
            _L('EQ','RESUME_FAIL',{before:_stateBefore,err:(e && e.message) || String(e)});
        });
    } else {
        _L('EQ','KICK',{state:_qpAudioCtx ? _qpAudioCtx.state : 'no_ctx'});
    }
}

// Debug console : window._qpEqDebug() → état complet (contexte + élément audio)
window._qpEqDebug = function() {
    var a = document.getElementById('quranAudioPlayer');
    var info = {
        ctxState:     _qpAudioCtx ? _qpAudioCtx.state : 'no_ctx',
        hasAnalyser:  !!_qpAnalyser,
        audioSrc:     a ? a.currentSrc || a.src : null,
        audioPaused:  a ? a.paused : null,
        audioMuted:   a ? a.muted : null,
        audioVolume:  a ? a.volume : null,
        currentTime:  a ? a.currentTime : null
    };
    console.log('[EQ DEBUG]', info);
    return info;
};

// Démarre l'animation (appelé sur 'play' / 'playing')
function _qpStartEq() {
    const icon = document.getElementById('customQuranIcon');
    if (!icon) return;
    icon.classList.add('qpPlaying');

    const apiOk = _qpInitAnalyser() && _qpAudioCtx && _qpAudioCtx.state !== 'suspended';

    if (apiOk) {
        // Web Audio API active → animation pilotée par les fréquences réelles
        icon.classList.remove('qpCssAnim');
        if (!_qpRafId) _qpAnimLoop();
    } else {
        // Contexte suspendu (pas encore de geste) ou indisponible → CSS pur
        icon.classList.add('qpCssAnim');
        // Tenter de reprendre le contexte ; s'il se débloque, basculer en Web Audio
        if (_qpAudioCtx && _qpAudioCtx.state === 'suspended') {
            _qpAudioCtx.resume().then(function() {
                const ic = document.getElementById('customQuranIcon');
                if (ic && ic.classList.contains('qpPlaying')) {
                    ic.classList.remove('qpCssAnim');
                    if (!_qpRafId) _qpAnimLoop();
                }
            }).catch(function() { /* restera en CSS */ });
        }
    }
}
// Exposition explicite : _startQuranAutoPlayback (hors de portée lexicale) en
// a besoin -- cf. window._playQP plus haut pour le même constat.
window._qpStartEq = _qpStartEq;

// Arrête l'animation et remet l'icône livre (appelé sur 'pause' / 'ended')
function _qpStopEq() {
    const icon = document.getElementById('customQuranIcon');
    if (!icon) return;
    icon.classList.remove('qpPlaying', 'qpCssAnim');
    if (_qpRafId) { cancelAnimationFrame(_qpRafId); _qpRafId = null; }
    // Remettre toutes les barres à leur hauteur de repos
    icon.querySelectorAll('.qpEqBar').forEach(function(b) {
        b.style.height = '20%';
    });
}

// Boucle d'animation pilotée par les données FFT
function _qpAnimLoop() {
    const icon = document.getElementById('customQuranIcon');
    if (!icon || !icon.classList.contains('qpPlaying') || !_qpAnalyser) {
        _qpRafId = null;
        return;
    }
    _qpAnalyser.getByteFrequencyData(_qpFreqData);
    const bars  = icon.querySelectorAll('.qpEqBar');
    const total = _qpFreqData.length;

    bars.forEach(function(bar, i) {
        // Moyenne de la bande de fréquence correspondante (répartition log-ish)
        const from = Math.floor(i       * total / bars.length);
        const to   = Math.floor((i + 1) * total / bars.length);
        var   sum  = 0;
        for (var b = from; b < to; b++) sum += _qpFreqData[b];
        const avg  = sum / Math.max(1, to - from);
        const h    = Math.max(12, Math.round((avg / 255) * 92));
        bar.style.height = h + '%';
    });

    _qpRafId = requestAnimationFrame(_qpAnimLoop);
}


// ═══════════════════════════════════════════════════════════════════════════
// ── DÉVERROUILLAGE AUTOPLAY (politique navigateur) ─────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Chrome / Opera / Android bloquent audio.play() sans geste utilisateur.
//  Solution : modale "إضغط على موافق لتفعيل ترتيل القرآن"
//   • Le clic sur "موافق" EST le geste → déblocage garanti
//   • Un listener global reste en fallback silencieux (n'importe quel clic)
//

// ── Injection de la modale de déblocage (une seule fois) ─────────────────
(function _injectAutoplayUnlockModal() {
    const overlay = document.createElement('div');
    overlay.id = 'autoplayUnlockOverlay';
    overlay.className = 'aupHidden';
    overlay.innerHTML =
        '<div id="autoplayUnlockModal">' +
            '<div id="autoplayUnlockIcon">📖</div>' +
            '<div id="autoplayUnlockText">إضغط على موافق لتفعيل ترتيل القرآن</div>' +
            '<button id="autoplayUnlockBtn" onclick="_autoplayUnlockConfirm()">موافق</button>' +
        '</div>';
    // Appended to <html> pour rester immune à la rotation du body (vrRIGHT/vrLEFT)
    document.documentElement.appendChild(overlay);
})();

// ── Afficher / masquer ────────────────────────────────────────────────────
function _showAutoplayUnlockModal() {
    const el = document.getElementById('autoplayUnlockOverlay');
    if (el) el.classList.remove('aupHidden');
}
// Exposition globale : appelee depuis _startQuranAutoPlayback (scope global) --
// meme constat que window._hideAutoplayUnlockModal juste en dessous.
window._showAutoplayUnlockModal = _showAutoplayUnlockModal;
function _hideAutoplayUnlockModal() {
    const el = document.getElementById('autoplayUnlockOverlay');
    if (el) el.classList.add('aupHidden');
}
// Exposition globale : appelee depuis applyNextPrayerHighlight (scope global).
window._hideAutoplayUnlockModal = _hideAutoplayUnlockModal;

// ── Action du bouton موافق ────────────────────────────────────────────────
//  Appelée par onclick (donc : geste utilisateur garanti → audio autorisé)
function _autoplayUnlockConfirm() {
    _hideAutoplayUnlockModal();
    _doAudioUnlock();
}

// ── Logique de déverrouillage (partagée : bouton + fallback global) ───────
function _doAudioUnlock() {
    if (_audioUnlocked) return;
    _audioUnlocked = true;
    _L('AUDIO','FIRE',{action:'unlock',reason:'first_user_gesture'});

    if (_qpAudioCtx && _qpAudioCtx.state === 'suspended') {
        _qpAudioCtx.resume().then(function() {
            _L('AUDIO','FIRE',{action:'audiocontext_resume',result:'resumed'});
            // Basculer de l'animation CSS vers Web Audio si lecture en cours
            const icon = document.getElementById('customQuranIcon');
            if (icon && icon.classList.contains('qpPlaying') && _qpAnalyser) {
                icon.classList.remove('qpCssAnim');
                if (!_qpRafId) _qpAnimLoop();
            }
        }).catch(function(err) {
            // Catch obligatoire : sans lui, un reject devient une "unhandled rejection"
            // → TWKT:TypeError:NetworkError dans la console APK Android
            _L('AUDIO','SKIP',{action:'audiocontext_resume',reason:'resume_failed',
                err:(err && err.message || String(err))});
        });
    }

    // Relancer la lecture si un auto-start était en attente
    if (_pendingAutoStart) {
        _pendingAutoStart = false;
        const audio = document.getElementById('quranAudioPlayer');
        if (audio && audio.src && audio.paused) {
            var _src = audio.currentSrc || audio.src || '?';
            _L('AUDIO','FIRE',{action:'resume_after_unlock', url:_src});
            audio.play().catch(function(err) {
                _L('AUDIO','SKIP',{action:'resume_after_unlock',reason:'play_failed',
                    url:_src, err:(err && err.message || String(err))});
            });
        }
    }
}

// ── MARQUEE PENDANT LE COMPTE À REBOURS ──────────────────────────────────────
// • Dès le 1er tick du compteur : force l'affichage du marquee (s'il a du contenu)
// • Quand remainingSeconds passe à ≤ 59 : cache le marquee (dernière minute)
// • À la fin du compteur (IQAMA_TIME) : restaure l'état normal du marquee
//
// Cela corrige le cas où le marquee reste invisible après la fermeture de l'écran
// azan (qui remplace le conteneur par le texte de la sounna).
// ─────────────────────────────────────────────────────────────────────────────
(function _installMarqueeDuringCountdown() {

    var _marqueeShownByUs  = false;   // true après le premier _showMarquee() du cycle
    var _marqueeHiddenByUs = false;   // true après _hideMarquee() à 59 s

    // Force l'affichage du marquee UNE SEULE FOIS par cycle (évite de reconstruire
    // le container à chaque tick, ce qui redémarre l'animation).
    function _showMarquee() {
        // Effacer le display:none inline pose par _hideMarquee (updateMarqueeDisplayFunction ne le retire pas)
        var hrC = document.getElementById('marqueeContainerHorizontal');
        var vrC = document.getElementById('marqueeContainerVertical');
        if (hrC) hrC.style.display = '';
        if (vrC) vrC.style.display = '';
        if (typeof updateMarqueeDisplayFunction === 'function')
            updateMarqueeDisplayFunction();
    }

    // Cache les deux conteneurs marquee (horizontal + vertical)
    function _hideMarquee() {
        // Garde-fou : ce mecanisme ne concerne QUE le compte a rebours iqama.
        // Si le ticker azan (sounna, cf. plus bas dans ce fichier) est actif,
        // ne jamais le geler -- stopMarqueeAnimation() agit sur l'element
        // marqueeElement PARTAGE, quel que soit son contenu actuel.
        if (typeof window._ucIsAzanMarqueeActive === 'function' && window._ucIsAzanMarqueeActive()) return;
        var hrC = document.getElementById('marqueeContainerHorizontal');
        var vrC = document.getElementById('marqueeContainerVertical');
        if (hrC) hrC.style.display = 'none';
        if (vrC) vrC.style.display = 'none';
        if (typeof stopMarqueeAnimation === 'function') stopMarqueeAnimation();
    }

    ucOn(UC_EVT.COUNTDOWN_TICK, function(e) {
        var rem = e.remainingSeconds;

        if (rem > 59) {
            // Une seule fois au démarrage du compteur
            if (_marqueeShownByUs) return;
            _showMarquee();
            _marqueeShownByUs = true;
        } else if (rem === 59) {
            // Franchissement du seuil : on cache le marquee une seule fois
            if (_marqueeHiddenByUs) return;
            _hideMarquee();
            _marqueeHiddenByUs = true;
            _L('MARQUEE', 'HIDE', { trigger: 'countdown_59s' });
        }
        // Entre 0 et 59 : rien à faire, le marquee reste caché
    });

    ucOn(UC_EVT.IQAMA_TIME, function() {
        // Fin du compteur : restaurer le marquee et réinitialiser les flags
        if (_marqueeHiddenByUs) {
            _showMarquee();
            _L('MARQUEE', 'SHOW', { trigger: 'iqama_time_restore' });
        }
        _marqueeShownByUs  = false;
        _marqueeHiddenByUs = false;
    });

})();
// ── COUNTER DRIFT CORRECTION ──────────────────────────────────
// Recale remainingSeconds sur Date.now() si l’intervalle setInterval d’rive
// (CPU chargé, tab brièvement en arrière-plan).
// Déclenche une correction si dérive > 2 s. Silencieuse (pas de trace debug) :
// la correction elle-même reste active, seul le bruit console a été retiré.

(function _installCounterDriftCorrection() {

    var _startTime = -1;   // Date.now() au démarrage du compteur
    var _startRem  = -1;   // remainingSeconds au démarrage

    // BUG (rapport debug #26, mosquée Ennour Ksibet, 25/07/2026) : _startTime/
    // _startRem ne sont réinitialisés qu'à la fin NATURELLE du compteur
    // (UC_EVT.IQAMA_TIME), jamais quand _ucResyncPrayerSequence redémarre le
    // compteur en cours de cycle (retour au premier plan). Après une mise en
    // arrière-plan prolongée qui englobe l'heure réelle de l'iqama, le premier
    // tick au réveil calcule encore l'écart par rapport à la référence
    // D'ORIGINE (avant la pause) au lieu du dernier redémarrage -- l'écart
    // devient énorme, la correction écrase remainingSeconds à ~1, et le tick
    // suivant déclenche startIqamaSequenceFunction() comme si l'iqama sonnait
    // à l'instant, alors que son horaire réel est passé depuis longtemps
    // (constaté : "texte_iqama" rejoué à l'ouverture de l'app après la prière).
    // Un Date.now() ne doit jamais servir de référence à travers une pause de
    // durée inconnue -- on détecte donc tout passage en arrière-plan depuis le
    // dernier tick et on réamorce la référence au lieu de "corriger" dessus.
    // RÉCIDIVE (rapport utilisateur, 27/07/2026, mosquée Youssef Ksibet) : le
    // simple réamorçage ci-dessus évite bien le faux déclenchement immédiat
    // du bug #26, mais déplace le problème -- si la pause en arrière-plan
    // englobe déjà l'échéance réelle du compteur (temps caché >= temps qu'il
    // restait au moment de la mise en veille), le réamorçage laisse le
    // compteur reprendre un décompte NORMAL depuis sa valeur figée : il finit
    // par atteindre 0 des heures plus tard et rejoue ALORS toute la séquence
    // de fin d'iqama (texte + rideau noir, startIqamaSequenceFunction) hors
    // de tout contexte réel. Constaté : séquence complète rejouée à 00h34
    // pour un compteur figé depuis avant minuit. On mémorise donc aussi le
    // temps restant AU MOMENT de la mise en veille (_remAtHide) : si le temps
    // passé caché le dépasse déjà, le compteur est irrémédiablement périmé et
    // on l'annule ENTIÈREMENT (comme les autres surcouches périmées dans
    // _ucResyncPrayerSequence) plutôt que de le laisser reprendre et se
    // déclencher en retard.
    var _hiddenAtMs = -1;
    var _remAtHide  = -1;
    var _wasHiddenSinceLastTick = false;
    document.addEventListener('visibilitychange', function () {
        if (document.hidden) {
            _wasHiddenSinceLastTick = true;
            _hiddenAtMs = Date.now();
            _remAtHide  = (typeof remainingSeconds !== 'undefined') ? remainingSeconds : -1;
        }
    });

    function _cancelStaleCounter(hiddenSec) {
        _L('CTR', 'CANCEL_STALE', { hiddenSec: Math.round(hiddenSec), remAtHide: _remAtHide });
        // Fonction canonique unique (cf. son commentaire, juste avant
        // _installResyncOnResume) -- evite que ce chemin diverge a nouveau de
        // _ucResyncPrayerSequence comme constate le 01/08/2026 (fix
        // secondCounterContainer ajoute la-bas, manquant ici).
        window._ucForceCloseAllCounterOverlays();
        _startTime = -1;
        _startRem  = -1;
    }

    ucOn(UC_EVT.COUNTDOWN_TICK, function(e) {
        var rem = e.remainingSeconds;

        // Premier tick, ou reprise après une mise en arrière-plan : la
        // référence précédente ne dit plus rien de fiable -- on réamorce
        // sans appliquer de correction sur ce tick, SAUF si l'échéance est
        // déjà passée pendant la pause (cf. commentaire ci-dessus).
        if (_startTime === -1 || _wasHiddenSinceLastTick) {
            if (_hiddenAtMs !== -1 && _remAtHide >= 0) {
                var hiddenSec = (Date.now() - _hiddenAtMs) / 1000;
                if (hiddenSec >= _remAtHide) {
                    _wasHiddenSinceLastTick = false;
                    _hiddenAtMs = -1;
                    _remAtHide  = -1;
                    _cancelStaleCounter(hiddenSec);
                    return;
                }
            }
            _startTime = Date.now();
            _startRem  = rem;
            _wasHiddenSinceLastTick = false;
            _hiddenAtMs = -1;
            _remAtHide  = -1;
            return;
        }

        // Valeur théorique basée sur l’horloge murale
        var elapsedSec = (Date.now() - _startTime) / 1000;
        var expected   = Math.round(_startRem - elapsedSec);
        var drift      = rem - expected;   // positif = compteur trop lent

        // Corriger si dérive > 2 secondes
        if (Math.abs(drift) > 2 && typeof remainingSeconds !== 'undefined') {
            // Clamp a 1 minimum (pas 0) : si expected <= 0 le compteur est
            // expire ; on laisse le tick naturel atteindre 0 et declencher
            // startIqamaSequenceFunction() normalement (check === 0 dans core).
            // Forcer 0 directement ferait passer le check et glisser en negatif.
            var _corrected = Math.max(1, expected);
            remainingSeconds = _corrected;
        }
    });

    // Réinitialiser à la fin du compteur
    ucOn(UC_EVT.IQAMA_TIME, function() {
        _startTime = -1;
        _startRem  = -1;
        _wasHiddenSinceLastTick = false;
        _hiddenAtMs = -1;
        _remAtHide  = -1;
    });

})();

// ── GARDE-FOU : la barre mini des horaires ne doit JAMAIS rester visible
// sans qu'un état actif ne le justifie ────────────────────────────────────
// BUG RÉCURRENT (28/07/2026, trois manifestations DIFFÉRENTES le même jour :
// pendant l'interlude azkar, après le nettoyage d'un compteur plein écran,
// et maintenant après un vrai cycle azan/iqama Isha réel) : la barre mini
// (miniPrayerTimesHorizontal/Vertical, affichée par le coeur via
// showPrayerTimesOverlayFunction lors de l'entrée en mode plein écran ou en
// azkar) se retrouve régulièrement laissée visible, superposée au tableau
// standard, alors que RIEN ne la justifie -- chaque chemin de code qui
// l'affiche doit explicitement la recacher au bon moment précis, et chaque
// nouveau scénario (azkar, compteur, cycle réel complet) en oublie un
// différent. Plutôt que de continuer à corriger au cas par cas -- ça revient
// systématiquement sous une forme différente -- ce garde-fou impose
// l'invariant directement, en balayage périodique léger : si la barre mini
// est visible mais qu'aucun état actif (compteur plein écran, azkar,
// compteur compact) ne la justifie, on la masque, peu importe la cause
// exacte de l'incohérence.
(function _installMiniOverlayInvariantGuard() {
    var CHECK_MS = 4000;
    function _sweep() {
        var justified = (typeof isFullScreenCounterMode !== 'undefined' && isFullScreenCounterMode) ||
                         (typeof isBigCounterActive !== 'undefined' && isBigCounterActive) ||
                         (typeof isIqamaCounterActive !== 'undefined' && isIqamaCounterActive);
        if (justified) return;
        ['miniPrayerTimesHorizontal', 'miniPrayerTimesVertical'].forEach(function (id) {
            var el = document.getElementById(id);
            if (el && el.className !== 'hiddenClass' && typeof window.hideElementFunction === 'function') {
                _L('CTR', 'MINI_OVERLAY_STUCK_CORRECTED', { id: id, prevClass: el.className });
                window.hideElementFunction(id);
            }
        });
    }
    setInterval(_sweep, CHECK_MS);
    _L('CUSTOM', 'INIT', { item: 'miniOverlayInvariantGuard' });
})();


// ── FIX : updateAthanIqamaDisplayFunction après recalcul heure fixe iqama ──────
// Dans editFixedIqamaXxxFunction() du core, l’ordre est :
//   1. écriture de ucFixedIqamaXxx
//   2. updateAthanIqamaDisplayFunction()  ← lit ucIqamaXxx ANCIEN (pas encore recalculé)
//   3. calculateAndDisplayTimesFunction() ← recalcule ucIqamaXxx depuis la nouvelle heure fixe
// On monkey-patche les 4 fonctions pour rappeler updateAthanIqamaDisplayFunction()
// une deuxième fois après calculateAndDisplayTimesFunction().
// La vérification isInputDialogOpen === true garantit qu’on n’agit que lors de la
// confirmation (pas lors de l’ouverture de la boite de dialogue).

(function _fixFixedIqamaDisplayUpdate() {

    var _names = [
        'editFixedIqamaFajrFunction',
        'editFixedIqamaDohrFunction',
        'editFixedIqamaAsrFunction',
        'editFixedIqamaIshaFunction',
    ];

    _names.forEach(function(name) {
        var _orig = window[name];
        if (typeof _orig !== 'function') return;
        window[name] = function() {
            _orig.apply(this, arguments);
            // isInputDialogOpen reste true pendant toute la durée du eval(pendingCallback)
            // Il est remis à false seulement après que eval() retourne.
            // On profite de cette fenêtre pour relancer l’affichage avec les valeurs
            // correctement recalculées par calculateAndDisplayTimesFunction().
            if (typeof isInputDialogOpen !== 'undefined' && isInputDialogOpen) {
                if (typeof updateAthanIqamaDisplayFunction === 'function') {
                    updateAthanIqamaDisplayFunction();
                }
            }
        };
    });

})();

// ── IQAMA ZERO BLINK : GARDE SUR L’ÉTAT DES CASES ───────────────────
// Règles :
//  Minaret : accessible ssi lightCfgCb_minaretOn coché ET ucLightMinaretOnUrl non vide
//  Mihrab  : accessible ssi lightCfgCb_mihrabOn  coché ET ucLightMihrabOnUrl  non vide
//            ET ucLightMihrabOnUrl != ucLightMinaretOnUrl
//  Sinon   : case décochée + grisée (disabled + opacity).

(function _installIqamaBlinkGuard() {

    function _setRowState(cb, accessible) {
        if (!cb) return;
        var row = cb.parentElement;
        cb.disabled = !accessible;
        if (row) {
            row.style.opacity       = accessible ? '' : '0.38';
            row.style.pointerEvents = accessible ? '' : 'none';
        }
        if (!accessible && cb.checked) {
            cb.checked = false;
        }
    }

    function _syncIqamaZeroBlinkState() {
        var cbMin = document.getElementById('iqamaZeroMinaretBlinkCb');
        var cbMih = document.getElementById('iqamaZeroMihrabBlinkCb');
        if (!cbMin && !cbMih) return;   // UI pas encore ouverte

        // ── Minaret ────────────────────────────────────────────────────────
        var minUrl = (JS_CUSTOM.ucLightMinaretOnUrl || '').trim();
        var minOk  = (JS_CUSTOM.ucLightMinaretOnEnabled == 1) && (minUrl !== '');

        _setRowState(cbMin, minOk);
        if (!minOk && JS_CUSTOM.ucIqamaZeroMinaretBlinkEnabled == 1) {
            JS_CUSTOM.ucIqamaZeroMinaretBlinkEnabled = 0;
            saveCustomSettingsFunction();
        }

        // ── Mihrab ─────────────────────────────────────────────────────────
        var mihUrl    = (JS_CUSTOM.ucLightMihrabOnUrl || '').trim();
        var sameAsMin = (mihUrl !== '') && (mihUrl === minUrl);
        var mihOk     = (JS_CUSTOM.ucLightMihrabOnEnabled == 1) && (mihUrl !== '') && !sameAsMin;

        _setRowState(cbMih, mihOk);
        if (!mihOk && JS_CUSTOM.ucIqamaZeroMihrabBlinkEnabled == 1) {
            JS_CUSTOM.ucIqamaZeroMihrabBlinkEnabled = 0;
            saveCustomSettingsFunction();
        }
    }

    // Brancher sur refreshIqamaZeroBlinkUI
    var _origRefreshBlink = refreshIqamaZeroBlinkUI;
    refreshIqamaZeroBlinkUI = function() {
        _origRefreshBlink();
        _syncIqamaZeroBlinkState();
    };

    // Brancher sur refreshLightProgrammingUI (changement URL ou enable)
    var _origRefreshLight = refreshLightProgrammingUI;
    refreshLightProgrammingUI = function() {
        _origRefreshLight();
        _syncIqamaZeroBlinkState();
    };

})();

// ── MIHRAB / MINARET : BLOCAGE RUNTIME SI MÊME URL ──────────────────────
// Si ucLightMihrabOnUrl == ucLightMinaretOnUrl, tout appel HTTP dont le label
// contient "mihrab" (mihrabOn, mihrabOff, mihrabBlink, mihrabOn[TEST]...)
// est bloqué avant d'atteindre le réseau, afin d'éviter tout chevauchement
// ou double commande sur le même équipement.
// Ce patch couvre :
//   • afterAzanHide  → mihrabOn
//   • afterBlackHide → mihrabOff
//   • IQAMA_TIME     → mihrabBlink (_runStrobe)
//   • ucTestLight()  → mihrabOn[TEST]

(function _installMihrabMinaretConflictGuard() {

    function _isMihrabConflictsMinaret() {
        var minUrl = (JS_CUSTOM.ucLightMinaretOnUrl || '').trim();
        var mihUrl = (JS_CUSTOM.ucLightMihrabOnUrl  || '').trim();
        return minUrl !== '' && mihUrl !== '' && minUrl === mihUrl;
    }

    var _origHttpCall = _ucHttpCall;
    _ucHttpCall = function(url, label, silent) {
        var lbl = String(label || '');
        if (_isMihrabConflictsMinaret() &&
            (lbl.indexOf('mihrab') !== -1 || lbl.indexOf('Mihrab') !== -1)) {
            // Bloquer : tracer uniquement si non-silent (évite le spam strobe)
            if (!silent) {
                _L('LIGHTS','SKIP',{item:lbl, reason:'mihrab_conflicts_minaret',
                                    url:(url||'').trim()});
            }
            return;
        }
        return _origHttpCall(url, label, silent);
    };

})();

// ── NO-MOBILE REMINDER ───────────────────────────────────────────────────────
// Affiche toutes les 2 min un overlay fond noir centrant spec/images/no-mobile.png
// uniquement si aucune modale / feature en cours n'est active.
// Visible 5s puis disparaît en fondu. Un clic le ferme immédiatement.

(function _initNoMobileReminder() {

    // Créer l'overlay une seule fois
    var _overlay = document.createElement('div');
    _overlay.id = 'nmrOverlay';
    var _img = document.createElement('img');
    _img.src = 'spec/images/no-mobile.webp';
    _img.alt = '';
    _overlay.appendChild(_img);
    document.body.appendChild(_overlay);

    var _visible   = false;
    var _hideTimer = null;
    var _interval  = null;
    _ucRegisterCleanup(function() {
        if (_hideTimer) { clearTimeout(_hideTimer);  _hideTimer = null; }
        if (_interval)  { clearInterval(_interval);  _interval  = null; }
        _hide();   // Fix: masquer visuellement l'overlay en plus d'annuler les timers
    });

    function _isMainPageActive() {
        var modals = document.querySelectorAll('.modalPopupClass');
        for (var i = 0; i < modals.length; i++) {
            var vis = getComputedStyle(modals[i]).visibility;
            if (vis === 'visible') return false;
        }
        var qp = document.getElementById('quranPlayerOverlay');
        if (qp && !qp.classList.contains('qpHidden')) return false;
        var au = document.getElementById('autoplayUnlockOverlay');
        if (au && !au.classList.contains('aupHidden')) return false;

        /* Ne pas afficher pendant le rideau noir (scaleX(1) = rideau actif) */
        var bsV = document.getElementById('blackScreenVertical');
        var bsH = document.getElementById('blackScreenHorizontal');
        if (bsV && bsV.style.transform === 'scaleX(1)') return false;
        if (bsH && bsH.style.transform === 'scaleX(1)') return false;

        /* Ne pas afficher pendant la fenêtre azan */
        /* Fix: isAzanPopupVisible est un 'let' dans m2body.js -> inaccessible depuis custom.js */
        /* On detecte via le DOM a la place */
        var _azH = document.getElementById('azanPopupHorizontal');
        var _azV = document.getElementById('azanPopupVertical');
        if ((_azH && getComputedStyle(_azH).visibility === 'visible') ||
            (_azV && getComputedStyle(_azV).visibility === 'visible')) return false;

        /* Ne pas afficher pendant les overlays hadith / adab */
        var joa = document.getElementById('jomoaAdabOverlay');
        if (joa && joa.classList.contains('joa-visible')) return false;
        var ih = document.getElementById('ucIqamaHadithOverlay');
        if (ih && ih.classList.contains('ucIH-visible')) return false;
        var ov15 = document.getElementById('ucIqama15sOverlay');
        if (ov15 && parseFloat(ov15.style.opacity) > 0) return false;

        /* Ne pas afficher pendant les azkar */
        var azkar = document.getElementById('azkarTextDisplayHorizontal');
        if (azkar && azkar.style.visibility === 'visible') return false;

        return true;
    }

    function _show() {
        if (_visible) return;
        var ok = _isMainPageActive();
        if (!ok) return;
        _visible = true;
        _overlay.classList.add('nmr-active');
        // _L('POPUP','SHOW',{item:'no_mobile'});  // désactivé — réactiver si besoin
        _hideTimer = setTimeout(_hide, (JS_CUSTOM.ucNMRDuration || 5) * 1000);
    }

    function _hide() {
        clearTimeout(_hideTimer);
        _visible = false;
        _overlay.classList.remove('nmr-active');
    }

    // Clic ou touche → fermeture immédiate
    _overlay.addEventListener('click',      _hide);
    _overlay.addEventListener('touchstart', _hide, { passive: true });
    _overlay.addEventListener('keydown',    _hide);

    /* Rideau noir → masquer immédiatement le NMR s'il est visible */
    ucOn(UC_EVT.BLACK_SHOW, function () {
        if (_visible) { _hide(); }
    });

    /* Fenêtre azan → masquer immédiatement le NMR s'il est visible */
    ucOn(UC_EVT.AZAN_SHOW, function () {
        if (_visible) { _hide(); }
    });

    /* Compteur iqama → masquer le NMR (iqama est un moment de recueillement) */
    ucOn(UC_EVT.IQAMA_TIME, function () {
        if (_visible) { _hide(); }
    });
    ucOn(UC_EVT.IQAMA_SHOW, function () {
        if (_visible) { _hide(); }
    });

    /* Azkar → masquer le NMR et redémarrer le cycle quand les azkar se ferment */
    (function _watchAzkar() {
        var azkarEl = document.getElementById('azkarTextDisplayHorizontal');
        if (!azkarEl) {
            /* L'élément n'existe pas encore — réessayer après le DOM */
            document.addEventListener('DOMContentLoaded', function () {
                azkarEl = document.getElementById('azkarTextDisplayHorizontal');
                if (azkarEl) _attachObserver(azkarEl);
            });
        } else {
            _attachObserver(azkarEl);
        }
        function _attachObserver(el) {
            var _prevVis = el.style.visibility;
            new MutationObserver(function () {
                var curVis = el.style.visibility;
                if (_prevVis === 'visible' && curVis !== 'visible') {
                    /* Les azkar viennent de se fermer */
                    if (_visible) _hide();
                    if (JS_CUSTOM.ucNoMobileReminderEnabled) {
                        /* Relancer le cycle : prochain affichage dans 2 min */
                        _stop();
                        _start();
                    }
                } else if (_prevVis !== 'visible' && curVis === 'visible') {
                    /* Les azkar viennent de s'ouvrir → masquer le NMR */
                    if (_visible) _hide();
                }
                _prevVis = curVis;
            }).observe(el, { attributes: true, attributeFilter: ['style'] });
        }
    })();

    function _start() {
        _stop();
        _interval = setInterval(function () {
            if (JS_CUSTOM.ucNoMobileReminderEnabled) _show();
        }, (JS_CUSTOM.ucNMRInterval || 120) * 1000);
    }

    function _stop() {
        if (_interval) { clearInterval(_interval); _interval = null; }
        _hide();
    }

    // Injection des boutons configurables devant le libellé noMobileReminder
    function _injectNMRButtons() {
        var lbl = document.querySelector('label[for="noMobileReminderCheckbox"]');
        if (!lbl || document.getElementById('nmrIntervalBtn')) return;
        var container = lbl.parentNode;

        var sepA = document.createTextNode('  ');
        var btnInterval = document.createElement('span');
        btnInterval.id = 'nmrIntervalBtn';
        btnInterval.className = 'clickableWhiteClass';
        btnInterval.title = 'تعديل فترة التكرار';
        btnInterval.onclick = function () { window.editNMRIntervalFunction(); };

        var sepB = document.createTextNode('  ');
        var btnDuration = document.createElement('span');
        btnDuration.id = 'nmrDurationBtn';
        btnDuration.className = 'clickableWhiteClass';
        btnDuration.title = 'تعديل مدة العرض';
        btnDuration.onclick = function () { window.editNMRDurationFunction(); };

        var sepC = document.createTextNode('  ');

        container.insertBefore(sepC, lbl);
        container.insertBefore(btnDuration, sepC);
        container.insertBefore(sepB, btnDuration);
        container.insertBefore(btnInterval, sepB);
        container.insertBefore(sepA, btnInterval);
        _updateNMRButtonLabels();
    }

    function _updateNMRButtonLabels() {
        var bi = document.getElementById('nmrIntervalBtn');
        var bd = document.getElementById('nmrDurationBtn');
        if (bi) bi.innerHTML = '⌛ ' + (JS_CUSTOM.ucNMRInterval || 120) + 's';
        if (bd) bd.innerHTML = '⏱ ' + (JS_CUSTOM.ucNMRDuration  || 5)   + 's';
    }

    // API publique
    window.toggleNoMobileReminderFunction = function () {
        JS_CUSTOM.ucNoMobileReminderEnabled = JS_CUSTOM.ucNoMobileReminderEnabled ? 0 : 1;
        saveCustomSettingsFunction();
        updateNoMobileReminderFunction();
    };

    window.editNMRIntervalFunction = function () {
        if (!isInputDialogOpen) {
            inputDialogValue = '';
            openInputDialogFunction(_dlgT('nmrInterval'), String(JS_CUSTOM.ucNMRInterval || 120), 'editNMRIntervalFunction()', true);
            return;
        }
        var n = parseInt(inputDialogValue, 10);
        if (!isNaN(n) && n > 0) {
            JS_CUSTOM.ucNMRInterval = n;
            saveCustomSettingsFunction();
            _updateNMRButtonLabels();
            if (JS_CUSTOM.ucNoMobileReminderEnabled) { _stop(); _start(); }
        }
    };

    window.editNMRDurationFunction = function () {
        if (!isInputDialogOpen) {
            inputDialogValue = '';
            openInputDialogFunction(_dlgT('nmrDuration'), String(JS_CUSTOM.ucNMRDuration || 5), 'editNMRDurationFunction()', true);
            return;
        }
        var n = parseInt(inputDialogValue, 10);
        if (!isNaN(n) && n > 0) {
            JS_CUSTOM.ucNMRDuration = n;
            saveCustomSettingsFunction();
            _updateNMRButtonLabels();
        }
    };

    window.updateNoMobileReminderFunction = function () {
        var cb = document.getElementById('noMobileReminderCheckbox');
        if (cb) cb.checked = !!JS_CUSTOM.ucNoMobileReminderEnabled;
        _injectNMRButtons();
        _updateNMRButtonLabels();
        if (JS_CUSTOM.ucNoMobileReminderEnabled) _start();
        else _stop();
    };

    // Initialisation au chargement
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', updateNoMobileReminderFunction);
    } else {
        updateNoMobileReminderFunction();
    }

})();

// ── FOND NOIR COMPTEUR IQAMA ──────────────────────────────────────────────────
// Quand ucCounterBlackBg = 1, force le background de
// fullScreenCounterBackgroundHorizontal à #000000 pendant toute la durée
// du compteur iqama. Utilise un MutationObserver avec disconnect/reconnect
// pour éviter toute boucle infinie.
// ─────────────────────────────────────────────────────────────────────────────
(function _initCounterBlackBg() {

    var _el  = null;
    var _obs = null;

    function _reconnect() {
        if (_obs && _el) _obs.observe(_el, { attributes: true, attributeFilter: ['style'] });
    }

    function _apply() {
        if (!_el || !JS_CUSTOM.ucCounterBlackBg) return;
        _obs.disconnect();                      // coupe l'observer AVANT d'écrire
        _el.style.background      = '#000000';
        _el.style.backgroundImage = 'none';
        _el.style.backgroundSize  = 'auto';
        setTimeout(_reconnect, 0);              // reconnecte APRÈS vidage des microtasks
    }

    function _injectCheckbox() {
        if (document.getElementById('counterBlackBgCheckbox')) return;
        var anchor = document.getElementById('noMobileReminderCheckbox');
        if (!anchor) return;
        var row = anchor.closest('div');
        if (!row) return;
        var div = document.createElement('div');
        div.innerHTML =
            '<input type="checkbox" id="counterBlackBgCheckbox"' +
            ' onchange="toggleCounterBlackBgFunction()"> &nbsp;' +
            '<label for="counterBlackBgCheckbox">خلفية عداد الإقامة سوداء</label>';
        row.insertAdjacentElement('afterend', div);
    }

    window.toggleCounterBlackBgFunction = function () {
        JS_CUSTOM.ucCounterBlackBg = JS_CUSTOM.ucCounterBlackBg ? 0 : 1;
        saveCustomSettingsFunction();
        window.updateCounterBlackBgFunction();
    };

    window.updateCounterBlackBgFunction = function () {
        var cb = document.getElementById('counterBlackBgCheckbox');
        if (cb) cb.checked = !!JS_CUSTOM.ucCounterBlackBg;
        if (JS_CUSTOM.ucCounterBlackBg) {
            _apply();
        } else if (_el) {
            // Rétablir le background natif en retirant les overrides inline
            _obs.disconnect();
            _el.style.background      = '';
            _el.style.backgroundImage = '';
            _el.style.backgroundSize  = '';
            setTimeout(_reconnect, 0);
        }
    };

    function _init() {
        _el = document.getElementById('fullScreenCounterBackgroundHorizontal');
        if (!_el) return;
        _obs = new MutationObserver(function () { _apply(); });
        _obs.observe(_el, { attributes: true, attributeFilter: ['style'] });
        _injectCheckbox();
        window.updateCounterBlackBgFunction();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _init);
    } else {
        _init();
    }

})();

// ── INTERVERSION AZAN / IQAMA (mode horizontal uniquement) ───────────────────
// Échange les positions verticales des horaires AZAN et IQAMA dans le
// tableau des prières horizontal (les libellés iqamaColLabelAzan/
// iqamaColLabelIqama suivent le même échange). N'a aucun effet sur le mode
// vertical : la classe est posée uniquement sur #mainHorizontalContainer, et
// toutes les règles CSS associées (cf. spec/custom.css) sont scopées sous ce
// sélecteur.
//
// Mémorisation PAR MODE d'affichage horizontal (JS_DATA.ucHrNamesInMiddle,
// 0-6) sans multiplier les flags : ucSwapAzanIqama est un bitmask où le bit N
// (1<<N) stocke l'état swap du mode N. Un seul flag numérique couvre donc
// tous les modes actuels ET futurs (jusqu'à 31 modes, largement suffisant) —
// ajouter un mode ne demande aucun nouveau flag ni migration.
// ─────────────────────────────────────────────────────────────────────────────
(function _initSwapAzanIqama() {

    var lang = _ucLang();
    var T = {
        label: {
            AR: 'تبديل مكاني توقيت الأذان والإقامة',
            FR: 'Intervertir les positions Azan / Iqama',
            EN: 'Swap Azan / Iqama positions',
            TR: 'Ezan / İkamet konumlarını değiştir',
            ID: 'Tukar posisi Azan / Iqama'
        }
    };
    function t(key) {
        var row = T[key];
        if (!row) return key;
        return row[lang] || row['EN'] || row['FR'] || key;
    }

    function _injectCheckbox() {
        if (document.getElementById('swapAzanIqamaCheckbox')) return;
        var anchor = document.getElementById('counterBlackBgCheckbox');
        if (!anchor) return;
        var row = anchor.closest('div');
        if (!row) return;
        // Ligne séparatrice de bloc (même convention que les <hr> déjà présents
        // entre les groupes de réglages) entre counterBlackBgCheckbox et
        // swapAzanIqamaCheckbox.
        var sep = document.createElement('hr');
        row.insertAdjacentElement('afterend', sep);
        var div = document.createElement('div');
        div.innerHTML =
            '<input type="checkbox" id="swapAzanIqamaCheckbox"' +
            ' onchange="toggleSwapAzanIqamaFunction()"> &nbsp;' +
            '<label for="swapAzanIqamaCheckbox">' + t('label') + '</label>';
        sep.insertAdjacentElement('afterend', div);
    }

    // Bit correspondant au mode d'affichage horizontal courant dans le
    // bitmask ucSwapAzanIqama (cf. commentaire d'en-tête).
    function _bitForCurrentMode() {
        var mode = (typeof JS_DATA !== 'undefined') ? (parseInt(JS_DATA.ucHrNamesInMiddle, 10) || 0) : 0;
        return 1 << mode;
    }

    window.toggleSwapAzanIqamaFunction = function () {
        JS_CUSTOM.ucSwapAzanIqama ^= _bitForCurrentMode();
        saveCustomSettingsFunction();
        window.updateSwapAzanIqamaFunction();
    };

    window.updateSwapAzanIqamaFunction = function () {
        var active = !!(JS_CUSTOM.ucSwapAzanIqama & _bitForCurrentMode());
        var cb = document.getElementById('swapAzanIqamaCheckbox');
        if (cb) cb.checked = active;
        var hmc = document.getElementById('mainHorizontalContainer');
        // Thème 1 (fond "arcade") exclu du swap : même coché, ce thème garde
        // toujours ses positions Azan/Iqama d'origine.
        var modeExcluded = (typeof JS_DATA !== 'undefined' && JS_DATA.ucHrNamesInMiddle == 1);
        if (hmc) hmc.classList.toggle('swapAzanIqamaActive', active && !modeExcluded);
    };

    function _init() {
        _injectCheckbox();
        window.updateSwapAzanIqamaFunction();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _init);
    } else {
        _init();
    }

})();

// ── JUMU'AH ADAB OVERLAY ─────────────────────────────────────────────────────
// Affiche 10 s après la fermeture de l'écran azan du vendredi un rappel
// du hadith sur l'obligation d'écouter le sermon en silence.
// Disparaît automatiquement ou sur clic/touche.
// ─────────────────────────────────────────────────────────────────────────────
(function _initJomoaAdabOverlay() {

    var _overlay = document.createElement('div');
    _overlay.id = 'jomoaAdabOverlay';
    _overlay.innerHTML =
        "<div class='joa-l1'>قال النبي ﷺ :</div>" +
        "<hr class='joa-sep'>" +
        "<div class='joa-l2'>«إذا قُلْتَ لِصَاحِبِكَ يَوْمَ الْجُمُعَةِ : أَنْصِتْ، وَالْإِمَامُ يَخْطُبُ، فَقَدْ لَغَوْتَ»</div>" +
        "<div class='joa-l3'>صحيح البخاري و مسلم</div>" +
        "<hr class='joa-sep'>" +
        "<div class='joa-l4'>وَقَالَ ﷺ : «وَمَنْ مَسَّ الْحَصَى فَقَدْ لَغَا» &nbsp;&nbsp;&mdash;&nbsp; صحيح مسلم</div>";

    document.documentElement.appendChild(_overlay);

    var _hideTimer = null;
    var _blackScreenTimer = null;
    _ucRegisterCleanup(function() {
        if (_hideTimer) { clearTimeout(_hideTimer); _hideTimer = null; }
        if (_blackScreenTimer) { clearTimeout(_blackScreenTimer); _blackScreenTimer = null; }
    });

    // Reduit encore le font-size de .joa-l2 si, malgre le clamp CSS, le mot
    // le plus a droite (ex. "لَغَوْتَ") deborde toujours de la largeur
    // disponible (retour utilisateur : constate sur boitier TV). white-space:
    // nowrap (custom.css) empeche le retour a la ligne -- sans ce filet,
    // le texte deborderait silencieusement au lieu de wrapper. scrollWidth
    // n'est fiable qu'une fois l'element mis en page (toujours vrai ici,
    // l'overlay est display:flex en permanence, seule son opacite change),
    // donc mesurable meme avant le premier _show().
    function _fitJoaL2() {
        var el = _overlay.querySelector('.joa-l2');
        if (!el) return;
        el.style.fontSize = '';   // repart de la taille CSS (clamp) avant de mesurer
        // Largeur de contenu reellement disponible pour un enfant flex de
        // _overlay : clientWidth INCLUT le padding (4% 6%, custom.css) alors
        // que max-width:90% (CSS) se resout sur la largeur de contenu du
        // conteneur, PADDING DEJA RETIRE -- reproduit ce calcul ici plutot
        // que d'utiliser clientWidth brut (sinon marge sous-estimee d'environ
        // 12%, un cas de bord pourrait encore deborder legerement).
        var _cs = getComputedStyle(_overlay);
        var _contentWidth = _overlay.clientWidth - parseFloat(_cs.paddingLeft || 0) - parseFloat(_cs.paddingRight || 0);
        var maxWidth = _contentWidth * 0.9;   // == max-width:90% du CSS
        var actualWidth = el.scrollWidth;
        if (maxWidth > 0 && actualWidth > maxWidth) {
            var computedPx = parseFloat(getComputedStyle(el).fontSize) || 18;
            var newPx = Math.max(10, Math.floor(computedPx * (maxWidth / actualWidth) * 0.97));
            el.style.fontSize = newPx + 'px';
        }
    }

    function _show() {
        clearTimeout(_hideTimer);
        clearTimeout(_blackScreenTimer);
        _fitJoaL2();
        _overlay.classList.add('joa-visible');
        _L('POPUP','SHOW',{item:'jomoa_adab',duration:'10s'});
        _hideTimer = setTimeout(_hide, _UC_JOMOA_ADAB_AUTOHIDE_MS);

        // Rideau noir Jumu'a : ouvre juste avant la fermeture PLANIFIÉE de
        // cette modale (retour utilisateur 22/08/2026 -- remplace l'ancien
        // déclenchement dohrTime+ucJomoaDimmBefore, dimmerBeforeValue masqué
        // et ignoré, cf. _ucJomoaBlackScreenCatchUp/_UC_JOMOA_ADAB_LS_KEY
        // plus bas dans ce fichier pour le détail et le rattrapage resync).
        try { localStorage.setItem(_UC_JOMOA_ADAB_LS_KEY, Date.now().toString()); } catch(e) {}
        _blackScreenTimer = setTimeout(function() {
            window._ucJomoaTriggerBlackScreenForAdab();
        }, _UC_JOMOA_ADAB_AUTOHIDE_MS - _UC_JOMOA_ADAB_LEAD_MS);
    }

    function _hide() {
        clearTimeout(_hideTimer);
        _overlay.classList.remove('joa-visible');
    }

    _overlay.addEventListener('click',      _hide);
    _overlay.addEventListener('touchstart', _hide, { passive: true });

    ucOn(UC_EVT.AZAN_HIDE, function() {
        if (_ucCurrentPrayerKey() !== 'JOMOA') return;
        // AZAN_HIDE tardif issu du setTimeout('hideAzanPopupFunction()', ...)
        // non annulable du CORE (cf. _ucLastResyncCloseAt tout en haut du
        // fichier, _installResyncOnResume — meme bug que postAzanDoua) : si ce
        // resync vient JUSTE de tout nettoyer, ignorer cet echo perime plutot
        // que de rouvrir le rappel jomoaa hors contexte.
        var _msSinceResync = Date.now() - (window._ucLastResyncCloseAt || 0);
        if (_msSinceResync < 5000) {
            _L('POPUP', 'SKIP', { item: 'jomoa_adab', reason: 'stale_echo_after_resync', msSinceResync: _msSinceResync });
            return;
        }
        _show();
    });

    // Test depuis la console : testJomoaAdab()   → overlay seul
    window.testJomoaAdab = _show;

    // Test depuis la console : testJomoaAzanHide() → simule fin d'azan Jumu'ah
    // Déclenche AZAN_HIDE avec _ucCurrentPrayerKey()='JOMOA' : overlay + lumières
    window.testJomoaAzanHide = function() {
        _lastAzanPrayer = 'JOMOA';
        _ucFire(UC_EVT.AZAN_HIDE, {});
        _L('TEST','FIRE',{action:'testJomoaAzanHide',evt:'AZAN_HIDE',prayer:'JOMOA'});
    };

// ── SIMUL(param) ─ simulation complète azan → iqama → rideau noir ────────────
// param : 1=Fajr  2=Dohr  3=Asr  4=Maghrib  5=Isha  6=Jumu'ah (spécial)
// Reproduit fidèlement le processus selon le paramétrage courant (JS_DATA) :
//   • Écran azan pendant JS_AZAN_WINDOW_SHOW_TIME secondes
//   • AZAN_SHOW / AZAN_HIDE / IQAMA_SHOW événements via les hooks existants
//   • Overlay Jumu'ah si param=6 (ucLightAmpliExtOff + jomoaAdabOverlay)
//   • Écran iqama puis rideau noir (selon ucShowIqamaScreen + ucBlackScreenInPraying)
// ─────────────────────────────────────────────────────────────────────────────
window.SIMUL = (function() {

    var _MAP = [
        null,   // 0 réservé
        { key: 'FAJR',  pIdx: 0, nameIdx: 0, iqamaKey: 'ucIqamaFAJR',  durKey: 'ucPrayDurationFAJR',  isJomoa: false },
        { key: 'DOHR',  pIdx: 2, nameIdx: 2, iqamaKey: 'ucIqamaDOHR',  durKey: 'ucPrayDurationDOHR',  isJomoa: false },
        { key: 'ASSR',  pIdx: 3, nameIdx: 3, iqamaKey: 'ucIqamaASSR',  durKey: 'ucPrayDurationASSR',  isJomoa: false },
        { key: 'MGRB',  pIdx: 4, nameIdx: 4, iqamaKey: 'ucIqamaMGRB',  durKey: 'ucPrayDurationMGRB',  isJomoa: false },
        { key: 'ISHA',  pIdx: 5, nameIdx: 5, iqamaKey: 'ucIqamaISHA',  durKey: 'ucPrayDurationISHA',  isJomoa: false },
        { key: 'JOMOA', pIdx: 2, nameIdx: 2, iqamaKey: 'ucIqamaDOHR',  durKey: 'ucPrayDurationDOHR',  isJomoa: true  }
    ];

    return function(param) {
        param = parseInt(param, 10);
        var p = _MAP[param];
        if (!p) {
            console.log('[SIMUL] usage : SIMUL(1) Fajr | SIMUL(2) Dohr | SIMUL(3) Asr | SIMUL(4) Maghrib | SIMUL(5) Isha | SIMUL(6) Jumu\'ah');
            return;
        }

        var pName   = p.isJomoa ? jomoaLabel : prayerNamesArray[p.nameIdx];
        var azanMs  = JS_AZAN_WINDOW_SHOW_TIME * 1000;
        var prayDur = JS_DATA[p.durKey] || 0;

        console.log('[SIMUL] 🕌 ' + p.key +
                    ' | azan: ' + JS_AZAN_WINDOW_SHOW_TIME + 's' +
                    ' | iqama: ' + (JS_DATA[p.iqamaKey] || '?') + 'min' +
                    ' | durée prière: ' + prayDur + 'min');

        // ── 1. Contexte prière ─────────────────────────────────────────────
        currentPrayerIndex    = p.pIdx;
        currentPrayerName     = pName;
        isFriday              = p.isJomoa;
        prayerDurationMinutes = prayDur;

        // ── 2. Remplir la page azan ────────────────────────────────────────
        azanPopupTitleVerticalElement.innerHTML   = JS_eLang.cx_AzanCalling;
        azanPopupTitleHorizontalElement.innerHTML = JS_eLang.cx_AzanCalling;
        azanPopupPrayerNameVerticalElement.innerHTML   = pName;
        azanPopupPrayerNameHorizontalElement.innerHTML = pName;
        azanPopupTimeVerticalElement.innerHTML    = currentTimeFormatted;
        azanPopupTimeHorizontalElement.innerHTML  = currentTimeFormatted;

        // ── 3. Afficher l'écran azan + déclencher AZAN_SHOW ───────────────
        if (JS_DATA.ucShowAzanWindow != 0) {
            showElementWithTransitionFunction('azanPopupVertical');
            showElementWithTransitionFunction('azanPopupHorizontal');
        }
        // _ucCurrentPrayerKey() sera mis à jour par le handler ucOn(AZAN_SHOW, ...)
        _ucFire(UC_EVT.AZAN_SHOW, {
            prayer:        p.key,
            timeInMinutes: currentTimeInMinutes,
            isDohaPrayer:  false
        });
        console.log('[SIMUL] ▶ AZAN_SHOW → fermeture dans ' + JS_AZAN_WINDOW_SHOW_TIME + 's');

        // ── 4. Après durée azan : cacher + AZAN_HIDE + lancer séquence iqama
        setTimeout(function() {
            hideAzanPopupFunction();     // monkey-patché → fire AZAN_HIDE automatiquement
            //  → overlay Jumu'ah s'affiche si param=2 (géré dans _initJomoaAdabOverlay)
            //  → ampliExtOff + lumières se déclenchent (délai jomoaDelay ou normal)
            console.log('[SIMUL] ▶ AZAN_HIDE → séquence iqama dans 0.8s');

            setTimeout(function() {
                startIqamaSequenceFunction();  // monkey-patché → fire IQAMA_SHOW
                //  → iqama popup ~10s → rideau noir si ucBlackScreenInPraying==1
                console.log('[SIMUL] ▶ IQAMA_SHOW → rideau noir dans ~12s');
            }, 800);

        }, azanMs);
    };

})();

})();

// ═══════════════════════════════════════════════════════════════════════════
// LAYOUT TOGGLE – 7 MODES
// Override de toggleHrNamesMiddleFunction + updateHrNamesPositionFunction
// pour ajouter des présentations visuelles supplémentaires au cycle.
//
//  0 – Standard         : noms en haut, heures au milieu, iqama en bas
//  1 – Noms au milieu   : noms + verset au centre, iqama en haut   (STD)
//  2 – Islamic Green    : mêmes positions que mode 0, cellules vert émeraude
//  3 – Gold Minimal     : mêmes positions que mode 1, cellules transparentes
//  4 – Classique        : mêmes positions que mode 1, fond pb.png/pbbis.png
//  5 – Ornement Élégant : mêmes positions que mode 1, cadre arc or/émeraude
//      + motif géométrique islamique (cf. _ucSetHrLayoutMode plus bas pour
//      le sélecteur nommé qui remplace le cycle "à l'aveugle" de la case).
//  6 – Classique (fin)  : mêmes positions que mode 4, fond pb6/pbc6/pp6.webp
//      (variantes de pbbis/pbc/pp.webp sans le contour épais extérieur ni la
//      marge -- demande explicite du 12/08/2026, cf. custom.css "MODE 6").
// ═══════════════════════════════════════════════════════════════════════════
(function _installLayoutModes() {

    window.toggleHrNamesMiddleFunction = function () {
        if (typeof isBigCounterActive !== 'undefined' && isBigCounterActive) return;
        JS_DATA.ucHrNamesInMiddle = (JS_DATA.ucHrNamesInMiddle + 1) % 7;
        saveSettingsToStorageFunction();
        updateHrNamesPositionFunction(true);
    };

    window.updateHrNamesPositionFunction = function (refreshIqamaDisplay) {
        document.getElementById('middleSalatNamesCheckbox').checked = (JS_DATA.ucHrNamesInMiddle == 1);

        var hrIqamaTopVariant    = '13%';
        var hrIqamaBottomVariant = '71%';
        if (JS_DATA.ucIqamaFullTimes == 1) {
            hrIqamaTopVariant    = '9%';
            hrIqamaBottomVariant = '67%';
        }

        var hmc = document.getElementById('mainHorizontalContainer');
        hmc.removeAttribute('data-layout-mode');

        if (JS_DATA.ucHrNamesInMiddle == 1) {
            // Mode 1 STD – noms au milieu
            // j6hourTOP/j5hourTOP remontés de 5% (64→59 / 60→55) : l'azan, en
            // bas dans ce thème, dépassait spacerCellFajrHorizontal par le bas.
            rootElement.style.setProperty('--jnamTOP',    '36%');
            rootElement.style.setProperty('--j6hourTOP',  '59%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--j5hourTOP',  '55%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--mt7',        '30%');

        } else if (JS_DATA.ucHrNamesInMiddle == 2) {
            // Mode 2 – Islamic Green
            // j6iqamaTOP/j5iqamaTOP remontés de 5% : l'horaire positionné en
            // bas (iqama par défaut, ou azan si le swap est actif) dépassait
            // vers le bas.
            rootElement.style.setProperty('--jnamTOP',    '4%');
            rootElement.style.setProperty('--j6hourTOP',  '35.5%');
            rootElement.style.setProperty('--j6iqamaTOP', 'calc(' + hrIqamaBottomVariant + ' - 5%)');
            rootElement.style.setProperty('--j5hourTOP',  '31.7%');
            rootElement.style.setProperty('--j5iqamaTOP', 'calc(' + hrIqamaBottomVariant + ' - 5%)');
            rootElement.style.setProperty('--mt7',        '1%');
            hmc.setAttribute('data-layout-mode', '2');

        } else if (JS_DATA.ucHrNamesInMiddle == 3) {
            // Mode 3 – Gold Minimal (positions identiques au mode 2)
            rootElement.style.setProperty('--jnamTOP',    '4%');
            rootElement.style.setProperty('--j6hourTOP',  '35.5%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaBottomVariant);
            rootElement.style.setProperty('--j5hourTOP',  '31.7%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaBottomVariant);
            rootElement.style.setProperty('--mt7',        '1%');
            hmc.setAttribute('data-layout-mode', '3');

        } else if (JS_DATA.ucHrNamesInMiddle == 4) {
            // Mode 4 – pb.png background (layout identique mode 1)
            rootElement.style.setProperty('--jnamTOP',    '36%');
            rootElement.style.setProperty('--j6hourTOP',  '64%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--j5hourTOP',  '60%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--mt7',        '30%');
            hmc.setAttribute('data-layout-mode', '4');

        } else if (JS_DATA.ucHrNamesInMiddle == 5) {
            // Mode 5 – Ornement Élégant (mêmes positions éprouvées que mode 1/4 :
            // seule la présentation change, cf. custom.css "MODE 5")
            rootElement.style.setProperty('--jnamTOP',    '36%');
            rootElement.style.setProperty('--j6hourTOP',  '64%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--j5hourTOP',  '60%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--mt7',        '30%');
            hmc.setAttribute('data-layout-mode', '5');

        } else if (JS_DATA.ucHrNamesInMiddle == 6) {
            // Mode 6 – Classique (fin) : positions identiques au mode 4, seules
            // les images changent (pb6/pbc6/pp6.webp -- contour épais + marge
            // retirés, cf. custom.css "MODE 6" et spec/images/, demande
            // explicite du 12/08/2026).
            rootElement.style.setProperty('--jnamTOP',    '36%');
            rootElement.style.setProperty('--j6hourTOP',  '64%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--j5hourTOP',  '60%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaTopVariant);
            rootElement.style.setProperty('--mt7',        '30%');
            hmc.setAttribute('data-layout-mode', '6');

        } else {
            // Mode 0 STD – noms en haut
            rootElement.style.setProperty('--jnamTOP',    '4%');
            rootElement.style.setProperty('--j6hourTOP',  '35.5%');
            rootElement.style.setProperty('--j6iqamaTOP', hrIqamaBottomVariant);
            rootElement.style.setProperty('--j5hourTOP',  '31.7%');
            rootElement.style.setProperty('--j5iqamaTOP', hrIqamaBottomVariant);
            rootElement.style.setProperty('--mt7',        '1%');
        }

        if (refreshIqamaDisplay) updateIqamaTimesDisplayFunction();
    };

    // Ré-appliquer immédiatement pour que les modes 2/3 (lus depuis
    // localStorage) appliquent bien le data-layout-mode dès le chargement.
    updateHrNamesPositionFunction(false);

    // Reglage direct d'un mode precis par index (0-5) - utilise par le
    // selecteur nomme (cf. _installLayoutModeSelector plus bas) pour choisir
    // un mode sans avoir a cliquer sur la case a cocher N fois. Partage la
    // meme logique que toggleHrNamesMiddleFunction (sauvegarde + re-render).
    window._ucSetHrLayoutMode = function (mode) {
        var m = ((mode % 7) + 7) % 7; // toujours positif meme si mode < 0
        var prevMode = JS_DATA.ucHrNamesInMiddle;
        JS_DATA.ucHrNamesInMiddle = m;
        saveSettingsToStorageFunction();

        // Mode 1 ("مركزي") : le fond arcade (hrCellBg9.png) n'est appliqué
        // par le core (m2body.js, updateIqamaTimesDisplayFunction) QUE quand
        // l'iqama s'affiche en durée ("12'"), jamais en heure complète
        // (HH:MM, fullIqamaTimesCheckbox) -- confirmé en conditions réelles
        // (capture boîtier Mediouni, 19/08/2026) : avec l'heure complète
        // active, le mode 1 affichait un simple fond carré au lieu de
        // l'arcade voulue. Plutôt que de forcer artificiellement le fond par
        // CSS (le mode 1 resterait alors incohérent avec son propre
        // affichage iqama), on désactive l'heure complète le temps du mode 1
        // et on la restaure telle quelle en le quittant.
        if (m === 1 && prevMode !== 1) {
            if (JS_DATA.ucIqamaFullTimes == 1 && typeof toggleIqamaFullTimesFunction === 'function') {
                JS_CUSTOM.ucMode1RestoreFullIqamaTimes = 1;
                saveCustomSettingsFunction();
                toggleIqamaFullTimesFunction();
            }
        } else if (m !== 1 && prevMode === 1) {
            if (JS_CUSTOM.ucMode1RestoreFullIqamaTimes == 1) {
                JS_CUSTOM.ucMode1RestoreFullIqamaTimes = 0;
                saveCustomSettingsFunction();
                if (JS_DATA.ucIqamaFullTimes != 1 && typeof toggleIqamaFullTimesFunction === 'function') {
                    toggleIqamaFullTimesFunction();
                }
            }
        }

        _ucSyncFullIqamaTimesAvailability();
        updateHrNamesPositionFunction(true);
    };

    // Grise fullIqamaTimesCheckbox en mode 1 (retour utilisateur explicite,
    // 19/08/2026) : au-dela du garde-fou d'entree/sortie ci-dessus, empeche
    // aussi l'utilisateur de recocher l'heure complete MANUELLEMENT pendant
    // que le mode 1 est actif (ce qui recreerait aussitot le fond carre au
    // lieu de l'arcade) -- disabled empeche a la fois le clic ET l'evenement
    // onchange, natif, aucune interception necessaire.
    function _ucSyncFullIqamaTimesAvailability() {
        var cb = document.getElementById('fullIqamaTimesCheckbox');
        if (cb) cb.disabled = (JS_DATA.ucHrNamesInMiddle == 1);
    }
    window._ucSyncFullIqamaTimesAvailability = _ucSyncFullIqamaTimesAvailability;
    _ucSyncFullIqamaTimesAvailability();

})();

// ── Selecteur nomme du mode d'affichage horizontal ──────────────────────────
// Remplace le cycle "a l'aveugle" de #middleSalatNamesCheckbox (une case a
// cocher qu'il fallait re-cliquer sans jamais voir le nom du mode courant)
// par un controle affichant le nom du mode + fleches precedent/suivant.
// index.html n'etant pas modifiable, on masque la ligne d'origine (meme
// pattern que _hideOldQrCheckboxRow un peu plus haut dans ce fichier) et on
// injecte le nouveau controle juste apres.
(function _installLayoutModeSelector() {
    var MODE_NAMES = ['قياسي', 'مركزي', 'أخضر إسلامي', 'ذهبي أنيق', 'زخرفة كلاسيكية', 'زخرفة أنيقة', 'زخرفة كلاسيكية (رفيعة)'];

    function _hideOldRow() {
        var cb = document.getElementById('middleSalatNamesCheckbox');
        if (!cb) return false;
        var row = cb.closest ? cb.closest('div') : cb.parentElement;
        if (row) row.style.display = 'none';
        return true;
    }

    function _buildSelector() {
        if (document.getElementById('ucHrLayoutModeRow')) return true; // deja injecte
        var cb = document.getElementById('middleSalatNamesCheckbox');
        if (!cb) return false;
        var row = cb.closest ? cb.closest('div') : cb.parentElement;
        if (!row || !row.parentNode) return false;

        var wrap = document.createElement('div');
        wrap.id = 'ucHrLayoutModeRow';
        wrap.innerHTML =
            '<span id="ucHrLayoutModePrev" class="ucHrLayoutModeArrow">&#9664;</span>' +
            '<span id="ucHrLayoutModeText">نمط عرض (أفقي) <b id="ucHrLayoutModeName"></b></span>' +
            '<span id="ucHrLayoutModeNext" class="ucHrLayoutModeArrow">&#9654;</span>';
        row.parentNode.insertBefore(wrap, row.nextSibling);

        function _refresh() {
            var idx = parseInt(JS_DATA.ucHrNamesInMiddle, 10) || 0;
            var lbl = document.getElementById('ucHrLayoutModeName');
            if (lbl) lbl.textContent = MODE_NAMES[idx] || idx;
        }

        document.getElementById('ucHrLayoutModePrev').addEventListener('click', function () {
            window._ucSetHrLayoutMode((parseInt(JS_DATA.ucHrNamesInMiddle, 10) || 0) - 1);
            _refresh();
        });
        document.getElementById('ucHrLayoutModeNext').addEventListener('click', function () {
            window._ucSetHrLayoutMode((parseInt(JS_DATA.ucHrNamesInMiddle, 10) || 0) + 1);
            _refresh();
        });

        _refresh();
        return true;
    }

    if (!_hideOldRow() || !_buildSelector()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_hideOldRow())   setTimeout(_hideOldRow, 300);
            if (!_buildSelector()) setTimeout(_buildSelector, 300);
        });
    }
})();

/* ── Swap Azan/Iqama : re-synchroniser quand le thème (mode) change ──────────
   Thème 1 exclu (cf. updateSwapAzanIqamaFunction) : si l'utilisateur revient
   au thème 1 pendant que la case est cochée, la classe swapAzanIqamaActive
   doit être retirée immédiatement, sans attendre un rechargement de page.
   ─────────────────────────────────────────────────────────────────────────── */
(function _hookSwapAzanIqamaToLayoutMode() {
    var _origUpdate = window.updateHrNamesPositionFunction;
    if (!_origUpdate) return;
    window.updateHrNamesPositionFunction = function () {
        _origUpdate.apply(this, arguments);
        if (typeof window.updateSwapAzanIqamaFunction === 'function') {
            window.updateSwapAzanIqamaFunction();
        }
    };
})();

/* ── Mode 3 : synchroniser la largeur du rectangle iqama sur celle de l'azan ─
   Quand fullIqamaTimesCheckbox est décoché, l'iqama peut afficher "10'" au
   lieu de "HH:MM" → le rectangle rétrécit. On impose min-width = largeur azan.
   ─────────────────────────────────────────────────────────────────────────── */
(function _initIqamaMinWidth() {

    function _clearMinWidth() {
        document.querySelectorAll(
            '#prayerTimesContainerHorizontal .iqamaTimeHorizontalClass'
        ).forEach(function (iq) { iq.style.minWidth = ''; });
    }

    function _sync() {
        if (JS_DATA.ucHrNamesInMiddle !== 3) {
            /* Nettoyer les styles inline résiduels quand on quitte le mode 3 */
            _clearMinWidth();
            return;
        }
        var cells = document.querySelectorAll(
            '#prayerTimesContainerHorizontal .prayerCellClass');
        cells.forEach(function (cell) {
            var az = cell.querySelector('.azanTimeHorizontalClass');
            var iq = cell.querySelector('.iqamaTimeHorizontalClass');
            if (!az || !iq) return;
            // Lire la largeur rendue du rectangle azan (inclut padding + border)
            var w = az.getBoundingClientRect().width;
            if (w > 0) iq.style.minWidth = w + 'px';
        });
    }

    // Lancer après que le moteur a fini de peindre la page
    function _scheduleSync() {
        setTimeout(_sync, 300);
    }

    // 1) Au chargement
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _scheduleSync);
    } else {
        _scheduleSync();
    }

    // 2) Quand le mode change (toggleHrNamesMiddleFunction)
    var _origUpdate = window.updateHrNamesPositionFunction;
    if (_origUpdate) {
        window.updateHrNamesPositionFunction = function () {
            _origUpdate.apply(this, arguments);
            _scheduleSync();
        };
    }

    // 3) Quand les valeurs iqama changent (fullIqamaTimesCheckbox, etc.)
    //    Observer les changements de texte dans les éléments iqama
    function _attachIqamaObserver() {
        var iqEls = document.querySelectorAll(
            '#prayerTimesContainerHorizontal .iqamaTimeHorizontalClass');
        if (!iqEls.length) { setTimeout(_attachIqamaObserver, 500); return; }
        var obs = new MutationObserver(_scheduleSync);
        iqEls.forEach(function (el) {
            obs.observe(el, { childList: true, characterData: true, subtree: true });
        });
    }
    _attachIqamaObserver();

    // API publique pour forcer une re-sync depuis la console
    window.syncIqamaMinWidth = _sync;

})();

/* ── Mode 3 : positionner les labels azan/iqama au bord droit du rectangle Fajr ─
   left: calc(100% + 0.3vw) est conçu pour width:100% ; en mode 3 les rectangles
   sont fit-content centrés donc on mesure le bord droit réel et on l'applique.
   ─────────────────────────────────────────────────────────────────────────────── */
(function _initIqamaLabelPosition() {

    function _positionLabels() {
        if (JS_DATA.ucHrNamesInMiddle !== 3) return;
        var fajrCell = document.getElementById('prayerCellFajrHorizontal');
        if (!fajrCell) return;
        var azRect = fajrCell.querySelector('.azanTimeHorizontalClass');
        if (!azRect) return;

        var azBR   = azRect.getBoundingClientRect();
        var cellBR = fajrCell.getBoundingClientRect();
        if (azBR.width === 0) return;

        /* Bord droit du rectangle azan, exprimé en px depuis le bord gauche de la cellule */
        var leftPx = (azBR.right - cellBR.left) + 3;

        var lblAz = document.getElementById('iqamaColLabelAzan');
        var lblIq = document.getElementById('iqamaColLabelIqama');
        if (lblAz) lblAz.style.left = leftPx + 'px';
        if (lblIq) lblIq.style.left = leftPx + 'px';
    }

    function _schedulePosition() { setTimeout(_positionLabels, 350); }

    /* 1) Au chargement */
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _schedulePosition);
    } else {
        _schedulePosition();
    }

    /* 2) Quand le mode change */
    var _origUpdate2 = window.updateHrNamesPositionFunction;
    if (_origUpdate2) {
        window.updateHrNamesPositionFunction = function () {
            _origUpdate2.apply(this, arguments);
            _schedulePosition();
        };
    }

    /* 3) Au redimensionnement de la fenêtre */
    window.addEventListener('resize', _schedulePosition);

    /* API console */
    window.syncIqamaLabelPosition = _positionLabels;

})();


// ── Fallback silencieux : n'importe quel geste déverrouille aussi ─────────
//  (cas : l'utilisateur ferme la modale d'une autre façon, ou interagit
//   avec l'écran avant que la modale ne s'affiche)
/* -- Masquage de ayaDisplayContainer H+V pendant le compte a rebours ----------------
   COUNTDOWN_TICK : visibility:hidden sur les deux containers (H et V).
   MutationObserver : reapplique immediatement si le core remet une valeur.
   IQAMA_TIME + AZAN_TIME : restauration (visibility:visible).
   ------------------------------------------------------------------------------------- */
(function _fixAyaPositionInCounter() {

    var _counterActive = false;

    function _hide(el)    { if (el && el.style.visibility !== 'hidden')  el.style.visibility = 'hidden';  }
    function _restore(el) { if (el && el.style.visibility !== '')        el.style.visibility = '';        }

    function _getH() { return document.getElementById('ayaDisplayContainerHorizontal'); }
    function _getV() { return document.getElementById('ayaDisplayContainerVertical');   }

    // MutationObserver : reaction instantanee si le core remet visibility
    function _watchEl(el) {
        if (!el) return;
        new MutationObserver(function() {
            if (_counterActive) _hide(el);
        }).observe(el, { attributes: true, attributeFilter: ['style'] });
    }

    _watchEl(_getH());
    _watchEl(_getV());

    // Pas d'exception pour isDohaCounter (compteur "minutes avant Doha", qui
    // démarre au chourouk) : le masquage doit s'appliquer à TOUT compteur
    // plein écran, Doha compris. Le core tente bien de repositionner le
    // verset "au-dessus" du compteur en plein écran (showIqamaCounter(),
    // m2body.js ~L2980 : `ayaContainerVertical.style.top = '11%'`), mais
    // `ayaContainerVertical`/`ayaContainerHorizontal` sont des noms
    // permutés dans le core (cf. m2body.js L126-129 et le commentaire de
    // _fixAyaFontSizeWideScreen plus bas dans ce fichier) : cet appel
    // repositionne en réalité le conteneur de l'AUTRE orientation, jamais
    // celui visible à l'écran. Sans ce masquage, le verset reste donc affiché
    // à sa position par défaut (~40% du haut, cf. style1/2.css) et chevauche
    // le compteur plein écran -- observé en pratique uniquement pendant le
    // compteur Doha/chourouk car une ancienne exception ici l'excluait du
    // masquage (les compteurs iqama normaux, eux, étaient déjà correctement
    // masqués et ne montraient donc jamais le bug côté core).
    ucOn(UC_EVT.COUNTDOWN_TICK, function() {
        if (!_counterActive) {
            _counterActive = true;
            _hide(_getH());
            _hide(_getV());
        }
    });

    ucOn(UC_EVT.IQAMA_TIME, function() {
        _counterActive = false;
        _restore(_getH());
        _restore(_getV());
    });

    ucOn(UC_EVT.AZAN_TIME, function() { _counterActive = false; });

    // Expose pour _ucResyncPrayerSequence (tout en haut du fichier) : le
    // resync apres un retour en premier plan appelle les fonctions coeur
    // DIRECTEMENT (jamais via UC_EVT.IQAMA_TIME/AZAN_TIME), donc _counterActive
    // peut rester bloque a true indefiniment si l'app etait backgroundee
    // PENDANT un countdown -- le MutationObserver continue alors de forcer
    // visibility:hidden sur le verset pour toujours, meme apres que le
    // compteur reel soit termine depuis longtemps (seul un reload manuel
    // reinitialisait ce flag jusqu'ici, cf. retour utilisateur 29/07/2026 :
    // page coherente au retour au premier plan sauf le verset, absent jusqu'au
    // reload).
    window._ucResetAyaPositionGuard = function() {
        _counterActive = false;
        _restore(_getH());
        _restore(_getV());
    };

})();


(function _installAudioUnlockFallback() {
    const EVTS = ['click', 'touchstart', 'touchend', 'pointerdown', 'keydown'];
    function _onGesture() {
        EVTS.forEach(function(e) { document.removeEventListener(e, _onGesture, true); });
        _hideAutoplayUnlockModal();   // fermer si encore ouverte
        _doAudioUnlock();
    }
    EVTS.forEach(function(e) {
        document.addEventListener(e, _onGesture, { capture: true, passive: true });
    });
})();


// ═══════════════════════════════════════════════════════════════════════════
// CIBLE DÉDIÉE POUR LE TAP SYNTHÉTIQUE NATIF (boîtiers uniquement)
// ─────────────────────────────────────────────────────────────────────────────
// MainActivity.kt::dispatchSyntheticUnlockTap() delivre un vrai MotionEvent au
// coin haut-droit (x = largeur vue - 1, y = 1) pour debloquer la politique
// autoplay au chargement (cf. commentaire Kotlin). Choisir une coordonnee
// d'ecran "vide" est fragile par nature : n'importe quel element futur (ou
// une modale deja ouverte au moment du tap, ex. azanCatalogOverlay) peut finir
// par occuper ce pixel et absorber le tap a sa place -- exactement le bug
// vecu deux fois de suite (coin (1,1) ouvrait le menu hamburger, 10/08/2026 ;
// puis le coin haut-droit choisi en remplacement fermait azanCatalogOverlay
// -- et n'importe quelle autre modale a fond cliquable, cf. mapLocatorOverlay/
// qiblaOverlay/qrCodeOverlay/quranPlayerOverlay -- si elle etait ouverte au
// moment du tap, 1.5s apres un rechargement de page pendant que la box etait
// en cours d'utilisation).
// Solution durable : un element dedie, TOUJOURS present, avec le z-index le
// plus eleve possible (au-dessus de n'importe quelle modale future, meme
// celles a 999999999) et sans aucun gestionnaire de clic -- le tap natif
// atterrit systematiquement dessus, quoi qu'il y ait en dessous, sans jamais
// interagir avec le contenu reel de la page.
// ═══════════════════════════════════════════════════════════════════════════
(function _installSyntheticUnlockTapTarget() {
    var el = document.createElement('div');
    el.id = 'ucSyntheticUnlockTarget';
    el.style.cssText = 'position:fixed;top:0;right:0;width:4px;height:4px;' +
        'z-index:2147483647;pointer-events:auto;background:transparent;';
    document.documentElement.appendChild(el);
})();


// ═══════════════════════════════════════════════════════════════════════════
// LIBELLÉS AZAN / IQAMA – cellule Fajr (mode fullIqamaTimes)
// Affiche "Azan" et "Iqama" à droite de la 1ère cellule quand les iqamas
// sont affichées en hh:mm, pour éviter toute confusion chez les fidèles.
// 100 % custom.js : les divs sont créés dynamiquement, index.html intact.
// Les textes sont dans la langue choisie via JS_eLang.
// ═══════════════════════════════════════════════════════════════════════════
(function _initFullIqamaColumnLabels() {

    var hmc      = document.getElementById('mainHorizontalContainer');
    var fajrCell = document.getElementById('prayerCellFajrHorizontal');

    /* Création dynamique des deux labels dans la cellule Fajr uniquement */
    var lblAzan = document.createElement('div');
    lblAzan.id        = 'iqamaColLabelAzan';
    lblAzan.className = 'iqamaColLabelClass iqamaColLabelAzanClass';

    var lblIqam = document.createElement('div');
    lblIqam.id        = 'iqamaColLabelIqama';
    lblIqam.className = 'iqamaColLabelClass iqamaColLabelIqamaClass';

    if (fajrCell) {
        fajrCell.appendChild(lblAzan);
        fajrCell.appendChild(lblIqam);
    }

    /* Applique / retire la classe selon l'état courant de ucIqamaFullTimes */
    function _syncClass() {
        if (!hmc) return;
        hmc.classList.toggle('fullIqamaTimesActive', JS_DATA.ucIqamaFullTimes == 1);
    }

    /* Injecte les textes traduits (cx_AzanNAME / cx_IQAMA) */
    function _setTexts() {
        lblAzan.textContent = (JS_eLang && JS_eLang.cx_AzanNAME) ? JS_eLang.cx_AzanNAME : 'أذان';
        lblIqam.textContent = (JS_eLang && JS_eLang.cx_IQAMA)    ? JS_eLang.cx_IQAMA    : 'إقامة';
    }

    /* Wrapping de updateIqamaTimesDisplayFunction :
       appelée à chaque changement d'état fullIqamaTimes et à chaque cycle,
       ce qui garantit que la classe et les textes sont toujours synchronisés. */
    var _origUpdate = window.updateIqamaTimesDisplayFunction;
    if (typeof _origUpdate === 'function') {
        window.updateIqamaTimesDisplayFunction = function () {
            var r = _origUpdate.apply(this, arguments);
            _setTexts();
            _syncClass();
            return r;
        };
    }

    _setTexts();
    _syncClass();

})();


// ═══════════════════════════════════════════════════════════════════════════
// ── FOND D'ÉCRAN DYNAMIQUE selon la prière (écran d'appel AZAN) ─────────────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Règles de sélection (mode HORIZONTAL uniquement) :
//    ISHA          → spec/images/dome_nuit.png
//    MGRB          → spec/images/dome_maghreb.png
//    ASSR / DOHR   → spec/images/dome_jours.png
//    FAJR (défaut) → spec/images/dome_fajr.png
//
//  En mode VERTICAL (normal ET kiosque "Forcer vertical", qui réutilise le
//  même conteneur #mainVerticalContainer) : fond NOIR uni, pas d'image dome.
//
//  Déclenchement : UC_EVT.AZAN_SHOW (juste après l'affichage du popup).
// ───────────────────────────────────────────────────────────────────────────
// Chemin de l'image de fond (écran d'appel azan) selon la prière -- partagé
// par _installAzanDynamicBackground et _patchApplyThemeForDome (même logique
// dupliquée à l'origine, factorisée ici). Bascule dome_xxx.webp/sansdome_xxx.webp
// selon JS_CUSTOM.ucAzanBgUseDome (case à cocher onglet "الأذان", demande
// explicite du 12/08/2026).
function _ucDomeImageForPrayer(prayer) {
    var base;
    switch (prayer) {
        case 'ISHA':  base = 'isha';     break;
        case 'MGRB':  base = 'maghreb';  break;
        case 'ASSR':  base = 'asr';      break;
        case 'JOMOA':
        case 'DOHR':  base = 'dohr';     break;
        case 'SHRQ':  base = 'doha';     break;
        default:      base = 'fajr';     break; // FAJR + fallback
    }
    var prefix = (JS_CUSTOM.ucAzanBgUseDome == 1) ? 'dome_' : 'sansdome_';
    return 'spec/images/' + prefix + base + '.webp';
}

(function _installAzanDynamicBackground() {

    /** Retourne le chemin de l'image de dôme selon la prière. */
    function _getDomeImage(prayer) {
        return _ucDomeImageForPrayer(prayer);
    }

    /** Image de dôme en HORIZONTAL ; fond NOIR uni en VERTICAL (normal ou
        forcé — les deux partagent le même conteneur vertical). */
    function _applyDomeBackground(imageUrl) {
        if (azanPopupBgHorizontal) {
            azanPopupBgHorizontal.style.background       = 'url(' + imageUrl + ')';
            azanPopupBgHorizontal.style.backgroundRepeat = 'no-repeat';
            azanPopupBgHorizontal.style.backgroundSize   = '100% 100%';
        }
        if (azanPopupBgVertical) {
            azanPopupBgVertical.style.background = '#000';
        }
        // Sans dôme : plus de silhouette à contourner -- heure/titre azan/nom
        // de la prière recentrés horizontalement (cf. .ucNoDomeCentered,
        // custom.css). Avec dôme : comportement d'origine (texte à gauche).
        var noDome = (JS_CUSTOM.ucAzanBgUseDome != 1);
        if (azanPopupHorizontalElement) azanPopupHorizontalElement.classList.toggle('ucNoDomeCentered', noDome);
        if (azanPopupVerticalElement)   azanPopupVerticalElement.classList.toggle('ucNoDomeCentered', noDome);
    }

    /**
     * Ajuste la couleur du texte du popup azan selon la prière.
     *
     * dome_jours (JOMOA / ASSR / DOHR) — fond ciel bleu + dôme doré :
     *   • Nom de la prière (grand texte) → doré foncé  #b8860b  cohérent avec le dôme
     *   • Titre "حان وقت الأذان" + heure → bleu marine  #1a3a6b  écho du ciel profond
     *
     * Autres prières → reset : couleurs CSS par défaut (blanches + ombre sombre).
     */
    // Table couleurs par prière pour le popup azan
    var _AZAN_COLORS = {
        FAJR: { clock: '#B8FFF1', clockShadow: '0 0 12px rgba(184,255,241,0.50)',
                azan:  '#7FFFD4', azanShadow:  '0 0 16px rgba(127,255,212,0.60)',
                prayer:'#FFFFFF', prayerShadow:'0 0 8px rgba(255,255,255,0.35)',
                doa:   '#8EDBFF', doaShadow:   '0 0 14px rgba(142,219,255,0.60)' },
        DOHR: { clock: '#FFF6D6', clockShadow: '0 0 10px rgba(255,245,210,0.45)',
                azan:  '#5F4707', azanShadow:  '0 0 14px rgba(95,71,7,0.55)',
                prayer:'#7A570A', prayerShadow:'0 0 8px rgba(122,87,10,0.40)',
                doa:   '#1a3a6b', doaShadow:   '0 0 12px rgba(26,58,107,0.60)' },
        ASSR: { clock: '#FFE08A', clockShadow: '0 0 10px rgba(255,224,138,0.45)',
                azan:  '#5F4707', azanShadow:  '0 0 14px rgba(95,71,7,0.55)',
                prayer:'#7A570A', prayerShadow:'0 0 8px rgba(122,87,10,0.40)',
                doa:   '#1a3a6b', doaShadow:   '0 0 12px rgba(26,58,107,0.60)' },
        MGRB: { clock: '#FFD36B', clockShadow: '0 0 12px rgba(255,211,107,0.55)',
                azan:  '#FF9E3D', azanShadow:  '0 0 16px rgba(255,120,40,0.60)',
                prayer:'#FFF4E8', prayerShadow:'0 0 10px rgba(255,244,232,0.40)',
                doa:   '#FFE066', doaShadow:   '0 0 14px rgba(255,224,102,0.60)' },
        ISHA: { clock: '#FFD9A8', clockShadow: '0 0 12px rgba(255,217,168,0.50)',
                azan:  '#FFB86B', azanShadow:  '0 0 16px rgba(255,170,90,0.60)',
                prayer:'#FFF7EF', prayerShadow:'0 0 10px rgba(255,247,239,0.40)',
                doa:   '#D6A6FF', doaShadow:   '0 0 14px rgba(214,166,255,0.65)' },
        // SHRQ (Doha) : clock + azan + prayer uniquement (marquee non affiché)
        SHRQ: { clock: '#FFF7DA', clockShadow: '0 0 12px rgba(255,244,204,0.45)',
                azan:  '#FFC94D', azanShadow:  '0 0 16px rgba(255,216,107,0.55)',
                prayer:'#FDFDFD', prayerShadow:'0 0 10px rgba(255,255,255,0.35)',
                doa:   '#6EF2FF', doaShadow:   '0 0 14px rgba(143,245,228,0.55)' }
    };
    // JOMOA = mêmes couleurs que DOHR (prière de jour)
    _AZAN_COLORS.JOMOA = _AZAN_COLORS.DOHR;

    /** Retourne la config couleur pour une prière (fallback FAJR). */
    function _getAzanColors(prayer) {
        return _AZAN_COLORS[prayer] || _AZAN_COLORS.FAJR;
    }

    // Expose pour _showAzanTicker (IIFE séparée)
    window._getAzanColors = _getAzanColors;

    function _applyAzanTextStyle(prayer) {
        var cfg = _getAzanColors(prayer);
        // Mode vertical : blanc fixe sur tous les items, quelle que soit la
        // prière (demande explicite). L'horizontal garde la couleur par
        // prière définie dans _AZAN_COLORS, donc non touché ici.
        var WHITE = '#FFFFFF';

        // Heure (clock)
        if (azanPopupTimeVerticalElement) {
            azanPopupTimeVerticalElement.style.color      = WHITE;
            azanPopupTimeVerticalElement.style.textShadow = cfg.clockShadow;
        }
        if (azanPopupTimeHorizontalElement) {
            azanPopupTimeHorizontalElement.style.color      = cfg.clock;
            azanPopupTimeHorizontalElement.style.textShadow = cfg.clockShadow;
        }
        // Titre azan
        if (azanPopupTitleVerticalElement) {
            azanPopupTitleVerticalElement.style.color      = WHITE;
            azanPopupTitleVerticalElement.style.textShadow = cfg.azanShadow;
        }
        if (azanPopupTitleHorizontalElement) {
            azanPopupTitleHorizontalElement.style.color      = cfg.azan;
            azanPopupTitleHorizontalElement.style.textShadow = cfg.azanShadow;
        }
        // Nom de la prière
        if (azanPopupPrayerNameVerticalElement) {
            azanPopupPrayerNameVerticalElement.style.color      = WHITE;
            azanPopupPrayerNameVerticalElement.style.textShadow = cfg.prayerShadow;
        }
        if (azanPopupPrayerNameHorizontalElement) {
            azanPopupPrayerNameHorizontalElement.style.color      = cfg.prayer;
            azanPopupPrayerNameHorizontalElement.style.textShadow = cfg.prayerShadow;
        }
    }

    ucOn(UC_EVT.AZAN_SHOW, function(e) {
        var prayer = e.prayer || '';
        _applyDomeBackground(_getDomeImage(prayer));
        _applyAzanTextStyle(prayer);
    });

})();

// ───────────────────────────────────────────────────────────────────────────
// Patch applyThemeFunction : restaure le dome.png apres chaque changement
// de theme / orientation si le popup azan est visible.
//
// Cause du bug : handleResizeFunction() appelle applyThemeFunction(false) a
// chaque resize / changement d'orientation. Cette fonction ecrase
// azanPopupBgHorizontal/Vertical.style.background avec le fond du theme,
// effacant l'image dome_xxx.png posee par _installAzanDynamicBackground.
// ───────────────────────────────────────────────────────────────────────────
(function _patchApplyThemeForDome() {
    if (typeof applyThemeFunction !== 'function') return;

    // Memorise la derniere priere affichee dans le popup azan
    var _domeActivePrayer = null;

    ucOn(UC_EVT.AZAN_SHOW, function(e) { _domeActivePrayer = e.prayer || null; });
    ucOn(UC_EVT.AZAN_HIDE, function()  { _domeActivePrayer = null; });

    // Correspondance priere → image (factorisée dans _ucDomeImageForPrayer,
    // cf. plus haut -- meme logique que _installAzanDynamicBackground)
    function _domeUrl(prayer) {
        return _ucDomeImageForPrayer(prayer);
    }

    var _origApplyTheme = applyThemeFunction;
    window.applyThemeFunction = function(withTransition) {
        _origApplyTheme(withTransition);
        // Si le popup azan est ouvert, le fond vient d'etre ecrase par le theme
        // → on reapplique immediatement le bon fond : image dome en horizontal,
        // noir uni en vertical (normal et forcé).
        if (_domeActivePrayer) {
            if (azanPopupBgHorizontal) {
                azanPopupBgHorizontal.style.background       = 'url(' + _domeUrl(_domeActivePrayer) + ')';
                azanPopupBgHorizontal.style.backgroundRepeat = 'no-repeat';
                azanPopupBgHorizontal.style.backgroundSize   = '100% 100%';
            }
            if (azanPopupBgVertical) {
                azanPopupBgVertical.style.background = '#000';
            }
            // FIX (retour utilisateur) : _applyDomeBackground (ci-dessus) pose
            // aussi la classe ucNoDomeCentered (heure/nom de priere recentres
            // quand ucAzanBgUseDome=0) -- oubliee ici jusqu'ici. Chaque
            // reapplication du theme pendant que le popup azan est ouvert
            // (ex. bascule jour/nuit en plein milieu de la page azan de
            // Jumu'a) restaurait le fond "sans dome" correct mais laissait le
            // texte se replacer comme si le dome etait affiche -- saut visuel
            // vers la gauche juste avant la fermeture de la page.
            var _noDome = (JS_CUSTOM.ucAzanBgUseDome != 1);
            if (azanPopupHorizontalElement) azanPopupHorizontalElement.classList.toggle('ucNoDomeCentered', _noDome);
            if (azanPopupVerticalElement)   azanPopupVerticalElement.classList.toggle('ucNoDomeCentered', _noDome);
            _L('SYS', 'DOME_RESTORE', {prayer: _domeActivePrayer});
        }
    };

    _L('SYS', 'PATCH', {fn: 'applyThemeFunction', for: 'dome_bg_orientation_fix'});
})();



// ═══════════════════════════════════════════════════════════════════════════
// ── SYNCHRONISATION DATE HIJRI (via API externe) ───────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Stratégie de planification :
//    • Tentative initiale : si aucun cache valide pour aujourd'hui → immédiat
//    • Succès  → prochaine synchro à 01:00 (cycle 24h)
//    • Échec   → retry dans 1h, puis encore 1h, … jusqu'au succès
//    • Hors-ligne ou erreur API → fallback automatique sur le calcul STD
//
//  Cache  : localStorage clé  JS_HIJRI_SYNC_CACHE  { date, d, m, y, ts }
//
//  Synchro manuelle depuis la console :  forceHijriSyncFunction()
//
//  URL configurable via l'UI (placeholders {d} {m} {y} remplacés à l'appel)
//    Ex : https://www.salahhour.com/index.php/api/calendar?day={d}&month={m}&year={y}&convert_to=0
// ───────────────────────────────────────────────────────────────────────────

// ── Namespace HijriApi ────────────────────────────────────────────────────
//  Expose HijriApi.buildUrl(d, m, y) pour une utilisation externe si besoin.
(function (global) {
    global.HijriApi = {
        buildUrl: function (d, m, y) {
            var tpl = (JS_CUSTOM.ucHijriSyncUrl || '')
                .replace('{d}', d).replace('{m}', m).replace('{y}', y);
            dolog('[HijriSync] APIURL=' + tpl);
            return tpl;
        }
    };
})(window);

// ── État & cache ─────────────────────────────────────────────────────────
const _HIJRI_SYNC_KEY = 'JS_HIJRI_SYNC_CACHE';
let _hijriSyncCache   = null;
let _hijriSyncTimer   = null;

// ── État & cache : source officielle par pays (Supabase, cf. table
//    hijri_month_starts) — prioritaire sur la synchro API générique
//    ci-dessus quand une entrée valide couvre la date du jour.
//
//    IMPORTANT : on persiste la ligne BRUTE (date de début grégorienne du
//    mois hijri + mois/année hijri), PAS un couple {d,m,y} figé pour "today".
//    Cela permet de recalculer le jour hijri courant localement, de façon
//    SYNCHRONE et SANS RÉSEAU, à chaque démarrage/rafraîchissement — y
//    compris au passage de minuit — tant que la ligne connue couvre encore
//    la date du jour (jour calculé entre 1 et 30). Avant ce changement, le
//    cache stockait un {d,m,y} figé valable uniquement pour un jour-clé
//    exact : il fallait donc RE-INTERROGER Supabase à chaque nouveau jour
//    (et au premier lancement) avant de pouvoir afficher la bonne valeur,
//    ce qui explique l'incohérence observée ("la 1ère valeur affichée après
//    install/refresh n'est pas systématiquement celle de Supabase") — la
//    fenêtre réseau (souvent > 200ms sur 1ère requête à froid) pouvait être
//    interrompue par le location.reload() de _applyMosqueConfig() (premier
//    lancement), ou simplement ne pas être terminée au moment où l'utilisateur
//    regarde l'écran.
const _HIJRI_OFFICIAL_KEY = 'JS_HIJRI_OFFICIAL_CACHE';
let _hijriOfficialRaw     = null; // { country, gregorianStartDate, hijriMonth, hijriYear, ts }

(function _loadHijriSyncCache() {
    try {
        const raw = localStorage.getItem(_HIJRI_SYNC_KEY);
        if (raw) _hijriSyncCache = JSON.parse(raw);
    } catch (e) {}
    try {
        const rawO = localStorage.getItem(_HIJRI_OFFICIAL_KEY);
        if (rawO) _hijriOfficialRaw = JSON.parse(rawO);
    } catch (e) {}
})();

// ── Calcul LOCAL (sans réseau) du jour hijri courant à partir de la
//    dernière ligne officielle connue. Retourne null si aucune ligne en
//    cache, si elle concerne un autre pays (changement de ville/mosquée),
//    ou si le calcul sort de la plage valide [1,30] (mois hijri suivant pas
//    encore annoncé → il faut alors retenter le réseau, cf. _attemptHijriSync).
function _computeOfficialToday(raw) {
    if (!raw || !raw.gregorianStartDate) return null;
    if (raw.country !== _resolveMosqueCountry()) return null;
    try {
        const start       = new Date(raw.gregorianStartDate + 'T00:00:00');
        const now         = new Date();
        const nowMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const d           = Math.round((nowMidnight - start) / 86400000) + 1;
        if (d < 1 || d > 30) return null;
        return { d: d, m: raw.hijriMonth, y: raw.hijriYear };
    } catch (e) { return null; }
}

// ── Helpers temporels ─────────────────────────────────────────────────────
function _hijriTodayKey() {
    const n = new Date();
    return n.getFullYear() + '-' + (n.getMonth() + 1) + '-' + n.getDate();
}

// ── Résolution du pays de la mosquée (préfixe de LOCATION_CODE, ex.
//    'tn.monastir' → 'TN'), utilisée pour interroger hijri_month_starts.
function _resolveMosqueCountry() {
    try {
        const loc = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.LOCATION_CODE) || '';
        const cc  = String(loc).split('.')[0];
        return cc ? cc.toUpperCase() : null;
    } catch (e) { return null; }
}

function _msUntil1am() {
    const now     = new Date();
    const next1am = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 1, 0, 0, 0);
    if (next1am <= now) next1am.setDate(next1am.getDate() + 1);
    return next1am - now;
}

// ── Scheduler ────────────────────────────────────────────────────────────
function _scheduleHijriSync(delayMs, reason) {
    if (_hijriSyncTimer) clearTimeout(_hijriSyncTimer);
    const target = new Date(Date.now() + delayMs);
    const hh = ('0' + target.getHours()).slice(-2);
    const mm = ('0' + target.getMinutes()).slice(-2);
    const min = Math.round(delayMs / 60000);
    dolog('[HijriSync] prochaine ' + (reason || 'tentative') + ' à ' + hh + ':' + mm + ' (dans ' + min + 'min)');
    _hijriSyncTimer = setTimeout(_attemptHijriSync, delayMs);
}

// ── Parser multi-format ───────────────────────────────────────────────────
//  Essaie plusieurs structures JSON courantes pour extraire d/m/y hijri.
function _parseHijriResponse(json) {
    let hd, hm, hy;

    // Format 1 : { data: { hijri_date: { day, month, year } } }
    if (json.data && json.data.hijri_date) {
        hd = json.data.hijri_date.day;
        hm = json.data.hijri_date.month;
        hy = json.data.hijri_date.year;
    }
    // Format 2 : { hijri_day, hijri_month, hijri_year }
    else if (json.hijri_day !== undefined) {
        hd = json.hijri_day; hm = json.hijri_month; hy = json.hijri_year;
    }
    // Format 3 : { hijri: { day, month, year } }
    else if (json.hijri && json.hijri.day !== undefined) {
        hd = json.hijri.day; hm = json.hijri.month; hy = json.hijri.year;
    }
    // Format 4 : { day, month, year } direct
    else if (json.day !== undefined && json.month !== undefined && json.year !== undefined) {
        hd = json.day; hm = json.month; hy = json.year;
    }
    // Format 5 : tableau [{ hijri_day|day, hijri_month|month, hijri_year|year }]
    else if (Array.isArray(json) && json.length > 0) {
        const first = json[0];
        hd = first.hijri_day !== undefined ? first.hijri_day : first.day;
        hm = first.hijri_month !== undefined ? first.hijri_month : first.month;
        hy = first.hijri_year !== undefined ? first.hijri_year : first.year;
    }

    // Format salahhour.com : { "to": "1447-10-29", "success": true }
    // (prioritaire car réponse directe connue)
    if (!hd && json.to && typeof json.to === 'string' && json.success) {
        const parts = json.to.split('-');
        if (parts.length === 3) { hy = parts[0]; hm = parts[1]; hd = parts[2]; }
    }

    hd = parseInt(hd, 10);
    hm = parseInt(hm, 10);
    hy = parseInt(hy, 10);

    if (!hd || !hm || !hy || hd < 1 || hd > 30 || hm < 1 || hm > 12 || hy < 1400 || hy > 1700) {
        dolog('[HijriSync] ⚠ parse échoué. Réponse brute (200c): ' + JSON.stringify(json).substring(0, 200));
        return null;
    }
    return { d: hd, m: hm, y: hy };
}

// ── Source officielle par pays (Supabase, table hijri_month_starts) ──────
//  Cherche la ligne la plus récente dont gregorian_start_date <= aujourd'hui
//  pour le pays de la mosquée, puis vérifie qu'elle couvre bien la date du
//  jour (jour calculé entre 1 et 30). Une entrée absente ou périmée n'est
//  PAS une erreur : c'est l'état normal tant que l'annonce officielle du
//  mois suivant n'a pas encore été saisie (elle ne peut arriver que le soir
//  du 29e jour hijri ou après) → callback(null) fait simplement retomber
//  sur la synchro API générique existante.
function _attemptOfficialHijriMonthStart(callback) {
    const country = _resolveMosqueCountry();
    if (!country) { callback(null); return; }

    const _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
                  || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    const _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
                  || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';

    const now      = new Date();
    const isoToday = now.getFullYear() + '-' + ('0' + (now.getMonth() + 1)).slice(-2) + '-' + ('0' + now.getDate()).slice(-2);
    const url      = _SB_URL + '/rest/v1/hijri_month_starts?country=eq.' + encodeURIComponent(country)
                   + '&gregorian_start_date=lte.' + isoToday
                   + '&order=gregorian_start_date.desc&limit=1';

    fetch(url, { headers: { apikey: _SB_KEY, Authorization: 'Bearer ' + _SB_KEY } })
        .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function (rows) {
            if (!rows || !rows.length) {
                dolog('[HijriSync] officiel (' + country + ') : aucune entrée → fallback');
                callback(null);
                return;
            }
            const row        = rows[0];
            const start      = new Date(row.gregorian_start_date + 'T00:00:00');
            const nowMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            const d = Math.round((nowMidnight - start) / 86400000) + 1;
            if (d < 1 || d > 30) {
                dolog('[HijriSync] officiel (' + country + ') : entrée périmée (d=' + d + ') → fallback');
                callback(null);
                return;
            }
            dolog('[HijriSync] officiel ✅ ' + country + ' → ' + d + '/' + row.hijri_month + '/' + row.hijri_year);
            callback({ d: d, m: row.hijri_month, y: row.hijri_year }, {
                country: country, gregorianStartDate: row.gregorian_start_date,
                hijriMonth: row.hijri_month, hijriYear: row.hijri_year, ts: Date.now()
            });
        })
        .catch(function (err) {
            dolog('[HijriSync] officiel (' + country + ') échec: ' + err.message + ' → fallback');
            callback(null);
        });
}

// ── Tentative de synchronisation (source officielle → API générique) ─────
//  ① Source officielle par pays (Supabase) — prioritaire si valide pour
//     aujourd'hui.
//  ② Sinon, synchro API générique existante (salahhour.com, inchangée).
//  ③ Sinon, le calcul STD (toujours exécuté en base, cf. _installHijriSyncOverride)
//     reste la valeur affichée — comportement inchangé.
function _attemptHijriSync() {
    if (JS_CUSTOM.ucHijriSyncEnabled != 1) return;

    if (!navigator.onLine) {
        dolog('[HijriSync] hors-ligne → retry dans 1h');
        _scheduleHijriSync(3600000, 'retry');
        refreshHijriSyncUI();
        return;
    }

    const today = _hijriTodayKey();

    _attemptOfficialHijriMonthStart(function (officialResult, rawRow) {
        if (officialResult) {
            _hijriOfficialRaw = rawRow;
            try { localStorage.setItem(_HIJRI_OFFICIAL_KEY, JSON.stringify(_hijriOfficialRaw)); } catch (e) {}
            _forceHijriDisplayRefresh();
            refreshHijriSyncUI();
            _scheduleHijriSync(_msUntil1am(), 'synchro');
            return;
        }
        // Pas de NOUVELLE donnée officielle (échec réseau, hors-ligne, ou pas
        // de ligne Supabase valide pour aujourd'hui) : on NE supprime PAS le
        // cache brut existant — il reste utilisable tel quel tant que son
        // calcul local (_computeOfficialToday) retombe dans la plage [1,30].
        // Ça évite de perdre une valeur officielle encore parfaitement valide
        // à cause d'un simple raté réseau (ex. fetch coupé par le
        // location.reload() de _applyMosqueConfig() au premier lancement).
        const stillLocal = _computeOfficialToday(_hijriOfficialRaw);
        if (stillLocal) {
            dolog('[HijriSync] pas de nouvelle donnée réseau, mais cache officiel local encore valide → conservé');
            _forceHijriDisplayRefresh();
            refreshHijriSyncUI();
            _scheduleHijriSync(3600000, 'retry-officiel');
            return;
        }
        _attemptSalahhourSync(today);
    });
}

// ── Synchro API générique (salahhour.com) — logique existante, inchangée,
//    extraite dans sa propre fonction pour être appelée en fallback.
function _attemptSalahhourSync(today) {
    const now   = new Date();
    const d     = now.getDate();
    const m     = now.getMonth() + 1;
    const y     = now.getFullYear();
    const url   = HijriApi.buildUrl(d, m, y);

    // Timeout manuel compatible avec tous les navigateurs supportés
    const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    const fetchOpts  = controller ? { signal: controller.signal } : {};
    const timeoutId  = controller ? setTimeout(function () { controller.abort(); }, 10000) : null;

    dolog('[HijriSync] tentative pour ' + today + '...');

    fetch(url, fetchOpts)
        .then(function (resp) {
            if (timeoutId) clearTimeout(timeoutId);
            if (!resp.ok) throw new Error('HTTP ' + resp.status);
            return resp.json();
        })
        .then(function (json) {
            const result = _parseHijriResponse(json);
            if (!result) throw new Error('format réponse non reconnu');

            _hijriSyncCache = { date: today, d: result.d, m: result.m, y: result.y, ts: Date.now() };
            localStorage.setItem(_HIJRI_SYNC_KEY, JSON.stringify(_hijriSyncCache));
            dolog('[HijriSync] ✅ succès → ' + result.d + '/' + result.m + '/' + result.y);
            _forceHijriDisplayRefresh();
            refreshHijriSyncUI();
            _scheduleHijriSync(_msUntil1am(), 'synchro');
        })
        .catch(function (err) {
            if (timeoutId) clearTimeout(timeoutId);
            dolog('[HijriSync] ❌ échec: ' + err.message + ' → retry dans 1h');
            refreshHijriSyncUI();
            _scheduleHijriSync(3600000, 'retry');
        });
}

// ── Forcer le rafraîchissement visuel de la date Hijri ───────────────────
//  Appelé dès qu'on a un résultat valide (cache ou fetch) pour éviter
//  d'attendre le prochain tick de l'horloge (qui peut être à la prochaine minute).
function _forceHijriDisplayRefresh() {
    try {
        // calculateAndDisplayTimesFunction est la fonction principale de l'app ;
        // elle appelle MiladiToHIJRI et met à jour tous les éléments DOM.
        if (typeof calculateAndDisplayTimesFunction === 'function') {
            calculateAndDisplayTimesFunction();
        }
    } catch (e) {
        dolog('[HijriSync] _forceHijriDisplayRefresh: ' + e.message);
    }
}

// ── Démarrage / redémarrage du scheduler ─────────────────────────────────
//  Ne saute la tentative immédiate QUE si la source officielle est déjà
//  résolue pour aujourd'hui. Un cache salahhour seul (ex. hérité d'un jour
//  où la source officielle n'existait pas encore, ou simplement d'une
//  tentative précédente aujourd'hui où l'officiel était absent) ne doit
//  jamais empêcher de retenter l'officiel au reload suivant.
function _startHijriSyncScheduler() {
    if (JS_CUSTOM.ucHijriSyncEnabled != 1) return;
    if (_hijriSyncTimer) clearTimeout(_hijriSyncTimer);

    // Calcul LOCAL d'abord (aucune attente réseau) : si la dernière ligne
    // officielle connue couvre encore aujourd'hui, on l'affiche immédiatement.
    if (_computeOfficialToday(_hijriOfficialRaw)) {
        dolog('[HijriSync] officiel (cache local) valide pour aujourd\'hui → affichage immédiat');
        _forceHijriDisplayRefresh();
        _scheduleHijriSync(_msUntil1am(), 'synchro');
    } else {
        dolog('[HijriSync] source officielle non résolue localement pour aujourd\'hui → tentative réseau');
        _attemptHijriSync();
    }
}

// ── Override MiladiToHIJRI ────────────────────────────────────────────────
//  Principe : le calcul STD tourne toujours en premier (sécurité + fallback
//  automatique si aucune source externe n'est valide). Ensuite, si la
//  synchro est active, on préfère (dans l'ordre) :
//    ① la source officielle par pays (Supabase, hijri_month_starts)
//    ② la synchro API générique (salahhour.com)
//  et on réécrit toutes les variables globales Hijri avec la première
//  source valide pour aujourd'hui.
(function _installHijriSyncOverride() {
    const _orig = window.MiladiToHIJRI;
    if (typeof _orig !== 'function') {
        dolog('[HijriSync] ⚠ MiladiToHIJRI introuvable → override ignoré');
        return;
    }

    window.MiladiToHIJRI = function (myDate, _dek) {
        // ① Calcul STD – toujours exécuté (fallback automatique si aucune source externe n'est OK)
        _orig(myDate, _dek);

        const todayKey       = _hijriTodayKey();
        const officialToday  = JS_CUSTOM.ucHijriSyncEnabled == 1 ? _computeOfficialToday(_hijriOfficialRaw) : null;
        const officialValid  = !!officialToday;
        const salahhourValid = JS_CUSTOM.ucHijriSyncEnabled == 1 && !officialValid &&
            !!_hijriSyncCache && _hijriSyncCache.date === todayKey;

        // ② Coloration du jour
        //   hijriOffsetActive : décalage manuel → rouge
        //   hijriOfficialOk   : source officielle par pays OK + pas de décalage → or
        //   hijriSyncOk       : API générique OK + pas de décalage → vert
        //   (mutuellement exclusifs : _dek=0 ↔ pas de rouge ; officiel prioritaire sur générique)
        document.body.classList.toggle('hijriOffsetActive', !!_dek);
        document.body.classList.toggle('hijriOfficialOk', !_dek && officialValid);
        document.body.classList.toggle('hijriSyncOk',      !_dek && salahhourValid);

        // ③ Vérifications avant override
        if (!officialValid && !salahhourValid) return;
        const source = officialValid ? officialToday : _hijriSyncCache;

        // ④ Appliquer le décalage manuel sur la valeur retenue. _dek ne vaut
        //    jamais plus de ±3 (cf. adjustHijriDateFunction, m2body.js), donc
        //    un seul passage de correction suffit — mais il faut ADDITIONNER
        //    30 (pas y forcer une valeur fixe), sinon -1/-2/-3 s'écrasent tous
        //    sur le même "30" au lieu de donner 30/29/28.
        let sd = source.d + (_dek | 0);
        let sm = source.m;
        const sy = source.y;
        if (sd < 1)  { sd += 30; sm--; }
        if (sd > 30) { sd -= 30; sm++; }
        if (sm < 1)  sm = 12;
        if (sm > 12) sm = 1;

        const jsHoursNow = myDate.getHours();

        // ③ Reconstruire toutes les variables globales Hijri (miroir exact de MiladiToHIJRI)
        isRamadan             = (sm == 9);
        hijriDateString       = "<span class='hijriDateClass'><span id='hijriDaySpan'> " + sd + "</span> " + hijriMonthsArray[sm - 1] + " </span><span id='hijriYearSpan'>" + sy + "</span>";
        hijriDateShort        = "<span id='hijriDaySpan'> " + sd + "</span> " + hijriMonthsArray[sm - 1] + " <span id='hijriYearSpan'>" + sy + "</span>";
        hijriDateArray        = [sd, hijriMonthsArray[sm - 1], sy];

        isEidAlAdhaPeriod     = ((sm == 12) && (sd >= 9 && sd <= 13));
        isLastDaysRamadan     = ((sm == 8)  && (sd >= 29));
        isFirstTenDhulHijjah  = ((sm == 12) && (sd >= 1  && sd <= 9));
        isLastTenRamadan      = ((sm == 9)  && (sd >= 20 && sd < 29));
        isEidOrTashreeq       = (sm == 10 && sd == 1) || ((sm == 12) && (sd >= 10 && sd <= 13));
        isWhiteDaysPeriod     = (sd >= 12 && sd <= 14) && (!isRamadan && !isEidAlAdhaPeriod && !isLastDaysRamadan);

        const xMM = ('0' + sm).slice(-2);
        const xDD = ('0' + sd).slice(-2);
        hijriMonthDay         = xMM + '/' + xDD;

        isDhulHijjahFirstNine = ((sm == 12) && (sd >= 1 && sd <= 9));
        specialEventLabel     = isDhulHijjahFirstNine ? '10DLHJ' : '';

        isEidFitrPeriod = ((sm == 9) && (sd >= 28));
        if ((sm == 10) && (sd == 1)  && (jsHoursNow < 10)) isEidFitrPeriod = true;

        isEidAdhaPeriod = ((sm == 12) && (sd >= 7 && sd <= 9));
        if ((sm == 12) && (sd == 10) && (jsHoursNow < 10)) isEidAdhaPeriod = true;

        // Compteur Ramadan (isMuharam/isShaban)
        if (sm == 7)      ramadanDaysLeftText = ' 1 Month,' + (30 - sd) + ' days ';
        else if (sm == 8) ramadanDaysLeftText = (30 - sd) + ' days ';

    };

    
})();

// ── Injection UI dans la modale Tech Options ─────────────────────────────
(function _injectHijriSyncUI() {
    const container = document.getElementById('techOptionsContentContainer');
    if (!container) return;

    // Plus de <hr> au-dessus (demande explicite du 14/08/2026 -- ce bloc vit
    // maintenant dans l'onglet "أخرى"/"Date et Météo" du menu principal,
    // cf. _installMenuSectionSubTabs, qui ne récupère un <hr> voisin QUE
    // s'il en trouve un juste avant hijriRow -- sans lui, rien n'est déplacé,
    // ce qui est le comportement voulu ici).
    // hijriSyncUrlButton n'affiche plus l'URL brute (trop encombrant à
    // l'écran) : simple icône 🔗 cliquable à côté du libellé, qui ouvre
    // toujours la même boîte de saisie (editHijriSyncUrlFunction) -- l'URL
    // complète reste visible/modifiable une fois la boîte ouverte, via
    // title=... en info-bulle pour un usage souris/desktop.
    container.insertAdjacentHTML('beforeend',
        "<!-- ═══ SYNCHRONISATION DATE HIJRI ═══ -->" +
        "<div>" +
            "<input type='checkbox' id='hijriSyncEnabledCheckbox' onchange='toggleHijriSyncFunction();'>" +
            "&nbsp;<span>مزامنة التاريخ الهجري</span>" +
            "&nbsp;<span class='clickableWhiteClass' id='hijriSyncUrlButton'" +
            "  onclick='editHijriSyncUrlFunction();'" +
            "  style='cursor:pointer;vertical-align:middle;'>🔗</span>" +
        "</div>" +
        "<div id='hijriSyncStatusRow' style='padding:2px 0 4px 26px;font-size:.82em;opacity:.7;'></div>"
    );

    refreshHijriSyncUI();
    _startHijriSyncScheduler();
})();

// ── Fonctions UI ──────────────────────────────────────────────────────────

function toggleHijriSyncFunction() {
    JS_CUSTOM.ucHijriSyncEnabled = +(!JS_CUSTOM.ucHijriSyncEnabled);
    saveCustomSettingsFunction();
    if (JS_CUSTOM.ucHijriSyncEnabled == 1) {
        // Activation explicite de la case (demande du 14/08/2026) : on vide
        // le cache existant (générique + officiel Supabase) et on retente
        // une VRAIE synchro réseau, plutôt que _startHijriSyncScheduler()
        // seul, qui aurait pu se contenter d'un cache encore valide pour
        // aujourd'hui (cf. commentaire de _startHijriSyncScheduler) sans
        // jamais retaper le réseau -- l'utilisateur qui réactive la case
        // s'attend à une tentative immédiate et fraîche.
        _hijriSyncCache   = null;
        _hijriOfficialRaw = null;
        try { localStorage.removeItem(_HIJRI_SYNC_KEY); } catch (e) {}
        try { localStorage.removeItem(_HIJRI_OFFICIAL_KEY); } catch (e) {}
        if (_hijriSyncTimer) { clearTimeout(_hijriSyncTimer); _hijriSyncTimer = null; }
        dolog('[HijriSync] activé → cache vidé, resynchro forcée');
        _attemptHijriSync();
    } else {
        if (_hijriSyncTimer) { clearTimeout(_hijriSyncTimer); _hijriSyncTimer = null; }
        dolog('[HijriSync] désactivé');
    }
    refreshHijriSyncUI();
}

function editHijriSyncUrlFunction() {
    if (!isInputDialogOpen) {
        inputDialogValue  = '';
        isInputDialogOpen = false;
        openInputDialogFunction(_dlgT('hijriSyncUrl'), JS_CUSTOM.ucHijriSyncUrl, 'editHijriSyncUrlFunction()', true);
        return;
    }
    const val = String(inputDialogValue || '').trim();
    if (val) JS_CUSTOM.ucHijriSyncUrl = val;
    saveCustomSettingsFunction();
    refreshHijriSyncUI();
}

function refreshHijriSyncUI() {
    const cb        = document.getElementById('hijriSyncEnabledCheckbox');
    const urlBtn    = document.getElementById('hijriSyncUrlButton');
    const statusRow = document.getElementById('hijriSyncStatusRow');

    if (cb)     cb.checked       = (JS_CUSTOM.ucHijriSyncEnabled == 1);
    // Icône fixe (🔗), plus d'URL affichée en clair (cf. _injectHijriSyncUI) --
    // seul le title= (info-bulle) reflète la valeur courante.
    if (urlBtn) urlBtn.title      = JS_CUSTOM.ucHijriSyncUrl || '';

    if (statusRow) {
        if (JS_CUSTOM.ucHijriSyncEnabled != 1) {
            statusRow.innerHTML = '';
        } else {
            const today = _hijriTodayKey();
            function _fmtTs(ts) {
                if (!ts) return '';
                var d  = new Date(ts);
                var dd = ('0' + d.getDate())    .slice(-2);
                var mm = ('0' + (d.getMonth()+1)).slice(-2);
                var yy = d.getFullYear();
                var hh = ('0' + d.getHours())   .slice(-2);
                var mn = ('0' + d.getMinutes())  .slice(-2);
                return ' — ' + dd + '/' + mm + '/' + yy + ' ' + hh + ':' + mn;
            }
            const officialTodayUI = _computeOfficialToday(_hijriOfficialRaw);
            if (officialTodayUI) {
                statusRow.innerHTML = '🏅 مصدر رسمي (' + (_resolveMosqueCountry() || '?') + '): '
                    + officialTodayUI.d + '/' + officialTodayUI.m + '/' + officialTodayUI.y
                    + _fmtTs(_hijriOfficialRaw && _hijriOfficialRaw.ts);
            } else if (_hijriSyncCache && _hijriSyncCache.date === today) {
                statusRow.innerHTML = '✅ آخر مزامنة: ' + _hijriSyncCache.d + '/' + _hijriSyncCache.m + '/' + _hijriSyncCache.y
                    + _fmtTs(_hijriSyncCache.ts);
            } else {
                statusRow.innerHTML = '⏳ في انتظار المزامنة…';
            }
        }
    }

    // Mise à jour immédiate de la couleur du jour hijri après chaque changement de statut sync
    var _dek = (typeof JS_CUSTOM !== 'undefined') ? (JS_CUSTOM.ucHijriDateFixer || 0) : 0;
    var _todayNow        = _hijriTodayKey();
    var _officialOkNow   = !_dek && JS_CUSTOM.ucHijriSyncEnabled == 1 &&
        !!_computeOfficialToday(_hijriOfficialRaw);
    var _salahhourOkNow  = !_dek && JS_CUSTOM.ucHijriSyncEnabled == 1 && !_officialOkNow &&
        !!_hijriSyncCache && _hijriSyncCache.date === _todayNow;
    document.body.classList.toggle('hijriOfficialOk', _officialOkNow);
    document.body.classList.toggle('hijriSyncOk',      _salahhourOkNow);
}

// ── Synchro manuelle ─────────────────────────────────────────────────────
//  Depuis la console du navigateur :   forceHijriSyncFunction()
//  Ou depuis n'importe quel bouton custom : onclick="forceHijriSyncFunction()"
function forceHijriSyncFunction() {
    dolog('[HijriSync] 🔄 synchro manuelle déclenchée');
    if (_hijriSyncTimer) { clearTimeout(_hijriSyncTimer); _hijriSyncTimer = null; }
    _attemptHijriSync();
}


