(function _installLogoFrame() {
    function _init() {
        var logo  = document.getElementById('appLogoImageHorizontal');
        var jomoa = document.getElementById('jomoaCounterHorizontal');
        if (!logo || !jomoa) { setTimeout(_init, 300); return; }
        if (document.getElementById('appLogoFrameHorizontal')) return;
        var frame = document.createElement('div');
        frame.id = 'appLogoFrameHorizontal';
        logo.parentNode.insertBefore(frame, logo);
        frame.style.visibility = (logo.style.visibility === 'hidden') ? 'hidden' : 'visible';
        var _origFn = window.updateJomoaLogoDisplayFunction;
        window.updateJomoaLogoDisplayFunction = function() {
            _origFn.apply(this, arguments);
            var frm = document.getElementById('appLogoFrameHorizontal');
            var lgo = document.getElementById('appLogoImageHorizontal');
            if (frm && lgo) frm.style.visibility = lgo.style.visibility === 'hidden' ? 'hidden' : 'visible';
        };
        _L('LOGO','FRAME_INIT',{});
    }
    setTimeout(_init, 600);
})();

// ==========================================================================
// -- JOMOA (JUMU'AH) EN MODE VERTICAL ---------------------------------------
// Mode horizontal (core) : quand JS_DATA.ucJomoaOnHRscreen == 1, le logo
// (#appLogoImageHorizontal) est remplacé par l'heure de la jomoa + le nom de
// la prière (#jomoaCounterHorizontal), cf. updateJomoaLogoDisplayFunction
// dans m2body.js. Aucun équivalent n'existe en mode vertical (confirmé :
// zéro référence à #appLogoImage dans toute la logique jomoa du core) —
// cette IIFE l'ajoute : un nouvel élément #jomoaCounterVertical, positionné
// exactement comme #appLogoImage (mêmes règles par thème classicVrClass/
// specialVrClass, cf. custom.css), qui reprend AUSSI le comportement
// cliquable du logo (ouverture de la barre flottante à 4 icônes, cf.
// _installLogoQuickBar plus bas) — ce qui est cliquable via le logo doit le
// rester quand la jomoa est affichée à sa place.
(function _installJomoaVertical() {
    var logoVr = document.getElementById('appLogoImage');
    if (!logoVr) return;

    var counter = document.createElement('div');
    counter.id = 'jomoaCounterVertical';
    var timeEl  = document.createElement('div');
    timeEl.id   = 'jomoaTimeDisplayVertical';
    var labelEl = document.createElement('div');
    labelEl.id  = 'jomoaLabelVertical';
    counter.appendChild(timeEl);
    counter.appendChild(labelEl);
    logoVr.parentNode.insertBefore(counter, logoVr);

    // Même libellé que la version horizontale (texte localisé core, posé une
    // seule fois au boot côté horizontal, jamais rafraîchi ensuite — même
    // limitation déjà existante, reprise ici à l'identique par cohérence).
    labelEl.textContent = (typeof JS_eLang !== 'undefined' && JS_eLang.cx_JOMOA) || '';

    // Même comportement cliquable que #appLogoImage : ouvre la barre
    // flottante à 4 icônes (cf. createCustomSideIcons plus haut).
    counter.addEventListener('click', function() {
        if (typeof window.openLogoQuickBar === 'function') window.openLogoQuickBar();
    });

    // #jomoaTimeDisplayHorizontal est déjà corrigé (bug "0AUTO") par
    // _patchJomoaDisplay plus haut AVANT que notre propre wrapper (plus bas)
    // ne s'exécute : on se contente de copier ce résultat déjà correct,
    // sans dupliquer la logique AUTO/heure fixe.
    function _refreshContent() {
        var hTime = document.getElementById('jomoaTimeDisplayHorizontal');
        if (hTime) timeEl.innerHTML = hTime.innerHTML;
    }

    function _refreshVisibility() {
        if (JS_DATA.ucJomoaOnHRscreen == 1) {
            hideElementByIdFunction('appLogoImage');
            showElementFunction('jomoaCounterVertical');
            _refreshContent();
        } else {
            showElementFunction('appLogoImage');
            hideElementByIdFunction('jomoaCounterVertical');
        }
    }
    _refreshVisibility();

    // Suit exactement le même déclencheur que la version horizontale (toggle
    // Jumu'ah depuis les réglages, layout 5-boîtes, etc.) —
    // window.updateJomoaLogoDisplayFunction peut déjà avoir été enrichie par
    // une autre IIFE (_installLogoFrame, juste au-dessus) : on l'appelle
    // d'abord, puis on ajoute notre propre bascule verticale par-dessus.
    var _origToggle = window.updateJomoaLogoDisplayFunction;
    window.updateJomoaLogoDisplayFunction = function() {
        _origToggle.apply(this, arguments);
        _refreshVisibility();
    };

    // Contenu (heure) rafraîchi à chaque cycle, comme la version horizontale.
    var _origDisplay = window.updateMosqueAndDateDisplayFunction;
    window.updateMosqueAndDateDisplayFunction = function() {
        _origDisplay.apply(this, arguments);
        if (JS_DATA.ucJomoaOnHRscreen == 1) _refreshContent();
    };

    _L('CUSTOM', 'INIT', { item: 'jomoaVertical' });
})();

// ==========================================================================
// -- GROUPE VISUEL : ucSelectMosqueButton + ucEditMosqueNameButton +
//    ucMosqueNotifButton -----------------------------------------------------
// Regroupe ces 3 boutons dans un conteneur commun (#ucMosqueButtonsGroup, cf.
// custom.css pour la séparation visuelle haut/bas), pour donner l'impression
// d'un bloc distinct entre la zone selectCountryButton/selectCityButton
// (au-dessus) et ucExportConfigButton/ucImportConfigButton (en dessous).
// S'exécute après que TOUS ces éléments existent déjà (poll/retry) : les deux
// premiers (créés respectivement par _installMosqueSelector et
// _installMosqueNotifPanel) sont déplacés dans le groupe via appendChild
// (déplace, ne copie pas — tout leur comportement reste intact) ; le nouveau
// bouton du milieu est créé ici directement ; ucExportConfigButton/
// ucImportConfigButton restent à leur place d'origine (ancrés sur
// ucMosqueNotifButton) et se retrouvent donc mécaniquement juste après le
// groupe une fois ucSelectMosqueButton/ucMosqueNotifButton partis.
(function _installMosqueButtonsGroup() {
    function _init() {
        var selectMosqueBtn = document.getElementById('ucSelectMosqueButton');
        var notifBtn        = document.getElementById('ucMosqueNotifButton');
        var cityBtn         = document.getElementById('selectCityButton');
        var exportBtn       = document.getElementById('ucExportConfigButton');
        if (!selectMosqueBtn || !notifBtn || !cityBtn || !exportBtn) {
            setTimeout(_init, 300);
            return;
        }
        if (document.getElementById('ucMosqueButtonsGroup')) return;

        // Nouveau bouton : exactement la même fonction que mosqueNameOptionLabel
        // (span core, onclick="editMosqueNameFunction()", index.html) — même
        // libellé (JS_eLang.cx_MenuMosqueNAME) et même comportement (dialog
        // d'édition du nom de la mosquée, cf. editMosqueNameFunction, m2body.js),
        // simplement sous forme de "vrai bouton" comme les 2 autres.
        var nameBtn = document.createElement('button');
        nameBtn.type        = 'button';
        nameBtn.id          = 'ucEditMosqueNameButton';
        nameBtn.className   = 'addSlideButtonClass cursorPointerClass';
        nameBtn.textContent = (typeof JS_eLang !== 'undefined' && JS_eLang.cx_MenuMosqueNAME) || '';
        nameBtn.addEventListener('click', function() {
            if (typeof editMosqueNameFunction === 'function') editMosqueNameFunction();
        });

        var group = document.createElement('div');
        group.id = 'ucMosqueButtonsGroup';
        cityBtn.insertAdjacentElement('afterend', group);

        group.appendChild(selectMosqueBtn);
        group.appendChild(nameBtn);
        group.appendChild(notifBtn);

        _L('CUSTOM', 'INIT', { item: 'mosqueButtonsGroup' });
    }
    _init();
})();

// ==========================================================================
// -- BLOC useWcsvCheckbox EN DERNIER DANS #locationContentContainer ---------
// Ordre core (index.html) : useWcsvCheckbox+label+hr (bloc A) PUIS
// .locationSettingsClass (bloc B, qui contient citySelectionTitle/
// selectCountryButton/selectCityButton + les boutons ci-dessus + le reste).
// On veut l'inverse : bloc A en dernier. Déplace tous les noeuds qui
// précèdent .locationSettingsClass vers la fin du conteneur, dans leur ordre
// d'origine (appendChild successifs = ordre préservé) — fonctionne quels que
// soient les nœuds exacts (input, texte "&nbsp;", label, <hr>), sans dépendre
// de leur nombre/type précis. Regroupés dans un wrapper (au lieu de rester
// des nœuds détachés) pour pouvoir les masquer d'un bloc. Masqué en
// permanence, tous appareils confondus (demande explicite du 14/08/2026,
// remplace le masquage précédent limité au téléphone) : ce réglage (fichier
// wcsv.js à éditer manuellement dans le dossier de l'appli) ne doit plus être
// visible du tout dans l'UI.
(function _installMoveWcsvBlockLast() {
    function _init() {
        var container  = document.getElementById('locationContentContainer');
        var settingsDiv = container && container.querySelector('.locationSettingsClass');
        if (!container || !settingsDiv) { setTimeout(_init, 300); return; }
        var wrap = document.createElement('div');
        wrap.id = 'ucWcsvBlockWrap';
        while (container.firstChild !== settingsDiv) {
            wrap.appendChild(container.firstChild);
        }
        container.appendChild(wrap);

        wrap.style.display = 'none';

        _L('CUSTOM', 'INIT', { item: 'moveWcsvBlockLast' });
    }
    _init();
})();

