// -- ALERT BY VOICE --------------------------------------------------------
(function _installAlertByVoice() {
    var LOCAL_SRC  = 'spec/audio/alert_voice.ogg';
    var _audio     = null;
    var _resolvedSrc = null;
    // _audio est un élément DÉTACHÉ du DOM (jamais appendChild), recréé au
    // besoin par _getAudio() -- fermeture directe (cf. tout en haut du
    // fichier, _installUniversalFlipToMute).
    _ucRegisterFlipMuteTarget(function() { return _audio; });
    function _probe() {
        if (JS_CUSTOM.ucQuranServerEnabled != 1) { _resolvedSrc = LOCAL_SRC; return; }
        var base = (JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '');
        var serverSrc = base + '/AUDIO/alert_voice.mp3';
        var xhr = new XMLHttpRequest(); xhr.open('HEAD', serverSrc, true); xhr.timeout = 3000;
        function _useLocal(r) { _resolvedSrc = LOCAL_SRC; _L('AUDIO','WARN',{action:'alert_voice_probe',reason:r,fallback:'local'}); }
        xhr.onload = function() { if (xhr.status>=200&&xhr.status<400) { _resolvedSrc=serverSrc; _L('AUDIO','FIRE',{action:'alert_voice_probe',src:serverSrc,source:'server'}); } else _useLocal('http_'+xhr.status); };
        xhr.onerror = function() { _useLocal('server_unreachable'); };
        xhr.ontimeout = function() { _useLocal('server_timeout'); };
        xhr.send();
    }
    _probe();
    function _getAudio(src) {
        if (!_audio || _audio.dataset.src !== src) { _audio = new Audio(src); _audio.dataset.src = src; _audio.preload = 'auto'; }
        return _audio;
    }
    function _play() {
        var src = _resolvedSrc || LOCAL_SRC;
        var a = _getAudio(src);
        a.currentTime = 0;
        function _tryLocal() {
            if (src === LOCAL_SRC) return;
            var b = _getAudio(LOCAL_SRC); b.currentTime = 0;
            b.play().catch(function(err2) { _L('AUDIO','ERR',{action:'alert_voice',src:LOCAL_SRC,err:(err2&&err2.message)||String(err2)}); });
        }
        _L('AUDIO','FIRE',{action:'alert_voice',src:src});
        a.play().catch(function(err) { _L('AUDIO','WARN',{action:'alert_voice',src:src,err:(err&&err.message)||String(err)}); _tryLocal(); });
        a.addEventListener('error', function _onErr() { a.removeEventListener('error',_onErr); _tryLocal(); }, {once:true});
    }
    var _firedThisCycle = false;
    ucOn(UC_EVT.IQAMA_TIME, function() { _firedThisCycle = false; });
    ucOn(UC_EVT.COUNTDOWN_TICK, function(e) {
        if (JS_CUSTOM.ucAlertByVoiceEnabled != 1) return;
        if (_firedThisCycle) return;
        if (e.isDohaPrayer) return;
        var target = Math.max(8, Math.min(59, parseInt(JS_CUSTOM.ucAlertByVoiceDelay, 10) || 12));
        if (e.remainingSeconds !== target) return;
        _firedThisCycle = true;
        _play();
    });
    // -- Injection UI sous alertLastMinuteCheckbox ---------------------
    function _injectCheckbox() {
        var ref = document.getElementById('alertLastMinuteCheckbox');
        if (!ref) { setTimeout(_injectCheckbox, 600); return; }
        if (document.getElementById('alertByVoiceCheckbox')) return;

        var parentDiv = ref.closest ? ref.closest('div') : ref.parentNode;
        if (!parentDiv) return;

        var newDiv = document.createElement('div');
        newDiv.className = 'ucAlertVoiceRow';
        newDiv.innerHTML =
            "<input type='checkbox' id='alertByVoiceCheckbox'" +
            " onchange='window._ucToggleAlertByVoice();'>" +
            "<label for='alertByVoiceCheckbox' class='ucAlertVoiceLabel'>" +
            "تنبيه صوتي بإغلاق الهاتف" +
            "</label>" +
            "<button id='alertByVoiceDelayBtn' class='ucAlertVoiceDelayBtn'" +
            " onclick='window._ucEditAlertVoiceDelay();'" +
            " title='الثانية التي يُشغَّل فيها الصوت (8-59)'>" +
            (JS_CUSTOM.ucAlertByVoiceDelay || 12) + 's' +
            "</button>" +
            "<button id='alertByVoicePlayBtn' class='ucAlertVoicePlayBtn' title='تشغيل'" +
            " onclick='window._ucPlayAlertVoice();'>" +
            "&#9654;" +
            "</button>";

        parentDiv.insertAdjacentElement('afterend', newDiv);
        document.getElementById('alertByVoiceCheckbox').checked = (JS_CUSTOM.ucAlertByVoiceEnabled == 1);
        _L('CFG', 'INJECT', { item: 'alertByVoiceCheckbox' });
    }
        window._ucToggleAlertByVoice = function() {
        JS_CUSTOM.ucAlertByVoiceEnabled = JS_CUSTOM.ucAlertByVoiceEnabled == 1 ? 0 : 1;
        saveCustomSettingsFunction();
        var cb = document.getElementById('alertByVoiceCheckbox');
        if (cb) cb.checked = (JS_CUSTOM.ucAlertByVoiceEnabled == 1);
        _L('CFG','SET',{ucAlertByVoiceEnabled:JS_CUSTOM.ucAlertByVoiceEnabled});
    };
    window._ucEditAlertVoiceDelay = function() {
        var container = document.getElementById('inputDialogContainer');
        if (!container || container.style.visibility !== 'visible') {
            openInputDialogFunction(_dlgT('alertVoiceDelay'), JS_CUSTOM.ucAlertByVoiceDelay || 12, 'window._ucEditAlertVoiceDelay()', true);
            return;
        }
        var field = document.getElementById('inputDialogTextField');
        var val = parseInt(field ? field.value : '12', 10);
        if (isNaN(val) || val < 12) val = 12;
        if (val > 59) val = 59;
        JS_CUSTOM.ucAlertByVoiceDelay = val;
        saveCustomSettingsFunction();
        var btn = document.getElementById('alertByVoiceDelayBtn');
        if (btn) btn.textContent = val + 's';
        _L('CFG','SET',{ucAlertByVoiceDelay:val});
    };
    window._ucPlayAlertVoice = function() { _play(); };
    _injectCheckbox();
})();

// ── BOX CONTROL OVERLAY  (Volume + WiFi)  ─────────────────────────────────────
// Lien injecte dans #menuFooterLinks ; overlay avec 2 sections :
//   1. Volume musique  : mute/unmute, +/-10%, +/-5%, presets, slider
//   2. WiFi            : on/off, statut, SSID
// Utilise ucQuranServerUrl comme base (ex. http://127.0.0.1:8080).
// ──────────────────────────────────────────────────────────────────────────────
(function _initBoxControlOverlay() {

    function _base() {
        return (JS_CUSTOM.ucBoxServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '');
    }
    function _displayHost() {
        return _base().replace(/^https?:\/\//, '').replace(/\/.*$/, '');
    }

    // ── Helpers API ──────────────────────────────────────────────────────────
    function _api(endpoint, cb) {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', _base() + endpoint, true);
        xhr.timeout = 5000;
        xhr.onload = function() {
            try { cb(null, JSON.parse(xhr.responseText)); }
            catch(e) { cb('parse_error', null); }
        };
        xhr.onerror   = function() { cb('unreachable', null); };
        xhr.ontimeout = function() { cb('timeout', null); };
        xhr.send();
    }

    // ── DOM helpers ──────────────────────────────────────────────────────────
    function _el(id) { return document.getElementById(id); }
    function _setStatus(id, text, cls) {
        var el = _el(id);
        if (!el) return;
        el.textContent = text;
        el.className = 'ucBCStatus' + (cls ? ' ' + cls : '');
    }
    function _disableBtn(id, dis) {
        var el = _el(id);
        if (el) { el.disabled = dis; el.classList.toggle('muted', dis); }
    }

    // ── Injection HTML overlay ────────────────────────────────────────────────
    var overlay = document.createElement('div');
    overlay.id = 'ucBoxControlOverlay';
    overlay.onclick = function(e) { if (e.target === overlay) window.closeBoxControl(); };

    overlay.innerHTML = [
        '<div id="ucBoxControlModal">',
        '  <div id="ucBCHeader">',
        '    <span id="ucBCTitle">&#9881; CONTROLE BOX</span>',
        '    <span id="ucBCServerBtn" onclick="window._bcEditServerUrl()" title="Changer le serveur">127.0.0.1:8080</span>',
        '    <span id="ucBCClose" onclick="window.closeBoxControl()">&#10006;</span>',
        '  </div>',
        '  <div class="ucBCSection">',
        '    <div class="ucBCSectionTitle">&#9834; Volume musique</div>',
        '    <div id="ucBCVolStatus" class="ucBCStatus">...</div>',
        '    <input id="ucBCVolSlider" type="range" min="0" max="100" value="50"',
        '           oninput="_bcApplySlider(this.value)" onchange="_bcSetVol(this.value)">',
        '    <div class="ucBCBtnRow">',
        '      <button class="ucBCBtn" onclick="window._bcStepVol(-10)">&#9660;10%</button>',
        '      <button class="ucBCBtn" onclick="window._bcStepVol(-5)">&#9660;5%</button>',
        '      <button class="ucBCBtn" onclick="window._bcStepVol(5)">&#9650;5%</button>',
        '      <button class="ucBCBtn" onclick="window._bcStepVol(10)">&#9650;10%</button>',
        '      <button class="ucBCBtn danger" onclick="window._bcMute()">Muet</button>',
        '      <button class="ucBCBtn primary" onclick="window._bcUnmute()">Restaurer</button>',
        '      <button class="ucBCBtn primary" onclick="window._bcSetVol(100)">100%</button>',
        '    </div>',
        '  </div>',
        '  <div class="ucBCSection">',
        '    <div class="ucBCSectionTitle">&#128246; WiFi</div>',
        '    <div id="ucBCWifiStatus" class="ucBCStatus">',
        '      <span id="ucBCWifiDot"></span><span id="ucBCWifiText">...</span>',
        '    </div>',
        '    <div class="ucBCInfoRow"><span class="ucBCInfoLabel">SSID</span><span id="ucBCWifiSsid" class="ucBCInfoVal">—</span></div>',
        '    <div class="ucBCInfoRow"><span class="ucBCInfoLabel">IP</span><span id="ucBCWifiIp" class="ucBCInfoVal">—</span></div>',
        '    <div class="ucBCBtnRow" style="margin-top:7px">',
        '      <button class="ucBCBtn primary" onclick="window._bcWifi(\x27on\x27)">&#9654; Activer</button>',
        '      <button class="ucBCBtn danger"  onclick="window._bcWifi(\x27off\x27)">&#9632; Couper</button>',
        '      <button class="ucBCBtn" onclick="window._bcRefreshWifi()">&#8635;</button>',
        '    </div>',
        '  </div>',
        '</div>'
    ].join('\n');

    document.documentElement.appendChild(overlay);

    // ── Injecter le lien dans #menuFooterLinks ────────────────────────────────
    (function _injectLink() {
        var footer = document.getElementById('menuFooterLinks');
        if (!footer) return;
        var br = document.createElement('br');
        var a  = document.createElement('a');
        a.href = '#';
        a.innerHTML = '&#9654; CONTR&Ocirc;LE BOX';
        a.onclick = function(e) { e.preventDefault(); window.openBoxControl(); };
        footer.appendChild(br);
        footer.appendChild(a);
    })();

    // ── Volume ────────────────────────────────────────────────────────────────
    function _refreshVolume() {
        _setStatus('ucBCVolStatus', 'Chargement...', '');
        _api('/api/audio/status', function(err, data) {
            if (err || !data) {
                _setStatus('ucBCVolStatus', 'Serveur inaccessible', 'err');
                return;
            }
            var pct = data.music_max > 0 ? Math.round(data.music * 100 / data.music_max) : 0;
            _setStatus('ucBCVolStatus',
                'Musique : ' + pct + '%  (' + data.music + '/' + data.music_max + ')'
                + (data.system !== undefined ? '   |   Systeme : ' + data.system + '/' + data.system_max : ''),
                pct > 0 ? 'ok' : 'warn');
            var sl = _el('ucBCVolSlider');
            if (sl) sl.value = pct;
        });
    }

    function _setVolPct(pct) {
        pct = Math.max(0, Math.min(100, parseInt(pct, 10)));
        _api('/api/audio/volume?level=' + pct, function(err, data) {
            if (err || !data) { _setStatus('ucBCVolStatus', 'Erreur : ' + (err || 'unknown'), 'err'); return; }
            var sl = _el('ucBCVolSlider');
            if (sl) sl.value = data.level_pct;
            _setStatus('ucBCVolStatus',
                'Musique : ' + data.level_pct + '%  (' + data.volume + '/' + data.max + ')',
                data.level_pct > 0 ? 'ok' : 'warn');
        });
    }

    function _stepVol(step) {
        var endpoint = step > 0
            ? '/api/audio/volume/up?step='   + Math.abs(step)
            : '/api/audio/volume/down?step=' + Math.abs(step);
        _api(endpoint, function(err, data) {
            if (err || !data) { _setStatus('ucBCVolStatus', 'Erreur : ' + (err || 'unknown'), 'err'); return; }
            var sl = _el('ucBCVolSlider');
            if (sl) sl.value = data.level_pct;
            _setStatus('ucBCVolStatus',
                'Musique : ' + data.level_pct + '%  (' + data.volume + '/' + data.max + ')',
                data.level_pct > 0 ? 'ok' : 'warn');
        });
    }

    // Mise a jour visuelle du slider sans appel reseau (feedback immediat)
    window._bcApplySlider = function(val) {
        _setStatus('ucBCVolStatus', 'Volume : ' + val + '%', '');
    };

    // ── WiFi ──────────────────────────────────────────────────────────────────
    function _refreshWifi() {
        var dot  = _el('ucBCWifiDot');
        var txt  = _el('ucBCWifiText');
        var ssidEl = _el('ucBCWifiSsid');
        var ipEl   = _el('ucBCWifiIp');
        if (txt) txt.textContent = 'Chargement...';
        if (dot) dot.className = 'busy';
        if (ssidEl) ssidEl.textContent = '...';
        if (ipEl)   ipEl.textContent   = '...';
        _api('/wifi/status', function(err, data) {
            if (err || !data) {
                if (dot) dot.className = 'off';
                if (txt) txt.textContent = 'Serveur inaccessible';
                if (ssidEl) ssidEl.textContent = '—';
                if (ipEl)   ipEl.textContent   = '—';
                _setStatus('ucBCWifiStatus', '', 'err');
                return;
            }
            var on = data.enabled;
            if (dot) dot.className = on ? 'on' : 'off';
            if (txt) txt.textContent = (on ? 'Actif' : 'Inactif') + '  (SDK ' + data.android_sdk + ')';
            if (ssidEl) ssidEl.textContent = (data.ssid && data.ssid.length > 0) ? data.ssid : '—';
            if (ipEl)   ipEl.textContent   = (data.ip   && data.ip.length   > 0) ? data.ip   : '—';
        });
    }

    function _setWifi(state) {
        var dot  = _el('ucBCWifiDot');
        var txt  = _el('ucBCWifiText');
        if (dot) dot.className = 'busy';
        if (txt) txt.textContent = state === 'on' ? 'Activation...' : 'Desactivation...';
        _disableBtn('ucBCWifiOnBtn',  true);
        _disableBtn('ucBCWifiOffBtn', true);
        _api('/wifi/' + state, function(err, data) {
            _disableBtn('ucBCWifiOnBtn',  false);
            _disableBtn('ucBCWifiOffBtn', false);
            if (err || !data || data.error) {
                if (dot) dot.className = 'off';
                var msg = (data && data.message) ? data.message : (err || 'erreur inconnue');
                if (txt) txt.textContent = 'Echec : ' + msg;
                return;
            }
            // Re-lire le statut apres 1 s pour confirmer
            setTimeout(_refreshWifi, 1000);
        });
    }

    // ── API publique ──────────────────────────────────────────────────────────
    window.openBoxControl = function() {
        if (typeof closeMenuFunction === 'function') closeMenuFunction();
        overlay.classList.add('bcVisible');
        var btn = document.getElementById('ucBCServerBtn');
        if (btn) btn.textContent = _displayHost();
        _refreshVolume();
        _refreshWifi();
    };
    window.closeBoxControl  = function() { overlay.classList.remove('bcVisible'); };
    var _bcServerDlgOpen = false;
    window._bcEditServerUrl = function() {
        if (!_bcServerDlgOpen) {
            // Phase 1 : ouvrir le dialog
            _bcServerDlgOpen = true;
            openInputDialogFunction(
                _dlgT('boxServerUrl'),
                JS_CUSTOM.ucBoxServerUrl || 'http://127.0.0.1:8080',
                'window._bcEditServerUrl()', true);
        } else {
            // Phase 2 : OK appuye — inputDialogValue contient la saisie
            _bcServerDlgOpen = false;
            var val = (typeof inputDialogValue !== 'undefined' ? inputDialogValue : '').trim();
            if (val) {
                if (!/^https?:\/\//.test(val)) val = 'http://' + val;
                JS_CUSTOM.ucBoxServerUrl = val.replace(/\/+$/, '');
                saveCustomSettingsFunction();
                var btn = document.getElementById('ucBCServerBtn');
                if (btn) btn.textContent = _displayHost();
                _L('BOX','SET',{ucBoxServerUrl: JS_CUSTOM.ucBoxServerUrl});
                _refreshVolume();
                _refreshWifi();
            }
        }
    };
    window._bcSetVol        = function(pct) { _setVolPct(pct); };
    window._bcStepVol       = function(step) { _stepVol(step); };
    window._bcMute          = function() {
        _api('/api/audio/mute', function(err, data) {
            if (err || !data) { _setStatus('ucBCVolStatus', 'Erreur mute', 'err'); return; }
            _setStatus('ucBCVolStatus', 'Son coupe', 'warn');
            var sl = _el('ucBCVolSlider'); if (sl) sl.value = 0;
        });
    };
    window._bcUnmute        = function() {
        _api('/api/audio/unmute', function(err, data) {
            if (err || !data) { _setStatus('ucBCVolStatus', 'Erreur unmute', 'err'); return; }
            var pct = data.music_max > 0 ? Math.round(data.music * 100 / data.music_max) : 50;
            _setStatus('ucBCVolStatus', 'Restaure : ' + data.music + '/' + (data.music_max || '?'), 'ok');
            var sl = _el('ucBCVolSlider'); if (sl) sl.value = pct;
        });
    };
    window._bcWifi          = function(state) { _setWifi(state); };
    window._bcRefreshWifi   = function() { _refreshWifi(); };
    window._bcRefreshVol    = function() { _refreshVolume(); };

    _L('CUSTOM', 'INIT', { item: 'BoxControlOverlay' });
})();

// ── Déplacer eidFitr + eidAdha après dohrXminAsrLabel ──────────────────────
// index.html (core, non modifiable) : eid items se trouvent entre iqamaHadith
// et les checkboxes audio. On les repositionne ici via DOM après dohrXminAsr.
(function _reorderEidSettings() {
    var eidFitrEl = document.getElementById('eidFitrCheckbox');
    var eidAdhaEl = document.getElementById('eidAdhaCheckbox');
    var dohrLabel = document.getElementById('dohrXminAsrLabel');
    if (!eidFitrEl || !eidAdhaEl || !dohrLabel) return;

    var eidFitrDiv = eidFitrEl.parentNode;
    var eidAdhaDiv = eidAdhaEl.parentNode;
    var dohrDiv    = dohrLabel.parentNode;

    // HR entre iqamaHadith et eid (ligne 714) → sera orphelin, supprimer
    var hrBeforeEid = eidFitrDiv.previousElementSibling;

    // HR après eid (ligne 718) → déplacer avec les items
    var hrAfterEid  = eidAdhaDiv.nextElementSibling;

    // Point d'insertion : après le <hr> qui suit déjà dohrXminAsrLabel
    var hrAfterDohr = dohrDiv.nextElementSibling;
    if (hrAfterDohr && hrAfterDohr.tagName === 'HR') {
        hrAfterDohr.after(eidFitrDiv, eidAdhaDiv, hrAfterEid);
    } else {
        dohrDiv.after(eidFitrDiv, eidAdhaDiv);
    }

    // Le <hr> (ligne 714) reste en place : après déplacement des eid, il sépare
    // naturellement iqamaHadith de azanIqamaByVoice. Rien à faire.

    _L('CUSTOM', 'INIT', { item: 'reorderEidSettings' });
})();

// ── Garde anti-bruteforce PIN (partagée par TOUS les écrans de saisie PIN :
// déverrouillage de la rangée admin, envoi Notifier, envoi Message, envoi
// Janaza, changement de PIN). Après 3 codes erronés consécutifs sur N'IMPORTE
// LEQUEL de ces écrans, blocage de 30s avant de pouvoir retenter — partout,
// pas seulement sur l'écran fautif. Compteur en mémoire (non persisté) :
// repart de zéro à chaque relance de l'app.
var _ucPinGuard = (function() {
    var MAX_ATTEMPTS = 3;
    var LOCKOUT_MS   = 30000;
    var failCount    = 0;
    var lockUntil    = 0;

    function _remainingMs() {
        var rem = lockUntil - Date.now();
        return rem > 0 ? rem : 0;
    }
    function _lockedMsg(seconds) {
        var lang = _ucLang();
        var L = {
            AR: 'محاولات كثيرة، أعد المحاولة بعد ' + seconds + ' ثانية',
            FR: 'Trop d’essais, réessayez dans ' + seconds + 's',
            EN: 'Too many attempts, retry in ' + seconds + 's',
            TR: 'Çok fazla deneme, ' + seconds + 's sonra tekrar deneyin',
            ID: 'Terlalu banyak percobaan, coba lagi dalam ' + seconds + 'd'
        };
        return L[lang] || L.EN;
    }
    // Vérifie l'état du verrou ; si bloqué, écrit le décompte dans errEl (si
    // fourni) et retourne true (l'appelant doit stopper son traitement).
    function check(errEl) {
        var rem = _remainingMs();
        if (rem > 0) {
            if (errEl) errEl.textContent = _lockedMsg(Math.ceil(rem / 1000));
            return true;
        }
        return false;
    }
    // À appeler après un PIN erroné (pas pour les autres erreurs de saisie,
    // ex. format invalide ou champs vides, qui ne sont pas des tentatives PIN).
    function fail() {
        failCount++;
        if (failCount >= MAX_ATTEMPTS) {
            lockUntil = Date.now() + LOCKOUT_MS;
            failCount = 0;
        }
    }
    // À appeler après un PIN correct, pour réinitialiser le compteur.
    function success() {
        failCount = 0;
        lockUntil = 0;
    }
    return { check: check, fail: fail, success: success };
})();
window._ucPinGuard = _ucPinGuard;

// ── PIN administrateur par défaut, masqué dans le code source ──────────────
// JS_CUSTOM.ucAdminPin (défini par l'utilisateur via "Code PIN") est TOUJOURS
// prioritaire ; ceci ne sert que de valeur de repli tant qu'aucun PIN n'a
// encore été choisi. Volontairement PAS écrit en clair ici (ni dans les
// commentaires) : un développeur lisant ce fichier ne doit pas pouvoir
// connaître la valeur d'un simple coup d'œil/grep. XOR à un seul octet —
// c'est de l'obscurcissement, pas un vrai chiffrement (tout code exécuté
// côté client est par nature reproductible par quiconque l'exécute), mais
// ça suffit à empêcher la lecture directe de la chaîne en clair.
function _ucDefaultAdminPin() {
    var K = 42;
    var enc = [24, 30, 27, 26, 27, 19, 29, 24];
    var out = '';
    for (var i = 0; i < enc.length; i++) out += String.fromCharCode(enc[i] ^ K);
    return out;
}

// ── Boutons "Notifier" + "Code PIN" apres eidAdha ──────────────────────────
// PIN stocke dans JS_CUSTOM.ucAdminPin (4 a 8 chiffres, defaut cf.
// _ucDefaultAdminPin() ci-dessus).
// Bouton Notifier : demande PIN → si correct → message (API a brancher ensuite).
// Bouton Code PIN : dialog 3 champs pour changer le PIN.
(function _installAdminNotifyPanel() {
    var PIN_KEY = 'ucAdminPin';

    function _getPin() { return JS_CUSTOM[PIN_KEY] || _ucDefaultAdminPin(); }
    function _setPin(pin) {
        JS_CUSTOM[PIN_KEY] = pin;
        if (typeof saveCustomSettingsFunction === 'function') saveCustomSettingsFunction();
        return _pushPinHash(pin);   // promesse {ok, status?, error?, skipped?}
    }

    function _pinSbCfg() {
        return {
            url: (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
                 || 'https://tjmjmlzwzebocfdmifrg.supabase.co',
            key: (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
                 || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4'
        };
    }

    // PATCH mosques.pin_hash + pose les gardes d'auto-écriture
    // (UC_SELF_WRITE_INFLIGHT / UC_SELF_WRITE_UPDATED_AT) pour que le polling de
    // config de CETTE box ne prenne pas sa propre écriture pour une modif
    // distante et ne reboucle pas en reload (même garde que
    // _installAutoExportAfterRemoteEdit). `pin_hash` n'est pas une colonne
    // horaire → le trigger on_mosque_update ne notifie personne.
    function _patchPinHashToServer(mid, hash) {
        var c = _pinSbCfg();
        try { localStorage.setItem('UC_SELF_WRITE_INFLIGHT', String(Date.now())); } catch (e) {}
        return fetch(c.url + '/rest/v1/mosques?mosque_id=eq.' + encodeURIComponent(mid) + '&select=updated_at', {
            method: 'PATCH',
            headers: {
                'Content-Type':  'application/json',
                'apikey':         c.key,
                'Authorization': 'Bearer ' + c.key,
                'Prefer':         'return=representation',
            },
            body: JSON.stringify({ pin_hash: hash }),
        })
        .then(function (r) {
            if (!r.ok) { _L('CFG', 'PIN_HASH_PUSH_ERR', { mosque_id: mid, status: r.status }); return { ok: false, status: r.status }; }
            return r.json().catch(function () { return null; }).then(function (rows) {
                try {
                    var ua = rows && rows[0] && rows[0].updated_at;
                    if (ua) localStorage.setItem('UC_SELF_WRITE_UPDATED_AT', ua);
                    localStorage.removeItem('UC_SELF_WRITE_INFLIGHT');
                } catch (e) {}
                _L('CFG', 'PIN_HASH_PUSHED', { mosque_id: mid });
                return { ok: true };
            });
        })
        .catch(function (e) {
            _L('CFG', 'PIN_HASH_PUSH_ERR', { mosque_id: mid, error: (e && e.message) || String(e) });
            return { ok: false, error: (e && e.message) || String(e) };
        });
    }

    // Pousse le hash (jamais le PIN en clair) vers mosques.pin_hash -- c'est CE
    // hash que rapid-service compare au PIN saisi dans l'écran « إدارة عن بعد »
    // (_installRemoteMosqueAdmin). **BOX UNIQUEMENT** : toutes les mosquées ont
    // une box, elle est la source de vérité du PIN d'admin à distance. Un
    // téléphone qui change son PIN local ne touche donc PLUS mosques.pin_hash
    // (fin du risque « PIN local de la box ≠ hash serveur », désync silencieuse).
    // Retourne une promesse {ok, status?, error?, skipped?} : le dialogue « Code
    // PIN » l'attend et affiche un vrai retour (fini le best-effort silencieux
    // qui laissait croire à une synchro réussie alors que le push avait échoué).
    function _pushPinHash(pin) {
        if (!_ucLwdIsBox()) return Promise.resolve({ ok: true, skipped: 'not_box' });
        var mid = window._ucCurrentMosqueId();
        if (!mid || (typeof _ucIsAnonymousMosqueId === 'function' && _ucIsAnonymousMosqueId(mid))) {
            return Promise.resolve({ ok: true, skipped: 'no_mosque' });
        }
        return _ucSha256Hex(pin).then(function (hash) {
            return _patchPinHashToServer(mid, hash);
        }).catch(function (e) {
            _L('CFG', 'PIN_HASH_PUSH_ERR', { mosque_id: mid, error: (e && e.message) || String(e) });
            return { ok: false, error: (e && e.message) || String(e) };
        });
    }

    // Auto-réparation au démarrage (box uniquement) : re-pousse mosques.pin_hash
    // à partir du PIN local de la box s'il est absent côté serveur ou divergent.
    // Corrige tout seul les cas : PIN jamais synchronisé (pin_hash NULL → 403 à
    // distance), push jadis échoué faute de réseau, désync après une écriture
    // parasite. Ne pousse JAMAIS le PIN d'usine (public) — dans ce cas l'admin
    // distant reste volontairement à 403 tant qu'un vrai PIN n'est pas défini
    // sur l'écran de la mosquée.
    var _pinHealDone = false;
    function _pinHashSelfHeal(attempt) {
        if (_pinHealDone || !_ucLwdIsBox()) return;
        attempt = attempt || 1;
        var mid = window._ucCurrentMosqueId && window._ucCurrentMosqueId();
        if (!mid || (typeof _ucIsAnonymousMosqueId === 'function' && _ucIsAnonymousMosqueId(mid))) return;
        var localPin = JS_CUSTOM[PIN_KEY] || _ucDefaultAdminPin();
        if (localPin === _ucDefaultAdminPin()) {
            _pinHealDone = true;
            _L('CFG', 'PIN_HASH_SELF_HEAL_SKIP', { mosque_id: mid, reason: 'still_default' });
            return;
        }
        var c = _pinSbCfg();
        _ucSha256Hex(localPin).then(function (hash) {
            return fetch(c.url + '/rest/v1/mosques?mosque_id=eq.' + encodeURIComponent(mid) + '&select=pin_hash',
                  { headers: { apikey: c.key, Authorization: 'Bearer ' + c.key } })
            .then(function (r) { return r.json(); })
            .then(function (rows) {
                var cur = (rows && rows[0]) ? rows[0].pin_hash : undefined;
                if (cur === hash) { _pinHealDone = true; _L('CFG', 'PIN_HASH_SELF_HEAL_OK', { mosque_id: mid }); return; }
                var reason = cur ? 'mismatch' : 'null';
                return _patchPinHashToServer(mid, hash).then(function (res) {
                    if (res.ok) _pinHealDone = true;
                    _L('CFG', 'PIN_HASH_SELF_HEAL_' + (res.ok ? 'PUSHED' : 'ERR'),
                       { mosque_id: mid, reason: reason, status: res.status || 0 });
                    if (!res.ok && attempt < 2) setTimeout(function () { _pinHashSelfHeal(attempt + 1); }, 63000);
                });
            });
        }).catch(function (e) {
            _L('CFG', 'PIN_HASH_SELF_HEAL_ERR', { mosque_id: mid, error: (e && e.message) || String(e) });
            if (attempt < 2) setTimeout(function () { _pinHashSelfHeal(attempt + 1); }, 63000);
        });
    }
    setTimeout(function () { _pinHashSelfHeal(1); }, 12000);

    // ── Boutons apres eidAdha ─────────────────────────────────────────────
    var eidAdhaEl = document.getElementById('eidAdhaCheckbox');
    if (!eidAdhaEl) return;

    // Ligne 1 (toujours accessible, indépendamment du code PIN) : ucMaJBtn
    // seul, centré — rempli plus bas par _installConfigSync.
    var alwaysRow = document.createElement('div');
    alwaysRow.id = 'ucAdminAlwaysRow';

    // Rangée protégée par le cadenas/code PIN — regroupée en 2 paquets
    // thématiques (retour ergonomie 27/08/2026, remplace l'ancien agencement
    // "ligne 3/4/5" purement positionnel, sans lien visuel entre boutons) :
    //   - Communication (envoi vers les fidèles) : ligne 4 (ucNotifierBtn
    //     seul) + ligne 3 (ucMsgBtn + ucJanazaBtn, remplies par
    //     _installAdminMessagePanel/_installAdminJanazaPanel) + légende
    //     "dernier envoi" (#ucAdminCommStatus, cf. _ucRefreshAdminStatus).
    //   - Système (gestion de cet appareil) : ligne "Pin" (ucPinChangeBtn
    //     seul) + ligne 5 (ucHistoryBtn seul, remplie par
    //     _installNotifHistoryPanel).
    // Les ids de lignes (ucAdminBtnLine3/4/5) restent identiques : les 3
    // autres IIFE qui y ajoutent un bouton (getElementById + appendChild)
    // n'ont rien à changer, seule leur position dans l'arborescence bouge.
    var btnRow = document.createElement('div');
    btnRow.id = 'ucAdminBtnRow';

    // Chaque groupe est UNE SEULE ligne (grid à N colonnes) qui héberge tous
    // ses boutons ensemble -- pas de sous-lignes séparées par bouton seul
    // (version précédente : Notifier/Code PIN isolés sur leur propre ligne
    // au-dessus du reste de leur groupe, incohérent avec "même groupe = même
    // ligne", retour utilisateur 27/08/2026).
    var groupComm = document.createElement('div');
    groupComm.className = 'ucAdminBtnGroup';
    var groupCommTitle = document.createElement('div');
    groupCommTitle.id = 'ucAdminGroupCommTitle';
    groupCommTitle.className = 'ucAdminBtnGroupTitle';
    var line3 = document.createElement('div');
    line3.id = 'ucAdminBtnLine3';
    var commStatus = document.createElement('div');
    commStatus.id = 'ucAdminCommStatus';
    commStatus.className = 'ucAdminStatusCaption';
    groupComm.appendChild(groupCommTitle);
    groupComm.appendChild(line3);
    groupComm.appendChild(commStatus);

    var groupSystem = document.createElement('div');
    groupSystem.className = 'ucAdminBtnGroup';
    var groupSystemTitle = document.createElement('div');
    groupSystemTitle.id = 'ucAdminGroupSystemTitle';
    groupSystemTitle.className = 'ucAdminBtnGroupTitle';
    var line5 = document.createElement('div');
    line5.id = 'ucAdminBtnLine5';
    groupSystem.appendChild(groupSystemTitle);
    groupSystem.appendChild(line5);

    btnRow.appendChild(groupComm);
    btnRow.appendChild(groupSystem);

    // Style unifié "pastille dorée" (.ucAdminActionBtn, custom.css) —
    // cohérent avec le reste de la modale (Proposer mosquée, Export/Import
    // config), remplace la classe core .addSlideButtonClass (bouton plat
    // générique, ancien style hérité du gestionnaire de récitateurs).
    function _makeBtn(id, label) {
        var b = document.createElement('button');
        b.type = 'button';
        b.id = id;
        b.className = 'ucAdminActionBtn cursorPointerClass';
        b.textContent = label;
        return b;
    }
    var btnNotify = _makeBtn('ucNotifierBtn',  'Notifier');
    var btnPin    = _makeBtn('ucPinChangeBtn', 'Code PIN');
    // Ajoutés en premier dans leur ligne respective : _installAdminMessagePanel/
    // _installAdminJanazaPanel (ligne 3) et _installNotifHistoryPanel (ligne
    // 5) ajoutent leur propre bouton APRÈS, via le même getElementById --
    // ordre final ligne 3 = Notifier, Message, Janaza ; ligne 5 = Code PIN,
    // Historique (RTL : le premier ajouté est le plus à droite).
    line3.appendChild(btnNotify);
    line5.appendChild(btnPin);

    // ── Légendes d'état (dernière synchro / dernier envoi) ─────────────────
    // Discrètes, purement informatives : donnent un repère "est-ce que ça a
    // marché ?" sans passer par l'historique complet. _ucGetNotifHistory /
    // UC_LAST_CONFIG_SYNC ne sont définis que plus loin dans ce fichier —
    // lookup différé au moment de l'appel (comme window._ucToast ailleurs),
    // donc sans danger même si cette fonction est appelée avant leur
    // définition (se contente d'afficher "Jamais" tant qu'ils n'existent pas).
    function _adminStatusLabels() {
        var L = {
            AR: { lastSync: 'آخر تحديث', lastSent: 'آخر إرسال', never: 'لم يحدث بعد' },
            FR: { lastSync: 'Dernière mise à jour', lastSent: 'Dernier envoi', never: 'Jamais' },
            EN: { lastSync: 'Last update', lastSent: 'Last sent', never: 'Never' },
            TR: { lastSync: 'Son güncelleme', lastSent: 'Son gönderim', never: 'Hiç' },
            ID: { lastSync: 'Pembaruan terakhir', lastSent: 'Terakhir dikirim', never: 'Belum pernah' }
        };
        return L[_ucLang()] || L.EN;
    }
    function _fmtAdminStatusTs(iso) {
        var d = new Date(iso);
        if (isNaN(d.getTime())) return '';
        function p2(n) { return (n < 10 ? '0' : '') + n; }
        return p2(d.getDate()) + '/' + p2(d.getMonth() + 1) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes());
    }
    function _ucRefreshAdminStatus() {
        var T = _adminStatusLabels();
        var majStatus = document.getElementById('ucMaJStatus');
        if (majStatus) {
            var lastSync = ''; try { lastSync = localStorage.getItem('UC_LAST_CONFIG_SYNC') || ''; } catch (e) {}
            majStatus.textContent = T.lastSync + ' : ' + (lastSync ? _fmtAdminStatusTs(lastSync) : T.never);
        }
        if (commStatus) {
            var hist = (window._ucGetNotifHistory && window._ucGetNotifHistory()) || [];
            commStatus.textContent = T.lastSent + ' : ' + (hist.length ? _fmtAdminStatusTs(hist[0].ts) : T.never);
        }
    }
    window._ucRefreshAdminStatus = _ucRefreshAdminStatus;

    // ── Mise à jour auto quotidienne (heure réglable) — box uniquement ─────
    // Remplace le déclenchement par push (peu fiable sur certains boîtiers,
    // cf. discussion 31/07/2026). Sciemment PAS dans #ucAdminBtnRow (pas
    // besoin du code PIN, demande explicite 01/08/2026 : un simple réglage
    // d'appareil, pas une action distante sur une mosquée). Heure éditée via
    // openInputDialogFunction (boîte de saisie libre déjà utilisée partout
    // ailleurs dans l'app, ex. editReciterNameFunction) plutôt qu'un <input
    // type=time> (rendu natif du navigateur jugé peu adapté, demande
    // explicite 01/08/2026). Chaque changement (case OU heure confirmée)
    // s'applique immédiatement, sans bouton "Enregistrer" séparé -- la
    // confirmation de la boîte de saisie en tient déjà lieu pour l'heure.
    var dailyUpdateRow = document.createElement('div');
    dailyUpdateRow.id = 'ucAutoDailyUpdateRow';
    var _isBoxForDailyUpdate = !!(window.AndroidMobile && typeof window.AndroidMobile.isAndroidTv === 'function'
        && window.AndroidMobile.isAndroidTv());
    if (_isBoxForDailyUpdate) {
        var dailyUpdateLabel = document.createElement('label');
        dailyUpdateLabel.id = 'ucAutoDailyUpdateLabel';
        dailyUpdateLabel.style.display = 'flex';
        dailyUpdateLabel.style.alignItems = 'center';
        dailyUpdateLabel.style.gap = '6px';
        dailyUpdateLabel.style.fontSize = '0.85em';
        dailyUpdateLabel.style.margin = '6px 0';

        var dailyUpdateCheckbox = document.createElement('input');
        dailyUpdateCheckbox.type = 'checkbox';
        dailyUpdateCheckbox.id = 'ucAutoDailyUpdateCheckbox';
        dailyUpdateCheckbox.checked = !!JS_CUSTOM.ucAutoDailyUpdateEnabled;
        dailyUpdateCheckbox.addEventListener('change', function () {
            JS_CUSTOM.ucAutoDailyUpdateEnabled = this.checked ? 1 : 0;
            _applyDailyUpdateNative();
        });

        var dailyUpdateText = document.createElement('span');
        dailyUpdateText.textContent = 'Mise à jour auto à';

        var btnEditDailyUpdateTime = _makeBtn('ucAutoDailyUpdateTimeBtn', JS_CUSTOM.ucAutoDailyUpdateTime || '01:00');
        btnEditDailyUpdateTime.style.width = 'auto';
        btnEditDailyUpdateTime.style.height = 'auto';
        btnEditDailyUpdateTime.style.padding = '4px 10px';
        btnEditDailyUpdateTime.addEventListener('click', function () { window._ucEditAutoDailyUpdateTime(); });

        dailyUpdateLabel.appendChild(dailyUpdateCheckbox);
        dailyUpdateLabel.appendChild(dailyUpdateText);
        dailyUpdateLabel.appendChild(btnEditDailyUpdateTime);
        dailyUpdateRow.appendChild(dailyUpdateLabel);

        var dailyUpdateStatus = document.createElement('span');
        dailyUpdateStatus.id = 'ucAutoDailyUpdateStatus';
        dailyUpdateStatus.style.fontSize = '0.8em';
        dailyUpdateStatus.style.opacity = '0.75';
        dailyUpdateRow.appendChild(dailyUpdateStatus);

        function _applyDailyUpdateNative() {
            var enabled = !!JS_CUSTOM.ucAutoDailyUpdateEnabled;
            var timeVal = JS_CUSTOM.ucAutoDailyUpdateTime || '01:00';
            var parts = timeVal.split(':');
            var hour = parseInt(parts[0], 10);
            var minute = parseInt(parts[1], 10);
            if (isNaN(hour) || hour < 0 || hour > 23) hour = 1;
            if (isNaN(minute) || minute < 0 || minute > 59) minute = 0;

            if (typeof saveCustomSettingsFunction === 'function') saveCustomSettingsFunction();
            if (window.AndroidMobile && typeof window.AndroidMobile.setAutoDailyUpdateEnabled === 'function') {
                window.AndroidMobile.setAutoDailyUpdateEnabled(enabled, hour, minute);
            }
            _L('CFG', 'SET', { ucAutoDailyUpdateEnabled: JS_CUSTOM.ucAutoDailyUpdateEnabled, ucAutoDailyUpdateTime: timeVal });
            dailyUpdateStatus.textContent = enabled ? ('Activé (' + timeVal + ')') : 'Désactivé';
        }
        window._ucApplyDailyUpdateNative = _applyDailyUpdateNative;

        // Boîte de saisie libre (HH:MM) -- pattern self-récursif standard de
        // cette app (cf. editReciterNameFunction) : le 1er appel ouvre la
        // boîte, le 2e (déclenché par son propre bouton OK) traite la saisie.
        window._ucEditAutoDailyUpdateTime = function () {
            if (!isInputDialogOpen) {
                inputDialogValue  = '';
                isInputDialogOpen = false;
                openInputDialogFunction('Heure de mise à jour (HH:MM)', JS_CUSTOM.ucAutoDailyUpdateTime || '01:00', 'window._ucEditAutoDailyUpdateTime()', true);
                return;
            }
            var raw = (inputDialogValue || '').trim();
            var m = raw.match(/^(\d{1,2}):(\d{2})$/);
            var hour = 1, minute = 0;
            if (m) {
                var h = parseInt(m[1], 10), mi = parseInt(m[2], 10);
                if (h >= 0 && h <= 23) hour = h;
                if (mi >= 0 && mi <= 59) minute = mi;
            }
            var normalized = (hour < 10 ? '0' : '') + hour + ':' + (minute < 10 ? '0' : '') + minute;
            JS_CUSTOM.ucAutoDailyUpdateTime = normalized;
            btnEditDailyUpdateTime.textContent = normalized;
            _applyDailyUpdateNative();
        };

        // Etat initial : applique tout de suite le réglage persisté (ex. après
        // un rechargement de la box), sans attendre une interaction.
        _applyDailyUpdateNative();
    }

    // Rattache DIRECTEMENT à #ucMosqueInfoAdminSection (déjà construite à ce
    // stade, cf. l'appel _buildModal() en fin de _installMosqueInfoModal plus
    // haut dans ce fichier) — jamais inséré dans adjustmentsContentContainer,
    // même de façon transitoire, contrairement à avant.
    var _adminSection = document.getElementById('ucMosqueInfoAdminSection');
    if (_adminSection) {
        _adminSection.appendChild(alwaysRow);
        _adminSection.appendChild(dailyUpdateRow);
        _adminSection.appendChild(btnRow);
    } else {
        // Filet de sécurité si la modale n'a exceptionnellement pas pu être
        // construite à temps : ancien emplacement, puis rattachement dès que
        // possible via _ucRelocateAdminRow.
        eidAdhaEl.parentNode.after(btnRow);
        btnRow.parentNode.insertBefore(alwaysRow, btnRow);
    }
    if (typeof window._ucRelocateAdminRow === 'function') window._ucRelocateAdminRow();

    // ── Style commun des overlays ─────────────────────────────────────────
    // z-index max (2147483647, comme #ucAdminUnlockOverlay plus bas) et non
    // 999999 : #ucMosqueInfoModal (custom.css) est passé à z-index:9999500
    // pour couvrir #ucSettingsButtonVertical, ce qui a fait passer TOUS les
    // overlays admin déclenchés depuis l'intérieur de cette modale (PIN
    // Notifier/changement, Message, Janaza, Historique, aperçu payload) sous
    // la modale elle-même -- clic sans effet visible (retour utilisateur
    // 27/08/2026 : bouton Message "ne fait rien" alors que l'overlay
    // s'ouvrait bel et bien, juste caché derrière). Corrigé partout où ce
    // symptôme s'applique (cf. mêmes overlays plus bas dans ce fichier).
    var OV_WRAP = [
        'display:none', 'position:fixed', 'top:0', 'right:0', 'bottom:0', 'left:0',
        'background:rgba(0,0,0,0.72)', 'z-index:2147483647',
        'align-items:center', 'justify-content:center'
    ].join(';');
    var BOX_STYLE = [
        'background:#1a1a2e', 'border:1px solid #555', 'border-radius:10px',
        'padding:24px', 'min-width:270px', 'text-align:center',
        'color:#fff', 'font-family:inherit'
    ].join(';');
    var INP_STYLE = [
        'width:220px', 'padding:8px', 'font-size:1.25em', 'letter-spacing:0.18em',
        'text-align:center', 'background:#0d0d1a', 'border:1px solid #888',
        'color:#fff', 'border-radius:6px', 'box-sizing:border-box', 'margin: 0 auto', 'display:block'
    ].join(';');
    var INP_SM = INP_STYLE.replace('1.25em','0.95em').replace('0.18em','0.06em');
    var ERR_STYLE = 'color:#ff4444;font-size:0.85em;min-height:1.2em;margin:8px 0 0;';
    var BTN_ROW   = 'display:flex;gap:10px;justify-content:center;margin-top:14px;';

    function _overlay(id, inner) {
        var d = document.createElement('div');
        d.id = id;
        d.style.cssText = OV_WRAP;
        d.innerHTML = '<div style="' + BOX_STYLE + '">' + inner + '</div>';
        document.body.appendChild(d);
        return d;
    }

    // ── Overlay 1 : verification PIN (Notifier) ───────────────────────────
    var ovVerify = _overlay('ucPinVerifyOverlay', [
        '<p style="margin:0 0 14px;font-size:1.1em;">Code PIN administrateur</p>',
        '<input id="ucPinVerifyInput" type="password" maxlength="8"',
        ' inputmode="numeric" style="' + INP_STYLE + '"/>',
        '<p id="ucPinVerifyErr" style="' + ERR_STYLE + '"></p>',
        '<div style="' + BTN_ROW + '">',
        '<span id="ucPinVerifyCancel" class="ucModalBtn ucModalBtn--secondary">Annuler</span>',
        '<span id="ucPinVerifyOk"     class="ucModalBtn ucModalBtn--primary">OK</span>',
        '</div>'
    ].join(''));

    // ── Overlay 2 : changement de PIN ─────────────────────────────────────
    var ovChange = _overlay('ucPinChangeOverlay', [
        '<p style="margin:0 0 14px;font-size:1.1em;">Changer le code PIN</p>',
        '<input id="ucPinOld"  type="password" maxlength="8" inputmode="numeric"',
        ' placeholder="Ancien PIN" style="' + INP_SM + ';margin-bottom:8px;"/>',
        '<input id="ucPinNew"  type="password" maxlength="8" inputmode="numeric"',
        ' placeholder="Nouveau PIN (4 a 8 chiffres)" style="' + INP_SM + ';margin-bottom:8px;"/>',
        '<input id="ucPinConf" type="password" maxlength="8" inputmode="numeric"',
        ' placeholder="Confirmer" style="' + INP_SM + '"/>',
        '<p id="ucPinChangeHint" style="color:rgba(223,205,177,0.7);font-size:0.8em;margin:10px 0 0;line-height:1.35;"></p>',
        '<p id="ucPinChangeErr" style="' + ERR_STYLE + '"></p>',
        '<div style="' + BTN_ROW + '">',
        '<span id="ucPinChangeCancel" class="ucModalBtn ucModalBtn--secondary">Annuler</span>',
        '<span id="ucPinChangeOk"     class="ucModalBtn ucModalBtn--primary">Confirmer</span>',
        '</div>'
    ].join(''));

    // ── Helpers ───────────────────────────────────────────────────────────
    function _el(id) { return document.getElementById(id); }
    function _show(ov) { ov.style.display = 'flex'; }
    function _hide(ov) { ov.style.display = 'none'; }

    // ── Bouton Notifier ───────────────────────────────────────────────────
    btnNotify.addEventListener('click', function() {
        _el('ucPinVerifyInput').value = '';
        _el('ucPinVerifyErr').textContent = '';
        _show(ovVerify);
        _el('ucPinVerifyInput').focus();
    });
    _el('ucPinVerifyCancel').addEventListener('click', function() { _hide(ovVerify); });
    _el('ucPinVerifyOk').addEventListener('click', function() {
        if (_el('ucPinVerifyInput').value === _getPin()) {
            _hide(ovVerify);
            // NB: ce handler est remplace par _installAdminPayloadPreview() plus bas,
            // qui clone #ucPinVerifyOk (supprime ce listener) et branche le vrai envoi.
            // Voir _sendPayload() dans _installAdminPayloadPreview.
            _ucToast((window._ucAdminMsg && window._ucAdminMsg.notifOk) || 'Notification envoyée', 'ok');
        } else {
            _el('ucPinVerifyErr').textContent = (window._ucAdminMsg && window._ucAdminMsg.pinErr) || 'Code PIN incorrect';
            _el('ucPinVerifyInput').select();
        }
    });
    _el('ucPinVerifyInput').addEventListener('keydown', function(e) {
        if (e.key === 'Enter') _el('ucPinVerifyOk').click();
    });

    // ── Bouton Code PIN ───────────────────────────────────────────────────
    btnPin.addEventListener('click', function() {
        ['ucPinOld','ucPinNew','ucPinConf'].forEach(function(id) { _el(id).value = ''; });
        _el('ucPinChangeErr').textContent = '';
        _el('ucPinChangeErr').style.color = '';
        _show(ovChange);
        _el('ucPinOld').focus();
    });
    _el('ucPinChangeCancel').addEventListener('click', function() { _hide(ovChange); });
    _el('ucPinChangeOk').addEventListener('click', function() {
        var err  = _el('ucPinChangeErr');
        var okBtn = _el('ucPinChangeOk');
        if (window._ucPinGuard && window._ucPinGuard.check(err)) return;
        var old  = _el('ucPinOld').value;
        var nw   = _el('ucPinNew').value;
        var conf = _el('ucPinConf').value;
        err.style.color = '';
        if (old  !== _getPin())          { window._ucPinGuard && window._ucPinGuard.fail(); err.textContent = (window._ucAdminMsg && window._ucAdminMsg.oldPinErr) || 'Ancien PIN incorrect';                       return; }
        if (!/^\d{4,8}$/.test(nw))       { err.textContent = (window._ucAdminMsg && window._ucAdminMsg.pin4Err) || 'Le nouveau PIN doit comporter entre 4 et 8 chiffres'; return; }
        if (nw !== conf)                  { err.textContent = (window._ucAdminMsg && window._ucAdminMsg.pinMismatch) || 'Les deux PIN ne correspondent pas'; return; }
        window._ucPinGuard && window._ucPinGuard.success();
        // PIN appliqué localement tout de suite ; on ATTEND le résultat de la
        // synchro serveur avant de fermer, pour ne jamais laisser croire que
        // l'admin à distance est armé alors que le push a échoué (box hors ligne).
        err.style.color = 'rgba(223,205,177,0.85)';
        err.textContent = (window._ucAdminMsg && window._ucAdminMsg.pinSyncing) || 'Synchronisation avec le serveur…';
        okBtn.style.pointerEvents = 'none';
        okBtn.style.opacity = '0.55';
        _setPin(nw).then(function (res) {
            okBtn.style.pointerEvents = '';
            okBtn.style.opacity = '';
            if (res && res.skipped) {
                // Téléphone : ce PIN ne vaut que sur cet appareil, aucune synchro.
                _hide(ovChange);
                _ucToast((window._ucAdminMsg && window._ucAdminMsg.pinLocalOnly) || 'Code PIN de cet appareil modifié', 'ok');
                return;
            }
            if (res && res.ok) {
                _hide(ovChange);
                _ucToast((window._ucAdminMsg && window._ucAdminMsg.pinSyncOk) || 'Code PIN modifié et synchronisé ✓', 'ok');
            } else {
                err.style.color = '#e0b050';
                err.textContent = (window._ucAdminMsg && window._ucAdminMsg.pinSyncFail)
                    || 'PIN changé sur cet écran, mais NON synchronisé au serveur. Reconnectez Internet et refaites l’opération.';
            }
        });
    });

    // ── Toast helper (compatible WebView Android + web) ──────────────────
    window._ucToast = function _ucToast(msg, type) {
        var t = document.getElementById('ucToast');
        if (!t) {
            t = document.createElement('div');
            t.id = 'ucToast';
            t.style.cssText = [
                'position:fixed', 'bottom:12%', 'left:50%', 'transform:translateX(-50%)',
                'background:rgba(0,0,0,0.82)', 'color:#fff', 'padding:10px 22px',
                'border-radius:24px', 'font-size:1em', 'z-index:2147483647',
                // Même correctif de z-index que OV_WRAP plus haut : ce toast
                // confirme les envois Notifier/Message/Janaza/PIN, tous
                // déclenchés depuis #ucMosqueInfoModal -- devait rester
                // au-dessus d'elle, pas en dessous.
                'pointer-events:none', 'transition:opacity 0.4s',
                'white-space:nowrap', 'display:none'
            ].join(';');
            document.body.appendChild(t);
        }
        t.textContent = msg;
        t.style.borderLeft = (type === 'ok') ? '4px solid #4caf50' : '4px solid #ff4444';
        t.style.display = 'block';
        t.style.opacity = '1';
        clearTimeout(t._tid);
        t._tid = setTimeout(function() {
            t.style.opacity = '0';
            setTimeout(function() { t.style.display = 'none'; }, 400);
        }, 2800);
    }

    _updateAdminLabels();
    _L('CUSTOM', 'INIT', { item: 'adminNotifyPanel' });
})();

// ── Traductions panneau admin (multilingue) ───────────────────────────────────────
// Applique les libellés des boutons + dialogs selon JS_DATA.ucLangNOW.
// window._ucAdminMsg est lu par les handlers déjà créés dans _installAdminNotifyPanel.
