        janazaDohr:   { AR: 'الظهر', FR: 'Dhuhr', EN: 'Dhuhr' },
        janazaAsr:    { AR: 'العصر', FR: 'Asr',   EN: 'Asr' },
        janazaNameReq: { AR: 'الاسم واللقب مطلوب', FR: 'Nom et prénom requis', EN: 'Name and surname required' },
        previewTitle:  { AR: 'معاينة البيانات', FR: 'Aperçu des données', EN: 'Data preview' },
