// ── Conteneur des liens de menu "prioritaires" ──────────────────────────────
// Injecté comme tout premier enfant de #languageSelectionContainer (donc
// au-dessus de la liste des langues et de #menuFooterLinks) pour les liens
// ucCheckUpdateMenuLink / ucQrCodeMenuLink / ucTourRelaunchLink, qui doivent
// rester visibles en haut du menu plutôt que noyés tout en bas.
function _ucGetTopMenuLinksContainer() {
    var container = document.getElementById('ucTopMenuLinks');
    if (container) return container;
    var langSection = document.getElementById('languageSelectionContainer');
    if (!langSection) return null;
    container = document.createElement('div');
    container.id = 'ucTopMenuLinks';
    langSection.insertBefore(container, langSection.firstChild);
    return container;
}

// Insère `a` (+ un <br> qui le suit) tout en haut du conteneur partagé
// ci-dessus, c.-à-d. avant tout ce qui s'y trouve déjà. Les 3 injecteurs
// s'exécutant dans l'ordre tour -> qr -> update, ce "prepend" systématique
// produit l'ordre final voulu : update, qr, tour (le dernier exécuté finit
// en tête).
function _ucPrependTopMenuLink(a) {
    var container = _ucGetTopMenuLinksContainer();
    if (!container) return false;
    var br = document.createElement('br');
    var firstChild = container.firstChild;
    if (firstChild) {
        container.insertBefore(a, firstChild);
        container.insertBefore(br, firstChild);
    } else {
        container.appendChild(a);
        container.appendChild(br);
    }
    return true;
}

